'use client';

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import { useRouter, useParams } from 'next/navigation';
import {
  User,
  Crown,
  FileText,
  CreditCard,
  LogOut,
  Sparkles,
  ExternalLink,
  ShieldCheck,
  CheckCircle2,
  AlertCircle,
  HardDrive,
  Clock
} from 'lucide-react';
import { formatBytes } from '@/lib/utils';

export default function UserAccountPage() {
  const router = useRouter();
  const params = useParams();
  const locale = (params?.locale as string) || 'de';

  const [userData, setUserData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [loggingOut, setLoggingOut] = useState(false);
  const [billingLoading, setBillingLoading] = useState(false);
  const [billingError, setBillingError] = useState<string | null>(null);

  useEffect(() => {
    fetch('/api/v1/auth/me')
      .then(async (res) => {
        if (!res.ok) {
          router.push(`/${locale}/login?redirect=/${locale}/konto`);
          return;
        }
        const data = await res.json();
        setUserData(data);
      })
      .catch(() => {
        router.push(`/${locale}/login?redirect=/${locale}/konto`);
      })
      .finally(() => {
        setLoading(false);
      });
  }, [locale, router]);

  const handleLogout = async () => {
    setLoggingOut(true);
    try {
      await fetch('/api/v1/auth/logout', { method: 'POST' });
      router.push(`/${locale}`);
      router.refresh();
    } catch {
      router.push(`/${locale}`);
    }
  };

  const handleManageSubscription = async () => {
    setBillingLoading(true);
    setBillingError(null);
    try {
      const res = await fetch('/api/v1/stripe/portal', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ returnUrl: window.location.href }),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.message || data.error || 'Abrechnungsportal konnte nicht geladen werden.');
      }

      if (data.url) {
        window.location.href = data.url;
      }
    } catch (err: any) {
      setBillingError(err.message || 'Abrechnungsportal derzeit nicht verfügbar.');
    } finally {
      setBillingLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-[70vh] flex items-center justify-center">
        <div className="w-8 h-8 border-3 border-sky-600/30 border-t-sky-600 rounded-full animate-spin" />
