export async function PATCH(req: NextRequest) {
  try {
    const admin = await requireAdmin(req);
    const body = await req.json();
    const { toolSlug, updates } = body;

    if (!toolSlug || !updates || typeof updates !== 'object') {
      return NextResponse.json({ error: 'Ungültige Parameter: toolSlug und updates erforderlich.' }, { status: 400 });
    }

    const updated = await updateToolConfiguration(toolSlug, updates, admin.id);
    return NextResponse.json({ success: true, toolSlug, config: updated });
  } catch (err: any) {
    const status = err.statusCode || 500;
    return NextResponse.json({ error: err.message || 'Fehler beim Aktualisieren der Tool-Konfiguration' }, { status });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/server/auth/guards';
import { prisma, isDatabaseConfigured } from '@/server/db/prisma';

export async function GET(req: NextRequest) {
  try {
    await requireAdmin(req);

    if (!isDatabaseConfigured()) {
      return NextResponse.json({ users: [], total: 0 });
    }

    const users = await prisma.user.findMany({
      orderBy: { createdAt: 'desc' },
      take: 100,
      include: {
        subscription: true,
        _count: {
          select: { jobs: true },
        },
      },
    });

    const safeUsers = users.map((u) => ({
      id: u.id,
      email: u.email,
      name: u.name,
      role: u.role,
      plan: u.subscription?.plan || 'free',
      subscriptionStatus: u.subscription?.status || 'active',
      jobsCount: u._count.jobs,
      createdAt: u.createdAt,
      lastLoginAt: u.lastLoginAt,
    }));

    return NextResponse.json({ users: safeUsers, total: safeUsers.length });
  } catch (err: any) {
    const status = err.statusCode || 401;
    return NextResponse.json({ error: err.message || 'Nicht autorisiert' }, { status });
  }
}

export async function PATCH(req: NextRequest) {
  try {
    const admin = await requireAdmin(req);
    const body = await req.json();
    const { userId, role, plan } = body;

    if (!userId) {
      return NextResponse.json({ error: 'userId ist erforderlich.' }, { status: 400 });
    }

    if (!isDatabaseConfigured()) {
      return NextResponse.json({ error: 'Datenbank ist nicht konfiguriert.' }, { status: 503 });
    }

    if (role && ['USER', 'ADMIN'].includes(role)) {
      await prisma.user.update({
        where: { id: userId },
        data: { role },
      });
    }

    if (plan && ['free', 'pro', 'business'].includes(plan)) {
      await prisma.subscription.upsert({
        where: { userId },
        create: {
          userId,
          plan,
          status: 'active',
        },
        update: {
          plan,
        },
      });
    }

    // Audit Log
    await prisma.auditLog.create({
      data: {
        actorUserId: admin.id,
        action: 'USER_UPDATED',
        targetType: 'User',
        targetId: userId,
        metadata: JSON.stringify({ role, plan, timestamp: new Date().toISOString() }),
      },
    }).catch(() => {});

    return NextResponse.json({ success: true, userId });
  } catch (err: any) {
    const status = err.statusCode || 500;
    return NextResponse.json({ error: err.message || 'Fehler beim Aktualisieren des Benutzers' }, { status });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { analyticsService } from '@/server/analytics/analytics.service';
import { AnalyticsEventType } from '@/types/analytics';

const VALID_EVENT_TYPES: Set<AnalyticsEventType> = new Set([
  'tool_view',
  'upload_started',
  'upload_completed',
  'conversion_started',
  'conversion_completed',
  'conversion_failed',
  'download_completed',
  'pro_viewed',
  'pro_clicked',
  'signup_started',
  'signup_completed',
]);

export async function POST(req: NextRequest) {
  try {
    let body: any;
    const contentType = req.headers.get('content-type') || '';

    if (contentType.includes('application/json')) {
      body = await req.json();
    } else {
      // Beacon sends text/plain sometimes
      const text = await req.text();
      body = text ? JSON.parse(text) : {};
    }

    const { eventType, toolSlug, category, fileSizeBytes, outputSizeBytes, durationMs, referrerSlug, planId, interval, triggerReason } = body;

    if (!eventType || !VALID_EVENT_TYPES.has(eventType)) {
      return NextResponse.json({ error: 'Ungültiger oder fehlender Event-Typ.' }, { status: 400 });
    }

    // Strict privacy sanitization: Only pass safe operational metadata
    await analyticsService.track({
      eventType,
      toolSlug: typeof toolSlug === 'string' ? toolSlug.slice(0, 80) : undefined,
      category: typeof category === 'string' ? category.slice(0, 50) : undefined,
      fileSizeBytes: typeof fileSizeBytes === 'number' ? Math.max(0, fileSizeBytes) : undefined,
      outputSizeBytes: typeof outputSizeBytes === 'number' ? Math.max(0, outputSizeBytes) : undefined,
      durationMs: typeof durationMs === 'number' ? Math.max(0, durationMs) : undefined,
      referrerSlug: typeof referrerSlug === 'string' ? referrerSlug.slice(0, 80) : undefined,
      planId: typeof planId === 'string' ? planId.slice(0, 40) : undefined,
      interval: interval === 'monthly' || interval === 'yearly' ? interval : undefined,
      triggerReason: typeof triggerReason === 'string' ? triggerReason.slice(0, 120) : undefined,
    });

    return NextResponse.json({ success: true }, { status: 200 });
  } catch (err) {
    return NextResponse.json({ error: 'Fehler beim Aufzeichnen des Events.' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getSessionTokenFromCookie, destroySession, SESSION_COOKIE_NAME } from '@/server/auth/session';

export async function POST(req: NextRequest) {
  try {
    const token = await getSessionTokenFromCookie();
    if (token) {
      await destroySession(token);
    }

    const response = NextResponse.json({ success: true });

    response.cookies.set({
      name: SESSION_COOKIE_NAME,
      value: '',
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      path: '/',
      maxAge: 0,
    });

    return response;
  } catch (err: unknown) {
    console.error('[Logout API Error]:', err);
    return NextResponse.json({ success: true });
  }
}

import { isProRequest } from '@/server/security/request';
import { NextRequest, NextResponse } from 'next/server';
import { Readable } from 'stream';
import { jobQueue } from '@/server/queue/queue';
import { storageProvider } from '@/server/storage/storage';
import { verifySignedDownloadToken } from '@/server/security/signedUrl';
import { privacyConfig } from '@/config/privacy.config';
import { getInfrastructureConfig } from '@/config/infrastructure.config';
import { rateLimiter, getClientIp } from '@/server/security/rateLimiter';
import { analyticsService } from '@/server/analytics/analytics.service';

interface Params {
  params: Promise<{
    id: string;
  }>;
}

export async function GET(req: NextRequest, { params }: Params) {
  const { id } = await params;

  // Enforce rate limiting per client IP
  const ip = getClientIp(req);
  const isPro = isProRequest(req);
  const rateLimit = rateLimiter.check(ip, 'download', isPro);
  if (!rateLimit.allowed) {
    return NextResponse.json(
      { error: 'Zu viele Download-Anfragen. Bitte warten Sie einen Moment.', code: 'RATE_LIMIT_EXCEEDED' },
      {
        status: 429,
        headers: {
          'Retry-After': String(rateLimit.resetSeconds),
          'X-RateLimit-Limit': String(rateLimit.limit),
          'X-RateLimit-Remaining': '0',
        },
      }
    );
  }

  const token = req.nextUrl.searchParams.get('token');
  const exp = req.nextUrl.searchParams.get('exp');

  const verification = verifySignedDownloadToken(id, token, exp);
  if (!verification.valid) return NextResponse.json({ error: 'Ungueltiger oder abgelaufener Download-Link.' }, { status: 403 });

  const job = await jobQueue.getJob(id);

  if (!job) {
    return NextResponse.json(
      { error: 'Auftrag nicht gefunden oder abgelaufen.' },
      { status: 404 }
    );
  }

  if (job.status !== 'completed' || !job.output) {
    return NextResponse.json(
      { error: `Datei steht noch nicht zum Download bereit (Status: ${job.status}).` },
      { status: 400 }
    );
  }

  if (new Date(job.expiration).getTime() < Date.now()) {
    return NextResponse.json(
      { error: 'Die temporäre Datei ist abgelaufen und wurde aus Datenschutzgründen gelöscht.' },
      { status: 410 }
    );
  }

  try {
    const infraConfig = getInfrastructureConfig();
    const { stream: nodeStream, sizeBytes } = await storageProvider.createReadStream(
      job.output.storagePath,
      infraConfig.storage.streamChunkSizeBytes
    );

    // Track download_completed
    analyticsService.track({
      eventType: 'download_completed',
      toolSlug: job.type,
      outputSizeBytes: sizeBytes,
    }).catch(() => {});

    // Hook auto-cleanup when stream transmission completes or closes
    const autoCleanRequested = req.nextUrl.searchParams.get('autoclean') === 'true';
    if (infraConfig.storage.deleteOnDownload || autoCleanRequested) {
      (nodeStream as any).on('close', async () => {
        try {
          await storageProvider.delete(job.output!.storagePath);
          await jobQueue.updateJob(job.id, {
            status: 'expired',
            error: 'Datei nach erfolgreichem Download automatisch aus dem Speicher entfernt.',
          });
        } catch {
          // Cleanup best-effort
        }
      });
    }

    // Convert Node.js stream to Web ReadableStream for zero-copy transmission
    const webStream = Readable.toWeb(nodeStream as Readable);

    return new Response(webStream as any, {
      status: 200,
      headers: {
        'Content-Type': job.output.mimeType || 'application/octet-stream',
        'Content-Disposition': `attachment; filename="${encodeURIComponent(job.output.fileName)}"`,
        'Content-Length': sizeBytes.toString(),
        'Cache-Control': 'no-store, no-cache, must-revalidate, max-age=0',
        'Pragma': 'no-cache',
        'X-Content-Type-Options': 'nosniff',
        'X-Robots-Tag': 'noindex, nofollow, noarchive',
      },
    });
  } catch (err) {
    console.error('[Download Error]:', err);
    return NextResponse.json(
      { error: 'Die konvertierte Datei konnte nicht vom Speicher geladen werden.' },
      { status: 500 }
    );
  }
}

import { boundedFormData, isProRequest, requestError, RequestError } from '@/server/security/request';
import { NextRequest, NextResponse } from 'next/server';
import { pdfSecurityService, PdfPermissions, RedactionZone } from '@/server/services/adapters/PdfSecurityService';
import { rateLimiter, getClientIp } from '@/server/security/rateLimiter';
import { validateUploadedFile } from '@/server/security/fileValidator';
import { privacyLog } from '@/server/utils/privacyLogger';

export async function POST(req: NextRequest) {
  try {
    const apiKey = req.headers.get('x-api-key');
    const isPro = isProRequest(req);

    // 0. Rate limiting
    const ip = getClientIp(req);
    const rateLimit = rateLimiter.check(ip, 'security', isPro);
    if (!rateLimit.allowed) {
      return NextResponse.json(
        {
          error: 'Zu viele Sicherheitsoperationen. Bitte warten Sie einen Moment.',
          code: 'RATE_LIMIT_EXCEEDED',
        },
        {
          status: 429,
          headers: {
            'Retry-After': String(rateLimit.resetSeconds),
            'X-RateLimit-Limit': String(rateLimit.limit),
            'X-RateLimit-Remaining': '0',
          },
        }
      );
    }

    const formData = await boundedFormData(req, (isPro ? 250 : 50) * 1024 * 1024 + 65536);
    const file = formData.get('file') as File | null;
    const action = (formData.get('action') as string) || 'protect';

    if (!(file instanceof File)) {
      return NextResponse.json(
        { error: 'Keine PDF-Datei übertragen (Feld: file erforderlich).' },
        { status: 400 }
      );
    }

    // Limit free file sizes to 50MB
    const maxMB = isPro ? 250 : 50;
    if (file.size > maxMB * 1024 * 1024) {
      return NextResponse.json(
        { error: `Die Datei überschreitet die maximale Größe von ${maxMB} MB.` },
        { status: 413 }
      );
    }

    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);

    // Deep file validation (ensuring real %PDF- signature, not spoofed executable)
    const validation = validateUploadedFile(buffer, file.name, 'application/pdf');
    if (!validation.valid || validation.detectedFormat !== 'pdf') {
      return NextResponse.json(
        {
          error: validation.error || 'Die hochgeladene Datei ist kein gültiges PDF-Dokument.',
          code: validation.code || 'INVALID_PDF',
        },
        { status: 400 }
      );
    }

    const safeFilename = validation.safeFilename;
    const baseName = safeFilename.replace(/\.[^/.]+$/, '');

    let resultBuffer: Buffer;
    let outputFilename: string;

    switch (action) {
      case 'protect':
      case 'encrypt': {
        const userPassword = (formData.get('userPassword') as string) || (formData.get('password') as string) || '';
        const ownerPassword = (formData.get('ownerPassword') as string) || undefined;
        let perms: PdfPermissions | undefined;

        const rawPerms = formData.get('permissions') as string | null;
        if (rawPerms) {
          try {
            perms = JSON.parse(rawPerms);
          } catch {
            // Ignore parse errors
          }
        }

        if (!userPassword && !ownerPassword) {
          return NextResponse.json(
            { error: 'Bitte geben Sie ein Passwort zum Schutz der Datei an.' },
            { status: 400 }
          );
        }

        resultBuffer = await pdfSecurityService.protectPdf(buffer, userPassword, ownerPassword, perms);
        outputFilename = `coolwave_geschuetzt_${safeFilename}`;
        break;
      }

      case 'unlock':
      case 'decrypt':
      case 'remove_password': {
        const password = (formData.get('password') as string) || (formData.get('userPassword') as string) || undefined;
        resultBuffer = await pdfSecurityService.unlockPdf(buffer, password);
        outputFilename = `coolwave_entsperrt_${safeFilename}`;
        break;
      }

      case 'permissions': {
        const password = (formData.get('password') as string) || undefined;
        const newOwnerPassword = (formData.get('newOwnerPassword') as string) || undefined;
        let perms: PdfPermissions = {};

        const rawPerms = formData.get('permissions') as string | null;
        if (rawPerms) {
          try {
            perms = JSON.parse(rawPerms);
          } catch {
            // Ignore parse errors
          }
        }

        resultBuffer = await pdfSecurityService.changePermissions(buffer, password, perms, newOwnerPassword);
        outputFilename = `coolwave_berechtigungen_${safeFilename}`;
        break;
      }

      case 'redact': {
        let terms: string[] = [];
        const rawTerms = formData.get('terms') as string | null;
        if (rawTerms) {
          try {
            terms = JSON.parse(rawTerms);
          } catch {
            terms = rawTerms.split(',').map((t) => t.trim());
          }
        }

        let zones: RedactionZone[] = [];
        const rawZones = formData.get('zones') as string | null;
        if (rawZones) {
          try {
            zones = JSON.parse(rawZones);
          } catch {
            // Ignore invalid zones
          }
        }

        if (terms.length === 0 && zones.length === 0) {
          return NextResponse.json(
            { error: 'Bitte geben Sie mindestens einen zu schwärzenden Begriff oder Bereich an.' },
            { status: 400 }
          );
        }

        resultBuffer = await pdfSecurityService.trueRedact(buffer, terms, zones);
        outputFilename = `coolwave_geschwaerzt_${safeFilename}`;
        break;
      }

      case 'metadata_remove': {
        resultBuffer = await pdfSecurityService.stripMetadata(buffer);
        outputFilename = `coolwave_bereinigt_${safeFilename}`;
        break;
      }

      case 'sign': {
        const signaturePngBase64 = (formData.get('signature') as string) || undefined;
        const signerName = (formData.get('signerName') as string) || 'CoolWave Benutzer';
        const reason = (formData.get('reason') as string) || 'Dokumentenfreigabe & Integrität';
        const location = (formData.get('location') as string) || 'Deutschland';

        let pageIndex: number | undefined;
        const rawPage = formData.get('pageIndex') as string | null;
        if (rawPage !== null) pageIndex = parseInt(rawPage, 10);

        resultBuffer = await pdfSecurityService.signPdf(buffer, {
          signaturePngBase64,
          signerName,
          reason,
          location,
          pageIndex,
        });
        outputFilename = `coolwave_signiert_${safeFilename}`;
        break;
      }

      default:
        return NextResponse.json(
          { error: `Unbekannte Sicherheitsaktion: ${action}` },
          { status: 400 }
        );
    }

    // Return the processed PDF directly as downloadable binary with security headers
    return new NextResponse(resultBuffer as unknown as BodyInit, {
      status: 200,
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `attachment; filename="${encodeURIComponent(outputFilename)}"`,
        'X-Output-Filename': encodeURIComponent(outputFilename),
        'Cache-Control': 'no-store, no-cache, must-revalidate, max-age=0',
        'Pragma': 'no-cache',
        'X-Content-Type-Options': 'nosniff',
        'X-Robots-Tag': 'noindex, nofollow, noarchive',
      },
    });
  } catch (err: unknown) {
    const errorMsg = (err as Error)?.message || 'Fehler bei der Sicherheitsverarbeitung.';
    privacyLog('error', '[PDF Security Error]', { error: errorMsg });
    return err instanceof RequestError ? requestError(err) : NextResponse.json({ error: 'PDF-Verarbeitung fehlgeschlagen. Bitte pruefen Sie Datei und Passwort.', code: 'INVALID_PDF' }, { status: 422 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getStripe, isStripeConfigured } from '@/server/stripe/client';
import { prisma, isDatabaseConfigured } from '@/server/db/prisma';
import Stripe from 'stripe';

export async function POST(req: NextRequest) {
  try {
    if (!isStripeConfigured()) {
      return NextResponse.json({ received: true, ignored: 'Stripe not configured' });
    }

    const stripe = getStripe();
    if (!stripe) {
      return NextResponse.json({ error: 'Stripe not initialized' }, { status: 500 });
    }

    const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;
    if (!webhookSecret) {
      console.warn('[Stripe Webhook] STRIPE_WEBHOOK_SECRET not configured, skipping verification.');
      return NextResponse.json({ error: 'Webhook secret not set' }, { status: 500 });
    }

    const body = await req.text();
    const signature = req.headers.get('stripe-signature');

    if (!signature) {
      return NextResponse.json({ error: 'Missing stripe-signature header' }, { status: 400 });
    }

    let event: Stripe.Event;
    try {
      event = stripe.webhooks.constructEvent(body, signature, webhookSecret);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : 'Invalid signature';
      console.error('[Stripe Webhook Signature Error]:', msg);
      return NextResponse.json({ error: `Webhook Error: ${msg}` }, { status: 400 });
    }

    if (!isDatabaseConfigured()) {
      console.warn('[Stripe Webhook] Database not configured, cannot persist event:', event.type);
      return NextResponse.json({ received: true });
    }

    // Webhook Idempotency & Replay Defense: Ignore already-processed event IDs
    const existingLog = await prisma.auditLog.findFirst({
      where: {
        action: 'STRIPE_WEBHOOK_PROCESSED',
        targetId: event.id,
      },
    });

    if (existingLog) {
      return NextResponse.json({ received: true, duplicate: true });
    }

    // Process event types
    switch (event.type) {
      case 'checkout.session.completed': {
        const session = event.data.object as Stripe.Checkout.Session;
        const customerId = session.customer as string;
        const subscriptionId = session.subscription as string;
        const userId = session.metadata?.userId;

        if (userId && userId !== 'anonymous') {
          await prisma.subscription.upsert({
            where: { userId },
            create: {
              userId,
              stripeCustomerId: customerId,
              stripeSubscriptionId: subscriptionId,
              plan: 'pro',
              status: 'active',
            },
            update: {
              stripeCustomerId: customerId,
              stripeSubscriptionId: subscriptionId,
              plan: 'pro',
              status: 'active',
            },
          }).catch((err) => console.error('[Webhook] Failed to update subscription on checkout:', err));
        }
        break;
      }

      case 'customer.subscription.updated':
      case 'customer.subscription.created': {
        const sub = event.data.object as Stripe.Subscription;
        const customerId = sub.customer as string;
        const status = sub.status; // 'active', 'past_due', 'canceled', etc.
        const priceId = sub.items.data[0]?.price?.id;
        const plan = status === 'active' || status === 'trialing' ? 'pro' : 'free';
        const currentPeriodEnd = new Date((sub as any).current_period_end * 1000);
        const cancelAtPeriodEnd = sub.cancel_at_period_end;

        await prisma.subscription.updateMany({
          where: { stripeCustomerId: customerId },
          data: {
            stripeSubscriptionId: sub.id,
            stripePriceId: priceId,
            status,
            plan,
            currentPeriodEnd,
            cancelAtPeriodEnd,
          },
        }).catch((err) => console.error('[Webhook] Failed to update subscription on sub update:', err));
        break;
      }

      case 'customer.subscription.deleted': {
        const sub = event.data.object as Stripe.Subscription;
        const customerId = sub.customer as string;

        await prisma.subscription.updateMany({
          where: { stripeCustomerId: customerId },
          data: {
            status: 'canceled',
            plan: 'free',
            cancelAtPeriodEnd: false,
          },
        }).catch((err) => console.error('[Webhook] Failed to cancel subscription:', err));
        break;
      }

      case 'invoice.payment_failed': {
        const invoice = event.data.object as Stripe.Invoice;
        const customerId = invoice.customer as string;

        await prisma.subscription.updateMany({
          where: { stripeCustomerId: customerId },
          data: {
            status: 'past_due',
          },
        }).catch((err) => console.error('[Webhook] Failed to update status on payment failure:', err));
        break;
      }

      case 'invoice.paid': {
        const invoice = event.data.object as Stripe.Invoice;
        const customerId = invoice.customer as string;

        await prisma.subscription.updateMany({
          where: { stripeCustomerId: customerId },
          data: {
            status: 'active',
            plan: 'pro',
          },
        }).catch((err) => console.error('[Webhook] Failed to update status on invoice paid:', err));
        break;
      }

      default:
        // Unhandled event type
        break;
    }

    // Persist processed event ID in audit logs for idempotency
    await prisma.auditLog.create({
      data: {
        action: 'STRIPE_WEBHOOK_PROCESSED',
        targetType: 'StripeEvent',
        targetId: event.id,
        metadata: JSON.stringify({ type: event.type, timestamp: new Date().toISOString() }),
      },
    }).catch(() => {});

    return NextResponse.json({ received: true });
  } catch (err: unknown) {
    console.error('[Stripe Webhook Handler Error]:', err);
    return NextResponse.json({ error: 'Internal webhook error' }, { status: 500 });
  }
}

