'use client';

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import { Shield, Settings, X } from 'lucide-react';

export interface CookieConsentPreferences {
  essential: boolean;
  analytics: boolean;
  marketing: boolean;
  timestamp: string;
}

export function getCookieConsent(): CookieConsentPreferences | null {
  if (typeof window === 'undefined') return null;
  try {
    const raw = localStorage.getItem('coolwave_cookie_consent');
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

export function openCookiePreferencesModal() {
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('coolwave_open_cookie_preferences'));
  }
}

export function CookieBanner() {
  const [showBanner, setShowBanner] = useState(false);
  const [showPreferences, setShowPreferences] = useState(false);
  const [analytics, setAnalytics] = useState(false);
  const [marketing, setMarketing] = useState(false);

  useEffect(() => {
    try {
      const consent = localStorage.getItem('coolwave_cookie_consent');
      if (!consent) {
        queueMicrotask(() => {
          setShowBanner(true);
        });
      } else {
        const parsed = JSON.parse(consent);
        setAnalytics(!!parsed.analytics);
        setMarketing(!!parsed.marketing);
      }
    } catch {
      // In case localStorage is blocked
    }

    const handleOpen = () => {
      try {
        const current = getCookieConsent();
        if (current) {
          setAnalytics(!!current.analytics);
          setMarketing(!!current.marketing);
        }
      } catch {}
      setShowPreferences(true);
    };

    window.addEventListener('coolwave_open_cookie_preferences', handleOpen);
    return () => {
      window.removeEventListener('coolwave_open_cookie_preferences', handleOpen);
    };
  }, []);

  const saveConsent = (allAccepted: boolean, customAnalytics = false, customMarketing = false) => {
    const preferences: CookieConsentPreferences = {
      essential: true,
      analytics: allAccepted || customAnalytics,
      marketing: allAccepted || customMarketing,
      timestamp: new Date().toISOString(),
    };
    try {
      localStorage.setItem('coolwave_cookie_consent', JSON.stringify(preferences));
      window.dispatchEvent(new CustomEvent('coolwave_consent_updated', { detail: preferences }));
    } catch {}
    setShowBanner(false);
    setShowPreferences(false);
  };

  if (!showBanner && !showPreferences) return null;

  return (
    <>
      {/* Cookie Banner Bar */}
      {showBanner && (
        <div 
          role="region"
          aria-label="Cookie-Einwilligung"
          className="fixed bottom-0 inset-x-0 z-50 p-3.5 sm:p-6 bg-slate-900/95 backdrop-blur-md text-white border-t border-slate-800 shadow-2xl animate-fade-in safe-area-bottom"
        >
          <div className="max-w-7xl mx-auto flex flex-col md:flex-row items-start md:items-center justify-between gap-3 sm:gap-4">
            <div className="flex items-start gap-2.5 sm:gap-3 max-w-3xl">
              <div className="p-1.5 sm:p-2 rounded-lg bg-sky-600/20 text-sky-400 shrink-0 border border-sky-500/30 mt-0.5" aria-hidden="true">
                <Shield className="w-4 h-4 sm:w-5 sm:h-5" />
              </div>
              <div className="text-xs sm:text-sm text-slate-300 leading-relaxed">
                <span className="font-semibold text-white block mb-0.5 sm:mb-1 text-xs sm:text-sm">
                  Datenschutz & Privatsphäre bei CoolWave
                </span>
                Wir verwenden technisch notwendige Cookies und mit Ihrer Einwilligung anonyme Analysen zur Produktverbesserung. Dokumente verarbeiten wir lokal im Browser. Details in der{' '}
                <Link href="/de/datenschutz" className="underline text-sky-400 hover:text-sky-300">
                  Datenschutzerklärung
                </Link>{' '}
                und{' '}
                <Link href="/de/cookie-richtlinie" className="underline text-sky-400 hover:text-sky-300">
                  Cookie-Richtlinie
                </Link>.
              </div>
            </div>

            {/* Responsive Actions: stacked layout on mobile for easy thumb tapping */}
            <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2 shrink-0 w-full md:w-auto">
              <button
                onClick={() => saveConsent(true)}
                className="order-1 sm:order-3 min-h-[44px] px-4 py-2.5 rounded-xl bg-sky-600 hover:bg-sky-500 active:bg-sky-700 text-white text-xs font-bold transition-colors shadow-sm touch-manipulation text-center cursor-pointer"
              >
                Alle akzeptieren
              </button>

              <div className="order-2 flex items-center gap-2">
                <button
                  onClick={() => saveConsent(false)}
                  className="flex-1 sm:flex-none min-h-[44px] px-3.5 py-2.5 rounded-xl border border-slate-700 bg-slate-800/80 hover:bg-slate-700 text-slate-300 text-xs font-semibold transition-colors touch-manipulation text-center cursor-pointer"
                >
                  Nur notwendige
                </button>
                <button
                  onClick={() => setShowPreferences(true)}
                  className="flex-1 sm:flex-none min-h-[44px] px-3 py-2.5 rounded-xl border border-slate-700 bg-transparent hover:bg-slate-800 text-slate-400 hover:text-slate-200 text-xs font-semibold transition-colors flex items-center justify-center gap-1.5 touch-manipulation cursor-pointer"
                >
                  <Settings className="w-3.5 h-3.5" aria-hidden="true" />
                  <span>Anpassen</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Preferences Modal */}
      {showPreferences && (
        <div 
          role="dialog"
          aria-modal="true"
          aria-labelledby="cookie-preferences-title"
          className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-slate-900/70 backdrop-blur-xs overflow-y-auto animate-fade-in"
        >
          <div className="w-full max-w-lg bg-white rounded-2xl shadow-2xl border border-slate-200 p-4 sm:p-6 text-slate-900 my-auto max-h-[90vh] flex flex-col">
            <div className="flex items-center justify-between pb-3 sm:pb-4 border-b border-slate-100 shrink-0">
              <h3 id="cookie-preferences-title" className="text-sm sm:text-base font-bold text-slate-900">Cookie-Einstellungen</h3>
              <button
                onClick={() => setShowPreferences(false)}
                className="w-9 h-9 flex items-center justify-center rounded-lg text-slate-400 hover:text-slate-600 active:bg-slate-100 touch-manipulation cursor-pointer"
                aria-label="Einstellungen schließen"
              >
                <X className="w-5 h-5" aria-hidden="true" />
              </button>
            </div>

            <div className="py-4 space-y-3 sm:space-y-4 text-xs sm:text-sm overflow-y-auto flex-1">
              <div className="p-3 sm:p-3.5 rounded-xl bg-slate-50 border border-slate-200 flex items-start justify-between gap-3">
                <div>
                  <div className="font-semibold text-slate-900 text-xs sm:text-sm">Technisch notwendig</div>
                  <p className="text-slate-500 text-[11px] sm:text-xs mt-0.5">
                    Unverzichtbar für die Funktionalität der Werkzeuge und Sicherheitseinstellungen.
                  </p>
                </div>
                <span className="text-[10px] sm:text-xs font-semibold text-sky-700 bg-sky-100 px-2 py-1 rounded shrink-0">
                  Immer aktiv
                </span>
              </div>

              <label className="p-3 sm:p-3.5 rounded-xl bg-white border border-slate-200 flex items-start justify-between gap-3 cursor-pointer hover:bg-slate-50/50 transition">
                <div>
                  <div className="font-semibold text-slate-900 text-xs sm:text-sm">Anonyme Analyse</div>
                  <p className="text-slate-500 text-[11px] sm:text-xs mt-0.5">
                    Hilft uns zu verstehen, welche Werkzeuge und Funktionen am häufigsten genutzt werden.
                  </p>
                </div>
                <input
                  type="checkbox"
                  checked={analytics}
                  onChange={(e) => setAnalytics(e.target.checked)}
                  className="w-5 h-5 text-sky-600 rounded border-slate-300 focus:ring-sky-500 mt-0.5 cursor-pointer touch-manipulation shrink-0"
                />
              </label>

              <label className="p-3 sm:p-3.5 rounded-xl bg-white border border-slate-200 flex items-start justify-between gap-3 cursor-pointer hover:bg-slate-50/50 transition">
                <div>
                  <div className="font-semibold text-slate-900 text-xs sm:text-sm">Personalisierte Werbung</div>
                  <p className="text-slate-500 text-[11px] sm:text-xs mt-0.5">
                    Ermöglicht das Einblenden relevanter Partnerangebote zur Finanzierung der kostenlosen Werkzeuge.
                  </p>
                </div>
                <input
                  type="checkbox"
                  checked={marketing}
                  onChange={(e) => setMarketing(e.target.checked)}
                  className="w-5 h-5 text-sky-600 rounded border-slate-300 focus:ring-sky-500 mt-0.5 cursor-pointer touch-manipulation shrink-0"
                />
              </label>
            </div>

            <div className="flex justify-end gap-2.5 pt-3 sm:pt-4 border-t border-slate-100 shrink-0">
              <button
                onClick={() => saveConsent(false, analytics, marketing)}
                className="w-full sm:w-auto min-h-[44px] px-5 py-2.5 rounded-xl bg-sky-600 hover:bg-sky-700 text-white text-xs font-semibold transition-colors touch-manipulation text-center"
              >
                Auswahl speichern
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import { 
  Search, 
  Menu, 
  X, 
  Sparkles, 
  Globe, 
  History, 
  Zap, 
  Crown,
  User,
  FileText,
  Image as ImageIcon,
  FileSpreadsheet,
  Wrench,
  ShieldCheck,
  ScanText,
  ChevronRight,
} from 'lucide-react';
import { SearchModal } from './SearchModal';
import { UpgradeModal } from '@/components/monetization/UpgradeModal';
import { ConversionHistoryDrawer } from '@/components/monetization/ConversionHistoryDrawer';
import { getClientSubscription, SubscriptionTier } from '@/lib/monetization/subscription';

export function Header() {
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isUpgradeOpen, setIsUpgradeOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [tier, setTier] = useState<SubscriptionTier>('free');
  const [currentUser, setCurrentUser] = useState<any>(null);

  useEffect(() => {
    fetch('/api/v1/auth/me')
      .then((r) => (r.ok ? r.json() : null))
      .then((d) => {
        if (d?.user) setCurrentUser(d.user);
      })
      .catch(() => {});
  }, []);

  useEffect(() => {
    const updateSubscription = () => {
      const sub = getClientSubscription();
      setTier(sub.tier);
    };

    updateSubscription();
    window.addEventListener('coolwave_subscription_changed', updateSubscription);
    return () => window.removeEventListener('coolwave_subscription_changed', updateSubscription);
  }, []);

  // Global shortcuts (Ctrl+K for search, Escape for mobile menu)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        setIsSearchOpen((prev) => !prev);
      } else if (e.key === 'Escape' && isMobileMenuOpen) {
        setIsMobileMenuOpen(false);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isMobileMenuOpen]);

  // Lock body scroll when mobile menu is open
  useEffect(() => {
    if (isMobileMenuOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => { document.body.style.overflow = ''; };
  }, [isMobileMenuOpen]);

  const isPro = tier === 'pro' || tier === 'business';

  const closeMobileMenu = () => setIsMobileMenuOpen(false);

  return (
    <>
      <header className="sticky top-0 z-40 w-full bg-white/95 backdrop-blur-md border-b border-slate-200 safe-area-top">
        <div className="max-w-7xl mx-auto px-3 sm:px-6 lg:px-8 h-14 sm:h-16 flex items-center justify-between gap-2 sm:gap-4">
          {/* Brand Logo */}
          <Link href="/de" className="flex items-center gap-2 shrink-0 group" onClick={closeMobileMenu}>
            <div className="w-8 h-8 sm:w-9 sm:h-9 rounded-lg bg-sky-600 text-white flex items-center justify-center font-black text-lg shadow-sm shadow-sky-600/20 group-hover:bg-sky-700 transition-colors">
              <svg className="w-4 h-4 sm:w-5 sm:h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 10V3L4 14h7v7l9-11h-7z" />
              </svg>
            </div>
            <div className="flex flex-col">
              <span className="text-lg sm:text-xl font-bold tracking-tight text-slate-900 leading-tight">
                Cool<span className="text-sky-600">Wave</span>
              </span>
              <span className="hidden sm:block text-[10px] font-medium text-slate-400 -mt-1 tracking-wider uppercase">
                Datei- &amp; PDF-Tools
              </span>
            </div>
          </Link>

          {/* Desktop Navigation */}
          <nav aria-label="Hauptnavigation" className="hidden md:flex items-center gap-0.5 lg:gap-1">
            <Link
              href="/de/kategorie/pdf"
              className="flex items-center gap-1.5 px-3 py-2 rounded-md text-sm font-medium text-slate-700 hover:text-sky-700 hover:bg-slate-50 transition-colors"
            >
              <FileText className="w-3.5 h-3.5 text-rose-500" />
              PDF-Tools
            </Link>
            <Link
              href="/de/kategorie/images"
              className="flex items-center gap-1.5 px-3 py-2 rounded-md text-sm font-medium text-slate-700 hover:text-sky-700 hover:bg-slate-50 transition-colors"
            >
              <ImageIcon className="w-3.5 h-3.5 text-purple-500" />
              Bild-Tools
            </Link>
            <Link
              href="/de/kategorie/documents"
              className="flex items-center gap-1.5 px-3 py-2 rounded-md text-sm font-medium text-slate-700 hover:text-sky-700 hover:bg-slate-50 transition-colors"
            >
              <FileSpreadsheet className="w-3.5 h-3.5 text-blue-500" />
              Dokumente
            </Link>
            <Link
              href="/de/kategorie/utilities"
              className="flex items-center gap-1.5 px-3 py-2 rounded-md text-sm font-medium text-slate-700 hover:text-sky-700 hover:bg-slate-50 transition-colors"
            >
              <Wrench className="w-3.5 h-3.5 text-slate-500" />
              Werkzeuge
            </Link>
            <Link
              href="/de/preise"
              className="flex items-center gap-1.5 px-3 py-2 rounded-md text-sm font-semibold text-slate-700 hover:text-sky-700 hover:bg-slate-50 transition-colors"
            >
              <Sparkles className="w-4 h-4 text-amber-500" />
              <span>Preise &amp; Tarife</span>
            </Link>
          </nav>

          {/* Right Actions: Search, History, User Tier, Upgrade */}
          <div className="flex items-center gap-1.5 sm:gap-3">
            {/* Search Trigger */}
            <button
              onClick={() => setIsSearchOpen(true)}
              className="flex items-center gap-2 px-2.5 sm:px-3 py-1.5 rounded-lg border border-slate-200 bg-slate-50 text-slate-500 hover:text-slate-800 hover:border-slate-300 hover:bg-white text-xs sm:text-sm font-normal transition-all touch-target-44 cursor-pointer"
              aria-label="Werkzeuge durchsuchen (Strg+K)"
              aria-haspopup="dialog"
            >
              <Search className="w-4 h-4 text-slate-400" />
              <span className="hidden sm:inline">Werkzeuge suchen...</span>
              <kbd className="hidden lg:inline-block px-1.5 py-0.5 text-[10px] font-mono text-slate-400 bg-white border border-slate-200 rounded">
                Strg+K
              </kbd>
            </button>

            {/* Conversion History Button */}
            <button
              onClick={() => setIsHistoryOpen(true)}
              type="button"
              className="p-2 rounded-lg border border-slate-200 bg-slate-50 text-slate-600 hover:text-slate-900 hover:bg-white transition cursor-pointer touch-target-44"
              aria-label="Konvertierungsverlauf anzeigen"
              aria-haspopup="dialog"
              title="Konvertierungsverlauf anzeigen"
            >
              <History className="w-4 h-4" />
            </button>

            {/* User Tier Badge — Desktop only */}
            <button
              onClick={() => setIsUpgradeOpen(true)}
              type="button"
              aria-label={isPro ? "Pro-Abonnement aktiv – Details anzeigen" : "Kostenlose Version – Zu Pro wechseln"}
              aria-haspopup="dialog"
              className={`hidden sm:inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold transition border cursor-pointer ${
                isPro
                  ? 'bg-amber-500/10 text-amber-700 border-amber-300/50 hover:bg-amber-500/20'
                  : 'bg-slate-100 text-slate-700 border-slate-200 hover:bg-slate-200'
              }`}
            >
              {isPro ? (
                <>
                  <Crown className="w-3.5 h-3.5 text-amber-600 fill-amber-500" />
                  <span>Pro aktiv</span>
                </>
              ) : (
                <>
                  <Zap className="w-3.5 h-3.5 text-slate-500" />
                  <span>Kostenlos</span>
                </>
              )}
            </button>

            {/* User Account / Login Button */}
            {currentUser ? (
              <Link
                href="/de/konto"
                className="inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg border border-slate-200 bg-slate-50 hover:bg-slate-100 text-slate-700 text-xs font-semibold transition"
                title={currentUser.email}
              >
                <User className="w-3.5 h-3.5 text-sky-600" />
                <span className="hidden sm:inline max-w-[80px] truncate">{currentUser.name || 'Konto'}</span>
                {currentUser.role === 'ADMIN' && (
                  <span className="px-1 py-0.5 bg-purple-100 text-purple-800 text-[9px] font-bold rounded">
                    Admin
                  </span>
                )}
              </Link>
            ) : (
              <Link
                href="/de/login"
                className="hidden sm:inline-flex items-center gap-1 px-3 py-1.5 rounded-lg border border-slate-200 bg-white hover:bg-slate-50 text-slate-700 text-xs font-semibold transition"
              >
                <span>Anmelden</span>
              </Link>
            )}

            {/* Pro Upgrade CTA — Desktop only */}
            {!isPro && (
              <button
                onClick={() => setIsUpgradeOpen(true)}
                type="button"
                aria-label="Zu CoolWave Pro wechseln"
