export type DocConvertMode = 
  | 'pdf-to-word' 
  | 'word-to-pdf' 
  | 'pdf-to-excel' 
  | 'excel-to-pdf' 
  | 'pdf-to-ppt' 
  | 'ppt-to-pdf'
  | 'doc-to-pdf'
  | 'odt-to-pdf'
  | 'rtf-to-pdf'
  | 'txt-to-pdf'
  | 'html-to-pdf'
  | 'doc-to-docx'
  | 'docx-to-doc'
  | 'odt-to-docx'
  | 'docx-to-odt'
  | 'rtf-to-docx'
  | 'txt-to-docx'
  | 'xls-to-xlsx'
  | 'xlsx-to-xls'
  | 'csv-to-xlsx'
  | 'xlsx-to-csv'
  | 'csv-to-pdf'
  | 'ppt-to-pptx'
  | 'pptx-to-ppt'
  | 'odp-to-pptx'
  | 'epub-to-pdf'
  | 'epub-to-txt';

interface DocConvertEngineProps {
  mode: DocConvertMode;
}

export function DocConvertEngine({ mode }: DocConvertEngineProps) {
  const [singleFile, setSingleFile] = useState<File | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [resultBlob, setResultBlob] = useState<Blob | null>(null);
  const [outputFilename, setOutputFilename] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Batch states
  const [batchItems, setBatchItems] = useState<BatchItem[]>([]);
  const [isBatchMode, setIsBatchMode] = useState(false);
  const [isZipping, setIsZipping] = useState(false);
  const abortControllerRef = useRef<AbortController | null>(null);

  const isPro = typeof window !== 'undefined' && localStorage.getItem('coolwave_pro_active') === 'true';
  const limits = getBatchLimits(isPro);

  const getAcceptedExtensions = (): string[] => {
    switch (mode) {
      case 'pdf-to-word':
      case 'pdf-to-excel':
      case 'pdf-to-ppt':
        return ['.pdf'];
      case 'word-to-pdf':
      case 'docx-to-doc':
      case 'docx-to-odt':
        return ['.docx'];
      case 'doc-to-pdf':
      case 'doc-to-docx':
        return ['.doc'];
      case 'odt-to-pdf':
      case 'odt-to-docx':
        return ['.odt'];
      case 'rtf-to-pdf':
      case 'rtf-to-docx':
        return ['.rtf'];
      case 'txt-to-pdf':
      case 'txt-to-docx':
        return ['.txt'];
      case 'html-to-pdf':
        return ['.html', '.htm'];
      case 'excel-to-pdf':
      case 'xlsx-to-xls':
      case 'xlsx-to-csv':
        return ['.xlsx'];
      case 'xls-to-xlsx':
        return ['.xls'];
      case 'csv-to-xlsx':
      case 'csv-to-pdf':
        return ['.csv'];
      case 'ppt-to-pdf':
      case 'pptx-to-ppt':
        return ['.pptx'];
      case 'ppt-to-pptx':
        return ['.ppt'];
      case 'odp-to-pptx':
        return ['.odp'];
      case 'epub-to-pdf':
      case 'epub-to-txt':
        return ['.epub'];
      default:
        return ['.pdf', '.docx', '.xlsx', '.pptx', '.txt'];
    }
  };

  const getTargetExtension = (): string => {
    switch (mode) {
      case 'pdf-to-word':
      case 'doc-to-docx':
      case 'odt-to-docx':
      case 'rtf-to-docx':
      case 'txt-to-docx':
        return 'docx';
      case 'docx-to-doc':
        return 'doc';
      case 'docx-to-odt':
        return 'odt';
      case 'pdf-to-excel':
      case 'xls-to-xlsx':
      case 'csv-to-xlsx':
        return 'xlsx';
      case 'xlsx-to-xls':
        return 'xls';
      case 'xlsx-to-csv':
        return 'csv';
      case 'pdf-to-ppt':
      case 'ppt-to-pptx':
      case 'odp-to-pptx':
        return 'pptx';
      case 'pptx-to-ppt':
        return 'ppt';
      case 'epub-to-txt':
        return 'txt';
      default:
        return 'pdf';
    }
  };

  const getJobType = (): string => {
    switch (mode) {
      case 'pdf-to-word': return 'office_pdf_to_docx';
      case 'word-to-pdf': return 'office_docx_to_pdf';
      case 'pdf-to-excel': return 'office_pdf_to_xlsx';
      case 'excel-to-pdf': return 'office_xlsx_to_pdf';
      case 'pdf-to-ppt': return 'office_pdf_to_pptx';
      case 'ppt-to-pdf': return 'office_pptx_to_pdf';
      case 'doc-to-pdf': return 'office_doc_to_pdf';
      case 'odt-to-pdf': return 'office_odt_to_pdf';
      case 'rtf-to-pdf': return 'office_rtf_to_pdf';
      case 'txt-to-pdf': return 'office_txt_to_pdf';
      case 'html-to-pdf': return 'office_html_to_pdf';
      case 'doc-to-docx': return 'office_doc_to_docx';
      case 'docx-to-doc': return 'office_docx_to_doc';
      case 'odt-to-docx': return 'office_odt_to_docx';
      case 'docx-to-odt': return 'office_docx_to_odt';
      case 'rtf-to-docx': return 'office_rtf_to_docx';
      case 'txt-to-docx': return 'office_txt_to_docx';
      case 'xls-to-xlsx': return 'office_xls_to_xlsx';
      case 'xlsx-to-xls': return 'office_xlsx_to_xls';
      case 'csv-to-xlsx': return 'office_csv_to_xlsx';
      case 'xlsx-to-csv': return 'office_xlsx_to_csv';
      case 'csv-to-pdf': return 'office_csv_to_pdf';
      case 'ppt-to-pptx': return 'office_ppt_to_pptx';
      case 'pptx-to-ppt': return 'office_pptx_to_ppt';
      case 'odp-to-pptx': return 'office_odp_to_pptx';
      case 'epub-to-pdf': return 'office_epub_to_pdf';
      case 'epub-to-txt': return 'office_epub_to_txt';
      default: return 'office_convert';
    }
  };

  const getModeLabel = (): string => {
    switch (mode) {
      case 'pdf-to-word': return 'In Word umwandeln (DOCX)';
      case 'word-to-pdf': return 'In PDF umwandeln';
      case 'pdf-to-excel': return 'In Excel umwandeln (XLSX)';
      case 'excel-to-pdf': return 'In PDF umwandeln';
      case 'pdf-to-ppt': return 'In PowerPoint umwandeln (PPTX)';
      case 'ppt-to-pdf': return 'In PDF umwandeln';
      case 'doc-to-pdf': return 'Klassisches DOC in PDF umwandeln';
      case 'odt-to-pdf': return 'OpenDocument in PDF umwandeln';
      case 'rtf-to-pdf': return 'Rich-Text in PDF umwandeln';
      case 'txt-to-pdf': return 'Textdatei in PDF layouten';
      case 'html-to-pdf': return 'HTML-Code in PDF rendern';
      case 'doc-to-docx': return 'Altes DOC in modernes DOCX umwandeln';
      case 'docx-to-doc': return 'DOCX in abwärtskompatibles DOC umwandeln';
      case 'odt-to-docx': return 'OpenDocument (ODT) in Word (DOCX) umwandeln';
      case 'docx-to-odt': return 'Word (DOCX) in OpenDocument (ODT) umwandeln';
      case 'rtf-to-docx': return 'Rich Text (RTF) in Word (DOCX) umwandeln';
      case 'txt-to-docx': return 'Textdatei (TXT) in Word (DOCX) formatieren';
      case 'xls-to-xlsx': return 'Altes XLS in modernes XLSX umwandeln';
      case 'xlsx-to-xls': return 'XLSX in abwärtskompatibles XLS umwandeln';
      case 'csv-to-xlsx': return 'CSV-Tabelle in Excel (XLSX) umwandeln';
      case 'xlsx-to-csv': return 'Excel-Tabelle in CSV exportieren';
      case 'csv-to-pdf': return 'CSV-Tabelle in formatiertes PDF umwandeln';
      case 'ppt-to-pptx': return 'Altes PPT in modernes PPTX umwandeln';
      case 'pptx-to-ppt': return 'PowerPoint (PPTX) als PPT speichern';
      case 'odp-to-pptx': return 'OpenDocument (ODP) in PowerPoint (PPTX) umwandeln';
      case 'epub-to-pdf': return 'EPUB eBook in druckbares PDF umwandeln';
      case 'epub-to-txt': return 'EPUB eBook in reinen Text extrahieren';
      default: return 'Dokument umwandeln';
    }
  };

  const getModeIcon = () => {
    if (mode.includes('excel') || mode.includes('csv') || mode.includes('xls')) return <FileSpreadsheet className="w-5 h-5" />;
    if (mode.includes('ppt') || mode.includes('odp')) return <Presentation className="w-5 h-5" />;
    if (mode.includes('epub')) return <BookOpen className="w-5 h-5" />;
    if (mode.includes('html') || mode.includes('txt')) return <FileCode className="w-5 h-5" />;
    return <FileText className="w-5 h-5" />;
  };

  const handleFilesSelected = (files: File[]) => {
    if (files.length === 0) return;

    if (files.length === 1 && !isBatchMode && batchItems.length === 0) {
      setSingleFile(files[0]);
      setIsBatchMode(false);
      setError(null);
      setResultBlob(null);
      trackEvent('upload_completed', { mode, size: files[0].size });
    } else {
      const validation = validateBatchFiles(files, isPro);
      if (!validation.valid) {
        alert(validation.error);
        return;
      }

      setIsBatchMode(true);
      setSingleFile(null);
      const newItems: BatchItem[] = files.map((f, idx) => ({
        id: `doc_batch_${Date.now()}_${idx}_${Math.random().toString(36).substring(7)}`,
        file: f,
        status: 'queued',
        progress: 0,
      }));
      setBatchItems(newItems);
      trackEvent('batch_upload_completed', { mode, count: files.length });
    }
  };

  /**
   * Helper to execute a single document conversion via /api/v1/jobs
   */
  const convertSingleDoc = async (
    file: File,
    onProgress?: (pct: number, statusText?: string) => void,
    signal?: AbortSignal
  ): Promise<{ blob: Blob; fileName: string; size: number }> => {
    onProgress?.(15, 'Dokument wird an Server übertragen...');

    const formData = new FormData();
    formData.append('file', file);
    formData.append('type', getJobType());
    formData.append('targetFormat', getTargetExtension());

    const res = await fetch('/api/v1/jobs', {
      method: 'POST',
      body: formData,
      signal,
    });

    if (!res.ok) {
      const errorData = await res.json().catch(() => ({}));
      throw new Error(errorData.error || `Server-Fehler: HTTP ${res.status}`);
    }

    const jobData = await res.json();
    const jobId = jobData.jobId;

    onProgress?.(35, 'In Warteschlange...');

    let attempts = 0;
    const maxAttempts = 60;
    let completedJob = null;

    while (attempts < maxAttempts) {
      attempts++;
      await new Promise((r) => setTimeout(r, 600));

      if (signal?.aborted) {
        throw new Error('Konvertierung abgebrochen.');
      }

      const pollRes = await fetch(`/api/v1/jobs/${jobId}`, { signal });
      if (!pollRes.ok) continue;

      const pollData = await pollRes.json();
      const currentJob = pollData;

      if (currentJob.status === 'processing') {
        const curProgress = Math.max(35, Math.min(currentJob.progress || 50, 85));
        onProgress?.(curProgress, `Wird transformiert (${curProgress}%)...`);
      } else if (currentJob.status === 'completed') {
        completedJob = currentJob;
        break;
      } else if (currentJob.status === 'failed') {
        throw new Error(currentJob.error || 'Konvertierung fehlgeschlagen.');
      }
    }

    if (!completedJob) {
      throw new Error('Zeitüberschreitung bei der Verarbeitung des Dokuments.');
    }

    onProgress?.(90, 'Ergebnis wird empfangen...');
    const downloadRes = await fetch(completedJob.output.downloadUrl, { signal });
    if (!downloadRes.ok) {
      throw new Error('Download der Datei fehlgeschlagen.');
    }

    const blob = await downloadRes.blob();
    const baseName = file.name.substring(0, file.name.lastIndexOf('.')) || file.name;
    const outName = `coolwave_${baseName}.${getTargetExtension()}`;

    onProgress?.(100, 'Fertig');
    return { blob, fileName: outName, size: blob.size };
  };

  // Single file execute
  const executeSingleConversion = async () => {
    if (!singleFile) return;
    setError(null);
    setIsProcessing(true);
    setProgress(15);
    setStatusText('Dokument wird zum sicheren Konvertierungs-Worker übertragen...');
    trackEvent('conversion_started', { mode });

    abortControllerRef.current = new AbortController();

    try {
      const result = await convertSingleDoc(
        singleFile,
        (p, msg) => {
          setProgress(p);
          if (msg) setStatusText(msg);
        },
        abortControllerRef.current.signal
      );

      setResultBlob(result.blob);
      setOutputFilename(result.fileName);
      setProgress(100);
      setIsProcessing(false);
      trackEvent('conversion_completed', { mode, size: result.size });
    } catch (err: any) {
      console.error(err);
      setIsProcessing(false);
      setError(err.message || 'Fehler bei der Konvertierung.');
      trackEvent('conversion_failed', { mode, error: err.message });
    }
  };

  // Batch execute
  const startBatch = async () => {
    if (batchItems.length === 0) return;
    setIsProcessing(true);
    abortControllerRef.current = new AbortController();

    const tasks = batchItems.map((item) => ({
      id: item.id,
      run: async (signal?: AbortSignal) => {
        if (signal?.aborted) throw new Error('Abgebrochen');
        return await convertSingleDoc(
          item.file,
          (pct, statusText) => {
            setBatchItems((prev) =>
              prev.map((i) => (i.id === item.id ? { ...i, progress: pct, statusText } : i))
            );
          },
          signal
        );
      },
    }));

    await runConcurrentBatch(tasks, {
      concurrency: limits.clientConcurrency,
      signal: abortControllerRef.current.signal,
      onItemStart: (id) => {
        setBatchItems((prev) =>
          prev.map((i) => (i.id === id ? { ...i, status: 'processing', progress: 10 } : i))
        );
      },
      onItemComplete: (id, result) => {
        setBatchItems((prev) =>
          prev.map((i) =>
            i.id === id
              ? {
                  ...i,
                  status: 'completed',
                  progress: 100,
                  outputBlob: result.blob,
                  outputFileName: result.fileName,
                  outputSize: result.size,
                }
              : i
          )
        );
      },
      onItemError: (id, err) => {
        setBatchItems((prev) =>
          prev.map((i) =>
            i.id === id ? { ...i, status: 'failed', error: err.message, progress: 0 } : i
          )
        );
      },
    });

    setIsProcessing(false);
  };

  const cancelBatch = () => {
    abortControllerRef.current?.abort();
    setIsProcessing(false);
    setBatchItems((prev) =>
      prev.map((i) => (i.status === 'processing' || i.status === 'queued' ? { ...i, status: 'cancelled' } : i))
    );
  };

  const clearQueue = () => {
    setBatchItems([]);
    setIsBatchMode(false);
  };

  const removeItem = (id: string) => {
    setBatchItems((prev) => prev.filter((i) => i.id !== id));
  };

  const downloadItem = (item: BatchItem) => {
    if (item.outputBlob && item.outputFileName) {
      downloadBlob(item.outputBlob, item.outputFileName);
    }
  };

  const downloadAllZip = async () => {
    const completedItems = batchItems.filter((i) => i.status === 'completed' && i.outputBlob);
    if (completedItems.length === 0) return;

    setIsZipping(true);
    try {
      const zip = new JSZip();
      completedItems.forEach((item) => {
        if (item.outputBlob && item.outputFileName) {
          zip.file(item.outputFileName, item.outputBlob);
        }
      });

      const zipBlob = await zip.generateAsync({ type: 'blob' });
      downloadBlob(zipBlob, `coolwave_dokumente_stapel_${Date.now()}.zip`);
    } catch (err) {
      console.error('[Zip Error]:', err);
      alert('Fehler beim Erstellen des ZIP-Archivs.');
    } finally {
      setIsZipping(false);
    }
  };

  const handleResetSingle = () => {
    setSingleFile(null);
    setResultBlob(null);
    setError(null);
    setIsProcessing(false);
    setProgress(0);
  };

  if (resultBlob && singleFile) {
    return (
      <DownloadBox
        filename={outputFilename}
        originalSizeBytes={singleFile.size}
        resultSizeBytes={resultBlob.size}
        onDownload={() => downloadBlob(resultBlob, outputFilename)}
        onReset={handleResetSingle}
        downloadLabel="Konvertiertes Dokument herunterladen"
      />
    );
  }

  if (isProcessing && !isBatchMode) {
    return (
      <ProcessingStatus
        progress={progress}
        statusText={statusText}
        onCancel={() => {
          abortControllerRef.current?.abort();
          setIsProcessing(false);
        }}
      />
    );
  }

  return (
    <div className="w-full space-y-6">
      {mode === 'pptx-to-ppt' && (
        <div className="p-4 rounded-xl bg-amber-50 border border-amber-200 text-amber-800 flex items-start gap-3">
          <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
          <div className="text-sm leading-relaxed">
            <span className="font-semibold">Hinweis zum veralteten PPT-Format (Office 97–2003):</span>
            <p className="mt-1">
              Das binäre .ppt-Format ist veraltet und wird auf modernen Betriebssystemen und Mobilgeräten häufig blockiert. Für maximale Kompatibilität empfehlen wir die Umwandlung in PDF:{' '}
              <a href="/de/powerpoint-in-pdf-umwandeln" className="font-medium underline hover:text-amber-950">
                PowerPoint in PDF umwandeln →
              </a>
            </p>
          </div>
        </div>
      )}

      {error && (
        <div className="p-4 rounded-xl bg-red-50 border border-red-200 text-red-700 flex items-center gap-3">
          <AlertCircle className="w-5 h-5 shrink-0" />
          <p className="text-sm font-medium">{error}</p>
        </div>
      )}

      {isBatchMode && batchItems.length > 0 ? (
        <BatchProcessingQueue
          items={batchItems}
          isProcessing={isProcessing}
          onStartBatch={startBatch}
          onCancelBatch={cancelBatch}
          onClearQueue={clearQueue}
          onRemoveItem={removeItem}
          onDownloadItem={downloadItem}
          onDownloadAllZip={downloadAllZip}
          isZipping={isZipping}
          toolTitle={`Dokumente umwandeln (Stapel · ${getModeLabel()})`}
        />
      ) : !singleFile ? (
        <FileUploader
          acceptedExtensions={getAcceptedExtensions()}
          maxFileSizeMB={limits.maxFileSizeMB}
          allowMultiple={true}
          onFilesSelected={handleFilesSelected}
          title="Dokumente hier ablegen (Einzel- oder Stapelverarbeitung)"
          subtitle={`Unterstützt: ${getAcceptedExtensions().join(', ').toUpperCase()} • Bis zu ${limits.maxBatchFiles} Dateien gleichzeitig (${isPro ? 'Pro' : 'Kostenlos'})`}
        />
      ) : (
        /* Single File View (Preserved) */
        <div className="bg-white rounded-2xl border border-slate-200 p-6 sm:p-8 shadow-sm">
          <div className="flex items-center gap-3 pb-6 border-b border-slate-100">
            <div className="p-3 rounded-xl bg-sky-50 text-sky-700 border border-sky-100">
              {getModeIcon()}
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900">{singleFile.name}</h3>
              <p className="text-xs text-slate-500 mt-0.5">
                Dateigröße: <span className="font-semibold text-slate-700">{formatBytes(singleFile.size)}</span> • Zielformat:{' '}
                <span className="font-bold text-sky-700 uppercase">.{getTargetExtension()}</span>
              </p>
            </div>
          </div>

          <div className="pt-6 flex flex-col sm:flex-row items-center justify-between gap-4">
            <button
              onClick={handleResetSingle}
              className="text-xs text-slate-500 hover:text-slate-800 font-medium"
            >
              Anderes Dokument wählen
            </button>

            <button
              onClick={executeSingleConversion}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm sm:text-base shadow-sm transition-colors"
            >
              <RefreshCw className="w-4 h-4" />
              <span>{getModeLabel()}</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { Star, Download } from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { formatBytes } from '@/lib/utils';

const FAVICON_SIZES = [16, 32, 48, 64, 96, 128, 180, 192, 256, 512];

interface SizedBlob {
  size: number;
  blob: Blob;
  filename: string;
}

export function FaviconEngine() {
  const [file, setFile] = useState<File | null>(null);
  const [imgEl, setImgEl] = useState<HTMLImageElement | null>(null);
  const [selectedSizes, setSelectedSizes] = useState<number[]>([16, 32, 48, 180, 192]);
  const [outputFormat, setOutputFormat] = useState<'png' | 'ico'>('png');
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [results, setResults] = useState<SizedBlob[]>([]);

  const handleFileSelected = (files: File[]) => {
    if (files.length === 0) return;
    const f = files[0]; setFile(f);
    const url = URL.createObjectURL(f);
    const img = new Image(); img.src = url;
    img.onload = () => setImgEl(img);
  };

  const toggleSize = (s: number) => {
    setSelectedSizes((prev) => prev.includes(s) ? prev.filter((x) => x !== s) : [...prev, s].sort((a, b) => a - b));
  };

  const renderAtSize = (img: HTMLImageElement, px: number): Promise<Blob> => {
    return new Promise((resolve, reject) => {
      const canvas = document.createElement('canvas');
      canvas.width = px; canvas.height = px;
      const ctx = canvas.getContext('2d')!;
      ctx.clearRect(0, 0, px, px);
      // Square crop from center
      const minSide = Math.min(img.naturalWidth, img.naturalHeight);
      const sx = (img.naturalWidth - minSide) / 2;
      const sy = (img.naturalHeight - minSide) / 2;
      ctx.drawImage(img, sx, sy, minSide, minSide, 0, 0, px, px);
      canvas.toBlob((blob) => blob ? resolve(blob) : reject(new Error('Failed')), 'image/png', 1.0);
    });
  };

  const executeProcess = async () => {
    if (!imgEl || !file || selectedSizes.length === 0) return;
    setIsProcessing(true); setResults([]);
    const sizedBlobs: SizedBlob[] = [];
    for (let i = 0; i < selectedSizes.length; i++) {
      const px = selectedSizes[i];
      setProgress(Math.round((i / selectedSizes.length) * 90));
      setStatusText('Erstelle ' + px + 'x' + px + 'px Favicon...');
      try {
        const blob = await renderAtSize(imgEl, px);
        sizedBlobs.push({ size: px, blob, filename: 'favicon_' + px + 'x' + px + '.png' });
      } catch { console.error('Failed to render size', px); }
    }
    setProgress(100);
    setResults(sizedBlobs);
    setIsProcessing(false);
  };

  const downloadAll = async () => {
    if (results.length === 0) return;
    const { default: JSZip } = await import('jszip');
    const zip = new JSZip();
    results.forEach((r) => zip.file(r.filename, r.blob));
    // Add manifest snippet
    const manifest = {
      icons: results.map((r) => ({ src: '/' + r.filename, sizes: r.size + 'x' + r.size, type: 'image/png' }))
    };
    zip.file('manifest_icons.json', JSON.stringify(manifest, null, 2));
    zip.file('README.txt', 'Favicon-Paket erstellt mit CoolWave\n\nDateien:\n' + results.map((r) => r.filename).join('\n') + '\n\nFuer Ihre HTML-Datei:\n<link rel="icon" type="image/png" sizes="32x32" href="/favicon_32x32.png">\n<link rel="apple-touch-icon" href="/favicon_180x180.png">');
    const content = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(content);
    const a = document.createElement('a'); a.href = url; a.download = 'coolwave_favicons.zip'; a.click();
  };

  const downloadSingle = (r: SizedBlob) => {
    const url = URL.createObjectURL(r.blob);
    const a = document.createElement('a'); a.href = url; a.download = r.filename; a.click();
  };

  const handleReset = () => { setFile(null); setImgEl(null); setResults([]); setIsProcessing(false); };

  if (isProcessing) return <ProcessingStatus progress={progress} statusText={statusText} />;

  if (results.length > 0 && file) {
    return (
      <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm space-y-6">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-sky-100 rounded-xl flex items-center justify-center">
            <Star className="w-5 h-5 text-sky-600" />
          </div>
          <div>
            <h3 className="font-bold text-slate-900">Favicons erfolgreich erstellt!</h3>
            <p className="text-xs text-slate-500">{results.length} Groessen generiert</p>
          </div>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          {results.map((r) => (
            <div key={r.size} className="border border-slate-200 rounded-xl p-3 flex flex-col items-center gap-2 hover:border-sky-300 transition-colors">
              <img src={URL.createObjectURL(r.blob)} alt={`Favicon Vorschau ${r.size}x${r.size} Pixel`} className="w-12 h-12 object-contain rounded bg-slate-50 border border-slate-100" />
              <div className="text-center">
                <div className="text-xs font-bold text-slate-800">{r.size}x{r.size}</div>
                <div className="text-[10px] text-slate-400">{formatBytes(r.blob.size)}</div>
              </div>
              <button onClick={() => downloadSingle(r)} className="text-[11px] text-sky-600 hover:text-sky-700 font-semibold flex items-center gap-0.5">
                <Download className="w-3 h-3" /> PNG
              </button>
            </div>
          ))}
        </div>

        <div className="bg-slate-50 border border-slate-200 rounded-xl p-4">
          <h4 className="text-xs font-bold text-slate-700 mb-2">HTML-Einbindung</h4>
          <pre className="text-[11px] text-slate-600 whitespace-pre-wrap font-mono overflow-x-auto">{`<link rel="icon" type="image/png" sizes="32x32" href="/favicon_32x32.png">
<link rel="icon" type="image/png" sizes="16x16" href="/favicon_16x16.png">
<link rel="apple-touch-icon" href="/favicon_180x180.png">
<link rel="manifest" href="/manifest.json">`}</pre>
        </div>

        <div className="flex flex-col sm:flex-row gap-3 pt-2 border-t border-slate-100">
          <button onClick={handleReset} className="text-xs text-slate-500 hover:text-slate-800 font-medium">Neues Bild</button>
          <button onClick={downloadAll} className="flex-1 inline-flex items-center justify-center gap-2 px-6 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm shadow-sm transition-colors">
            <Download className="w-4 h-4" /> Alle als ZIP herunterladen
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full">
      {!imgEl ? (
        <FileUploader acceptedExtensions={['.jpg', '.jpeg', '.png', '.webp', '.svg', '.gif']} maxFileSizeMB={10} onFilesSelected={handleFileSelected}
          title="Favicon erstellen" subtitle="Logo oder Bild hochladen – CoolWave generiert alle Favicon-Groessen fuer Browser, PWA und Apple-Geraete" />
      ) : (
        <div className="bg-white rounded-2xl border border-slate-200 p-4 sm:p-6 shadow-sm space-y-5">
          <div className="flex items-center gap-4 pb-4 border-b border-slate-100">
            <div className="w-16 h-16 rounded-xl border border-slate-200 bg-slate-50 overflow-hidden flex items-center justify-center shrink-0">
              <img src={imgEl.src} alt={file ? `Favicon-Quellbild ${file.name}` : "Favicon-Quellbild Vorschau"} className="w-full h-full object-contain" />
            </div>
            <div>
              <p className="font-bold text-slate-900 text-sm truncate max-w-xs">{file?.name}</p>
              <p className="text-xs text-slate-500 mt-0.5">{formatBytes(file!.size)} &mdash; {imgEl.naturalWidth} x {imgEl.naturalHeight} px</p>
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider mb-3">Groessen auswaehlen</label>
            <div className="flex flex-wrap gap-2">
              {FAVICON_SIZES.map((s) => (
                <button key={s} type="button" onClick={() => toggleSize(s)}
                  className={'px-3 py-1.5 rounded-lg border text-xs font-semibold transition-colors ' + (selectedSizes.includes(s) ? 'border-sky-500 bg-sky-50 text-sky-700' : 'border-slate-200 text-slate-600 hover:border-sky-400')}>
                  {s}x{s}
                </button>
              ))}
            </div>
            <p className="text-[11px] text-slate-400 mt-2">16/32/48 = Browser-Tab &bull; 180 = Apple Touch Icon &bull; 192/512 = PWA Manifest</p>
          </div>

          <div>
            <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider mb-2">Ausgabeformat</label>
            <div className="flex gap-2">
              {(['png', 'ico'] as const).map((fmt) => (
                <button key={fmt} type="button" onClick={() => setOutputFormat(fmt)}
                  className={'px-4 py-2 rounded-lg border text-xs font-semibold transition-colors ' + (outputFormat === fmt ? 'border-sky-500 bg-sky-50 text-sky-700' : 'border-slate-200 text-slate-600 hover:border-sky-400')}>
                  .{fmt.toUpperCase()}
                </button>
              ))}
            </div>
            <p className="text-[11px] text-slate-400 mt-1">PNG wird als ZIP-Bundle geliefert; ICO fasst alle Groessen in einer Datei zusammen (Browser-Standard)</p>
          </div>

          <div className="flex flex-col sm:flex-row items-center justify-between gap-3 pt-2 border-t border-slate-100">
            <button onClick={handleReset} className="text-xs text-slate-500 hover:text-slate-800 font-medium">Anderes Bild</button>
            <button onClick={executeProcess} disabled={selectedSizes.length === 0}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 disabled:opacity-50 text-white font-bold text-sm shadow-sm transition-colors">
              <Star className="w-4 h-4" /> Favicons generieren
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useRef } from 'react';
import { Shrink, Image as ImageIcon, Sparkles, Layers, Sliders } from 'lucide-react';
import JSZip from 'jszip';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { DownloadBox } from '@/components/tools/DownloadBox';
import { BatchProcessingQueue, BatchItem } from '@/components/tools/BatchProcessingQueue';
import { downloadBlob, formatBytes } from '@/lib/utils';
import { trackEvent } from '@/lib/analytics';
import { runConcurrentBatch } from '@/lib/batch-queue';
import { getBatchLimits, validateBatchFiles } from '@/config/batch.config';

export function ImageCompressEngine() {
  const [singleFile, setSingleFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [quality, setQuality] = useState<number>(80);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [compressedBlob, setCompressedBlob] = useState<Blob | null>(null);
  const [outputFilename, setOutputFilename] = useState('');

  // Batch states
  const [batchItems, setBatchItems] = useState<BatchItem[]>([]);
  const [isBatchMode, setIsBatchMode] = useState(false);
  const [isZipping, setIsZipping] = useState(false);
  const abortControllerRef = useRef<AbortController | null>(null);

  const isPro = typeof window !== 'undefined' && localStorage.getItem('coolwave_pro_active') === 'true';
  const limits = getBatchLimits(isPro);

  const handleFilesSelected = (files: File[]) => {
    if (files.length === 0) return;

    if (files.length === 1 && !isBatchMode && batchItems.length === 0) {
      // Single-file workflow
      const f = files[0];
      setSingleFile(f);
      setPreviewUrl(URL.createObjectURL(f));
      setIsBatchMode(false);
      trackEvent('upload_completed', { toolSlug: 'bild-komprimieren', size: f.size });
    } else {
      // Batch mode
      const validation = validateBatchFiles(files, isPro);
      if (!validation.valid) {
        alert(validation.error);
        return;
      }

      setIsBatchMode(true);
      setSingleFile(null);
      const newItems: BatchItem[] = files.map((f, idx) => ({
        id: `batch_img_${Date.now()}_${idx}_${Math.random().toString(36).substring(7)}`,
        file: f,
        status: 'queued',
        progress: 0,
      }));
      setBatchItems(newItems);
      trackEvent('batch_upload_completed', { toolSlug: 'bild-komprimieren', count: files.length });
    }
  };

  /**
   * Helper to compress an individual image via HTML5 Canvas
   */
  const compressSingleImage = async (
    file: File,
    qualityLevel: number,
    onProgress?: (pct: number, text?: string) => void
  ): Promise<{ blob: Blob; fileName: string }> => {
    onProgress?.(25, 'Bild wird dekodiert...');

    const objectUrl = URL.createObjectURL(file);
    try {
      const img = new Image();
      img.src = objectUrl;
      await new Promise((res, rej) => {
        img.onload = res;
        img.onerror = rej;
      });

      onProgress?.(60, 'Optimierung & Kompression...');
      const canvas = document.createElement('canvas');
      canvas.width = img.naturalWidth || img.width;
      canvas.height = img.naturalHeight || img.height;
      const ctx = canvas.getContext('2d');
      if (!ctx) throw new Error('Canvas 2D-Kontext nicht verfügbar');

      const isJpg = file.type === 'image/jpeg' || /\.(jpg|jpeg)$/i.test(file.name);
      if (isJpg) {
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
      }
      ctx.drawImage(img, 0, 0);

      onProgress?.(85, 'Blob wird generiert...');
      const targetMime = file.type === 'image/png' ? 'image/png' : 'image/jpeg';
      const compressionFactor = qualityLevel / 100;

      const blob = await new Promise<Blob>((res, rej) => {
        canvas.toBlob(
          (b) => (b ? res(b) : rej(new Error('Kompression fehlgeschlagen'))),
          targetMime,
          compressionFactor
        );
      });

      onProgress?.(100, 'Fertig');
      return {
        blob,
        fileName: `coolwave_komprimiert_${file.name}`,
      };
    } finally {
      URL.revokeObjectURL(objectUrl);
    }
  };

  // Single-file execution
  const executeSingleCompress = async () => {
    if (!singleFile) return;
    setIsProcessing(true);
    setProgress(30);
    setStatusText('Bilddaten werden komprimiert...');
    trackEvent('conversion_started', { toolSlug: 'bild-komprimieren', quality });

    try {
      const result = await compressSingleImage(singleFile, quality, (p, msg) => {
        setProgress(p);
        if (msg) setStatusText(msg);
      });
      setCompressedBlob(result.blob);
      setOutputFilename(result.fileName);
      setIsProcessing(false);
      trackEvent('conversion_completed', { toolSlug: 'bild-komprimieren' });
    } catch (err) {
      console.error(err);
      setIsProcessing(false);
      alert('Fehler bei der Bildkomprimierung.');
      trackEvent('conversion_failed', { toolSlug: 'bild-komprimieren' });
    }
  };

  // Batch execution
  const startBatch = async () => {
    if (batchItems.length === 0) return;
    setIsProcessing(true);
    abortControllerRef.current = new AbortController();

    const tasks = batchItems.map((item) => ({
      id: item.id,
      run: async (signal?: AbortSignal) => {
        if (signal?.aborted) throw new Error('Abgebrochen');
        return await compressSingleImage(item.file, quality, (pct, statusText) => {
          setBatchItems((prev) =>
            prev.map((i) => (i.id === item.id ? { ...i, progress: pct, statusText } : i))
          );
        });
      },
    }));

    await runConcurrentBatch(tasks, {
      concurrency: limits.clientConcurrency,
      signal: abortControllerRef.current.signal,
      onItemStart: (id) => {
        setBatchItems((prev) =>
          prev.map((i) => (i.id === id ? { ...i, status: 'processing', progress: 10 } : i))
        );
      },
      onItemComplete: (id, result) => {
        setBatchItems((prev) =>
          prev.map((i) =>
            i.id === id
              ? {
                  ...i,
                  status: 'completed',
                  progress: 100,
                  outputBlob: result.blob,
                  outputFileName: result.fileName,
                  outputSize: result.blob.size,
                }
              : i
          )
        );
      },
      onItemError: (id, err) => {
        setBatchItems((prev) =>
          prev.map((i) =>
            i.id === id ? { ...i, status: 'failed', error: err.message, progress: 0 } : i
          )
        );
      },
    });

    setIsProcessing(false);
  };

  const cancelBatch = () => {
    abortControllerRef.current?.abort();
    setIsProcessing(false);
    setBatchItems((prev) =>
      prev.map((i) => (i.status === 'processing' || i.status === 'queued' ? { ...i, status: 'cancelled' } : i))
    );
  };

  const clearQueue = () => {
    setBatchItems([]);
    setIsBatchMode(false);
  };

  const removeItem = (id: string) => {
    setBatchItems((prev) => prev.filter((i) => i.id !== id));
  };

  const downloadItem = (item: BatchItem) => {
    if (item.outputBlob && item.outputFileName) {
      downloadBlob(item.outputBlob, item.outputFileName);
    }
  };

  const downloadAllZip = async () => {
    const completedItems = batchItems.filter((i) => i.status === 'completed' && i.outputBlob);
    if (completedItems.length === 0) return;

    setIsZipping(true);
    try {
      const zip = new JSZip();
      completedItems.forEach((item) => {
        if (item.outputBlob && item.outputFileName) {
          zip.file(item.outputFileName, item.outputBlob);
        }
      });

      const zipBlob = await zip.generateAsync({ type: 'blob' });
      downloadBlob(zipBlob, `coolwave_bilder_komprimiert_${Date.now()}.zip`);
    } catch (err) {
      console.error('[Zip Error]:', err);
      alert('Fehler beim Erstellen des ZIP-Archivs.');
    } finally {
      setIsZipping(false);
    }
  };

  const handleResetSingle = () => {
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setSingleFile(null);
    setPreviewUrl(null);
    setCompressedBlob(null);
    setIsProcessing(false);
  };

  // Single-file completed view
  if (compressedBlob && singleFile) {
    return (
      <DownloadBox
        filename={outputFilename}
        originalSizeBytes={singleFile.size}
        resultSizeBytes={compressedBlob.size}
        onDownload={() => downloadBlob(compressedBlob, outputFilename)}
        onReset={handleResetSingle}
        downloadLabel="Komprimiertes Bild herunterladen"
      />
    );
  }

  // Single-file in-progress view
  if (isProcessing && !isBatchMode) {
    return <ProcessingStatus progress={progress} statusText={statusText} />;
  }

  return (
    <div className="w-full space-y-6">
      {/* Batch Queue View */}
      {isBatchMode && batchItems.length > 0 ? (
        <div className="space-y-6">
          {/* Quality Slider for Batch */}
          <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">
            <div className="flex items-center justify-between mb-2">
              <label className="text-xs font-bold text-slate-700 uppercase tracking-wider flex items-center gap-2">
                <Sliders className="w-4 h-4 text-sky-600" />
                Kompressionsstufe für alle Bilder
              </label>
              <span className="text-xs font-mono font-bold text-sky-700 bg-sky-50 px-2.5 py-1 rounded-lg border border-sky-200">
                {quality}% Qualität
              </span>
            </div>
            <input
              type="range"
              min="10"
              max="95"
              step="5"
              value={quality}
              disabled={isProcessing}
              onChange={(e) => setQuality(parseInt(e.target.value, 10))}
              className="w-full accent-sky-600 cursor-pointer disabled:opacity-50"
            />
            <div className="flex justify-between text-[11px] text-slate-400 mt-1.5">
              <span>Maximale Einsparung (10%)</span>
              <span className="font-semibold text-sky-600">Empfohlen: 80%</span>
              <span>Beste visuelle Schärfe (95%)</span>
            </div>
          </div>

          <BatchProcessingQueue
            items={batchItems}
            isProcessing={isProcessing}
            onStartBatch={startBatch}
            onCancelBatch={cancelBatch}
            onClearQueue={clearQueue}
            onRemoveItem={removeItem}
            onDownloadItem={downloadItem}
            onDownloadAllZip={downloadAllZip}
            isZipping={isZipping}
            toolTitle="Bilder-Stapelkomprimierung"
          />
        </div>
      ) : !singleFile ? (
        /* Empty Uploader State */
        <FileUploader
          acceptedExtensions={['.jpg', '.jpeg', '.png', '.webp']}
          maxFileSizeMB={limits.maxFileSizeMB}
          allowMultiple={true}
          onFilesSelected={handleFilesSelected}
          title="Bilder hier ablegen (Einzel- oder Stapelmodus)"
          subtitle={`Reduzieren Sie JPG, PNG & WebP Dateigrößen • Bis zu ${limits.maxBatchFiles} Bilder gleichzeitig (${isPro ? 'Pro' : 'Kostenlos'})`}
        />
      ) : (
        /* Single File View (Preserved) */
        <div className="bg-white rounded-2xl border border-slate-200 p-6 sm:p-8 shadow-sm">
          <div className="flex flex-col sm:flex-row items-center gap-6 pb-6 border-b border-slate-100">
            {previewUrl && (
              <div className="w-24 h-24 sm:w-28 sm:h-28 rounded-xl border border-slate-200 bg-slate-50 overflow-hidden flex items-center justify-center shrink-0">
                <img src={previewUrl} alt={`Komprimierungsvorschau von ${singleFile.name}`} className="w-full h-full object-contain" />
              </div>
            )}

            <div className="flex-1 text-center sm:text-left">
              <h3 className="text-base font-bold text-slate-900 truncate max-w-md">
                {singleFile.name}
              </h3>
              <p className="text-xs text-slate-500 mt-0.5">
                Aktuelle Dateigröße: <span className="font-semibold text-slate-700">{formatBytes(singleFile.size)}</span>
              </p>
            </div>
          </div>

          <div className="py-6 max-w-lg">
            <div className="flex items-center justify-between mb-2">
              <label className="text-xs font-bold text-slate-700 uppercase tracking-wider">
                Qualitätsstufe
              </label>
              <span className="text-xs font-mono font-bold text-sky-700 bg-sky-50 px-2 py-0.5 rounded">
                {quality}%
              </span>
            </div>

            <input
              type="range"
              min="10"
              max="95"
              step="5"
              value={quality}
              onChange={(e) => setQuality(parseInt(e.target.value, 10))}
              className="w-full accent-sky-600 cursor-pointer"
            />

            <div className="flex justify-between text-[11px] text-slate-400 mt-1.5">
              <span>Kleinste Datei (10%)</span>
              <span className="font-semibold text-sky-600">Empfohlen: 80%</span>
              <span>Beste Qualität (95%)</span>
            </div>
          </div>

          <div className="pt-6 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4">
            <button
              onClick={handleResetSingle}
              className="text-xs text-slate-500 hover:text-slate-800 font-medium"
            >
              Anderes Bild wählen
            </button>

            <button
              onClick={executeSingleCompress}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm sm:text-base shadow-sm transition-colors"
            >
              <Shrink className="w-4 h-4" />
              <span>Bild jetzt verkleinern</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useRef } from 'react';
import { PDFDocument } from 'pdf-lib';
import JSZip from 'jszip';
import { 
  ArrowLeft, 
  ArrowRight, 
  Trash2, 
  RefreshCw, 
  Image as ImageIcon,
  Sliders,
  CheckCircle,
  Download,
  AlertCircle,
  Layers
} from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { DownloadBox } from '@/components/tools/DownloadBox';
import { BatchProcessingQueue, BatchItem } from '@/components/tools/BatchProcessingQueue';
import { downloadBlob, formatBytes } from '@/lib/utils';
import { trackEvent } from '@/lib/analytics';
import { runConcurrentBatch } from '@/lib/batch-queue';
import { getBatchLimits, validateBatchFiles } from '@/config/batch.config';

export type ImageTargetFormat =
  | 'PNG'
  | 'JPG'
  | 'WebP'
  | 'GIF'
  | 'SVG'
  | 'BMP'
  | 'TIFF'
  | 'ICO'
  | 'AVIF'
  | 'PDF';

interface ImageConvertEngineProps {
  targetFormat: ImageTargetFormat;
  sourceExtensions: string[];
}

export function ImageConvertEngine({ targetFormat, sourceExtensions }: ImageConvertEngineProps) {
  const [files, setFiles] = useState<File[]>([]);
  const [previewUrls, setPreviewUrls] = useState<string[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [resultBlob, setResultBlob] = useState<Blob | null>(null);
  const [resultDownloadUrl, setResultDownloadUrl] = useState<string | null>(null);
  const [outputFilename, setOutputFilename] = useState('');
  const [quality, setQuality] = useState<number>(90);
  const [backgroundColor, setBackgroundColor] = useState<string>('#ffffff');
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Batch states
  const [batchItems, setBatchItems] = useState<BatchItem[]>([]);
  const [isZipping, setIsZipping] = useState(false);
  const abortControllerRef = useRef<AbortController | null>(null);

  const isPro = typeof window !== 'undefined' && localStorage.getItem('coolwave_pro_active') === 'true';
  const limits = getBatchLimits(isPro);

  const handleFilesSelected = (newFiles: File[]) => {
    if (newFiles.length === 0) return;
    setErrorMsg(null);

    if (targetFormat === 'PDF') {
      const combined = [...files, ...newFiles];
      setFiles(combined);
      const urls = combined.map((f) => URL.createObjectURL(f));
      setPreviewUrls(urls);
      trackEvent('upload_completed', { targetFormat, count: newFiles.length });
      return;
    }

    if (newFiles.length === 1 && files.length === 0 && batchItems.length === 0) {
      // Single file workflow
      setFiles([newFiles[0]]);
      setPreviewUrls([URL.createObjectURL(newFiles[0])]);
      setBatchItems([]);
      trackEvent('upload_completed', { targetFormat, count: 1 });
    } else {
      // Batch workflow
      const combined = [...files, ...newFiles];
      const validation = validateBatchFiles(combined, isPro);
      if (!validation.valid) {
        alert(validation.error);
        return;
      }

      setFiles(combined);
      const newItems: BatchItem[] = combined.map((f, idx) => ({
        id: `img_batch_${Date.now()}_${idx}_${Math.random().toString(36).substring(7)}`,
        file: f,
        status: 'queued',
        progress: 0,
      }));
      setBatchItems(newItems);
      trackEvent('batch_upload_completed', { targetFormat, count: combined.length });
    }
  };

  const moveFile = (index: number, direction: 'left' | 'right') => {
    const targetIdx = direction === 'left' ? index - 1 : index + 1;
    if (targetIdx < 0 || targetIdx >= files.length) return;
    const updatedFiles = [...files];
    const tempFile = updatedFiles[index];
    updatedFiles[index] = updatedFiles[targetIdx];
    updatedFiles[targetIdx] = tempFile;

    const updatedUrls = [...previewUrls];
    const tempUrl = updatedUrls[index];
    updatedUrls[index] = updatedUrls[targetIdx];
    updatedUrls[targetIdx] = tempUrl;

    setFiles(updatedFiles);
    setPreviewUrls(updatedUrls);
  };

  const removeFile = (index: number) => {
    const updatedFiles = files.filter((_, i) => i !== index);
    const updatedUrls = previewUrls.filter((_, i) => i !== index);
    setFiles(updatedFiles);
    setPreviewUrls(updatedUrls);
  };

  const canProcessInBrowser = (file: File, target: ImageTargetFormat): boolean => {
    const ext = (file.name.split('.').pop() || '').toLowerCase();
    if (ext === 'heic' || ext === 'heif' || ext === 'tiff' || ext === 'tif') return false;
    if (target === 'SVG' || target === 'ICO' || target === 'BMP' || target === 'TIFF' || target === 'GIF') return false;
    if (target === 'PDF') return true;
    return target === 'PNG' || target === 'JPG' || target === 'WebP';
  };

  /**
   * Universal single-file processor (Client Canvas OR Server Worker)
   */
  const convertSingleFile = async (
    file: File,
    onProgress?: (pct: number, msg?: string) => void
  ): Promise<{ blob: Blob; fileName: string; size: number }> => {
    const baseName = file.name.substring(0, file.name.lastIndexOf('.')) || file.name;
    const ext = targetFormat.toLowerCase();
    const outName = `coolwave_${baseName}.${ext}`;

    if (canProcessInBrowser(file, targetFormat)) {
      onProgress?.(30, 'Bild wird im Browser transformiert...');
      const objectUrl = URL.createObjectURL(file);
      try {
        const img = new Image();
        img.src = objectUrl;
        await new Promise((res, rej) => {
          img.onload = res;
          img.onerror = rej;
        });

        const canvas = document.createElement('canvas');
        canvas.width = img.naturalWidth || img.width;
        canvas.height = img.naturalHeight || img.height;
        const ctx = canvas.getContext('2d');
        if (!ctx) throw new Error('Canvas 2D nicht verfügbar');

        if (targetFormat === 'JPG') {
          ctx.fillStyle = backgroundColor;
          ctx.fillRect(0, 0, canvas.width, canvas.height);
        }
        ctx.drawImage(img, 0, 0);

        const mimeMap: Record<string, string> = {
          PNG: 'image/png',
          JPG: 'image/jpeg',
          WebP: 'image/webp',
        };
        const targetMime = mimeMap[targetFormat] || 'image/png';
        const q = targetFormat === 'PNG' ? undefined : quality / 100;

        onProgress?.(70, 'Blob wird erzeugt...');
        const blob = await new Promise<Blob>((res, rej) => {
          canvas.toBlob(
            (b) => (b ? res(b) : rej(new Error('Konnte Bild nicht konvertieren'))),
            targetMime,
            q
          );
        });

        onProgress?.(100, 'Fertig');
        return { blob, fileName: outName, size: blob.size };
      } finally {
        URL.revokeObjectURL(objectUrl);
      }
    } else {
      // Server-side worker processing
      onProgress?.(20, 'Übertragung an Worker...');
      const formData = new FormData();
      formData.append('file', file);
      formData.append('type', 'image_convert');
      formData.append('targetFormat', targetFormat.toLowerCase());
      formData.append(
        'options',
        JSON.stringify({
          targetFormat: targetFormat.toLowerCase(),
          quality,
          backgroundColor,
        })
      );

      const res = await fetch('/api/v1/jobs', {
        method: 'POST',
        body: formData,
      });

      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        throw new Error(errData.error || `Server-Fehler: ${res.statusText}`);
      }

      const jobData = await res.json();
      const jobId = jobData.jobId;

      let pollCount = 0;
      while (pollCount < 60) {
        await new Promise((r) => setTimeout(r, 1200));
        pollCount++;

        const checkRes = await fetch(`/api/v1/jobs/${jobId}`);
        if (!checkRes.ok) continue;

        const pollData = await checkRes.json();
        if (pollData.progress) {
          onProgress?.(Math.max(30, pollData.progress), 'Server verarbeitet...');
        }

        if (pollData.status === 'completed' && pollData.output?.downloadUrl) {
          const downloadRes = await fetch(pollData.output.downloadUrl);
          const blob = await downloadRes.blob();
          onProgress?.(100, 'Fertig');
          return { blob, fileName: pollData.output.fileName || outName, size: blob.size };
        }

        if (pollData.status === 'failed') {
          throw new Error(pollData.error || 'Server-Konvertierung fehlgeschlagen');
        }
      }

      throw new Error('Zeitüberschreitung bei der Serververarbeitung');
    }
  };

  // Single-file execute
  const executeSingleConversion = async () => {
    if (files.length === 0) return;
    setIsProcessing(true);
    setProgress(15);
    setErrorMsg(null);
    setStatusText('Initialisierung...');

    try {
      if (targetFormat === 'PDF') {
        const pdf = await PDFDocument.create();
        for (let i = 0; i < files.length; i++) {
          const currentFile = files[i];
          const pct = 15 + Math.round(((i + 1) / files.length) * 70);
          setProgress(pct);
          setStatusText(`Bild ${i + 1} von ${files.length} wird eingebettet...`);

          const arrayBuffer = await currentFile.arrayBuffer();
          let embeddedImage;
          if (currentFile.type === 'image/png' || currentFile.name.toLowerCase().endsWith('.png')) {
            embeddedImage = await pdf.embedPng(arrayBuffer);
          } else {
            embeddedImage = await pdf.embedJpg(arrayBuffer);
          }

          const { width, height } = embeddedImage.scale(1);
          const page = pdf.addPage([width, height]);
          page.drawImage(embeddedImage, { x: 0, y: 0, width, height });
        }

        setProgress(90);
        setStatusText('PDF wird finalisiert...');
        const pdfBytes = await pdf.save();
        const blob = new Blob([pdfBytes as unknown as BlobPart], { type: 'application/pdf' });
        setResultBlob(blob);

        const base = files[0].name.substring(0, files[0].name.lastIndexOf('.')) || 'bilder';
        setOutputFilename(files.length === 1 ? `coolwave_${base}.pdf` : `coolwave_${base}_kombiniert.pdf`);
        setProgress(100);
        setIsProcessing(false);
        trackEvent('conversion_completed', { targetFormat });
        return;
      }

      const result = await convertSingleFile(files[0], (p, msg) => {
        setProgress(p);
        if (msg) setStatusText(msg);
      });

      setResultBlob(result.blob);
      setOutputFilename(result.fileName);
      setProgress(100);
      setIsProcessing(false);
      trackEvent('conversion_completed', { targetFormat, mode: 'browser' });
    } catch (err: any) {
      console.error(err);
      setIsProcessing(false);
      setErrorMsg(err.message || 'Fehler bei der Konvertierung.');
      trackEvent('conversion_failed', { targetFormat, error: err.message });
    }
  };

  // Batch execute
  const startBatch = async () => {
    if (batchItems.length === 0) return;
    setIsProcessing(true);
    abortControllerRef.current = new AbortController();

    const tasks = batchItems.map((item) => ({
      id: item.id,
      run: async (signal?: AbortSignal) => {
        if (signal?.aborted) throw new Error('Abgebrochen');
        return await convertSingleFile(item.file, (pct, statusText) => {
          setBatchItems((prev) =>
            prev.map((i) => (i.id === item.id ? { ...i, progress: pct, statusText } : i))
          );
        });
      },
    }));

    await runConcurrentBatch(tasks, {
      concurrency: limits.clientConcurrency,
      signal: abortControllerRef.current.signal,
      onItemStart: (id) => {
        setBatchItems((prev) =>
          prev.map((i) => (i.id === id ? { ...i, status: 'processing', progress: 10 } : i))
        );
      },
      onItemComplete: (id, result) => {
        setBatchItems((prev) =>
          prev.map((i) =>
            i.id === id
              ? {
                  ...i,
                  status: 'completed',
                  progress: 100,
                  outputBlob: result.blob,
                  outputFileName: result.fileName,
                  outputSize: result.size,
                }
              : i
          )
        );
      },
      onItemError: (id, err) => {
        setBatchItems((prev) =>
          prev.map((i) =>
            i.id === id ? { ...i, status: 'failed', error: err.message, progress: 0 } : i
          )
        );
      },
    });

    setIsProcessing(false);
  };

  const cancelBatch = () => {
    abortControllerRef.current?.abort();
    setIsProcessing(false);
    setBatchItems((prev) =>
      prev.map((i) => (i.status === 'processing' || i.status === 'queued' ? { ...i, status: 'cancelled' } : i))
    );
  };

  const clearQueue = () => {
    setFiles([]);
    setPreviewUrls([]);
    setBatchItems([]);
  };

  const removeItem = (id: string) => {
    setBatchItems((prev) => prev.filter((i) => i.id !== id));
  };

  const downloadItem = (item: BatchItem) => {
    if (item.outputBlob && item.outputFileName) {
      downloadBlob(item.outputBlob, item.outputFileName);
    }
  };

  const downloadAllZip = async () => {
    const completedItems = batchItems.filter((i) => i.status === 'completed' && i.outputBlob);
    if (completedItems.length === 0) return;

    setIsZipping(true);
    try {
      const zip = new JSZip();
      completedItems.forEach((item) => {
        if (item.outputBlob && item.outputFileName) {
          zip.file(item.outputFileName, item.outputBlob);
        }
      });

      const zipBlob = await zip.generateAsync({ type: 'blob' });
      downloadBlob(zipBlob, `coolwave_${targetFormat.toLowerCase()}_stapel_${Date.now()}.zip`);
    } catch (err) {
      console.error('[Zip Error]:', err);
      alert('Fehler beim Erstellen des ZIP-Archivs.');
    } finally {
      setIsZipping(false);
    }
  };

  const handleResetSingle = () => {
    setFiles([]);
    setPreviewUrls([]);
    setResultBlob(null);
    setResultDownloadUrl(null);
    setProgress(0);
    setIsProcessing(false);
    setErrorMsg(null);
  };

  const isBatchView = batchItems.length > 1 && targetFormat !== 'PDF';

  return (
