              <div className="md:col-span-2 space-y-4">
                {(targetFormat === 'JPG' || targetFormat === 'WebP' || targetFormat === 'AVIF') && (
                  <div className="space-y-2 bg-slate-50 p-4 rounded-xl border border-slate-200">
                    <div className="flex justify-between items-center text-xs font-semibold text-slate-700">
                      <span className="flex items-center gap-1.5">
                        <Sliders className="w-3.5 h-3.5 text-sky-600" />
                        Bildqualität / Kompression:
                      </span>
                      <span className="text-sky-600 font-bold">{quality}%</span>
                    </div>
                    <input
                      type="range"
                      min={40}
                      max={100}
                      value={quality}
                      onChange={(e) => setQuality(Number(e.target.value))}
                      className="w-full accent-sky-600 cursor-pointer"
                    />
                  </div>
                )}

                {(targetFormat === 'JPG' || targetFormat === 'BMP') && (
                  <div className="space-y-2 bg-slate-50 p-4 rounded-xl border border-slate-200">
                    <span className="text-xs font-semibold text-slate-700 block">
                      Hintergrundfarbe (für transparente Bereiche):
                    </span>
                    <div className="flex items-center gap-3">
                      <button
                        type="button"
                        onClick={() => setBackgroundColor('#ffffff')}
                        className={`px-3 py-1.5 rounded-lg text-xs font-medium border flex items-center gap-1.5 cursor-pointer ${
                          backgroundColor === '#ffffff'
                            ? 'border-sky-500 bg-sky-50 text-sky-700 font-bold'
                            : 'border-slate-200 bg-white text-slate-700'
                        }`}
                      >
                        <span className="w-3 h-3 rounded-full bg-white border border-slate-300" />
                        Weiß
                      </button>
                      <button
                        type="button"
                        onClick={() => setBackgroundColor('#000000')}
                        className={`px-3 py-1.5 rounded-lg text-xs font-medium border flex items-center gap-1.5 cursor-pointer ${
                          backgroundColor === '#000000'
                            ? 'border-sky-500 bg-sky-50 text-sky-700 font-bold'
                            : 'border-slate-200 bg-white text-slate-700'
                        }`}
                      >
                        <span className="w-3 h-3 rounded-full bg-black border border-slate-700" />
                        Schwarz
                      </button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Multi-image to PDF preview gallery */}
          {targetFormat === 'PDF' && files.length > 1 && (
            <div className="space-y-3">
              <span className="text-xs font-semibold text-slate-700 block">
                Seitenreihenfolge im PDF (Bilder neu anordnen):
              </span>
              <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-6 gap-3">
                {files.map((file, idx) => (
                  <div key={idx} className="relative group border border-slate-200 rounded-xl p-2 bg-slate-50 flex flex-col items-center">
                    <span className="absolute top-1 left-1 bg-slate-800 text-white text-[10px] w-5 h-5 rounded-full flex items-center justify-center font-bold z-10">
                      {idx + 1}
                    </span>
                    <img src={previewUrls[idx]} alt={`Miniaturansicht Seite ${idx + 1}: ${file.name}`} className="w-full h-20 object-contain rounded mb-2" />
                    <span className="text-[10px] text-slate-600 truncate w-full text-center">{file.name}</span>
                    <div className="flex items-center gap-1 mt-1">
                      <button type="button" onClick={() => moveFile(idx, 'left')} disabled={idx === 0} className="p-1 rounded bg-white shadow-xs hover:bg-slate-100 disabled:opacity-30">
                        <ArrowLeft className="w-3 h-3" />
                      </button>
                      <button type="button" onClick={() => moveFile(idx, 'right')} disabled={idx === files.length - 1} className="p-1 rounded bg-white shadow-xs hover:bg-slate-100 disabled:opacity-30">
                        <ArrowRight className="w-3 h-3" />
                      </button>
                      <button type="button" onClick={() => removeFile(idx)} className="p-1 rounded bg-white text-red-500 shadow-xs hover:bg-red-50">
                        <Trash2 className="w-3 h-3" />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="pt-4 border-t border-slate-100 flex items-center justify-end">
            <button
              onClick={executeSingleConversion}
              className="inline-flex items-center gap-2 px-6 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm shadow-sm transition"
            >
              <RefreshCw className="w-4 h-4" />
              <span>{targetFormat === 'PDF' ? 'PDF jetzt zusammenfügen' : 'Jetzt umwandeln'}</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

﻿'use client';

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { Crop, RotateCcw } from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { DownloadBox } from '@/components/tools/DownloadBox';
import { downloadBlob, formatBytes } from '@/lib/utils';

interface CropRect {
  x: number;
  y: number;
  w: number;
  h: number;
}

const PRESETS: { label: string; ratio: number | null }[] = [
  { label: 'Frei', ratio: null },
  { label: '1:1', ratio: 1 },
  { label: '4:3', ratio: 4 / 3 },
  { label: '16:9', ratio: 16 / 9 },
  { label: '3:2', ratio: 3 / 2 },
  { label: '3:4', ratio: 3 / 4 },
  { label: '9:16', ratio: 9 / 16 },
];

interface ImageCropEngineProps {
  circleMode?: boolean;
}

export function ImageCropEngine({ circleMode = false }: ImageCropEngineProps) {
  const [file, setFile] = useState<File | null>(null);
  const [imgEl, setImgEl] = useState<HTMLImageElement | null>(null);
  const [naturalW, setNaturalW] = useState(0);
  const [naturalH, setNaturalH] = useState(0);
  const [crop, setCrop] = useState<CropRect>({ x: 0, y: 0, w: 1, h: 1 });
  const [selectedPreset, setSelectedPreset] = useState<string>(circleMode ? '1:1' : 'Frei');
  const [lockedRatio, setLockedRatio] = useState<number | null>(circleMode ? 1 : null);
  const [isDragging, setIsDragging] = useState(false);
  const [dragMode, setDragMode] = useState<'create' | 'move' | 'resize-br'>('create');
  const [dragStart, setDragStart] = useState({ x: 0, y: 0, cropSnap: { x: 0, y: 0, w: 0, h: 0 } });
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [resultBlob, setResultBlob] = useState<Blob | null>(null);
  const [outputFilename, setOutputFilename] = useState('');

  const drawPreview = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas || !imgEl) return;
    const container = containerRef.current;
    if (!container) return;
    const maxW = container.clientWidth;
    const maxH = Math.min(480, window.innerHeight * 0.55);
    const scale = Math.min(maxW / imgEl.naturalWidth, maxH / imgEl.naturalHeight, 1);
    const dW = Math.round(imgEl.naturalWidth * scale);
    const dH = Math.round(imgEl.naturalHeight * scale);
    canvas.width = dW;
    canvas.height = dH;
    const ctx = canvas.getContext('2d')!;
    const cs = 12;
    for (let cy = 0; cy < dH; cy += cs) {
      for (let cx = 0; cx < dW; cx += cs) {
        ctx.fillStyle = (Math.floor(cx / cs) + Math.floor(cy / cs)) % 2 === 0 ? '#e2e8f0' : '#f8fafc';
        ctx.fillRect(cx, cy, cs, cs);
      }
    }
    ctx.drawImage(imgEl, 0, 0, dW, dH);
    ctx.fillStyle = 'rgba(0,0,0,0.45)';
    const rx = crop.x * dW, ry = crop.y * dH, rw = crop.w * dW, rh = crop.h * dH;
    ctx.fillRect(0, 0, dW, ry);
    ctx.fillRect(0, ry + rh, dW, dH - ry - rh);
    ctx.fillRect(0, ry, rx, rh);
    ctx.fillRect(rx + rw, ry, dW - rx - rw, rh);
    ctx.strokeStyle = '#38bdf8';
    ctx.lineWidth = 2;
    if (circleMode) {
      ctx.beginPath();
      ctx.ellipse(rx + rw / 2, ry + rh / 2, rw / 2, rh / 2, 0, 0, 2 * Math.PI);
      ctx.stroke();
    } else {
      ctx.strokeRect(rx, ry, rw, rh);
      ctx.strokeStyle = 'rgba(255,255,255,0.25)';
      ctx.lineWidth = 0.5;
      [1, 2].forEach((n) => {
        ctx.beginPath(); ctx.moveTo(rx + (rw * n) / 3, ry); ctx.lineTo(rx + (rw * n) / 3, ry + rh); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(rx, ry + (rh * n) / 3); ctx.lineTo(rx + rw, ry + (rh * n) / 3); ctx.stroke();
      });
    }
    const hSize = 8;
    ctx.fillStyle = '#38bdf8';
    [[rx, ry], [rx + rw - hSize, ry], [rx, ry + rh - hSize], [rx + rw - hSize, ry + rh - hSize]].forEach(([hx, hy]) => {
      ctx.fillRect(hx, hy, hSize, hSize);
    });
  }, [imgEl, crop, circleMode]);

  useEffect(() => { drawPreview(); }, [drawPreview]);

  const getRelPos = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current!;
    const rect = canvas.getBoundingClientRect();
    return { rx: (e.clientX - rect.left) / canvas.width, ry: (e.clientY - rect.top) / canvas.height };
  };

  const onMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!imgEl) return;
    const { rx, ry } = getRelPos(e);
    const { x, y, w, h } = crop;
    const near = 0.03;
    if (Math.abs(rx - (x + w)) < near && Math.abs(ry - (y + h)) < near) {
      setDragMode('resize-br');
    } else if (rx >= x && rx <= x + w && ry >= y && ry <= y + h) {
      setDragMode('move');
    } else {
      setDragMode('create');
    }
    setDragStart({ x: rx, y: ry, cropSnap: { ...crop } });
    setIsDragging(true);
  };

  const onMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!isDragging) return;
    const { rx, ry } = getRelPos(e);
    const dx = rx - dragStart.x, dy = ry - dragStart.y;
    if (dragMode === 'create') {
      let nx = Math.min(dragStart.x, rx), ny = Math.min(dragStart.y, ry);
      let nw = Math.abs(rx - dragStart.x), nh = Math.abs(ry - dragStart.y);
      if (lockedRatio) { if (nw / nh > lockedRatio) { nh = nw / lockedRatio; } else { nw = nh * lockedRatio; } }
      nw = Math.min(nw, 1 - nx); nh = Math.min(nh, 1 - ny);
      setCrop({ x: Math.max(0, nx), y: Math.max(0, ny), w: Math.max(0.01, nw), h: Math.max(0.01, nh) });
    } else if (dragMode === 'move') {
      const nx = Math.max(0, Math.min(dragStart.cropSnap.x + dx, 1 - dragStart.cropSnap.w));
      const ny = Math.max(0, Math.min(dragStart.cropSnap.y + dy, 1 - dragStart.cropSnap.h));
      setCrop({ ...dragStart.cropSnap, x: nx, y: ny });
    } else if (dragMode === 'resize-br') {
      let nw = dragStart.cropSnap.w + dx, nh = dragStart.cropSnap.h + dy;
      if (lockedRatio) { nh = nw / lockedRatio; }
      setCrop({ ...dragStart.cropSnap, w: Math.max(0.02, Math.min(nw, 1 - dragStart.cropSnap.x)), h: Math.max(0.02, Math.min(nh, 1 - dragStart.cropSnap.y)) });
    }
  };

  const handleFileSelected = (files: File[]) => {
    if (files.length === 0) return;
    const f = files[0];
    setFile(f);
    const url = URL.createObjectURL(f);
    const img = new Image();
    img.src = url;
    img.onload = () => {
      setNaturalW(img.naturalWidth); setNaturalH(img.naturalHeight); setImgEl(img);
      if (circleMode) {
        const minSide = Math.min(img.naturalWidth, img.naturalHeight);
        setCrop({ x: (img.naturalWidth - minSide) / 2 / img.naturalWidth, y: (img.naturalHeight - minSide) / 2 / img.naturalHeight, w: minSide / img.naturalWidth, h: minSide / img.naturalHeight });
      } else { setCrop({ x: 0.1, y: 0.1, w: 0.8, h: 0.8 }); }
    };
  };

  const applyPreset = (preset: { label: string; ratio: number | null }) => {
    setSelectedPreset(preset.label); setLockedRatio(preset.ratio);
    if (preset.ratio && naturalW && naturalH) {
      let nw = 0.8, nh = nw / preset.ratio;
      if (nh > 0.8) { nh = 0.8; nw = nh * preset.ratio; }
      setCrop({ x: 0.5 - nw / 2, y: 0.5 - nh / 2, w: nw, h: nh });
    }
  };

  const executeCrop = async () => {
    if (!imgEl || !file) return;
    setIsProcessing(true); setProgress(30); setStatusText('Bild wird zugeschnitten...');
    try {
      const canvas = document.createElement('canvas');
      const cX = Math.round(crop.x * naturalW), cY = Math.round(crop.y * naturalH);
      const cW = Math.round(crop.w * naturalW), cH = Math.round(crop.h * naturalH);
      canvas.width = cW; canvas.height = cH;
      const ctx = canvas.getContext('2d')!;
      if (circleMode) { ctx.beginPath(); ctx.ellipse(cW / 2, cH / 2, cW / 2, cH / 2, 0, 0, 2 * Math.PI); ctx.clip(); }
      ctx.drawImage(imgEl, cX, cY, cW, cH, 0, 0, cW, cH);
      setProgress(80); setStatusText('Exportiere...');
      const mime = (circleMode || file.type === 'image/png') ? 'image/png' : 'image/jpeg';
      canvas.toBlob((blob) => {
        if (!blob) throw new Error('Export fehler');
        setResultBlob(blob);
        const ext = mime === 'image/png' ? '.png' : '.jpg';
        const base = file.name.replace(/\.[^.]+$/, '');
        setOutputFilename('coolwave_' + (circleMode ? 'kreis_' : 'zugeschnitten_') + base + ext);
        setProgress(100); setIsProcessing(false);
      }, mime, 0.92);
    } catch { setIsProcessing(false); alert('Fehler beim Zuschneiden.'); }
  };

  const handleReset = () => { setFile(null); setImgEl(null); setResultBlob(null); setIsProcessing(false); };
  const cropPxW = Math.round(crop.w * naturalW);
  const cropPxH = Math.round(crop.h * naturalH);

  if (resultBlob && file) {
    return (
      <DownloadBox
        filename={outputFilename} originalSizeBytes={file.size} resultSizeBytes={resultBlob.size}
        onDownload={() => { const url = URL.createObjectURL(resultBlob); const a = document.createElement('a'); a.href = url; a.download = outputFilename; a.click(); }}
        onReset={handleReset} downloadLabel={circleMode ? 'Kreis-Bild herunterladen' : 'Zugeschnittenes Bild herunterladen'}
      />
    );
  }
  if (isProcessing) return <ProcessingStatus progress={progress} statusText={statusText} />;

  return (
    <div className="w-full">
      {!imgEl ? (
        <FileUploader acceptedExtensions={['.jpg', '.jpeg', '.png', '.webp', '.gif', '.bmp']} maxFileSizeMB={50} onFilesSelected={handleFileSelected}
          title={circleMode ? 'Bild fuer kreisfoermigen Zuschnitt ablegen' : 'Bild zum Zuschneiden ablegen'}
          subtitle={circleMode ? 'Fuer Profilbilder: Bild auf einen Kreis zuschneiden' : 'Definieren Sie den Ausschnitt per Drag-and-Drop'} />
      ) : (
        <div className="bg-white rounded-2xl border border-slate-200 p-4 sm:p-6 shadow-sm space-y-4">
          {!circleMode && (
            <div>
              <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider mb-2">Seitenverhaeltnis</label>
              <div className="flex flex-wrap gap-2">
                {PRESETS.map((p) => (
                  <button key={p.label} type="button" onClick={() => applyPreset(p)}
                    className={'px-3 py-1 rounded-lg border text-xs font-semibold transition-colors ' + (selectedPreset === p.label ? 'border-sky-500 bg-sky-50 text-sky-700' : 'border-slate-200 text-slate-600 hover:border-sky-400')}>
                    {p.label}
                  </button>
                ))}
              </div>
            </div>
          )}
          <div ref={containerRef} className="relative w-full overflow-hidden rounded-xl border border-slate-200 bg-slate-50">
            <canvas ref={canvasRef} onMouseDown={onMouseDown} onMouseMove={onMouseMove} onMouseUp={() => setIsDragging(false)} onMouseLeave={() => setIsDragging(false)}
              className="block w-full cursor-crosshair touch-none" style={{ maxHeight: '480px', objectFit: 'contain' }} />
          </div>
          <div className="flex flex-wrap items-center gap-4 text-xs text-slate-500">
            <span>Original: <strong className="text-slate-800 font-mono">{naturalW} x {naturalH} px</strong></span>
            <span>Ausschnitt: <strong className="text-sky-700 font-mono">{cropPxW} x {cropPxH} px</strong></span>
            <span className="text-[11px]">({formatBytes(file!.size)})</span>
          </div>
          <div className="flex flex-col sm:flex-row items-center justify-between gap-3 pt-2 border-t border-slate-100">
            <button onClick={handleReset} className="text-xs text-slate-500 hover:text-slate-800 font-medium inline-flex items-center gap-1">
              <RotateCcw className="w-3.5 h-3.5" /> Anderes Bild
            </button>
            <button onClick={executeCrop} disabled={cropPxW < 2 || cropPxH < 2}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 disabled:opacity-50 text-white font-bold text-sm shadow-sm transition-colors">
              <Crop className="w-4 h-4" />
              {circleMode ? 'Kreisfoermig zuschneiden' : 'Bild zuschneiden'}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { SlidersHorizontal, Eraser } from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { DownloadBox } from '@/components/tools/DownloadBox';
import { formatBytes } from '@/lib/utils';

// DPI is embedded in PNG chunks or JPEG APP0/APP1 segments.
// We set the pixel density in the canvas output via a Blob approach.
// For JPEG we patch the APP0 JFIF or Exif DPI fields.

function writeJfifDpi(jpegBytes: Uint8Array, dpi: number): Uint8Array {
  // Find JFIF APP0 marker (FF E0) and patch Xdensity/Ydensity
  let i = 2;
  while (i < jpegBytes.length - 1) {
    if (jpegBytes[i] === 0xFF) {
      const marker = jpegBytes[i + 1];
      const len = (jpegBytes[i + 2] << 8) | jpegBytes[i + 3];
      if (marker === 0xE0 && len >= 16) {
        // JFIF: units byte at i+11, Xdensity at i+12, Ydensity at i+14
        const seg = jpegBytes.slice(i, i + 2 + len);
        if (seg[4] === 0x4A && seg[5] === 0x46 && seg[6] === 0x49 && seg[7] === 0x46) {
          // units = 1 (DPI)
          jpegBytes[i + 11] = 1;
          jpegBytes[i + 12] = (dpi >> 8) & 0xFF;
          jpegBytes[i + 13] = dpi & 0xFF;
          jpegBytes[i + 14] = (dpi >> 8) & 0xFF;
          jpegBytes[i + 15] = dpi & 0xFF;
          return jpegBytes;
        }
      }
      i += 2 + len;
    } else { i++; }
  }
  return jpegBytes; // Return unchanged if JFIF not found
}

function writePngDpi(pngBytes: Uint8Array, dpi: number): Uint8Array {
  // pHYs chunk: 4 bytes ppuX, 4 bytes ppuY, 1 byte unit (1=meter)
  const ppm = Math.round(dpi / 0.0254); // pixels per meter
  const phys = new Uint8Array(9 + 12);
  const view = new DataView(phys.buffer);
  // chunk length = 9
  view.setUint32(0, 9);
  phys[4] = 0x70; phys[5] = 0x48; phys[6] = 0x59; phys[7] = 0x73; // 'pHYs'
  view.setUint32(8, ppm); view.setUint32(12, ppm);
  phys[16] = 1; // unit meter
  // CRC32
  const crcData = phys.slice(4, 17);
  const crc = crc32(crcData);
  view.setUint32(17, crc);
  // Insert pHYs chunk after PNG signature (8 bytes) and IHDR chunk (4+4+13+4=25 bytes)
  const insertAt = 33; // After signature + IHDR
  const result = new Uint8Array(pngBytes.length + phys.length);
  result.set(pngBytes.slice(0, insertAt), 0);
  result.set(phys, insertAt);
  result.set(pngBytes.slice(insertAt), insertAt + phys.length);
  return result;
}

function crc32(data: Uint8Array): number {
  let crc = 0xFFFFFFFF;
  const table = makeCrcTable();
  for (let i = 0; i < data.length; i++) { crc = (crc >>> 8) ^ table[(crc ^ data[i]) & 0xFF]; }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function makeCrcTable(): Uint32Array {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) { c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1); }
    t[n] = c;
  }
  return t;
}

interface ImageDpiEngineProps {
  stripMetadata?: boolean;
}

export function ImageDpiEngine({ stripMetadata = false }: ImageDpiEngineProps) {
  const [file, setFile] = useState<File | null>(null);
  const [imgEl, setImgEl] = useState<HTMLImageElement | null>(null);
  const [dpi, setDpi] = useState(150);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [resultBlob, setResultBlob] = useState<Blob | null>(null);
  const [outputFilename, setOutputFilename] = useState('');

  const handleFileSelected = (files: File[]) => {
    if (files.length === 0) return;
    const f = files[0]; setFile(f);
    const url = URL.createObjectURL(f);
    const img = new Image(); img.src = url;
    img.onload = () => setImgEl(img);
  };

  const executeProcess = async () => {
    if (!imgEl || !file) return;
    setIsProcessing(true); setProgress(20);
    setStatusText(stripMetadata ? 'Metadaten werden entfernt...' : 'DPI wird gesetzt...');
    try {
      const canvas = document.createElement('canvas');
      canvas.width = imgEl.naturalWidth; canvas.height = imgEl.naturalHeight;
      const ctx = canvas.getContext('2d')!;
      ctx.drawImage(imgEl, 0, 0);
      setProgress(60); setStatusText('Exportiere...');
      const isPng = file.type === 'image/png' || file.name.toLowerCase().endsWith('.png');
      const mime = isPng ? 'image/png' : 'image/jpeg';
      canvas.toBlob(async (blob) => {
        if (!blob) throw new Error('Export fehler');
        if (stripMetadata) {
          // Canvas re-draw already strips Exif. Done.
          setResultBlob(blob);
          const ext = isPng ? '.png' : '.jpg';
          setOutputFilename('coolwave_no_meta_' + file.name.replace(/\.[^.]+$/, '') + ext);
          setProgress(100); setIsProcessing(false);
          return;
        }
        // Patch DPI into the raw bytes
        const buf = await blob.arrayBuffer();
        let bytes: Uint8Array = new Uint8Array(buf);
        if (isPng) { bytes = writePngDpi(bytes, dpi) as Uint8Array; }
        else { bytes = writeJfifDpi(bytes, dpi) as Uint8Array; }
        const cleanBuf: ArrayBuffer = new Uint8Array(bytes).buffer;
        const finalBlob = new Blob([cleanBuf], { type: mime });
        setResultBlob(finalBlob);
        const ext = isPng ? '.png' : '.jpg';
        setOutputFilename('coolwave_' + dpi + 'dpi_' + file.name.replace(/\.[^.]+$/, '') + ext);
        setProgress(100); setIsProcessing(false);
      }, mime, 0.96);
    } catch { setIsProcessing(false); alert('Fehler bei der Verarbeitung.'); }
  };

  const handleReset = () => { setFile(null); setImgEl(null); setResultBlob(null); setIsProcessing(false); };

  const DPI_PRESETS = [72, 96, 150, 300, 600];

  if (resultBlob && file) {
    return (
      <DownloadBox filename={outputFilename} originalSizeBytes={file.size} resultSizeBytes={resultBlob.size}
        onDownload={() => { const url = URL.createObjectURL(resultBlob); const a = document.createElement('a'); a.href = url; a.download = outputFilename; a.click(); }}
        onReset={handleReset} downloadLabel={stripMetadata ? 'Bereinigtes Bild herunterladen' : 'Bild mit neuem DPI herunterladen'} />
    );
  }
  if (isProcessing) return <ProcessingStatus progress={progress} statusText={statusText} />;

  return (
    <div className="w-full">
      {!imgEl ? (
        <FileUploader acceptedExtensions={['.jpg', '.jpeg', '.png']} maxFileSizeMB={50} onFilesSelected={handleFileSelected}
          title={stripMetadata ? 'Bild zum Bereinigen ablegen' : 'Bild fuer DPI-Aenderung ablegen'}
          subtitle={stripMetadata ? 'Entfernt EXIF, IPTC, XMP und alle Metadaten aus JPEG/PNG-Dateien' : 'DPI-Wert fuer Druck und Veroeffentlichung festlegen'} />
      ) : (
        <div className="bg-white rounded-2xl border border-slate-200 p-4 sm:p-6 shadow-sm space-y-5">
          <div className="flex items-center gap-4 pb-4 border-b border-slate-100">
            <div className="w-16 h-16 rounded-xl border border-slate-200 bg-slate-50 overflow-hidden flex items-center justify-center shrink-0">
              <img src={imgEl.src} alt={file ? `Bildvorschau von ${file.name}` : "Bildvorschau"} className="w-full h-full object-contain" />
            </div>
            <div>
              <p className="font-bold text-slate-900 text-sm truncate max-w-xs">{file?.name}</p>
              <p className="text-xs text-slate-500 mt-0.5">{formatBytes(file!.size)} &mdash; {imgEl.naturalWidth} x {imgEl.naturalHeight} px</p>
            </div>
          </div>

          {!stripMetadata && (
            <div className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider mb-2">DPI-Schnellauswahl</label>
                <div className="flex flex-wrap gap-2">
                  {DPI_PRESETS.map((d) => (
                    <button key={d} type="button" onClick={() => setDpi(d)}
                      className={'px-3 py-1.5 rounded-lg border text-xs font-semibold transition-colors ' + (dpi === d ? 'border-sky-500 bg-sky-50 text-sky-700' : 'border-slate-200 text-slate-600 hover:border-sky-400')}>
                      {d} DPI
                    </button>
                  ))}
                </div>
                <p className="text-[11px] text-slate-400 mt-2">72 DPI = Bildschirm &bull; 150 DPI = Qualitätsdruck &bull; 300 DPI = Profidruck &bull; 600 DPI = Hochauflösender Druck</p>
              </div>
              <div>
                <div className="flex justify-between mb-1">
                  <label className="text-xs font-bold text-slate-600 uppercase tracking-wider">Benutzerdefiniert</label>
                  <span className="text-xs font-mono font-bold text-sky-700 bg-sky-50 px-2 py-0.5 rounded">{dpi} DPI</span>
                </div>
                <input type="range" min="72" max="1200" step="6" value={dpi} onChange={(e) => setDpi(+e.target.value)} className="w-full accent-sky-600 cursor-pointer" />
              </div>
            </div>
          )}

          {stripMetadata && (
            <div className="bg-amber-50 border border-amber-200 rounded-xl p-4">
              <h4 className="text-sm font-bold text-amber-800 mb-1">Was wird entfernt?</h4>
              <ul className="text-xs text-amber-700 space-y-1 list-disc list-inside">
                <li>EXIF-Daten (GPS-Koordinaten, Kameramodell, Aufnahmedatum)</li>
                <li>IPTC-Metadaten (Urheberrecht, Beschriftungen)</li>
                <li>XMP-Metadaten (Adobe-Informationen)</li>
                <li>Eingebettete Kommentare und Thumbnails</li>
              </ul>
              <p className="text-xs text-amber-600 mt-2">Die Bilddimensionen und -qualitaet bleiben vollstaendig erhalten.</p>
            </div>
          )}

          <div className="flex flex-col sm:flex-row items-center justify-between gap-3 pt-2 border-t border-slate-100">
            <button onClick={handleReset} className="text-xs text-slate-500 hover:text-slate-800 font-medium">Anderes Bild</button>
            <button onClick={executeProcess}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm shadow-sm transition-colors">
              {stripMetadata ? <Eraser className="w-4 h-4" /> : <SlidersHorizontal className="w-4 h-4" />}
              {stripMetadata ? 'Metadaten entfernen' : 'DPI aendern & herunterladen'}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

