interface ImageResizeEngineProps {
  isGrayscaleMode?: boolean;
}

export function ImageResizeEngine({ isGrayscaleMode = false }: ImageResizeEngineProps) {
  const [file, setFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [origWidth, setOrigWidth] = useState<number>(0);
  const [origHeight, setOrigHeight] = useState<number>(0);
  const [targetWidth, setTargetWidth] = useState<number>(0);
  const [targetHeight, setTargetHeight] = useState<number>(0);
  const [lockRatio, setLockRatio] = useState<boolean>(true);

  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [resultBlob, setResultBlob] = useState<Blob | null>(null);
  const [outputFilename, setOutputFilename] = useState('');

  const handleFileSelected = (files: File[]) => {
    if (files.length === 0) return;
    const f = files[0];
    setFile(f);
    const url = URL.createObjectURL(f);
    setPreviewUrl(url);

    const img = new Image();
    img.src = url;
    img.onload = () => {
      setOrigWidth(img.naturalWidth || img.width);
      setOrigHeight(img.naturalHeight || img.height);
      setTargetWidth(img.naturalWidth || img.width);
      setTargetHeight(img.naturalHeight || img.height);
    };
  };

  const handleWidthChange = (val: number) => {
    setTargetWidth(val);
    if (lockRatio && origWidth > 0) {
      const ratio = origHeight / origWidth;
      setTargetHeight(Math.round(val * ratio));
    }
  };

  const handleHeightChange = (val: number) => {
    setTargetHeight(val);
    if (lockRatio && origHeight > 0) {
      const ratio = origWidth / origHeight;
      setTargetWidth(Math.round(val * ratio));
    }
  };

  const setScalePreset = (percent: number) => {
    if (origWidth === 0) return;
    const factor = percent / 100;
    setTargetWidth(Math.round(origWidth * factor));
    setTargetHeight(Math.round(origHeight * factor));
  };

  const executeProcess = async () => {
    if (!file || !previewUrl) return;
    setIsProcessing(true);
    setProgress(30);
    setStatusText(isGrayscaleMode ? 'In Graustufen umwandeln...' : 'Bildmaße werden neu berechnet...');

    try {
      const img = new Image();
      img.src = previewUrl;
      await new Promise((res, rej) => {
        img.onload = res;
        img.onerror = rej;
      });

      const canvas = document.createElement('canvas');
      const w = isGrayscaleMode ? img.naturalWidth : targetWidth;
      const h = isGrayscaleMode ? img.naturalHeight : targetHeight;
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext('2d');
      if (!ctx) throw new Error('Canvas context nicht verfügbar');

      ctx.drawImage(img, 0, 0, w, h);

      // If grayscale mode, convert pixels using Rec. 709 luminance
      if (isGrayscaleMode) {
        setProgress(60);
        setStatusText('Luminanz-Filter wird berechnet...');
        const imageData = ctx.getImageData(0, 0, w, h);
        const data = imageData.data;
        for (let i = 0; i < data.length; i += 4) {
          const r = data[i];
          const g = data[i + 1];
          const b = data[i + 2];
          // Luminance formula
          const gray = 0.299 * r + 0.587 * g + 0.114 * b;
          data[i] = gray;
          data[i + 1] = gray;
          data[i + 2] = gray;
        }
        ctx.putImageData(imageData, 0, 0);
      }

      setProgress(85);
      setStatusText('Bild wird exportiert...');

      const mimeType = file.type === 'image/png' ? 'image/png' : 'image/jpeg';

      canvas.toBlob((blob) => {
        if (!blob) throw new Error('Export fehlgeschlagen');
        setResultBlob(blob);
        const prefix = isGrayscaleMode ? 'graustufen_' : 'skaliert_';
        setOutputFilename(`coolwave_${prefix}${file.name}`);
        setProgress(100);
        setIsProcessing(false);
      }, mimeType, 0.92);
    } catch (err) {
      console.error(err);
      setIsProcessing(false);
      alert('Fehler bei der Bildverarbeitung.');
    }
  };

  const handleDownload = () => {
    if (!resultBlob) return;
    downloadBlob(resultBlob, outputFilename);
  };

  const handleReset = () => {
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setFile(null);
    setPreviewUrl(null);
    setResultBlob(null);
    setIsProcessing(false);
  };

  if (resultBlob && file) {
    return (
      <DownloadBox
        filename={outputFilename}
        originalSizeBytes={file.size}
        resultSizeBytes={resultBlob.size}
        onDownload={handleDownload}
        onReset={handleReset}
        downloadLabel={isGrayscaleMode ? 'Schwarzweiß-Bild herunterladen' : 'Skaliertes Bild herunterladen'}
      />
    );
  }

  if (isProcessing) {
    return <ProcessingStatus progress={progress} statusText={statusText} />;
  }

  return (
    <div className="w-full">
      {!file ? (
        <FileUploader
          acceptedExtensions={['.jpg', '.jpeg', '.png', '.webp']}
          maxFileSizeMB={50}
          onFilesSelected={handleFileSelected}
          title={isGrayscaleMode ? 'Bild für Schwarzweiß ablegen' : 'Bild zum Skalieren ablegen'}
          subtitle={
            isGrayscaleMode
              ? 'Wandeln Sie Farbbilder sofort in stilvolle Graustufen-Grafiken um'
              : 'Passen Sie Breite und Höhe in Pixeln an oder skalieren Sie prozentual'
          }
        />
      ) : (
        <div className="bg-white rounded-2xl border border-slate-200 p-6 sm:p-8 shadow-sm">
          <div className="flex flex-col sm:flex-row items-center gap-6 pb-6 border-b border-slate-100">
            {previewUrl && (
              <div className="w-24 h-24 sm:w-28 sm:h-28 rounded-xl border border-slate-200 bg-slate-50 overflow-hidden flex items-center justify-center shrink-0">
                <img
                  src={previewUrl}
                  alt={`Bildvorschau von ${file.name}`}
                  className="w-full h-full object-contain"
                />
              </div>
            )}

            <div className="flex-1 text-center sm:text-left">
              <h3 className="text-base font-bold text-slate-900 truncate max-w-md">
                {file.name}
              </h3>
              <p className="text-xs text-slate-500 mt-0.5">
                {formatBytes(file.size)} • Originalmaße: {origWidth} × {origHeight} px
              </p>
            </div>
          </div>

          {!isGrayscaleMode && (
            <div className="py-6 space-y-4 max-w-lg">
              {/* Presets */}
              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                  Schnell-Skalierung
                </label>
                <div className="flex flex-wrap gap-2">
                  {[25, 50, 75, 100].map((pct) => (
                    <button
                      key={pct}
                      type="button"
                      onClick={() => setScalePreset(pct)}
                      className="px-3 py-1.5 rounded-lg border border-slate-200 hover:border-sky-500 text-xs font-semibold text-slate-700 transition-colors"
                    >
                      {pct}%
                    </button>
                  ))}
                </div>
              </div>

              {/* Exact pixel inputs */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 items-end">
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">
                    Breite (px)
                  </label>
                  <input
                    type="number"
                    value={targetWidth}
                    onChange={(e) => handleWidthChange(parseInt(e.target.value, 10) || 0)}
                    className="w-full px-3 py-2 rounded-xl border border-slate-300 text-sm text-slate-900 focus:outline-none focus:ring-2 focus:ring-sky-500 font-mono"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">
                    Höhe (px)
                  </label>
                  <input
                    type="number"
                    value={targetHeight}
                    onChange={(e) => handleHeightChange(parseInt(e.target.value, 10) || 0)}
                    className="w-full px-3 py-2 rounded-xl border border-slate-300 text-sm text-slate-900 focus:outline-none focus:ring-2 focus:ring-sky-500 font-mono"
                  />
                </div>
              </div>

              {/* Aspect Ratio Lock */}
              <button
                type="button"
                onClick={() => setLockRatio(!lockRatio)}
                className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-semibold border transition-colors ${
                  lockRatio
                    ? 'border-sky-600 bg-sky-50 text-sky-700'
                    : 'border-slate-200 text-slate-500'
                }`}
              >
                {lockRatio ? <Lock className="w-3.5 h-3.5" /> : <Unlock className="w-3.5 h-3.5" />}
                <span>Seitenverhältnis sperren</span>
              </button>
            </div>
          )}

          <div className="pt-6 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4">
            <button
              onClick={handleReset}
              className="text-xs text-slate-500 hover:text-slate-800 font-medium"
            >
              Anderes Bild wählen
            </button>

            <button
              onClick={executeProcess}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm sm:text-base shadow-sm transition-colors"
            >
              {isGrayscaleMode ? <Palette className="w-4 h-4" /> : <Maximize2 className="w-4 h-4" />}
              <span>{isGrayscaleMode ? 'In Schwarzweiß umwandeln' : 'Bildgröße anpassen'}</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

﻿'use client';

import React, { useState, useRef, useEffect } from 'react';
import { RotateCcw, RotateCw, FlipHorizontal, FlipVertical } from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { DownloadBox } from '@/components/tools/DownloadBox';
import { formatBytes } from '@/lib/utils';

type RotateMode = 'rotate' | 'flip';

interface ImageRotateFlipEngineProps {
  mode?: RotateMode;
}

export function ImageRotateFlipEngine({ mode = 'rotate' }: ImageRotateFlipEngineProps) {
  const [file, setFile] = useState<File | null>(null);
  const [imgEl, setImgEl] = useState<HTMLImageElement | null>(null);
  const [rotation, setRotation] = useState(0); // degrees: 0, 90, 180, 270
  const [flipH, setFlipH] = useState(false);
  const [flipV, setFlipV] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [resultBlob, setResultBlob] = useState<Blob | null>(null);
  const [outputFilename, setOutputFilename] = useState('');

  const drawPreview = () => {
    const canvas = canvasRef.current;
    if (!canvas || !imgEl) return;
    const rad = (rotation * Math.PI) / 180;
    const sw = rotation === 90 || rotation === 270 ? imgEl.naturalHeight : imgEl.naturalWidth;
    const sh = rotation === 90 || rotation === 270 ? imgEl.naturalWidth : imgEl.naturalHeight;
    const maxSide = 400;
    const scale = Math.min(maxSide / sw, maxSide / sh, 1);
    canvas.width = Math.round(sw * scale);
    canvas.height = Math.round(sh * scale);
    const ctx = canvas.getContext('2d')!;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();
    ctx.translate(canvas.width / 2, canvas.height / 2);
    ctx.rotate(rad);
    const scaleX = flipH ? -1 : 1;
    const scaleY = flipV ? -1 : 1;
    ctx.scale(scaleX * scale, scaleY * scale);
    ctx.drawImage(imgEl, -imgEl.naturalWidth / 2, -imgEl.naturalHeight / 2);
    ctx.restore();
  };

  useEffect(() => { drawPreview(); }, [imgEl, rotation, flipH, flipV]);

  const handleFileSelected = (files: File[]) => {
    if (files.length === 0) return;
    const f = files[0];
    setFile(f);
    const url = URL.createObjectURL(f);
    const img = new Image();
    img.src = url;
    img.onload = () => setImgEl(img);
  };

  const rotateLeft = () => setRotation((r) => (r - 90 + 360) % 360);
  const rotateRight = () => setRotation((r) => (r + 90) % 360);
  const setRotationDeg = (deg: number) => setRotation(deg);

  const executeProcess = async () => {
    if (!imgEl || !file) return;
    setIsProcessing(true); setProgress(30); setStatusText('Bild wird transformiert...');
    try {
      const rad = (rotation * Math.PI) / 180;
      const sw = rotation === 90 || rotation === 270 ? imgEl.naturalHeight : imgEl.naturalWidth;
      const sh = rotation === 90 || rotation === 270 ? imgEl.naturalWidth : imgEl.naturalHeight;
      const canvas = document.createElement('canvas');
      canvas.width = sw; canvas.height = sh;
      const ctx = canvas.getContext('2d')!;
      ctx.save();
      ctx.translate(sw / 2, sh / 2);
      ctx.rotate(rad);
      const scaleX = flipH ? -1 : 1;
      const scaleY = flipV ? -1 : 1;
      ctx.scale(scaleX, scaleY);
      ctx.drawImage(imgEl, -imgEl.naturalWidth / 2, -imgEl.naturalHeight / 2);
      ctx.restore();
      setProgress(80); setStatusText('Exportiere...');
      const mime = file.type === 'image/png' ? 'image/png' : 'image/jpeg';
      canvas.toBlob((blob) => {
        if (!blob) throw new Error('Export fehler');
        setResultBlob(blob);
        const ext = mime === 'image/png' ? '.png' : '.jpg';
        const base = file.name.replace(/\.[^.]+$/, '');
        const suffix = mode === 'flip' ? 'gespiegelt' : 'gedreht';
        setOutputFilename('coolwave_' + suffix + '_' + base + ext);
        setProgress(100); setIsProcessing(false);
      }, mime, 0.92);
    } catch { setIsProcessing(false); alert('Fehler bei der Verarbeitung.'); }
  };

  const handleReset = () => { setFile(null); setImgEl(null); setResultBlob(null); setRotation(0); setFlipH(false); setFlipV(false); setIsProcessing(false); };

  if (resultBlob && file) {
    return (
      <DownloadBox filename={outputFilename} originalSizeBytes={file.size} resultSizeBytes={resultBlob.size}
        onDownload={() => { const url = URL.createObjectURL(resultBlob); const a = document.createElement('a'); a.href = url; a.download = outputFilename; a.click(); }}
        onReset={handleReset} downloadLabel="Bild herunterladen" />
    );
  }
  if (isProcessing) return <ProcessingStatus progress={progress} statusText={statusText} />;

  const sw = imgEl ? (rotation === 90 || rotation === 270 ? imgEl.naturalHeight : imgEl.naturalWidth) : 0;
  const sh = imgEl ? (rotation === 90 || rotation === 270 ? imgEl.naturalWidth : imgEl.naturalHeight) : 0;

  return (
    <div className="w-full">
      {!imgEl ? (
        <FileUploader acceptedExtensions={['.jpg', '.jpeg', '.png', '.webp', '.gif', '.bmp']} maxFileSizeMB={50} onFilesSelected={handleFileSelected}
          title={mode === 'flip' ? 'Bild zum Spiegeln ablegen' : 'Bild zum Drehen ablegen'}
          subtitle={mode === 'flip' ? 'Horizontal oder vertikal spiegeln' : 'In 90-Grad-Schritten oder auf einen genauen Winkel drehen'} />
      ) : (
        <div className="bg-white rounded-2xl border border-slate-200 p-4 sm:p-6 shadow-sm space-y-4">
          <div className="flex flex-col items-center gap-4">
            <canvas ref={canvasRef} className="rounded-xl border border-slate-200 bg-slate-50 max-w-full" style={{ maxHeight: '360px' }} />
            <div className="text-xs text-slate-500">Ausgangsgroesse: {file?.name} &mdash; {formatBytes(file!.size)} | Ergebnis: <strong className="text-slate-800 font-mono">{sw} x {sh} px</strong></div>
          </div>

          {/* Rotate controls */}
          <div className="space-y-3">
            <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider">Drehen</label>
            <div className="flex flex-wrap gap-2">
              <button type="button" onClick={rotateLeft} className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg border border-slate-200 hover:border-sky-400 text-sm font-semibold text-slate-700 transition-colors">
                <RotateCcw className="w-4 h-4" /> 90° links
              </button>
              <button type="button" onClick={rotateRight} className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg border border-slate-200 hover:border-sky-400 text-sm font-semibold text-slate-700 transition-colors">
                <RotateCw className="w-4 h-4" /> 90° rechts
              </button>
              {[0, 90, 180, 270].map((deg) => (
                <button key={deg} type="button" onClick={() => setRotationDeg(deg)}
                  className={'px-3 py-2 rounded-lg border text-xs font-semibold transition-colors ' + (rotation === deg ? 'border-sky-500 bg-sky-50 text-sky-700' : 'border-slate-200 text-slate-600 hover:border-sky-400')}>
                  {deg}deg
                </button>
              ))}
            </div>
          </div>

          {/* Flip controls */}
          <div className="space-y-3">
            <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider">Spiegeln</label>
            <div className="flex flex-wrap gap-2">
              <button type="button" onClick={() => setFlipH((v) => !v)}
                className={'inline-flex items-center gap-1.5 px-4 py-2 rounded-lg border text-sm font-semibold transition-colors ' + (flipH ? 'border-sky-500 bg-sky-50 text-sky-700' : 'border-slate-200 text-slate-700 hover:border-sky-400')}>
                <FlipHorizontal className="w-4 h-4" /> Horizontal
              </button>
              <button type="button" onClick={() => setFlipV((v) => !v)}
                className={'inline-flex items-center gap-1.5 px-4 py-2 rounded-lg border text-sm font-semibold transition-colors ' + (flipV ? 'border-sky-500 bg-sky-50 text-sky-700' : 'border-slate-200 text-slate-700 hover:border-sky-400')}>
                <FlipVertical className="w-4 h-4" /> Vertikal
              </button>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row items-center justify-between gap-3 pt-2 border-t border-slate-100">
            <button onClick={handleReset} className="text-xs text-slate-500 hover:text-slate-800 font-medium">Anderes Bild</button>
            <button onClick={executeProcess}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm shadow-sm transition-colors">
              <RotateCw className="w-4 h-4" />
              {mode === 'flip' ? 'Bild spiegeln' : 'Bild drehen & herunterladen'}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

