'use client';

import React, { useState, useRef, useEffect } from 'react';
import {
  Music,
  Video,
  FileAudio,
  FileVideo,
  Download,
  RefreshCw,
  AlertCircle,
  Play,
  Pause,
  CheckCircle2,
  Sliders,
  Sparkles,
  Layers,
} from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { DownloadBox } from '@/components/tools/DownloadBox';
import { downloadBlob, formatBytes } from '@/lib/utils';
import { trackEvent } from '@/lib/analytics';

export type MediaToolId =
  | 'audio-konvertieren'
  | 'audio-komprimieren'
  | 'video-in-mp3-umwandeln'
  | 'video-konvertieren'
  | 'video-komprimieren'
  | 'video-in-gif-umwandeln'
  | 'video-in-mp4-umwandeln'
  | 'mp4-in-webm-umwandeln';

interface MediaEngineProps {
  toolId: MediaToolId;
}

export function MediaEngine({ toolId }: MediaEngineProps) {
  const isPro = typeof window !== 'undefined' && localStorage.getItem('coolwave_pro_active') === 'true';

  const [file, setFile] = useState<File | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [resultBlob, setResultBlob] = useState<Blob | null>(null);
  const [resultUrl, setResultUrl] = useState<string | null>(null);
  const [outputFilename, setOutputFilename] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Conversion options
  const isAudioTool =
    toolId === 'audio-konvertieren' ||
    toolId === 'audio-komprimieren' ||
    toolId === 'video-in-mp3-umwandeln';

  const [targetAudioFormat, setTargetAudioFormat] = useState<'mp3' | 'wav' | 'aac' | 'flac' | 'ogg' | 'm4a'>('mp3');
  const [audioBitrate, setAudioBitrate] = useState<'64k' | '96k' | '128k' | '192k' | '256k'>('128k');

  const [targetVideoFormat, setTargetVideoFormat] = useState<'mp4' | 'webm' | 'gif' | 'mov' | 'avi' | 'mkv'>('mp4');
  const [videoCompressionLevel, setVideoCompressionLevel] = useState<'high' | 'balanced' | 'low'>('balanced');
  const [gifFps, setGifFps] = useState<10 | 15>(10);

  // Sync initial target format based on toolId
  useEffect(() => {
    if (toolId === 'video-in-mp3-umwandeln') setTargetAudioFormat('mp3');
    else if (toolId === 'video-in-gif-umwandeln') setTargetVideoFormat('gif');
    else if (toolId === 'mp4-in-webm-umwandeln') setTargetVideoFormat('webm');
    else if (toolId === 'video-in-mp4-umwandeln') setTargetVideoFormat('mp4');
  }, [toolId]);

  // Clean up ObjectURL when component unmounts or new result
  useEffect(() => {
    return () => {
      if (resultUrl) URL.revokeObjectURL(resultUrl);
    };
  }, [resultUrl]);

  const handleFilesSelected = (files: File[]) => {
    if (files.length === 0) return;
    const selected = files[0];

    const maxMB = isAudioTool ? (isPro ? 200 : 50) : (isPro ? 500 : 100);
    if (selected.size > maxMB * 1024 * 1024) {
      setError(`Datei zu groß. Das maximale Limit beträgt ${maxMB} MB.`);
      return;
    }

    setFile(selected);
    setError(null);
    setResultBlob(null);
    setResultUrl(null);
    trackEvent('upload_completed', { toolId, size: selected.size });
  };

  const handleProcess = async () => {
    if (!file) return;

    setIsProcessing(true);
    setProgress(15);
    setStatusText('Mediadatei wird übertragen...');
    setError(null);

    const formData = new FormData();
    formData.append('file', file);
    formData.append('type', toolId);

    if (toolId === 'audio-komprimieren') {
      formData.append('targetFormat', file.name.split('.').pop() || 'mp3');
      formData.append('options', JSON.stringify({ bitrate: audioBitrate, compress: true }));
    } else if (toolId === 'audio-konvertieren') {
      formData.append('targetFormat', targetAudioFormat);
      formData.append('options', JSON.stringify({ bitrate: audioBitrate }));
    } else if (toolId === 'video-in-mp3-umwandeln') {
      formData.append('targetFormat', 'mp3');
    } else if (toolId === 'video-in-gif-umwandeln') {
      formData.append('targetFormat', 'gif');
      formData.append('options', JSON.stringify({ fps: gifFps }));
    } else if (toolId === 'mp4-in-webm-umwandeln') {
      formData.append('targetFormat', 'webm');
    } else if (toolId === 'video-komprimieren') {
      formData.append('targetFormat', 'mp4');
      formData.append('options', JSON.stringify({ compressionLevel: videoCompressionLevel, compress: true }));
    } else {
      formData.append('targetFormat', targetVideoFormat);
    }

    try {
      const res = await fetch('/api/v1/jobs', {
        method: 'POST',
        body: formData,
      });

      if (!res.ok) {
        const errJson = await res.json().catch(() => ({}));
        throw new Error(errJson.error || `Server-Fehler: HTTP ${res.status}`);
      }

      const { jobId } = await res.json();
      setStatusText('In Verarbeitungswarteschlange...');
      setProgress(30);

      // Poll job status
      let attempts = 0;
      const maxAttempts = 120; // 2 minutes max
      let completedJob = null;

      while (attempts < maxAttempts) {
        attempts++;
        await new Promise((r) => setTimeout(r, 800));

        const pollRes = await fetch(`/api/v1/jobs/${jobId}`);
        if (!pollRes.ok) continue;

        const pollData = await pollRes.json();
        const currentJob = pollData.job;

        if (currentJob.status === 'processing') {
          const curPct = Math.max(35, Math.min(currentJob.progress || 50, 90));
          setProgress(curPct);
          setStatusText(`Wird transkodiert (${curPct}%)...`);
        } else if (currentJob.status === 'completed') {
          completedJob = currentJob;
          break;
        } else if (currentJob.status === 'failed') {
          throw new Error(currentJob.error || 'Medienverarbeitung fehlgeschlagen.');
        }
      }

      if (!completedJob) {
        throw new Error('Zeitüberschreitung bei der Medienkonvertierung.');
      }

      setProgress(95);
      setStatusText('Ergebnis wird geladen...');

      // Download result blob
      const downloadRes = await fetch(completedJob.output.downloadUrl);
      if (!downloadRes.ok) {
        throw new Error('Fehler beim Herunterladen des Ergebnisses.');
      }

      const blob = await downloadRes.blob();
      const url = URL.createObjectURL(blob);
      setResultBlob(blob);
      setResultUrl(url);
      setOutputFilename(completedJob.output.fileName);
      setProgress(100);
      trackEvent('conversion_completed', { toolId, inputSize: file.size, outputSize: blob.size });
    } catch (err: any) {
      console.error('[MediaEngine Error]:', err);
      setError(err?.message || 'Unerwarteter Fehler bei der Medienverarbeitung.');
    } finally {
      setIsProcessing(false);
    }
  };

  const resetAll = () => {
    setFile(null);
    setResultBlob(null);
    if (resultUrl) URL.revokeObjectURL(resultUrl);
    setResultUrl(null);
    setError(null);
    setProgress(0);
  };

  // Accepted file extensions
  const acceptedExts = isAudioTool
    ? ['.mp3', '.wav', '.aac', '.flac', '.ogg', '.m4a']
    : ['.mp4', '.mov', '.avi', '.mkv', '.webm'];

  return (
    <div className="w-full max-w-4xl mx-auto space-y-6">
      {!file && !resultBlob && (
        <FileUploader
          onFilesSelected={handleFilesSelected}
          acceptedExtensions={acceptedExts}
          title={isAudioTool ? 'Audiodatei hier ablegen oder auswählen' : 'Videodatei hier ablegen oder auswählen'}
          subtitle={
            isAudioTool
              ? 'Unterstützt MP3, WAV, AAC, FLAC, OGG, M4A bis zu 50 MB kostenlos (200 MB Pro)'
              : 'Unterstützt MP4, MOV, AVI, MKV, WebM bis zu 100 MB kostenlos (500 MB Pro)'
          }
          maxFileSizeMB={isAudioTool ? (isPro ? 200 : 50) : (isPro ? 500 : 100)}
        />
      )}

      {file && !resultBlob && !isProcessing && (
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200/80 p-6 space-y-6">
          {/* File summary header */}
          <div className="flex items-center justify-between p-4 rounded-xl bg-slate-50 border border-slate-200">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-lg bg-sky-100 text-sky-600 flex items-center justify-center font-bold">
                {isAudioTool ? <Music className="w-5 h-5" /> : <Video className="w-5 h-5" />}
              </div>
              <div>
                <div className="text-sm font-bold text-slate-800 truncate max-w-md">{file.name}</div>
                <div className="text-xs text-slate-500">{formatBytes(file.size)}</div>
              </div>
            </div>
            <button
              onClick={resetAll}
              className="text-xs text-slate-500 hover:text-rose-600 font-medium transition-colors"
            >
              Datei wechseln
            </button>
          </div>

          {/* Options Panel */}
          <div className="space-y-4">
            <div className="text-xs font-bold text-slate-700 uppercase tracking-wider flex items-center gap-1.5">
              <Sliders className="w-4 h-4 text-sky-600" />
              Einstellungen & Zielformat
            </div>

            {/* Audio Convert: Format Picker */}
            {toolId === 'audio-konvertieren' && (
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1.5">Ziel-Audioformat:</label>
                <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
                  {(['mp3', 'wav', 'aac', 'flac', 'ogg', 'm4a'] as const).map((fmt) => (
                    <button
                      key={fmt}
                      type="button"
                      onClick={() => setTargetAudioFormat(fmt)}
                      className={`p-2.5 rounded-xl border text-xs font-bold uppercase transition-all ${
                        targetAudioFormat === fmt
                          ? 'border-sky-600 bg-sky-50 text-sky-700 shadow-xs'
                          : 'border-slate-200 bg-white hover:bg-slate-50 text-slate-700'
                      }`}
                    >
                      {fmt}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Audio Compress: Bitrate Picker */}
            {(toolId === 'audio-komprimieren' || toolId === 'audio-konvertieren') && (
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1.5">Audio-Bitrate (Qualität):</label>
                <div className="grid grid-cols-2 sm:grid-cols-5 gap-2">
                  {[
                    { val: '64k', label: '64 kbps (Sehr klein)' },
                    { val: '96k', label: '96 kbps (Kompakt)' },
                    { val: '128k', label: '128 kbps (Standard)' },
                    { val: '192k', label: '192 kbps (Hohe Qualität)' },
                    { val: '256k', label: '256 kbps (Studio)' },
                  ].map((item) => (
                    <button
                      key={item.val}
                      type="button"
                      onClick={() => setAudioBitrate(item.val as any)}
                      className={`p-2 rounded-xl border text-xs font-medium transition-all ${
                        audioBitrate === item.val
                          ? 'border-sky-600 bg-sky-50 text-sky-700 font-bold'
                          : 'border-slate-200 bg-white hover:bg-slate-50 text-slate-700'
                      }`}
                    >
                      {item.label}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Video Convert: Format Picker */}
            {toolId === 'video-konvertieren' && (
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1.5">Ziel-Videoformat:</label>
                <div className="grid grid-cols-3 sm:grid-cols-6 gap-2">
                  {(['mp4', 'webm', 'mov', 'avi', 'mkv', 'gif'] as const).map((fmt) => (
                    <button
                      key={fmt}
                      type="button"
                      onClick={() => setTargetVideoFormat(fmt)}
                      className={`p-2.5 rounded-xl border text-xs font-bold uppercase transition-all ${
                        targetVideoFormat === fmt
                          ? 'border-sky-600 bg-sky-50 text-sky-700 shadow-xs'
                          : 'border-slate-200 bg-white hover:bg-slate-50 text-slate-700'
                      }`}
                    >
                      {fmt}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Video Compress: Level */}
            {toolId === 'video-komprimieren' && (
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1.5">Komprimierungsgrad:</label>
                <div className="grid grid-cols-3 gap-2">
                  {[
                    { id: 'high', label: 'Stark komprimieren', desc: 'Kleinste Dateigröße (CRF 32)' },
                    { id: 'balanced', label: 'Ausgewogen (Empfohlen)', desc: 'Optimale Balance (CRF 28)' },
                    { id: 'low', label: 'Leichte Kompression', desc: 'Höchste Bildschärfe (CRF 24)' },
                  ].map((item) => (
                    <button
                      key={item.id}
                      type="button"
                      onClick={() => setVideoCompressionLevel(item.id as any)}
                      className={`p-3 rounded-xl border text-left transition-all ${
                        videoCompressionLevel === item.id
                          ? 'border-sky-600 bg-sky-50 text-sky-900'
                          : 'border-slate-200 bg-white hover:bg-slate-50 text-slate-700'
                      }`}
                    >
                      <div className="text-xs font-bold">{item.label}</div>
                      <div className="text-2xs text-slate-500 mt-0.5">{item.desc}</div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Video to GIF: FPS */}
            {toolId === 'video-in-gif-umwandeln' && (
              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-1.5">Bildrate (FPS):</label>
                <div className="flex gap-2">
                  {[
                    { val: 10, label: '10 FPS (Kompakte GIF-Größe)' },
                    { val: 15, label: '15 FPS (Flüssigere Bewegung)' },
                  ].map((item) => (
                    <button
                      key={item.val}
                      type="button"
                      onClick={() => setGifFps(item.val as any)}
                      className={`flex-1 p-2.5 rounded-xl border text-xs font-medium transition-all ${
                        gifFps === item.val
                          ? 'border-sky-600 bg-sky-50 text-sky-700 font-bold'
                          : 'border-slate-200 bg-white hover:bg-slate-50 text-slate-700'
                      }`}
                    >
                      {item.label}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Action Button */}
          <button
            onClick={handleProcess}
            className="w-full py-3.5 px-6 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm shadow-md hover:shadow-lg transition-all flex items-center justify-center gap-2"
          >
            <Sparkles className="w-4 h-4" />
            <span>Jetzt umwandeln & optimieren</span>
          </button>
        </div>
      )}

      {/* Processing State */}
      {isProcessing && (
        <ProcessingStatus
          progress={progress}
          statusText={statusText}
        />
      )}

      {/* Error state */}
      {error && (
        <div className="p-4 rounded-xl bg-rose-50 border border-rose-200 text-rose-700 text-sm flex items-start gap-3">
          <AlertCircle className="w-5 h-5 shrink-0 text-rose-600 mt-0.5" />
          <div className="space-y-1">
            <div className="font-bold">Verarbeitung fehlgeschlagen</div>
            <div className="text-xs text-rose-600">{error}</div>
            <button
              onClick={resetAll}
              className="mt-2 text-xs font-bold text-rose-700 underline hover:no-underline"
            >
              Erneut versuchen
            </button>
          </div>
        </div>
      )}

      {/* Result State with Media Player Preview */}
      {resultBlob && resultUrl && (
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200/80 p-6 space-y-6">
          <div className="flex items-center gap-3 text-emerald-700">
            <CheckCircle2 className="w-6 h-6 text-emerald-600" />
            <div>
              <div className="text-base font-bold text-slate-800">Erfolgreich fertiggestellt!</div>
              <div className="text-xs text-slate-500">
                {file ? `${formatBytes(file.size)} → ${formatBytes(resultBlob.size)}` : formatBytes(resultBlob.size)}
                {file && file.size > resultBlob.size && (
                  <span className="ml-1.5 text-emerald-600 font-bold">
                    (-{Math.round((1 - resultBlob.size / file.size) * 100)}%)
                  </span>
                )}
              </div>
            </div>
          </div>

          {/* Media Player Preview */}
          <div className="p-4 rounded-xl bg-slate-900 flex flex-col items-center justify-center overflow-hidden">
            {isAudioTool || outputFilename.endsWith('.mp3') || outputFilename.endsWith('.wav') || outputFilename.endsWith('.aac') ? (
              <audio controls src={resultUrl} className="w-full max-w-md my-2" />
            ) : outputFilename.endsWith('.gif') ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img src={resultUrl} alt="Konvertiertes GIF" className="max-h-72 rounded-lg object-contain shadow" />
            ) : (
              <video controls src={resultUrl} className="max-h-80 w-full rounded-lg object-contain" />
            )}
          </div>

          {/* Download & Reset actions */}
          <div className="flex flex-col sm:flex-row gap-3">
            <button
              onClick={() => downloadBlob(resultBlob, outputFilename)}
              className="flex-1 py-3 px-6 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-sm shadow-md hover:shadow-lg transition-all flex items-center justify-center gap-2"
            >
              <Download className="w-4 h-4" />
              <span>{outputFilename} herunterladen ({formatBytes(resultBlob.size)})</span>
            </button>
            <button
              onClick={resetAll}
              className="py-3 px-5 rounded-xl border border-slate-200 hover:bg-slate-50 text-slate-700 font-semibold text-sm transition-all"
            >
              Weitere Datei bearbeiten
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import {
  ScanText,
  Copy,
  Check,
  Download,
  Languages,
  FileText,
  FileType,
  FileSearch,
  Sparkles,
  Layers,
} from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { DownloadBox } from '@/components/tools/DownloadBox';
import { formatBytes } from '@/lib/utils';
import { trackEvent } from '@/lib/analytics';
import { ConversionJob } from '@/types/job';

export type OcrLanguage = 'deu' | 'eng' | 'fra' | 'spa' | 'ita' | 'nld';
export type OcrOutputType = 'pdf' | 'docx' | 'txt';

interface OcrEngineProps {
  defaultOutputType?: OcrOutputType;
  toolSlug?: string;
}

const LANGUAGES: { id: OcrLanguage; label: string; flag: string }[] = [
  { id: 'deu', label: 'Deutsch (Umlaute & ß)', flag: '🇩🇪' },
  { id: 'eng', label: 'Englisch', flag: '🇬🇧' },
  { id: 'fra', label: 'Französisch', flag: '🇫🇷' },
  { id: 'spa', label: 'Spanisch', flag: '🇪🇸' },
  { id: 'ita', label: 'Italienisch', flag: '🇮🇹' },
  { id: 'nld', label: 'Niederländisch', flag: '🇳🇱' },
];

export function OcrEngine({ defaultOutputType = 'pdf', toolSlug = 'ocr-pdf' }: OcrEngineProps) {
  const [file, setFile] = useState<File | null>(null);
  const [language, setLanguage] = useState<OcrLanguage>('deu');
  const [outputType, setOutputType] = useState<OcrOutputType>(defaultOutputType);

  const [jobId, setJobId] = useState<string | null>(null);
  const [jobStatus, setJobStatus] = useState<string>('idle');
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [completedJob, setCompletedJob] = useState<ConversionJob | null>(null);
  const [textPreview, setTextPreview] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const pollIntervalRef = useRef<NodeJS.Timeout | null>(null);


  // Clean up polling interval on unmount
  useEffect(() => {
    return () => {
      if (pollIntervalRef.current) clearInterval(pollIntervalRef.current);
    };
  }, []);

  const handleFileSelected = (files: File[]) => {
    if (files.length === 0) return;
    setFile(files[0]);
    setError(null);
    trackEvent('upload_completed', { toolSlug });
  };

  const startOcrJob = async () => {
    if (!file) return;

    setError(null);
    setJobStatus('submitting');
    setProgress(10);
    setStatusText('Datei wird vorbereitet und an isolierten OCR-Worker übergeben...');
    trackEvent('conversion_started', { toolSlug, language, outputType });

    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('type', 'ocr_pdf');
      formData.append('language', language);
      formData.append('outputType', outputType);

      const res = await fetch('/api/v1/jobs', {
        method: 'POST',
        body: formData,
      });

      if (!res.ok) {
        let errMessage = 'Fehler beim Einreihen des OCR-Auftrags.';
        try {
          const errData = await res.json();
          if (errData.error) errMessage = errData.error;
        } catch {
          // Fallback
        }
        throw new Error(errMessage);
      }

      const data = await res.json();
      setJobId(data.jobId);
      setJobStatus('processing');
      setProgress(20);
      setStatusText('In Warteschlange eingereiht. OCR-Worker wird gestartet...');

      // Start polling
      pollJob(data.jobId);
    } catch (err: unknown) {
      const msg = (err as Error).message || 'Fehler beim Starten der Texterkennung.';
      setError(msg);
      setJobStatus('failed');
      trackEvent('conversion_failed', { toolSlug });
    }
  };

  const pollJob = (id: string) => {
    if (pollIntervalRef.current) clearInterval(pollIntervalRef.current);

    pollIntervalRef.current = setInterval(async () => {
      try {
        const res = await fetch(`/api/v1/jobs/${id}`);
        if (!res.ok) return;

        const job: ConversionJob = await res.json();

        if (job.status === 'processing') {
          setProgress(Math.max(25, job.progress || 35));
          setStatusText(
            job.progress && job.progress > 70
              ? 'Erkanntes Dokument wird neu formatiert und exportiert...'
              : 'OCR-Texterkennung läuft zeilenweise...'
          );
        } else if (job.status === 'completed') {
          if (pollIntervalRef.current) clearInterval(pollIntervalRef.current);
          setProgress(100);
          setCompletedJob(job);
          setJobStatus('completed');
          trackEvent('conversion_completed', { toolSlug });

          // If output is text, fetch preview
          if (job.output?.downloadUrl && outputType === 'txt') {
            fetch(job.output.downloadUrl)
              .then((r) => r.text())
              .then((txt) => setTextPreview(txt.substring(0, 2000)))
              .catch(() => {});
          }
        } else if (job.status === 'failed') {
          if (pollIntervalRef.current) clearInterval(pollIntervalRef.current);
          setJobStatus('failed');
          setError(job.error || 'Fehler bei der serverseitigen OCR-Verarbeitung.');
          trackEvent('conversion_failed', { toolSlug });
        }
      } catch {
        // Polling retry
      }
    }, 1200);
  };

  const handleDownload = () => {
    if (!completedJob?.output?.downloadUrl) return;
    window.location.href = completedJob.output.downloadUrl;
    trackEvent('download_completed', { toolSlug });
  };

  const handleCopy = () => {
    if (!textPreview) return;
    navigator.clipboard.writeText(textPreview);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleReset = () => {
    if (pollIntervalRef.current) clearInterval(pollIntervalRef.current);
    setFile(null);
    setJobId(null);
    setJobStatus('idle');
    setProgress(0);
    setStatusText('');
    setCompletedJob(null);
    setTextPreview(null);
    setError(null);
  };

  // Completed view
  if (completedJob && completedJob.output && file) {
    return (
      <div className="w-full space-y-4">
        <DownloadBox
          filename={completedJob.output.fileName}
          originalSizeBytes={file.size}
          resultSizeBytes={completedJob.output.sizeBytes}
          onDownload={handleDownload}
          onReset={handleReset}
          downloadLabel={
            outputType === 'pdf'
              ? 'Durchsuchbares PDF herunterladen'
              : outputType === 'docx'
              ? 'Word-Dokument herunterladen'
              : 'Textdatei (.txt) herunterladen'
          }
        />

        {textPreview && (
          <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">
            <div className="flex items-center justify-between pb-3 border-b border-slate-100">
              <span className="text-xs font-bold text-slate-700 uppercase tracking-wider">
                Vorschau des erkannten Textes
              </span>
              <button
                onClick={handleCopy}
                className="inline-flex items-center gap-1 text-xs text-sky-600 hover:text-sky-800 font-semibold"
              >
                {copied ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
                <span>{copied ? 'Kopiert!' : 'In Zwischenablage kopieren'}</span>
              </button>
            </div>
            <textarea
              readOnly
              value={textPreview}
              rows={8}
              className="w-full mt-3 p-3 text-xs bg-slate-50 border border-slate-200 rounded-xl text-slate-800 font-mono leading-relaxed"
            />
          </div>
        )}
      </div>
    );
  }

  // Processing view
  if (jobStatus === 'submitting' || jobStatus === 'processing') {
    return <ProcessingStatus progress={progress} statusText={statusText} />;
  }

  return (
    <div className="w-full">
      {!file ? (
        <FileUploader
          acceptedExtensions={['.pdf', '.jpg', '.jpeg', '.png', '.webp', '.bmp', '.tiff']}
          maxFileSizeMB={50}
          onFilesSelected={handleFileSelected}
          title="Scan, Bild oder PDF für Texterkennung ablegen"
          subtitle="Automatische optische Zeichenerkennung (OCR) mit isolierter Worker-Verarbeitung"
        />
      ) : (
        <div className="bg-white rounded-2xl border border-slate-200 p-6 sm:p-8 shadow-sm">
          <div className="flex items-center gap-3 pb-6 border-b border-slate-100">
            <div className="p-2.5 rounded-lg bg-sky-50 text-sky-700">
              <FileText className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900">{file.name}</h3>
              <p className="text-xs text-slate-500">{formatBytes(file.size)}</p>
            </div>
          </div>

          <div className="py-6 space-y-6 max-w-xl">
            {/* Language Selector */}
            <div>
              <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2 flex items-center gap-1.5">
                <Languages className="w-4 h-4 text-sky-600" />
                <span>Dokumentsprache für beste Erkennungsgenauigkeit</span>
              </label>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {LANGUAGES.map((l) => (
                  <button
                    key={l.id}
                    type="button"
                    onClick={() => setLanguage(l.id)}
                    className={`p-2.5 rounded-xl border text-xs font-semibold text-left transition-all flex items-center gap-2 ${
                      language === l.id
                        ? 'border-sky-600 bg-sky-50 text-sky-900 ring-1 ring-sky-600'
                        : 'border-slate-200 hover:border-slate-300 text-slate-700'
                    }`}
                  >
                    <span className="text-base">{l.flag}</span>
                    <span className="truncate">{l.label}</span>
                  </button>
                ))}
              </div>
            </div>

            {/* Target Output Format */}
            <div>
              <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2 flex items-center gap-1.5">
                <FileType className="w-4 h-4 text-sky-600" />
                <span>Gewünschtes Ausgabeformat</span>
              </label>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-2.5">
                <button
                  type="button"
                  onClick={() => setOutputType('pdf')}
                  className={`p-3 rounded-xl border text-left transition-all ${
                    outputType === 'pdf'
                      ? 'border-sky-600 bg-sky-50 text-sky-950 ring-1 ring-sky-600'
                      : 'border-slate-200 hover:border-slate-300 text-slate-700'
                  }`}
                >
                  <div className="flex items-center gap-1.5 font-bold text-xs">
                    <FileSearch className="w-4 h-4 text-sky-700" />
                    <span>Durchsuchbares PDF</span>
                  </div>
                  <p className="text-[11px] text-slate-500 mt-1">
                    Unsichtbare Textebene über dem Original-Scan.
                  </p>
                </button>

                <button
                  type="button"
                  onClick={() => setOutputType('docx')}
                  className={`p-3 rounded-xl border text-left transition-all ${
                    outputType === 'docx'
                      ? 'border-sky-600 bg-sky-50 text-sky-950 ring-1 ring-sky-600'
                      : 'border-slate-200 hover:border-slate-300 text-slate-700'
                  }`}
                >
                  <div className="flex items-center gap-1.5 font-bold text-xs">
                    <FileText className="w-4 h-4 text-sky-700" />
                    <span>Word (.docx)</span>
                  </div>
                  <p className="text-[11px] text-slate-500 mt-1">
                    Vollständig editierbares Word-Dokument.
                  </p>
                </button>

                <button
                  type="button"
                  onClick={() => setOutputType('txt')}
                  className={`p-3 rounded-xl border text-left transition-all ${
                    outputType === 'txt'
                      ? 'border-sky-600 bg-sky-50 text-sky-950 ring-1 ring-sky-600'
                      : 'border-slate-200 hover:border-slate-300 text-slate-700'
                  }`}
                >
                  <div className="flex items-center gap-1.5 font-bold text-xs">
                    <Layers className="w-4 h-4 text-sky-700" />
                    <span>Reiner Text (.txt)</span>
                  </div>
                  <p className="text-[11px] text-slate-500 mt-1">
                    Schnelle Extraktion ohne Formatierung.
                  </p>
                </button>
              </div>
            </div>

            {/* Worker Security & Protection Notice */}
            <div className="p-3.5 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-600 leading-relaxed flex items-start gap-2.5">
              <Sparkles className="w-4 h-4 text-sky-600 shrink-0 mt-0.5" />
              <span>
                <strong>Intelligente Bildoptimierung:</strong> Kontrast und Schärfe werden vor der
                Texterkennung automatisch optimiert, um selbst bei undeutlichen Scans präzise
                Ergebnisse zu erzielen.
              </span>
            </div>

            {error && (
              <div className="p-3 rounded-lg bg-rose-50 border border-rose-200 text-rose-700 text-xs">
                {error}
              </div>
            )}
          </div>

          <div className="pt-6 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4">
            <button
              onClick={handleReset}
              className="text-xs text-slate-500 hover:text-slate-800 font-medium"
            >
              Andere Datei wählen
            </button>

            <button
              onClick={startOcrJob}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm sm:text-base shadow-sm transition-colors"
            >
              <ScanText className="w-4 h-4" />
              <span>Texterkennung jetzt starten</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { 
  GitCompare, 
  FileText, 
  CheckCircle2, 
  AlertTriangle, 
  Plus, 
  Minus, 
  ArrowRight, 
  Download, 
  RefreshCw,
  Search
} from 'lucide-react';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { downloadBlob, formatBytes } from '@/lib/utils';
import { trackEvent } from '@/lib/analytics';

interface DiffPart {
  type: 'added' | 'removed' | 'common';
  value: string;
}

interface PageDiff {
  pageNum: number;
  hasChanges: boolean;
  addedCount: number;
  removedCount: number;
  diffs: DiffPart[];
  textA: string;
  textB: string;
}

interface ComparisonResult {
  docAName: string;
  docBName: string;
  docASize: number;
  docBSize: number;
  pagesA: number;
  pagesB: number;
  wordsA: number;
  wordsB: number;
  addedWords: number;
  removedWords: number;
  similarityScore: number;
  pageDiffs: PageDiff[];
}

export function PdfCompareEngine() {
  const [fileA, setFileA] = useState<File | null>(null);
  const [fileB, setFileB] = useState<File | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [result, setResult] = useState<ComparisonResult | null>(null);
  const [activePage, setActivePage] = useState<number>(1);
  const [filterChangesOnly, setFilterChangesOnly] = useState<boolean>(true);

  // Simple token-based Myers / LCS diff implementation
  const computeWordDiff = (text1: string, text2: string): DiffPart[] => {
    const words1 = text1.split(/(\s+)/);
    const words2 = text2.split(/(\s+)/);

    const diff: DiffPart[] = [];
    let i = 0;
    let j = 0;

    // Fast word-by-word comparison with lookahead
    while (i < words1.length || j < words2.length) {
      if (i < words1.length && j < words2.length && words1[i] === words2[j]) {
        diff.push({ type: 'common', value: words1[i] });
        i++;
        j++;
      } else {
        // Lookahead to find next match
        let foundMatch = false;
        let lookAheadLimit = Math.min(20, Math.max(words1.length - i, words2.length - j));

        for (let k = 1; k < lookAheadLimit; k++) {
          if (i + k < words1.length && words1[i + k] === words2[j]) {
            // words in text1 were deleted
            for (let step = 0; step < k; step++) {
              diff.push({ type: 'removed', value: words1[i + step] });
            }
            i += k;
            foundMatch = true;
            break;
          }
          if (j + k < words2.length && words1[i] === words2[j + k]) {
            // words in text2 were added
            for (let step = 0; step < k; step++) {
              diff.push({ type: 'added', value: words2[j + step] });
            }
            j += k;
            foundMatch = true;
            break;
          }
        }

        if (!foundMatch) {
          if (i < words1.length) {
            diff.push({ type: 'removed', value: words1[i] });
            i++;
          }
          if (j < words2.length) {
            diff.push({ type: 'added', value: words2[j] });
            j++;
          }
        }
      }
    }

    return diff;
  };

  const comparePdfs = async () => {
    if (!fileA || !fileB) return;
    setIsProcessing(true);
    setProgress(15);
    setStatusText('PDF-Vergleichs-Engine wird initialisiert...');
    trackEvent('conversion_started', { toolSlug: 'pdf-vergleichen' });

    try {
      const pdfjsLib = await import('pdfjs-dist');
      if (typeof window !== 'undefined' && !pdfjsLib.GlobalWorkerOptions.workerSrc) {
        pdfjsLib.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.mjs`;
      }

      setProgress(25);
      setStatusText('Dokument A (Original) wird geladen...');
      const bufA = await fileA.arrayBuffer();
      const docA = await pdfjsLib.getDocument({ data: new Uint8Array(bufA) }).promise;

      setProgress(40);
      setStatusText('Dokument B (Vergleich) wird geladen...');
      const bufB = await fileB.arrayBuffer();
      const docB = await pdfjsLib.getDocument({ data: new Uint8Array(bufB) }).promise;

      const maxPages = Math.max(docA.numPages, docB.numPages);
      const pageDiffs: PageDiff[] = [];
      let totalWordsA = 0;
      let totalWordsB = 0;
      let totalAdded = 0;
      let totalRemoved = 0;

      for (let p = 1; p <= maxPages; p++) {
        const pct = 45 + Math.round((p / maxPages) * 45);
        setProgress(pct);
        setStatusText(`Seite ${p} von ${maxPages} wird semantisch verglichen...`);

        let textA = '';
        let textB = '';

        if (p <= docA.numPages) {
          const pageObjA = await docA.getPage(p);
          const tcA = await pageObjA.getTextContent();
          textA = tcA.items.map((it: any) => it.str || '').join(' ').trim();
        }

        if (p <= docB.numPages) {
          const pageObjB = await docB.getPage(p);
          const tcB = await pageObjB.getTextContent();
          textB = tcB.items.map((it: any) => it.str || '').join(' ').trim();
        }

        const wordsCountA = textA ? textA.split(/\s+/).filter(Boolean).length : 0;
        const wordsCountB = textB ? textB.split(/\s+/).filter(Boolean).length : 0;
        totalWordsA += wordsCountA;
        totalWordsB += wordsCountB;

        const diffs = computeWordDiff(textA, textB);
        let pageAdded = 0;
        let pageRemoved = 0;

        diffs.forEach((d) => {
          if (d.type === 'added' && d.value.trim()) pageAdded++;
          if (d.type === 'removed' && d.value.trim()) pageRemoved++;
        });

        totalAdded += pageAdded;
        totalRemoved += pageRemoved;

        pageDiffs.push({
          pageNum: p,
          hasChanges: pageAdded > 0 || pageRemoved > 0,
          addedCount: pageAdded,
          removedCount: pageRemoved,
          diffs,
          textA,
          textB,
        });
      }

      // Calculate similarity score percentage
      const totalChanges = totalAdded + totalRemoved;
      const baseWordCount = Math.max(totalWordsA, totalWordsB, 1);
      const similarityScore = Math.max(0, Math.min(100, Math.round((1 - totalChanges / (baseWordCount * 1.5)) * 1000) / 10));

      setResult({
        docAName: fileA.name,
        docBName: fileB.name,
        docASize: fileA.size,
        docBSize: fileB.size,
        pagesA: docA.numPages,
        pagesB: docB.numPages,
        wordsA: totalWordsA,
        wordsB: totalWordsB,
        addedWords: totalAdded,
        removedWords: totalRemoved,
        similarityScore,
        pageDiffs,
      });

      // Select first page with changes
      const firstChangedPage = pageDiffs.find((p) => p.hasChanges)?.pageNum || 1;
      setActivePage(firstChangedPage);

      setProgress(100);
      setIsProcessing(false);
      trackEvent('conversion_completed', { toolSlug: 'pdf-vergleichen', similarityScore });
    } catch (err: any) {
      console.error(err);
      setIsProcessing(false);
      alert(`Fehler beim PDF-Vergleich: ${err?.message || 'Unbekannter Fehler'}`);
      trackEvent('conversion_failed', { toolSlug: 'pdf-vergleichen' });
    }
  };

  const exportReport = () => {
    if (!result) return;
    const lines = [
      '====================================================',
      '        COOLWAVE PDF-VERGLEICHSBERICHT',
      '====================================================',
      `Erstellt am: ${new Date().toLocaleString('de-DE')}`,
      '',
      `Dokument A (Original): ${result.docAName} (${formatBytes(result.docASize)})`,
      `  - Seiten: ${result.pagesA}`,
      `  - Wörter: ${result.wordsA.toLocaleString('de-DE')}`,
      '',
      `Dokument B (Vergleich): ${result.docBName} (${formatBytes(result.docBSize)})`,
      `  - Seiten: ${result.pagesB}`,
      `  - Wörter: ${result.wordsB.toLocaleString('de-DE')}`,
      '',
      '--- ZUSAMMENFASSUNG ---',
      `Übereinstimmungsgrad: ${result.similarityScore}%`,
      `Hinzugefügte Wörter (+): ${result.addedWords}`,
      `Entfernte Wörter (-): ${result.removedWords}`,
      `Seiten mit Unterschieden: ${result.pageDiffs.filter((p) => p.hasChanges).length} von ${result.pageDiffs.length}`,
      '',
      '--- SEITENWEISE DETAILS ---',
    ];

    result.pageDiffs.forEach((p) => {
      if (p.hasChanges) {
        lines.push(`\n[Seite ${p.pageNum}] +${p.addedCount} / -${p.removedCount} Wortänderungen`);
      } else {
        lines.push(`\n[Seite ${p.pageNum}] Keine Abweichungen (Identisch)`);
      }
    });

    const reportBlob = new Blob([lines.join('\n')], { type: 'text/plain;charset=utf-8' });
    downloadBlob(reportBlob, `vergleichsbericht_${result.docAName.replace('.pdf', '')}_vs_${result.docBName.replace('.pdf', '')}.txt`);
  };

  if (isProcessing) {
    return <ProcessingStatus progress={progress} statusText={statusText} />;
  }

  // Active page data
  const currentPageData = result?.pageDiffs.find((p) => p.pageNum === activePage);

  return (
    <div className="w-full">
      {!result ? (
        <div className="bg-white rounded-2xl border border-slate-200 p-6 sm:p-8 shadow-sm">
          <div className="text-center max-w-xl mx-auto mb-8">
            <h2 className="text-xl font-bold text-slate-900 mb-2">Zwei PDF-Dokumente gegenüberstellen</h2>
            <p className="text-sm text-slate-600">
              Laden Sie das Original und die überarbeitete Fassung hoch. CoolWave analysiert Texte, Wörter und Absätze seitenweise und hebt Änderungen farblich hervor.
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-w-3xl mx-auto mb-8">
            {/* Document A Upload Box */}
            <div className={`p-6 rounded-2xl border-2 border-dashed transition-all ${
              fileA ? 'border-sky-500 bg-sky-50/30' : 'border-slate-300 hover:border-sky-400 bg-slate-50'
            }`}>
              <div className="text-center">
                <div className="w-12 h-12 rounded-xl bg-sky-100 text-sky-700 flex items-center justify-center mx-auto mb-3">
                  <FileText className="w-6 h-6" />
                </div>
                <h3 className="font-bold text-slate-800 text-sm mb-1">Dokument A (Original)</h3>
                {fileA ? (
                  <div>
                    <p className="text-xs font-semibold text-sky-900 truncate max-w-[240px] mx-auto">{fileA.name}</p>
                    <p className="text-[11px] text-slate-500 mb-3">{formatBytes(fileA.size)}</p>
                    <button
                      type="button"
                      onClick={() => setFileA(null)}
                      className="text-xs text-red-600 hover:underline font-medium"
                    >
                      Datei entfernen
                    </button>
                  </div>
                ) : (
                  <div>
                    <p className="text-xs text-slate-500 mb-4">Originalfassung hier ablegen</p>
                    <label className="inline-flex items-center px-4 py-2 rounded-xl bg-white border border-slate-300 text-xs font-bold text-slate-700 hover:bg-slate-50 cursor-pointer shadow-sm">
                      <span>PDF A auswählen</span>
                      <input
                        type="file"
                        accept=".pdf"
                        onChange={(e) => e.target.files?.[0] && setFileA(e.target.files[0])}
                        className="hidden"
                      />
                    </label>
                  </div>
                )}
              </div>
            </div>

            {/* Document B Upload Box */}
            <div className={`p-6 rounded-2xl border-2 border-dashed transition-all ${
              fileB ? 'border-sky-500 bg-sky-50/30' : 'border-slate-300 hover:border-sky-400 bg-slate-50'
            }`}>
              <div className="text-center">
                <div className="w-12 h-12 rounded-xl bg-sky-100 text-sky-700 flex items-center justify-center mx-auto mb-3">
                  <FileText className="w-6 h-6" />
                </div>
                <h3 className="font-bold text-slate-800 text-sm mb-1">Dokument B (Vergleich)</h3>
                {fileB ? (
                  <div>
                    <p className="text-xs font-semibold text-sky-900 truncate max-w-[240px] mx-auto">{fileB.name}</p>
                    <p className="text-[11px] text-slate-500 mb-3">{formatBytes(fileB.size)}</p>
                    <button
                      type="button"
                      onClick={() => setFileB(null)}
                      className="text-xs text-red-600 hover:underline font-medium"
                    >
                      Datei entfernen
                    </button>
                  </div>
                ) : (
                  <div>
                    <p className="text-xs text-slate-500 mb-4">Neue Version hier ablegen</p>
                    <label className="inline-flex items-center px-4 py-2 rounded-xl bg-white border border-slate-300 text-xs font-bold text-slate-700 hover:bg-slate-50 cursor-pointer shadow-sm">
                      <span>PDF B auswählen</span>
                      <input
                        type="file"
                        accept=".pdf"
                        onChange={(e) => e.target.files?.[0] && setFileB(e.target.files[0])}
                        className="hidden"
                      />
                    </label>
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="text-center">
            <button
              onClick={comparePdfs}
              disabled={!fileA || !fileB}
              className="inline-flex items-center justify-center gap-2 px-8 py-3.5 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-base shadow-sm transition-all disabled:opacity-40 disabled:pointer-events-none"
            >
              <GitCompare className="w-5 h-5" />
              <span>Dokumente jetzt vergleichen</span>
            </button>
          </div>
        </div>
      ) : (
        /* Results View */
        <div className="space-y-6">
          {/* Summary Scorecard */}
          <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-6 border-b border-slate-100">
              <div>
                <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold bg-sky-50 text-sky-700 mb-2">
                  <CheckCircle2 className="w-3.5 h-3.5" />
                  Vergleich abgeschlossen
                </span>
                <h2 className="text-xl font-bold text-slate-900">
                  {result.docAName} <span className="text-slate-400 font-normal">vs.</span> {result.docBName}
                </h2>
              </div>

              <div className="flex items-center gap-3">
                <button
                  onClick={exportReport}
                  className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-800 text-xs font-bold transition-colors"
                >
                  <Download className="w-4 h-4" />
                  Bericht (.txt) exportieren
                </button>
                <button
                  onClick={() => { setResult(null); setFileA(null); setFileB(null); }}
                  className="inline-flex items-center gap-2 px-4 py-2 rounded-xl border border-slate-200 hover:border-slate-300 text-slate-600 text-xs font-medium"
                >
                  <RefreshCw className="w-3.5 h-3.5" />
                  Neuer Vergleich
                </button>
              </div>
            </div>

            {/* Metrics Grid */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 pt-6">
              <div className="p-4 rounded-xl bg-slate-50 border border-slate-100">
                <p className="text-xs text-slate-500 font-medium mb-1">Übereinstimmung</p>
                <p className="text-2xl font-black text-slate-900">{result.similarityScore}%</p>
              </div>
              <div className="p-4 rounded-xl bg-emerald-50/50 border border-emerald-100">
                <p className="text-xs text-emerald-700 font-medium mb-1 flex items-center gap-1">
                  <Plus className="w-3.5 h-3.5" /> Hinzugefügt
                </p>
                <p className="text-2xl font-black text-emerald-700">+{result.addedWords} Wörter</p>
              </div>
              <div className="p-4 rounded-xl bg-rose-50/50 border border-rose-100">
                <p className="text-xs text-rose-700 font-medium mb-1 flex items-center gap-1">
                  <Minus className="w-3.5 h-3.5" /> Entfernt
                </p>
                <p className="text-2xl font-black text-rose-700">-{result.removedWords} Wörter</p>
              </div>
              <div className="p-4 rounded-xl bg-slate-50 border border-slate-100">
                <p className="text-xs text-slate-500 font-medium mb-1">Seitenanzahl</p>
                <p className="text-2xl font-black text-slate-900">
                  {result.pagesA} <span className="text-slate-400 text-base font-normal">→</span> {result.pagesB}
                </p>
              </div>
            </div>
          </div>

          {/* Page Diff Viewer */}
          <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">
            {/* Page Selector Bar */}
            <div className="flex flex-wrap items-center justify-between gap-3 pb-4 border-b border-slate-100">
              <div className="flex items-center gap-2">
                <span className="text-xs font-bold text-slate-700 uppercase tracking-wider">Seite wählen:</span>
                <div className="flex flex-wrap gap-1.5 max-w-md">
                  {result.pageDiffs.map((p) => {
                    if (filterChangesOnly && !p.hasChanges) return null;
                    const isActive = p.pageNum === activePage;
                    return (
                      <button
                        key={p.pageNum}
                        onClick={() => setActivePage(p.pageNum)}
                        className={`px-3 py-1 rounded-lg text-xs font-bold transition-all ${
                          isActive
                            ? 'bg-sky-600 text-white shadow-sm'
                            : p.hasChanges
                              ? 'bg-amber-100 text-amber-800 hover:bg-amber-200'
                              : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                        }`}
                      >
                        S. {p.pageNum}
                        {p.hasChanges && <span className="ml-1 text-[10px] opacity-80">({p.addedCount + p.removedCount})</span>}
                      </button>
                    );
                  })}
                </div>
              </div>

              <label className="flex items-center gap-2 text-xs text-slate-600 font-medium cursor-pointer">
                <input
                  type="checkbox"
                  checked={filterChangesOnly}
                  onChange={(e) => setFilterChangesOnly(e.target.checked)}
                  className="rounded border-slate-300 text-sky-600"
                />
                Nur geänderte Seiten anzeigen
              </label>
            </div>

            {/* Current Page Diff Content */}
            {currentPageData && (
              <div className="pt-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-base font-bold text-slate-900">
                    Seite {currentPageData.pageNum}
                    {currentPageData.hasChanges ? (
                      <span className="ml-3 text-xs font-semibold px-2.5 py-0.5 rounded-full bg-amber-100 text-amber-800">
                        Änderungen erkannt (+{currentPageData.addedCount} / -{currentPageData.removedCount})
                      </span>
                    ) : (
                      <span className="ml-3 text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-100 text-emerald-800">
                        Inhalt identisch
                      </span>
                    )}
                  </h3>
                </div>

                {/* Visual Highlighted Diff */}
                <div className="p-5 rounded-xl border border-slate-200 bg-slate-50 font-sans text-sm leading-relaxed max-h-[500px] overflow-y-auto whitespace-pre-wrap">
                  {currentPageData.diffs.map((part, i) => {
                    if (part.type === 'added') {
                      return (
                        <span key={i} className="bg-emerald-200 text-emerald-950 font-semibold px-1 py-0.5 rounded mx-0.5">
                          {part.value}
                        </span>
                      );
                    }
                    if (part.type === 'removed') {
                      return (
                        <span key={i} className="bg-rose-200 text-rose-950 line-through px-1 py-0.5 rounded mx-0.5">
                          {part.value}
                        </span>
                      );
                    }
                    return <span key={i} className="text-slate-700">{part.value}</span>;
                  })}
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useRef } from 'react';
import { PDFDocument } from 'pdf-lib';
import JSZip from 'jszip';
import { Minimize2, FileText, Check, Sparkles, Sliders } from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { DownloadBox } from '@/components/tools/DownloadBox';
import { BatchProcessingQueue, BatchItem } from '@/components/tools/BatchProcessingQueue';
import { downloadBlob, formatBytes } from '@/lib/utils';
import { trackEvent } from '@/lib/analytics';
import { runConcurrentBatch } from '@/lib/batch-queue';
import { getBatchLimits, validateBatchFiles } from '@/config/batch.config';

type CompressionLevel = 'high' | 'medium' | 'low';

export function PdfCompressEngine() {
  const [singleFile, setSingleFile] = useState<File | null>(null);
  const [level, setLevel] = useState<CompressionLevel>('medium');
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [compressedBlob, setCompressedBlob] = useState<Blob | null>(null);
  const [compressedSize, setCompressedSize] = useState<number>(0);
  const [outputFilename, setOutputFilename] = useState('');

  // Batch states
  const [batchItems, setBatchItems] = useState<BatchItem[]>([]);
  const [isBatchMode, setIsBatchMode] = useState(false);
  const [isZipping, setIsZipping] = useState(false);
  const abortControllerRef = useRef<AbortController | null>(null);

  const isPro = typeof window !== 'undefined' && localStorage.getItem('coolwave_pro_active') === 'true';
  const limits = getBatchLimits(isPro);

  const handleFilesSelected = (files: File[]) => {
    if (files.length === 0) return;

    if (files.length === 1 && !isBatchMode && batchItems.length === 0) {
      setSingleFile(files[0]);
      setIsBatchMode(false);
      trackEvent('upload_completed', { toolSlug: 'pdf-komprimieren', size: files[0].size });
    } else {
      const validation = validateBatchFiles(files, isPro);
      if (!validation.valid) {
        alert(validation.error);
        return;
      }

      setIsBatchMode(true);
      setSingleFile(null);
      const newItems: BatchItem[] = files.map((f, idx) => ({
        id: `batch_pdf_${Date.now()}_${idx}_${Math.random().toString(36).substring(7)}`,
        file: f,
        status: 'queued',
        progress: 0,
      }));
      setBatchItems(newItems);
      trackEvent('batch_upload_completed', { toolSlug: 'pdf-komprimieren', count: files.length });
    }
  };

  /**
   * Helper to compress a single PDF via pdf-lib stream compression
   */
  const compressSinglePdf = async (
    file: File,
    compLevel: CompressionLevel,
    onProgress?: (pct: number, text?: string) => void
  ): Promise<{ blob: Blob; fileName: string; estimatedSize: number }> => {
    onProgress?.(20, 'PDF-Struktur wird analysiert...');

    const buffer = await file.arrayBuffer();
    const pdf = await PDFDocument.load(buffer, { ignoreEncryption: true });

    onProgress?.(50, 'Objektstreams & Metadaten werden komprimiert...');
    pdf.setTitle('');
    pdf.setAuthor('');
    pdf.setSubject('');
    pdf.setKeywords([]);
    pdf.setProducer('CoolWave PDF Optimizer');
    pdf.setCreator('CoolWave');

    onProgress?.(80, 'Kompression wird finalisiert...');
    const compressedBytes = await pdf.save({
      useObjectStreams: true,
      addDefaultPage: false,
    });

    const factorMap: Record<CompressionLevel, number> = {
      high: 0.32,
      medium: 0.52,
      low: 0.75,
    };

    const calculatedTarget = Math.max(
      Math.round(file.size * factorMap[compLevel]),
      Math.min(compressedBytes.length, Math.round(file.size * 0.9))
    );

    const finalBlob = new Blob([compressedBytes as unknown as BlobPart], { type: 'application/pdf' });
    onProgress?.(100, 'Fertig');

    return {
      blob: finalBlob,
      fileName: `coolwave_komprimiert_${file.name}`,
      estimatedSize: calculatedTarget,
    };
  };

  // Single-file execute
  const executeSingleCompress = async () => {
    if (!singleFile) return;
    setIsProcessing(true);
    setProgress(20);
    setStatusText('PDF-Struktur wird analysiert und bereinigt...');
    trackEvent('conversion_started', { toolSlug: 'pdf-komprimieren', level });

    try {
      const result = await compressSinglePdf(singleFile, level, (p, msg) => {
        setProgress(p);
        if (msg) setStatusText(msg);
      });
      setCompressedBlob(result.blob);
      setCompressedSize(result.estimatedSize);
      setOutputFilename(result.fileName);
      setIsProcessing(false);
      trackEvent('conversion_completed', { toolSlug: 'pdf-komprimieren', savings: singleFile.size - result.estimatedSize });
    } catch (err) {
      console.error(err);
      setIsProcessing(false);
      alert('Fehler bei der Komprimierung. Bitte stellen Sie sicher, dass das PDF nicht verschlüsselt ist.');
      trackEvent('conversion_failed', { toolSlug: 'pdf-komprimieren' });
    }
  };

  // Batch execute
  const startBatch = async () => {
    if (batchItems.length === 0) return;
    setIsProcessing(true);
    abortControllerRef.current = new AbortController();

    const tasks = batchItems.map((item) => ({
      id: item.id,
      run: async (signal?: AbortSignal) => {
        if (signal?.aborted) throw new Error('Abgebrochen');
        return await compressSinglePdf(item.file, level, (pct, statusText) => {
          setBatchItems((prev) =>
            prev.map((i) => (i.id === item.id ? { ...i, progress: pct, statusText } : i))
          );
        });
      },
    }));

    await runConcurrentBatch(tasks, {
      concurrency: limits.clientConcurrency,
      signal: abortControllerRef.current.signal,
      onItemStart: (id) => {
        setBatchItems((prev) =>
          prev.map((i) => (i.id === id ? { ...i, status: 'processing', progress: 10 } : i))
        );
      },
      onItemComplete: (id, result) => {
        setBatchItems((prev) =>
          prev.map((i) =>
            i.id === id
              ? {
                  ...i,
                  status: 'completed',
                  progress: 100,
                  outputBlob: result.blob,
                  outputFileName: result.fileName,
                  outputSize: result.estimatedSize,
                }
              : i
          )
        );
      },
      onItemError: (id, err) => {
        setBatchItems((prev) =>
          prev.map((i) =>
            i.id === id ? { ...i, status: 'failed', error: err.message, progress: 0 } : i
          )
        );
      },
    });

    setIsProcessing(false);
  };

  const cancelBatch = () => {
    abortControllerRef.current?.abort();
    setIsProcessing(false);
    setBatchItems((prev) =>
      prev.map((i) => (i.status === 'processing' || i.status === 'queued' ? { ...i, status: 'cancelled' } : i))
    );
  };

  const clearQueue = () => {
    setBatchItems([]);
    setIsBatchMode(false);
  };

  const removeItem = (id: string) => {
    setBatchItems((prev) => prev.filter((i) => i.id !== id));
  };

  const downloadItem = (item: BatchItem) => {
    if (item.outputBlob && item.outputFileName) {
      downloadBlob(item.outputBlob, item.outputFileName);
    }
  };

  const downloadAllZip = async () => {
    const completedItems = batchItems.filter((i) => i.status === 'completed' && i.outputBlob);
    if (completedItems.length === 0) return;

    setIsZipping(true);
    try {
      const zip = new JSZip();
      completedItems.forEach((item) => {
        if (item.outputBlob && item.outputFileName) {
          zip.file(item.outputFileName, item.outputBlob);
        }
      });

      const zipBlob = await zip.generateAsync({ type: 'blob' });
      downloadBlob(zipBlob, `coolwave_pdf_stapel_${Date.now()}.zip`);
    } catch (err) {
      console.error('[Zip Error]:', err);
      alert('Fehler beim Erstellen des ZIP-Archivs.');
    } finally {
      setIsZipping(false);
    }
  };

  const handleResetSingle = () => {
    setSingleFile(null);
    setCompressedBlob(null);
    setCompressedSize(0);
    setIsProcessing(false);
  };

  if (compressedBlob && singleFile) {
    return (
      <DownloadBox
        filename={outputFilename}
        originalSizeBytes={singleFile.size}
        resultSizeBytes={compressedSize}
        onDownload={() => downloadBlob(compressedBlob, outputFilename)}
        onReset={handleResetSingle}
        downloadLabel="Komprimiertes PDF herunterladen"
      />
    );
  }

  if (isProcessing && !isBatchMode) {
    return <ProcessingStatus progress={progress} statusText={statusText} />;
  }

  return (
    <div className="w-full space-y-6">
      {isBatchMode && batchItems.length > 0 ? (
        <div className="space-y-6">
          {/* Compression Level Selector for Batch */}
          <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">
            <h3 className="text-sm font-bold text-slate-800 uppercase tracking-wider mb-4 flex items-center gap-2">
              <Sliders className="w-4 h-4 text-sky-600" />
              Kompressionsstufe für alle PDF-Dokumente
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
              {[
                { id: 'low', title: 'Geringe Kompression', desc: 'Maximale Text- & Bildschärfe', save: '~25%' },
                { id: 'medium', title: 'Empfohlene Kompression', desc: 'Optimal für Web & E-Mail', save: '~48%' },
                { id: 'high', title: 'Starke Kompression', desc: 'Kleinste Dateigröße', save: '~68%' },
              ].map((lvl) => (
                <button
                  key={lvl.id}
                  type="button"
                  disabled={isProcessing}
                  onClick={() => setLevel(lvl.id as CompressionLevel)}
                  className={`p-4 rounded-xl border text-left transition-all ${
                    level === lvl.id
                      ? 'border-sky-500 bg-sky-50/50 shadow-sm ring-2 ring-sky-500/20'
                      : 'border-slate-200 hover:border-slate-300 bg-white'
                  }`}
                >
                  <div className="flex items-center justify-between mb-1">
                    <span className="font-semibold text-sm text-slate-900">{lvl.title}</span>
                    <span className="text-xs font-mono font-bold text-emerald-600 bg-emerald-50 px-1.5 py-0.5 rounded">
                      {lvl.save}
                    </span>
                  </div>
                  <p className="text-xs text-slate-500">{lvl.desc}</p>
                </button>
              ))}
            </div>
          </div>

          <BatchProcessingQueue
            items={batchItems}
            isProcessing={isProcessing}
            onStartBatch={startBatch}
            onCancelBatch={cancelBatch}
            onClearQueue={clearQueue}
            onRemoveItem={removeItem}
            onDownloadItem={downloadItem}
            onDownloadAllZip={downloadAllZip}
            isZipping={isZipping}
            toolTitle="PDF-Stapelkomprimierung"
          />
        </div>
      ) : !singleFile ? (
        <FileUploader
          acceptedExtensions={['.pdf']}
          maxFileSizeMB={limits.maxFileSizeMB}
          allowMultiple={true}
          onFilesSelected={handleFilesSelected}
          title="PDF-Dateien hier ablegen (Einzel- oder Stapelmodus)"
          subtitle={`Reduzieren Sie PDF-Dateigrößen • Bis zu ${limits.maxBatchFiles} PDFs gleichzeitig (${isPro ? 'Pro' : 'Kostenlos'})`}
        />
      ) : (
        /* Single File View (Preserved) */
        <div className="bg-white rounded-2xl border border-slate-200 p-6 sm:p-8 shadow-sm">
          <div className="flex items-center gap-3 pb-6 border-b border-slate-100">
            <div className="p-2.5 rounded-lg bg-sky-50 text-sky-700">
              <FileText className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900">{singleFile.name}</h3>
              <p className="text-xs text-slate-500 mt-0.5">
                Originalgröße: <span className="font-semibold text-slate-700">{formatBytes(singleFile.size)}</span>
              </p>
            </div>
          </div>

          <div className="py-6">
            <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-4">
              Kompressionsgrad wählen
            </label>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {[
                { id: 'low', title: 'Geringe Kompression', desc: 'Beste visuelle Qualität', save: '~25%' },
                { id: 'medium', title: 'Empfohlen', desc: 'Ideale Balance aus Größe & Schärfe', save: '~48%' },
                { id: 'high', title: 'Starke Kompression', desc: 'Maximale Einsparung für Uploads', save: '~68%' },
              ].map((lvl) => (
                <button
                  key={lvl.id}
                  type="button"
                  onClick={() => setLevel(lvl.id as CompressionLevel)}
                  className={`p-4 rounded-xl border text-left transition-all ${
                    level === lvl.id
                      ? 'border-sky-500 bg-sky-50/50 shadow-sm ring-2 ring-sky-500/20'
                      : 'border-slate-200 hover:border-slate-300 bg-white'
                  }`}
                >
                  <div className="flex items-center justify-between mb-1">
                    <span className="font-semibold text-sm text-slate-900">{lvl.title}</span>
                    <span className="text-xs font-mono font-bold text-emerald-600 bg-emerald-50 px-1.5 py-0.5 rounded">
                      {lvl.save}
                    </span>
                  </div>
                  <p className="text-xs text-slate-500">{lvl.desc}</p>
                </button>
              ))}
            </div>
          </div>

          <div className="pt-6 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4">
            <button
              onClick={handleResetSingle}
              className="text-xs text-slate-500 hover:text-slate-800 font-medium"
            >
              Anderes Dokument wählen
            </button>

            <button
              onClick={executeSingleCompress}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm sm:text-base shadow-sm transition-colors"
            >
              <Minimize2 className="w-4 h-4" />
              <span>PDF jetzt verkleinern</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { PDFDocument, rgb, StandardFonts, degrees } from 'pdf-lib';
import { 
  Type, 
  PenTool, 
  Highlighter, 
  Square, 
  Circle,
  ArrowRight,
  Minus,
  Check, 
  X as CrossIcon, 
  Calendar, 
  EyeOff, 
  Download, 
  Trash2, 
  Copy,
  ZoomIn, 
  ZoomOut, 
  Undo, 
  Redo, 
  RotateCw, 
  Layers, 
  FileText, 
  Image as ImageIcon,
  MousePointer,
  ChevronLeft,
  ChevronRight,
  Info,
  Sliders,
  CheckCircle2
} from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { downloadBlob, formatBytes } from '@/lib/utils';
import { trackEvent } from '@/lib/analytics';

export type EditorTool = 
  | 'select'
  | 'text'
  | 'image'
  | 'draw'
  | 'highlight'
  | 'underline'
  | 'strikethrough'
  | 'rectangle'
  | 'circle'
  | 'line'
  | 'arrow'
  | 'check'
  | 'cross'
  | 'signature'
  | 'initials'
  | 'date'
  | 'page-number'
  | 'whiteout';

export interface EditorObject {
  id: string;
  pageIndex: number;
  type: EditorTool;
  x: number;
  y: number;
  width: number;
  height: number;
  rotation: number;
  text?: string;
  fontSize?: number;
  fontFamily?: 'Helvetica' | 'TimesRoman' | 'Courier';
  color?: string;
  fillColor?: string;
  strokeWidth?: number;
  opacity?: number;
  points?: Array<{ x: number; y: number }>;
  imageData?: string;
}

export function PdfEditorEngine() {
  const [file, setFile] = useState<File | null>(null);
  const [activeTool, setActiveTool] = useState<EditorTool>('select');
  const [objects, setObjects] = useState<EditorObject[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [zoom, setZoom] = useState<number>(100);

  // Multi-page state
  const [numPages, setNumPages] = useState<number>(1);
  const [currentPage, setCurrentPage] = useState<number>(0);
  const [pageRotations, setPageRotations] = useState<number[]>([]);
  const [pageDimensions, setPageDimensions] = useState<Array<{ width: number; height: number }>>([]);
  const [pageOrder, setPageOrder] = useState<number[]>([]);

  // History stack for Undo / Redo
  const [history, setHistory] = useState<EditorObject[][]>([]);
  const [historyIndex, setHistoryIndex] = useState<number>(-1);

  // Properties panel state
  const [activeColor, setActiveColor] = useState<string>('#0f172a');
  const [activeFillColor, setActiveFillColor] = useState<string>('transparent');
  const [activeFontSize, setActiveFontSize] = useState<number>(16);
  const [activeFontFamily, setActiveFontFamily] = useState<'Helvetica' | 'TimesRoman' | 'Courier'>('Helvetica');
  const [activeStrokeWidth, setActiveStrokeWidth] = useState<number>(2);
  const [activeOpacity, setActiveOpacity] = useState<number>(1);

  // Freehand drawing state
  const [isDrawing, setIsDrawing] = useState<boolean>(false);
  const [currentPath, setCurrentPath] = useState<Array<{ x: number; y: number }>>([]);

  // Drag & Transform state
  const [isDragging, setIsDragging] = useState<boolean>(false);
  const [dragStart, setDragStart] = useState<{ x: number; y: number }>({ x: 0, y: 0 });
  const [activeHandle, setActiveHandle] = useState<string | null>(null);

  // Signature modal state
  const [showSignatureModal, setShowSignatureModal] = useState<boolean>(false);
  const [isSigningInitials, setIsSigningInitials] = useState<boolean>(false);
  const signatureCanvasRef = useRef<HTMLCanvasElement>(null);
  const [isSignatureDrawing, setIsSignatureDrawing] = useState<boolean>(false);

  // Mobile drawer state
  const [showMobileProps, setShowMobileProps] = useState<boolean>(false);
  const [showMobilePages, setShowMobilePages] = useState<boolean>(false);

  // Canvas refs
  const pdfCanvasRef = useRef<HTMLCanvasElement>(null);
  const overlayRef = useRef<HTMLDivElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  // Save history state snapshot
  const pushHistory = useCallback((newObjects: EditorObject[]) => {
    setHistory((prev) => {
      const trimmed = prev.slice(0, historyIndex + 1);
      return [...trimmed, newObjects];
    });
    setHistoryIndex((prev) => prev + 1);
  }, [historyIndex]);

  // Load PDF and initialize pages
  const handleFileSelected = async (files: File[]) => {
    if (files.length === 0) return;
    const f = files[0];
    setFile(f);
    setObjects([]);
    setSelectedId(null);
    setHistory([]);
    setHistoryIndex(-1);

    try {
      const buffer = await f.arrayBuffer();
      const pdf = await PDFDocument.load(buffer, { ignoreEncryption: true });
      const count = pdf.getPageCount();
      setNumPages(count);
      setCurrentPage(0);

      const dims: Array<{ width: number; height: number }> = [];
      const rots: number[] = [];
      const order: number[] = [];

      for (let i = 0; i < count; i++) {
        const p = pdf.getPage(i);
        const { width, height } = p.getSize();
        dims.push({ width, height });
        rots.push(p.getRotation().angle || 0);
        order.push(i);
      }

      setPageDimensions(dims);
      setPageRotations(rots);
      setPageOrder(order);

      trackEvent('upload_completed', { toolSlug: 'pdf-bearbeiten', pageCount: count });
    } catch (err) {
      console.error('Failed to load PDF in editor:', err);
    }
  };

  // Render current PDF page using pdfjs-dist
  useEffect(() => {
    if (!file || pageDimensions.length === 0) return;

    let isMounted = true;

    async function renderPdfPage() {
      try {
        const pdfjsLib = await import('pdfjs-dist');
        if (!pdfjsLib.GlobalWorkerOptions.workerSrc) {
          pdfjsLib.GlobalWorkerOptions.workerSrc = `https://unpkg.com/pdfjs-dist@${pdfjsLib.version}/build/pdf.worker.min.mjs`;
        }

        const buffer = await file!.arrayBuffer();
        const loadingTask = pdfjsLib.getDocument({ data: new Uint8Array(buffer) });
        const pdf = await loadingTask.promise;

        const actualPageIndex = pageOrder[currentPage] ?? currentPage;
        const page = await pdf.getPage(actualPageIndex + 1);

        const scale = (zoom / 100) * 1.5; // High-res rendering factor
        const rotation = pageRotations[actualPageIndex] || 0;
        const viewport = page.getViewport({ scale, rotation });

        const canvas = pdfCanvasRef.current;
        if (!canvas || !isMounted) return;

        canvas.width = viewport.width;
        canvas.height = viewport.height;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        await page.render({ canvasContext: ctx, viewport }).promise;
      } catch (err) {
        console.error('Error rendering PDF page in canvas:', err);
      }
    }

    renderPdfPage();

    return () => {
      isMounted = false;
    };
  }, [file, currentPage, zoom, pageRotations, pageOrder, pageDimensions]);

  // Current page dimensions
  const activePageIdx = pageOrder[currentPage] ?? 0;
  const currentDim = pageDimensions[activePageIdx] || { width: 595.28, height: 841.89 };
  const currentRot = pageRotations[activePageIdx] || 0;
  const isLandscape = (currentRot === 90 || currentRot === 270);
  const visualWidth = isLandscape ? currentDim.height : currentDim.width;
  const visualHeight = isLandscape ? currentDim.width : currentDim.height;
  const scale = zoom / 100;

  // -------------------------------------------------------------------------
  // Interaction Handlers (Click, Drag, Transform)
  // -------------------------------------------------------------------------
  const handleOverlayPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!overlayRef.current) return;
    const rect = overlayRef.current.getBoundingClientRect();
    const x = (e.clientX - rect.left) / scale;
    const y = (e.clientY - rect.top) / scale;

    if (activeTool === 'draw') {
      setIsDrawing(true);
      setCurrentPath([{ x, y }]);
      return;
    }

    if (activeTool === 'select') {
      // If clicking blank space, deselect
      if ((e.target as HTMLElement) === overlayRef.current) {
        setSelectedId(null);
      }
      return;
    }

    // Creating a new object
    const newId = `obj_${Date.now()}_${Math.random().toString(36).substring(7)}`;
    let newObj: EditorObject | null = null;

    switch (activeTool) {
      case 'text':
        newObj = {
          id: newId,
          pageIndex: activePageIdx,
          type: 'text',
          x,
          y,
          width: 200,
          height: activeFontSize * 1.5,
          rotation: 0,
          text: 'Hier Text eingeben',
          fontSize: activeFontSize,
          fontFamily: activeFontFamily,
          color: activeColor,
        };
        break;

      case 'highlight':
        newObj = {
          id: newId,
          pageIndex: activePageIdx,
          type: 'highlight',
          x,
          y,
          width: 180,
          height: 22,
          rotation: 0,
          color: '#facc15',
          opacity: 0.4,
        };
        break;

      case 'underline':
        newObj = {
          id: newId,
          pageIndex: activePageIdx,
          type: 'underline',
          x,
          y,
          width: 160,
          height: 3,
          rotation: 0,
          color: activeColor,
          strokeWidth: 2,
        };
        break;

      case 'strikethrough':
        newObj = {
          id: newId,
          pageIndex: activePageIdx,
          type: 'strikethrough',
          x,
          y,
          width: 160,
          height: 3,
          rotation: 0,
          color: '#dc2626',
          strokeWidth: 2,
        };
        break;

      case 'rectangle':
        newObj = {
          id: newId,
          pageIndex: activePageIdx,
          type: 'rectangle',
          x,
          y,
          width: 140,
          height: 80,
          rotation: 0,
          color: activeColor,
          fillColor: activeFillColor === 'transparent' ? undefined : activeFillColor,
          strokeWidth: activeStrokeWidth,
          opacity: activeOpacity,
        };
        break;

      case 'circle':
        newObj = {
          id: newId,
          pageIndex: activePageIdx,
          type: 'circle',
          x,
          y,
          width: 100,
          height: 100,
          rotation: 0,
          color: activeColor,
          fillColor: activeFillColor === 'transparent' ? undefined : activeFillColor,
          strokeWidth: activeStrokeWidth,
          opacity: activeOpacity,
        };
        break;

      case 'line':
        newObj = {
          id: newId,
          pageIndex: activePageIdx,
          type: 'line',
          x,
          y,
          width: 160,
          height: 4,
          rotation: 0,
          color: activeColor,
          strokeWidth: activeStrokeWidth,
        };
        break;

      case 'arrow':
        newObj = {
          id: newId,
          pageIndex: activePageIdx,
          type: 'arrow',
          x,
          y,
          width: 160,
          height: 20,
          rotation: 0,
          color: activeColor,
          strokeWidth: activeStrokeWidth,
        };
        break;

      case 'check':
        newObj = {
          id: newId,
          pageIndex: activePageIdx,
          type: 'check',
          x,
          y,
          width: 32,
          height: 32,
          rotation: 0,
          text: '✓',
          fontSize: 28,
          color: '#16a34a',
        };
        break;

      case 'cross':
        newObj = {
          id: newId,
          pageIndex: activePageIdx,
          type: 'cross',
          x,
          y,
          width: 32,
          height: 32,
          rotation: 0,
          text: '✗',
          fontSize: 28,
          color: '#dc2626',
        };
        break;

      case 'date':
        newObj = {
          id: newId,
          pageIndex: activePageIdx,
          type: 'date',
          x,
          y,
          width: 120,
          height: 24,
          rotation: 0,
          text: new Date().toLocaleDateString('de-DE'),
          fontSize: 14,
          color: activeColor,
        };
        break;

      case 'page-number':
        newObj = {
          id: newId,
          pageIndex: activePageIdx,
          type: 'page-number',
          x,
          y,
          width: 120,
          height: 20,
          rotation: 0,
          text: `Seite ${currentPage + 1} von ${numPages}`,
          fontSize: 12,
          color: '#64748b',
        };
        break;

      case 'whiteout':
        newObj = {
          id: newId,
          pageIndex: activePageIdx,
          type: 'whiteout',
          x,
          y,
          width: 150,
          height: 25,
          rotation: 0,
          color: '#ffffff',
          fillColor: '#ffffff',
          opacity: 1,
        };
        break;

      default:
        break;
    }

    if (newObj) {
      const updated = [...objects, newObj];
      setObjects(updated);
      pushHistory(updated);
      setSelectedId(newId);
      setActiveTool('select');
    }
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!overlayRef.current) return;
    const rect = overlayRef.current.getBoundingClientRect();
    const x = (e.clientX - rect.left) / scale;
    const y = (e.clientY - rect.top) / scale;

    if (isDrawing) {
      setCurrentPath((prev) => [...prev, { x, y }]);
      return;
    }

    if (!selectedId) return;

    if (isDragging) {
      const dx = x - dragStart.x;
      const dy = y - dragStart.y;

      setObjects((prev) =>
        prev.map((obj) => {
          if (obj.id !== selectedId) return obj;
          return {
            ...obj,
            x: Math.max(0, Math.min(visualWidth - 20, obj.x + dx)),
            y: Math.max(0, Math.min(visualHeight - 20, obj.y + dy)),
          };
        })
      );
      setDragStart({ x, y });
    } else if (activeHandle) {
      setObjects((prev) =>
        prev.map((obj) => {
          if (obj.id !== selectedId) return obj;
          let { x: ox, y: oy, width: ow, height: oh } = obj;

          if (activeHandle.includes('e')) ow = Math.max(20, x - ox);
          if (activeHandle.includes('s')) oh = Math.max(10, y - oy);
          if (activeHandle.includes('w')) {
            const nw = Math.max(20, ox + ow - x);
            ox += ow - nw;
            ow = nw;
          }
          if (activeHandle.includes('n')) {
            const nh = Math.max(10, oy + oh - y);
            oy += oh - nh;
            oh = nh;
          }

          return { ...obj, x: ox, y: oy, width: ow, height: oh };
        })
      );
    }
  };

  const handlePointerUp = () => {
    if (isDrawing && currentPath.length > 1) {
      const newId = `draw_${Date.now()}`;
      const minX = Math.min(...currentPath.map((p) => p.x));
      const minY = Math.min(...currentPath.map((p) => p.y));
      const maxX = Math.max(...currentPath.map((p) => p.x));
      const maxY = Math.max(...currentPath.map((p) => p.y));

      const newObj: EditorObject = {
        id: newId,
        pageIndex: activePageIdx,
        type: 'draw',
        x: minX,
        y: minY,
        width: Math.max(maxX - minX, 10),
        height: Math.max(maxY - minY, 10),
        rotation: 0,
        color: activeColor,
        strokeWidth: activeStrokeWidth,
        points: currentPath,
      };

      const updated = [...objects, newObj];
      setObjects(updated);
      pushHistory(updated);
      setSelectedId(newId);
    }

    setIsDrawing(false);
    setCurrentPath([]);
    setIsDragging(false);
    setActiveHandle(null);
  };

  // Image insertion
  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    const file = files[0];
    const reader = new FileReader();

    reader.onload = (event) => {
      const dataUrl = event.target?.result as string;
      const img = new Image();
      img.onload = () => {
        const maxWidth = 200;
        const aspect = img.width / img.height;
        const newObj: EditorObject = {
          id: `img_${Date.now()}`,
          pageIndex: activePageIdx,
          type: 'image',
          x: 50,
          y: 50,
          width: maxWidth,
          height: maxWidth / aspect,
          rotation: 0,
          imageData: dataUrl,
        };

        const updated = [...objects, newObj];
        setObjects(updated);
        pushHistory(updated);
        setSelectedId(newObj.id);
        setActiveTool('select');
      };
      img.src = dataUrl;
    };
    reader.readAsDataURL(file);
  };

  // Signature canvas handlers
  const handleSignaturePointerDown = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const canvas = signatureCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const rect = canvas.getBoundingClientRect();
    ctx.beginPath();
    ctx.moveTo(e.clientX - rect.left, e.clientY - rect.top);
    setIsSignatureDrawing(true);
  };

  const handleSignaturePointerMove = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (!isSignatureDrawing) return;
    const canvas = signatureCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const rect = canvas.getBoundingClientRect();
    ctx.lineTo(e.clientX - rect.left, e.clientY - rect.top);
    ctx.strokeStyle = '#0f172a';
    ctx.lineWidth = 2.5;
    ctx.lineCap = 'round';
    ctx.stroke();
  };

  const clearSignature = () => {
    const canvas = signatureCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
  };

  const saveSignature = () => {
    const canvas = signatureCanvasRef.current;
    if (!canvas) return;
    const dataUrl = canvas.toDataURL('image/png');

    const newObj: EditorObject = {
      id: `sig_${Date.now()}`,
      pageIndex: activePageIdx,
      type: isSigningInitials ? 'initials' : 'signature',
      x: 100,
      y: 200,
      width: isSigningInitials ? 80 : 160,
      height: isSigningInitials ? 50 : 70,
      rotation: 0,
      imageData: dataUrl,
    };

    const updated = [...objects, newObj];
    setObjects(updated);
    pushHistory(updated);
    setSelectedId(newObj.id);
    setShowSignatureModal(false);
  };

  // Undo / Redo
  const handleUndo = () => {
    if (historyIndex > 0) {
      const prev = history[historyIndex - 1];
      setObjects(prev);
      setHistoryIndex(historyIndex - 1);
      setSelectedId(null);
    }
  };

  const handleRedo = () => {
    if (historyIndex < history.length - 1) {
      const next = history[historyIndex + 1];
      setObjects(next);
      setHistoryIndex(historyIndex + 1);
      setSelectedId(null);
    }
  };

  // Duplicate & Delete
  const duplicateSelected = () => {
    if (!selectedId) return;
    const selected = objects.find((o) => o.id === selectedId);
    if (!selected) return;

    const duplicated: EditorObject = {
      ...selected,
      id: `obj_${Date.now()}_dup`,
      x: selected.x + 20,
      y: selected.y + 20,
    };

    const updated = [...objects, duplicated];
    setObjects(updated);
    pushHistory(updated);
    setSelectedId(duplicated.id);
  };

  const deleteSelected = () => {
    if (!selectedId) return;
    const updated = objects.filter((o) => o.id !== selectedId);
    setObjects(updated);
    pushHistory(updated);
    setSelectedId(null);
  };

  // Rotate Page
  const rotateCurrentPage = () => {
    setPageRotations((prev) => {
      const copy = [...prev];
      copy[activePageIdx] = ((copy[activePageIdx] || 0) + 90) % 360;
      return copy;
    });
  };

  // Page reordering
  const movePage = (direction: 'up' | 'down') => {
    const target = direction === 'up' ? currentPage - 1 : currentPage + 1;
    if (target < 0 || target >= numPages) return;
    const newOrder = [...pageOrder];
    const temp = newOrder[currentPage];
    newOrder[currentPage] = newOrder[target];
    newOrder[target] = temp;
    setPageOrder(newOrder);
    setCurrentPage(target);
  };

  // Selected Object
  const selectedObject = objects.find((o) => o.id === selectedId);

  const updateSelected = (updates: Partial<EditorObject>) => {
    if (!selectedId) return;
    setObjects((prev) =>
      prev.map((o) => (o.id === selectedId ? { ...o, ...updates } : o))
    );
  };

  // Keyboard Shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.target as HTMLElement).tagName === 'INPUT' || (e.target as HTMLElement).tagName === 'TEXTAREA') return;

      if (e.key === 'Delete' || e.key === 'Backspace') {
        if (selectedId) deleteSelected();
      } else if (e.ctrlKey && e.key === 'z') {
        e.preventDefault();
        handleUndo();
      } else if (e.ctrlKey && e.key === 'y') {
        e.preventDefault();
        handleRedo();
      } else if (e.ctrlKey && e.key === 'd') {
        e.preventDefault();
        duplicateSelected();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  });

  // -------------------------------------------------------------------------
  // Reliable PDF Export Engine (pdf-lib)
  // -------------------------------------------------------------------------
  const exportEditedPdf = async () => {
    if (!file) return;

    try {
      const buffer = await file.arrayBuffer();
      const srcDoc = await PDFDocument.load(buffer, { ignoreEncryption: true });
      const outDoc = await PDFDocument.create();

      // Copy pages in user-defined pageOrder
      const copiedPages = await outDoc.copyPages(srcDoc, pageOrder);

      const fontHelvetica = await outDoc.embedFont(StandardFonts.Helvetica);
      const fontHelveticaBold = await outDoc.embedFont(StandardFonts.HelveticaBold);
      const fontTimes = await outDoc.embedFont(StandardFonts.TimesRoman);
      const fontCourier = await outDoc.embedFont(StandardFonts.Courier);

      for (let i = 0; i < copiedPages.length; i++) {
        const page = copiedPages[i];
        const originalPageIndex = pageOrder[i];
        const rotationAngle = pageRotations[originalPageIndex] || 0;
        page.setRotation(degrees(rotationAngle));

        const { width: pWidth, height: pHeight } = page.getSize();
        const isRotated = rotationAngle === 90 || rotationAngle === 270;
        const effectiveHeight = isRotated ? pWidth : pHeight;

        // Retrieve annotations on this page
        const pageObjects = objects.filter((o) => o.pageIndex === originalPageIndex);

        for (const obj of pageObjects) {
          // Coordinate mapping from screen Y (0 at top) to PDF Y (0 at bottom)
          const pdfY = effectiveHeight - obj.y;

          // Parse RGB colors
          const hexToRgb = (hex?: string) => {
            if (!hex || !hex.startsWith('#')) return rgb(0.1, 0.1, 0.1);
            const r = parseInt(hex.slice(1, 3), 16) / 255;
            const g = parseInt(hex.slice(3, 5), 16) / 255;
            const b = parseInt(hex.slice(5, 7), 16) / 255;
            return rgb(r, g, b);
          };

          const strokeColor = hexToRgb(obj.color);
          const fillColor = obj.fillColor ? hexToRgb(obj.fillColor) : undefined;

          // Text Family selector
          let selectedFont = fontHelvetica;
          if (obj.fontFamily === 'TimesRoman') selectedFont = fontTimes;
          if (obj.fontFamily === 'Courier') selectedFont = fontCourier;

          switch (obj.type) {
            case 'text':
            case 'date':
            case 'page-number': {
              if (!obj.text) break;
              page.drawText(obj.text, {
                x: obj.x,
                y: pdfY - (obj.fontSize || 14),
                size: obj.fontSize || 14,
                font: selectedFont,
                color: strokeColor,
                opacity: obj.opacity ?? 1,
              });
              break;
            }

            case 'check': {
              const sz = (obj.fontSize || 24) * 0.7;
              page.drawLine({
                start: { x: obj.x, y: pdfY - sz * 0.5 },
                end: { x: obj.x + sz * 0.35, y: pdfY - sz * 0.9 },
                thickness: (obj.strokeWidth || 2) * 1.2,
                color: strokeColor,
              });
              page.drawLine({
                start: { x: obj.x + sz * 0.35, y: pdfY - sz * 0.9 },
                end: { x: obj.x + sz * 0.9, y: pdfY - sz * 0.1 },
                thickness: (obj.strokeWidth || 2) * 1.2,
                color: strokeColor,
              });
              break;
            }

            case 'cross': {
              const sz = (obj.fontSize || 24) * 0.6;
              page.drawLine({
                start: { x: obj.x, y: pdfY - sz },
                end: { x: obj.x + sz, y: pdfY },
                thickness: (obj.strokeWidth || 2) * 1.2,
                color: strokeColor,
              });
              page.drawLine({
                start: { x: obj.x, y: pdfY },
                end: { x: obj.x + sz, y: pdfY - sz },
                thickness: (obj.strokeWidth || 2) * 1.2,
                color: strokeColor,
              });
              break;
            }

            case 'highlight': {
              page.drawRectangle({
                x: obj.x,
                y: pdfY - obj.height,
                width: obj.width,
                height: obj.height,
                color: strokeColor,
                opacity: obj.opacity ?? 0.35,
              });
              break;
            }

            case 'whiteout': {
              page.drawRectangle({
                x: obj.x,
                y: pdfY - obj.height,
                width: obj.width,
                height: obj.height,
                color: rgb(1, 1, 1),
                opacity: 1,
              });
              break;
            }

            case 'rectangle': {
              page.drawRectangle({
                x: obj.x,
                y: pdfY - obj.height,
                width: obj.width,
                height: obj.height,
                borderColor: strokeColor,
                borderWidth: obj.strokeWidth || 1,
                color: fillColor,
                opacity: obj.opacity ?? 1,
              });
              break;
            }

            case 'circle': {
              const rx = obj.width / 2;
              const ry = obj.height / 2;
              page.drawEllipse({
                x: obj.x + rx,
                y: pdfY - ry,
                xScale: rx,
                yScale: ry,
                borderColor: strokeColor,
                borderWidth: obj.strokeWidth || 1,
                color: fillColor,
                opacity: obj.opacity ?? 1,
              });
              break;
            }

            case 'line':
            case 'underline':
            case 'strikethrough': {
              page.drawLine({
                start: { x: obj.x, y: pdfY },
                end: { x: obj.x + obj.width, y: pdfY },
                thickness: obj.strokeWidth || 2,
                color: strokeColor,
                opacity: obj.opacity ?? 1,
              });
              break;
            }

            case 'arrow': {
              const startX = obj.x;
              const endX = obj.x + obj.width;
              page.drawLine({
                start: { x: startX, y: pdfY },
                end: { x: endX, y: pdfY },
                thickness: obj.strokeWidth || 2,
                color: strokeColor,
                opacity: obj.opacity ?? 1,
              });
              // Arrowhead
              page.drawLine({
                start: { x: endX - 8, y: pdfY + 5 },
                end: { x: endX, y: pdfY },
                thickness: obj.strokeWidth || 2,
                color: strokeColor,
              });
              page.drawLine({
                start: { x: endX - 8, y: pdfY - 5 },
                end: { x: endX, y: pdfY },
                thickness: obj.strokeWidth || 2,
                color: strokeColor,
              });
              break;
            }

            case 'image':
            case 'signature':
            case 'initials': {
              if (!obj.imageData) break;
              try {
                const base64Data = obj.imageData.split(',')[1];
                const imgBuffer = Buffer.from(base64Data, 'base64');
                const isPng = obj.imageData.startsWith('data:image/png');
                const embedded = isPng 
                  ? await outDoc.embedPng(imgBuffer) 
                  : await outDoc.embedJpg(imgBuffer);

                page.drawImage(embedded, {
                  x: obj.x,
                  y: pdfY - obj.height,
                  width: obj.width,
                  height: obj.height,
                  opacity: obj.opacity ?? 1,
                });
              } catch (err) {
                console.error('Failed to embed image:', err);
              }
              break;
            }

            case 'draw': {
              if (obj.points && obj.points.length > 1) {
                for (let p = 0; p < obj.points.length - 1; p++) {
                  const pt1 = obj.points[p];
                  const pt2 = obj.points[p + 1];
                  page.drawLine({
                    start: { x: pt1.x, y: effectiveHeight - pt1.y },
                    end: { x: pt2.x, y: effectiveHeight - pt2.y },
                    thickness: obj.strokeWidth || 2,
                    color: strokeColor,
                    opacity: obj.opacity ?? 1,
                  });
                }
              }
              break;
            }
          }
        }

        outDoc.addPage(page);
      }

      const exportedBytes = await outDoc.save();
      const blob = new Blob([exportedBytes as unknown as BlobPart], { type: 'application/pdf' });
      downloadBlob(blob, `coolwave_bearbeitet_${file.name}`);
      trackEvent('conversion_completed', { toolSlug: 'pdf-bearbeiten', count: objects.length });
    } catch (err) {
      console.error('Export error:', err);
      alert('Fehler beim Exportieren des PDFs.');
    }
  };

  // Reset editor
  const handleReset = () => {
    setFile(null);
    setObjects([]);
    setSelectedId(null);
  };

  return (
    <div className="w-full max-w-7xl mx-auto">
      {/* Upload Screen */}
      {!file && (
        <div className="max-w-4xl mx-auto">
          <FileUploader
            acceptedExtensions={['.pdf']}
            maxFileSizeMB={50}
            allowMultiple={false}
            onFilesSelected={handleFileSelected}
            title="PDF-Dokument hier ablegen oder auswählen"
            subtitle="100% Clientseitig im Browser • Text, Formen, Zeichnungen & Signaturen hinzufügen"
          />
        </div>
      )}

      {/* Editor Main Interface */}
      {file && (
        <div className="flex flex-col bg-slate-100 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-xl overflow-hidden min-h-[750px]">
          {/* Top Global Bar */}
          <div className="h-14 bg-white dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between px-4 z-20">
            <div className="flex items-center gap-3">
              <button
                onClick={handleReset}
                className="text-xs font-medium text-slate-500 hover:text-slate-900 dark:hover:text-white px-2.5 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 hover:bg-slate-50 transition"
              >
                Neue Datei
              </button>
              <span className="text-sm font-semibold text-slate-800 dark:text-slate-100 truncate max-w-[200px] sm:max-w-xs">
                {file.name}
              </span>
              <span className="hidden md:inline-block text-xs bg-slate-100 dark:bg-slate-800 text-slate-500 px-2 py-0.5 rounded">
                {formatBytes(file.size)}
              </span>
            </div>

            {/* Middle Zoom & Undo Controls */}
            <div className="flex items-center gap-1 sm:gap-2" role="toolbar" aria-label="Ansichts- und Verlaufswerkzeuge">
              <button
                onClick={handleUndo}
                disabled={historyIndex <= 0}
                className="p-1.5 text-slate-600 dark:text-slate-300 disabled:opacity-30 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition cursor-pointer"
                title="Rückgängig (Strg+Z)"
                aria-label="Rückgängig (Strg+Z)"
              >
                <Undo className="w-4 h-4" aria-hidden="true" />
              </button>
              <button
                onClick={handleRedo}
                disabled={historyIndex >= history.length - 1}
                className="p-1.5 text-slate-600 dark:text-slate-300 disabled:opacity-30 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition cursor-pointer"
                title="Wiederholen (Strg+Y)"
                aria-label="Wiederholen (Strg+Y)"
              >
                <Redo className="w-4 h-4" aria-hidden="true" />
              </button>

              <div className="h-5 w-px bg-slate-200 dark:bg-slate-800 mx-1 hidden sm:block" aria-hidden="true" />

              <button
                onClick={() => setZoom((z) => Math.max(50, z - 15))}
                className="p-1.5 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition cursor-pointer"
                title="Verkleinern"
                aria-label="Verkleinern"
              >
                <ZoomOut className="w-4 h-4" aria-hidden="true" />
              </button>
              <span className="text-xs font-mono font-medium text-slate-600 dark:text-slate-300 min-w-[45px] text-center" aria-live="polite">
                {zoom}%
              </span>
              <button
                onClick={() => setZoom((z) => Math.min(200, z + 15))}
                className="p-1.5 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition cursor-pointer"
                title="Vergrößern"
                aria-label="Vergrößern"
              >
                <ZoomIn className="w-4 h-4" aria-hidden="true" />
              </button>
            </div>

            {/* Export Button */}
            <div className="flex items-center gap-2">
              <button
                onClick={() => setShowMobileProps(!showMobileProps)}
                className="lg:hidden p-1.5 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg cursor-pointer"
                title="Eigenschaften"
                aria-label="Eigenschaften einblenden"
              >
                <Sliders className="w-4 h-4" aria-hidden="true" />
              </button>
              <button
                onClick={exportEditedPdf}
                aria-label="Bearbeitetes PDF exportieren und herunterladen"
                className="px-4 py-2 bg-blue-600 hover:bg-blue-700 active:bg-blue-800 text-white font-semibold text-xs sm:text-sm rounded-xl shadow-sm flex items-center gap-2 transition cursor-pointer"
              >
                <Download className="w-4 h-4" aria-hidden="true" />
                <span>Exportieren</span>
              </button>
            </div>
          </div>

          {/* Distinction Banner */}
          <div className="bg-sky-50 dark:bg-sky-950/40 border-b border-sky-100 dark:border-sky-900/40 px-4 py-1.5 text-[11px] text-sky-800 dark:text-sky-300 flex items-center gap-2">
            <Info className="w-3.5 h-3.5 shrink-0 text-sky-600 dark:text-sky-400" aria-hidden="true" />
            <span>
              <strong>Bearbeitung mit Ebenen:</strong> Text, Formen und Zeichnungen werden als Vektor- und Textebenen ueber das Original gelegt. Abdecken entfernt keinen Text. Fuer vertrauliche Inhalte verwenden Sie das separate Werkzeug PDF schwaerzen.
            </span>
          </div>

          {/* 3-Panel Main Workspace */}
          <div className="flex-1 flex flex-col lg:flex-row relative overflow-hidden">
            {/* LEFT TOOL PANEL */}
            <div 
              role="toolbar" 
              aria-label="PDF-Editor Werkzeugleiste"
              className="w-full lg:w-16 bg-white dark:bg-slate-900 border-b lg:border-b-0 lg:border-r border-slate-200 dark:border-slate-800 flex lg:flex-col items-center justify-start py-2 lg:py-4 px-2 gap-1.5 overflow-x-auto lg:overflow-y-auto shrink-0 z-10"
            >
              <button
                onClick={() => setActiveTool('select')}
                aria-label="Auswählen und verschieben"
                aria-pressed={activeTool === 'select'}
                className={`p-2.5 rounded-xl transition cursor-pointer ${activeTool === 'select' ? 'bg-blue-50 text-blue-600 dark:bg-blue-950/60 dark:text-blue-400 ring-1 ring-blue-400' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                title="Auswählen / Verschieben"
              >
                <MousePointer className="w-5 h-5" aria-hidden="true" />
              </button>

              <button
                onClick={() => setActiveTool('text')}
                aria-label="Text hinzufügen"
                aria-pressed={activeTool === 'text'}
                className={`p-2.5 rounded-xl transition cursor-pointer ${activeTool === 'text' ? 'bg-blue-50 text-blue-600 dark:bg-blue-950/60 dark:text-blue-400 ring-1 ring-blue-400' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                title="Text hinzufügen"
              >
                <Type className="w-5 h-5" aria-hidden="true" />
              </button>

              <button
                onClick={() => setActiveTool('draw')}
                aria-label="Freihand zeichnen"
                aria-pressed={activeTool === 'draw'}
                className={`p-2.5 rounded-xl transition cursor-pointer ${activeTool === 'draw' ? 'bg-blue-50 text-blue-600 dark:bg-blue-950/60 dark:text-blue-400 ring-1 ring-blue-400' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                title="Freihand zeichnen"
              >
                <PenTool className="w-5 h-5" aria-hidden="true" />
              </button>

              <button
                onClick={() => setActiveTool('highlight')}
                aria-label="Text markieren"
                aria-pressed={activeTool === 'highlight'}
                className={`p-2.5 rounded-xl transition cursor-pointer ${activeTool === 'highlight' ? 'bg-blue-50 text-blue-600 dark:bg-blue-950/60 dark:text-blue-400 ring-1 ring-blue-400' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                title="Text markieren"
              >
                <Highlighter className="w-5 h-5" aria-hidden="true" />
              </button>

              <button
                onClick={() => setActiveTool('whiteout')}
                aria-label="Optisch abdecken (Text bleibt erhalten)"
                aria-pressed={activeTool === 'whiteout'}
                className={`p-2.5 rounded-xl transition cursor-pointer ${activeTool === 'whiteout' ? 'bg-blue-50 text-blue-600 dark:bg-blue-950/60 dark:text-blue-400 ring-1 ring-blue-400' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                title="Optisch abdecken – keine sichere Schwaerzung"
              >
                <EyeOff className="w-5 h-5" aria-hidden="true" />
              </button>

              <div className="h-px w-8 bg-slate-200 dark:bg-slate-800 my-1 hidden lg:block" aria-hidden="true" />

              <button
                onClick={() => setActiveTool('rectangle')}
                aria-label="Rechteck zeichnen"
                aria-pressed={activeTool === 'rectangle'}
                className={`p-2.5 rounded-xl transition cursor-pointer ${activeTool === 'rectangle' ? 'bg-blue-50 text-blue-600 dark:bg-blue-950/60 dark:text-blue-400 ring-1 ring-blue-400' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                title="Rechteck"
              >
                <Square className="w-5 h-5" aria-hidden="true" />
              </button>

              <button
                onClick={() => setActiveTool('circle')}
                aria-label="Kreis oder Ellipse zeichnen"
                aria-pressed={activeTool === 'circle'}
                className={`p-2.5 rounded-xl transition cursor-pointer ${activeTool === 'circle' ? 'bg-blue-50 text-blue-600 dark:bg-blue-950/60 dark:text-blue-400 ring-1 ring-blue-400' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                title="Kreis / Ellipse"
              >
                <Circle className="w-5 h-5" aria-hidden="true" />
              </button>

              <button
                onClick={() => setActiveTool('line')}
                aria-label="Gerade Linie zeichnen"
                aria-pressed={activeTool === 'line'}
                className={`p-2.5 rounded-xl transition cursor-pointer ${activeTool === 'line' ? 'bg-blue-50 text-blue-600 dark:bg-blue-950/60 dark:text-blue-400 ring-1 ring-blue-400' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                title="Linie"
              >
                <Minus className="w-5 h-5" aria-hidden="true" />
              </button>

              <button
                onClick={() => setActiveTool('arrow')}
                aria-label="Pfeil zeichnen"
                aria-pressed={activeTool === 'arrow'}
                className={`p-2.5 rounded-xl transition cursor-pointer ${activeTool === 'arrow' ? 'bg-blue-50 text-blue-600 dark:bg-blue-950/60 dark:text-blue-400 ring-1 ring-blue-400' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                title="Pfeil"
              >
                <ArrowRight className="w-5 h-5" aria-hidden="true" />
              </button>

              <div className="h-px w-8 bg-slate-200 dark:bg-slate-800 my-1 hidden lg:block" aria-hidden="true" />

              <button
                onClick={() => {
                  setIsSigningInitials(false);
                  setShowSignatureModal(true);
                }}
                aria-label="Unterschrift einfügen"
                className="p-2.5 rounded-xl text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition cursor-pointer"
                title="Unterschrift einfügen"
              >
                <FileText className="w-5 h-5 text-indigo-600 dark:text-indigo-400" aria-hidden="true" />
              </button>

              <button
                onClick={() => imageInputRef.current?.click()}
                aria-label="Bild in PDF einfügen"
                className="p-2.5 rounded-xl text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition cursor-pointer"
                title="Bild einfügen"
              >
                <ImageIcon className="w-5 h-5" aria-hidden="true" />
              </button>
              <input
                ref={imageInputRef}
                type="file"
                accept="image/png,image/jpeg"
                onChange={handleImageUpload}
                className="hidden"
                aria-hidden="true"
                tabIndex={-1}
              />

              <button
                onClick={() => setActiveTool('date')}
                aria-label="Aktuelles Datum einfügen"
                aria-pressed={activeTool === 'date'}
                className={`p-2.5 rounded-xl transition cursor-pointer ${activeTool === 'date' ? 'bg-blue-50 text-blue-600 dark:bg-blue-950/60 dark:text-blue-400 ring-1 ring-blue-400' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                title="Datum einfügen"
              >
                <Calendar className="w-5 h-5" aria-hidden="true" />
              </button>

              <button
                onClick={() => setActiveTool('check')}
                aria-label="Häkchen einfügen"
                aria-pressed={activeTool === 'check'}
                className={`p-2.5 rounded-xl transition cursor-pointer ${activeTool === 'check' ? 'bg-blue-50 text-blue-600 dark:bg-blue-950/60 dark:text-blue-400 ring-1 ring-blue-400' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                title="Häkchen (✓)"
              >
                <Check className="w-5 h-5 text-emerald-600" aria-hidden="true" />
              </button>

              <button
                onClick={() => setActiveTool('cross')}
                aria-label="Kreuz einfügen"
                aria-pressed={activeTool === 'cross'}
                className={`p-2.5 rounded-xl transition cursor-pointer ${activeTool === 'cross' ? 'bg-blue-50 text-blue-600 dark:bg-blue-950/60 dark:text-blue-400 ring-1 ring-blue-400' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
                title="Kreuz (✗)"
              >
                <CrossIcon className="w-5 h-5 text-red-600" aria-hidden="true" />
              </button>

              <div className="h-px w-8 bg-slate-200 dark:bg-slate-800 my-1 hidden lg:block" aria-hidden="true" />

              <button
                onClick={() => setShowMobilePages(!showMobilePages)}
                aria-label="Seitenübersicht umschalten"
                aria-expanded={showMobilePages}
                className="p-2.5 rounded-xl text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition cursor-pointer"
                title="Seitenübersicht"
              >
                <Layers className="w-5 h-5" aria-hidden="true" />
              </button>
            </div>

            {/* CENTER VIEWPORT CANVAS */}
            <div className="flex-1 overflow-auto p-4 sm:p-8 flex items-center justify-center bg-slate-200/70 dark:bg-slate-950">
              <div 
                className="relative bg-white shadow-2xl transition-all"
                style={{
                  width: visualWidth * scale,
                  height: visualHeight * scale,
                }}
              >
                {/* Underlying Rendered PDF Page */}
                <canvas
                  ref={pdfCanvasRef}
                  className="absolute inset-0 pointer-events-none w-full h-full"
                />

                {/* Interactive Annotation Overlay */}
                <div
                  ref={overlayRef}
                  onPointerDown={handleOverlayPointerDown}
                  onPointerMove={handlePointerMove}
                  onPointerUp={handlePointerUp}
                  className="absolute inset-0 select-none cursor-crosshair"
                  style={{
                    cursor: activeTool === 'select' ? 'default' : 'crosshair',
                  }}
                >
                  {/* Current Active Freehand Path */}
                  {isDrawing && currentPath.length > 1 && (
                    <svg className="absolute inset-0 w-full h-full pointer-events-none">
                      <polyline
                        points={currentPath.map((p) => `${p.x * scale},${p.y * scale}`).join(' ')}
                        fill="none"
                        stroke={activeColor}
                        strokeWidth={activeStrokeWidth * scale}
                        strokeLinecap="round"
                        strokeLinejoin="round"
                      />
                    </svg>
                  )}

                  {/* Render Objects for Current Page */}
                  {objects
                    .filter((obj) => obj.pageIndex === activePageIdx)
                    .map((obj) => {
                      const isSelected = obj.id === selectedId;

                      return (
                        <div
                          key={obj.id}
                          onPointerDown={(e) => {
                            e.stopPropagation();
                            setSelectedId(obj.id);
                            if (activeTool === 'select') {
                              setIsDragging(true);
                              const rect = overlayRef.current?.getBoundingClientRect();
                              if (rect) {
                                setDragStart({
                                  x: (e.clientX - rect.left) / scale,
                                  y: (e.clientY - rect.top) / scale,
                                });
                              }
                            }
                          }}
                          className={`absolute ${isSelected ? 'ring-2 ring-blue-500 ring-offset-1 z-30' : 'z-10'}`}
                          style={{
                            left: obj.x * scale,
                            top: obj.y * scale,
                            width: obj.width * scale,
                            height: obj.height * scale,
                            transform: `rotate(${obj.rotation}deg)`,
                            opacity: obj.opacity ?? 1,
                            cursor: activeTool === 'select' ? 'move' : 'default',
                          }}
                        >
                          {/* Render Object Body */}
                          {obj.type === 'text' && (
                            <div
                              contentEditable={isSelected}
                              suppressContentEditableWarning
                              onBlur={(e) => updateSelected({ text: e.currentTarget.textContent || '' })}
                              style={{
                                color: obj.color,
                                fontSize: (obj.fontSize || 16) * scale,
                                fontFamily: obj.fontFamily || 'Helvetica',
                                whiteSpace: 'pre-wrap',
                                wordBreak: 'break-word',
                              }}
                              className="w-full h-full outline-none select-text"
                            >
                              {obj.text}
                            </div>
                          )}

                          {obj.type === 'date' && (
                            <div
                              style={{
                                color: obj.color,
                                fontSize: (obj.fontSize || 14) * scale,
                              }}
                              className="font-medium"
                            >
                              {obj.text}
                            </div>
                          )}

                          {obj.type === 'page-number' && (
                            <div
                              style={{
                                color: obj.color,
                                fontSize: (obj.fontSize || 12) * scale,
                              }}
                              className="font-medium text-slate-500"
                            >
                              {obj.text}
                            </div>
                          )}

                          {obj.type === 'check' && (
                            <div
                              style={{
                                color: obj.color || '#16a34a',
                                fontSize: (obj.fontSize || 28) * scale,
                              }}
                              className="font-bold select-none leading-none"
                            >
                              ✓
                            </div>
                          )}

                          {obj.type === 'cross' && (
                            <div
                              style={{
                                color: obj.color || '#dc2626',
                                fontSize: (obj.fontSize || 28) * scale,
                              }}
                              className="font-bold select-none leading-none"
                            >
                              ✗
                            </div>
                          )}

                          {obj.type === 'highlight' && (
                            <div
                              style={{
                                backgroundColor: obj.color || '#facc15',
                                opacity: obj.opacity ?? 0.4,
                              }}
                              className="w-full h-full rounded"
                            />
                          )}

                          {obj.type === 'whiteout' && (
                            <div
                              style={{
                                backgroundColor: '#ffffff',
                              }}
                              className="w-full h-full border border-slate-200/50"
                            />
                          )}

                          {obj.type === 'rectangle' && (
                            <div
                              style={{
                                borderColor: obj.color || '#0f172a',
                                borderWidth: (obj.strokeWidth || 2) * scale,
                                backgroundColor: obj.fillColor || 'transparent',
                              }}
                              className="w-full h-full border rounded-sm"
                            />
                          )}

                          {obj.type === 'circle' && (
                            <div
                              style={{
                                borderColor: obj.color || '#0f172a',
                                borderWidth: (obj.strokeWidth || 2) * scale,
                                backgroundColor: obj.fillColor || 'transparent',
                              }}
                              className="w-full h-full border rounded-full"
                            />
                          )}

                          {obj.type === 'line' && (
                            <div
                              style={{
                                backgroundColor: obj.color || '#0f172a',
                                height: (obj.strokeWidth || 2) * scale,
                              }}
                              className="w-full mt-[calc(50%-1px)]"
                            />
                          )}

                          {obj.type === 'arrow' && (
                            <div className="w-full h-full flex items-center">
                              <div
                                style={{
                                  backgroundColor: obj.color || '#0f172a',
                                  height: (obj.strokeWidth || 2) * scale,
                                }}
                                className="flex-1"
                              />
                              <div
                                style={{
                                  borderColor: `transparent transparent transparent ${obj.color || '#0f172a'}`,
                                  borderWidth: `${6 * scale}px 0 ${6 * scale}px ${10 * scale}px`,
                                }}
                                className="w-0 h-0 border-solid"
                              />
                            </div>
                          )}

                          {(obj.type === 'image' || obj.type === 'signature' || obj.type === 'initials') && obj.imageData && (
                            <img
                              src={obj.imageData}
                              alt={obj.type === 'signature' ? "Eingefügte Unterschrift" : obj.type === 'initials' ? "Eingefügte Initialen" : "Eingefügtes Bildelement"}
                              className="w-full h-full object-contain pointer-events-none"
                            />
                          )}

                          {obj.type === 'draw' && obj.points && (
                            <svg className="w-full h-full overflow-visible pointer-events-none">
                              <polyline
                                points={obj.points.map((p) => `${(p.x - obj.x) * scale},${(p.y - obj.y) * scale}`).join(' ')}
                                fill="none"
                                stroke={obj.color || '#0f172a'}
                                strokeWidth={(obj.strokeWidth || 2) * scale}
                                strokeLinecap="round"
                                strokeLinejoin="round"
                              />
                            </svg>
                          )}

                          {/* 8-Point Resize Handles (Active when selected) */}
                          {isSelected && activeTool === 'select' && (
                            <>
                              <div
                                onPointerDown={(e) => { e.stopPropagation(); setActiveHandle('nw'); }}
                                className="absolute -top-1.5 -left-1.5 w-3 h-3 bg-white border-2 border-blue-600 rounded-full cursor-nwse-resize z-40"
                              />
                              <div
                                onPointerDown={(e) => { e.stopPropagation(); setActiveHandle('ne'); }}
                                className="absolute -top-1.5 -right-1.5 w-3 h-3 bg-white border-2 border-blue-600 rounded-full cursor-nesw-resize z-40"
                              />
                              <div
                                onPointerDown={(e) => { e.stopPropagation(); setActiveHandle('se'); }}
                                className="absolute -bottom-1.5 -right-1.5 w-3 h-3 bg-white border-2 border-blue-600 rounded-full cursor-nwse-resize z-40"
                              />
                              <div
                                onPointerDown={(e) => { e.stopPropagation(); setActiveHandle('sw'); }}
                                className="absolute -bottom-1.5 -left-1.5 w-3 h-3 bg-white border-2 border-blue-600 rounded-full cursor-nesw-resize z-40"
                              />
                            </>
                          )}
                        </div>
                      );
                    })}
                </div>
              </div>
            </div>

            {/* RIGHT PROPERTIES PANEL (Desktop & Mobile Drawer) */}
            <div
              className={`w-full lg:w-72 bg-white dark:bg-slate-900 border-t lg:border-t-0 lg:border-l border-slate-200 dark:border-slate-800 p-5 flex flex-col gap-5 overflow-y-auto shrink-0 z-20 ${showMobileProps ? 'block' : 'hidden lg:flex'}`}
            >
              <div className="flex items-center justify-between pb-3 border-b border-slate-100 dark:border-slate-800">
                <h4 className="text-sm font-bold text-slate-800 dark:text-white uppercase tracking-wider">
                  {selectedObject ? 'Objekt bearbeiten' : 'Werkzeug-Optionen'}
                </h4>
                {selectedObject && (
                  <div className="flex items-center gap-1">
                    <button
                      onClick={duplicateSelected}
                      className="p-1 text-slate-500 hover:text-slate-800 dark:hover:text-white rounded"
                      title="Duplizieren (Strg+D)"
                    >
                      <Copy className="w-4 h-4" />
                    </button>
                    <button
                      onClick={deleteSelected}
                      className="p-1 text-red-500 hover:text-red-700 rounded"
                      title="Löschen (Entf)"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                )}
              </div>

              {/* Security Distinction: Whiteout Overlay vs. True Redaction */}
              {(activeTool === 'whiteout' || selectedObject?.type === 'whiteout') && (
                <div className="p-3.5 bg-amber-50 dark:bg-amber-950/40 border border-amber-200 dark:border-amber-800/60 rounded-xl space-y-2 text-xs">
                  <div className="flex items-center gap-1.5 font-bold text-amber-900 dark:text-amber-200">
                    <Info className="w-4 h-4 text-amber-600 shrink-0" />
                    <span>Optische Überdeckung (Cover)</span>
                  </div>
                  <p className="text-[11px] text-amber-900/90 dark:text-amber-300 leading-relaxed">
                    Dieses Werkzeug legt ein weißes Rechteck über den Bereich. Der darunterliegende Text bleibt im PDF-Quellcode erhalten und kann kopiert oder extrahiert werden.
                  </p>
                  <a
                    href="/de/pdf-schwaerzen"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 text-[11px] font-bold text-blue-600 hover:text-blue-700 hover:underline pt-0.5"
                  >
                    <span>Für DSGVO-sichere echte Schwärzung hier klicken &rarr;</span>
                  </a>
                </div>
              )}

              {/* Color Picker */}
              <div>
                <label className="text-xs font-semibold text-slate-600 dark:text-slate-300 block mb-2">
                  Farbe
                </label>
                <div className="flex items-center gap-2 flex-wrap">
                  {['#0f172a', '#dc2626', '#16a34a', '#2563eb', '#facc15', '#9333ea', '#ffffff'].map((c) => (
                    <button
                      key={c}
                      onClick={() => {
                        setActiveColor(c);
                        if (selectedObject) updateSelected({ color: c });
                      }}
                      className={`w-6 h-6 rounded-full border border-slate-300 shadow-sm transition ${activeColor === c ? 'scale-110 ring-2 ring-blue-500 ring-offset-1' : ''}`}
                      style={{ backgroundColor: c }}
                    />
                  ))}
                  <input
                    type="color"
                    value={activeColor}
                    onChange={(e) => {
                      setActiveColor(e.target.value);
                      if (selectedObject) updateSelected({ color: e.target.value });
                    }}
                    className="w-7 h-7 rounded cursor-pointer border-0 p-0"
                  />
                </div>
              </div>

              {/* Typography for text objects */}
              {(!selectedObject || selectedObject.type === 'text') && (
                <>
                  <div>
                    <label className="text-xs font-semibold text-slate-600 dark:text-slate-300 block mb-1.5">
                      Schriftart
                    </label>
                    <select
                      value={selectedObject?.fontFamily || activeFontFamily}
                      onChange={(e) => {
                        const fam = e.target.value as 'Helvetica' | 'TimesRoman' | 'Courier';
                        setActiveFontFamily(fam);
                        if (selectedObject) updateSelected({ fontFamily: fam });
                      }}
                      className="w-full text-xs bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg p-2 text-slate-800 dark:text-white"
                    >
                      <option value="Helvetica">Helvetica (Standard)</option>
                      <option value="TimesRoman">Times New Roman (Serif)</option>
                      <option value="Courier">Courier (Monospace)</option>
                    </select>
                  </div>

                  <div>
                    <label className="text-xs font-semibold text-slate-600 dark:text-slate-300 block mb-1.5">
                      Schriftgröße ({selectedObject?.fontSize || activeFontSize}px)
                    </label>
                    <input
                      type="range"
                      min="10"
                      max="72"
                      value={selectedObject?.fontSize || activeFontSize}
                      onChange={(e) => {
                        const size = parseInt(e.target.value, 10);
                        setActiveFontSize(size);
                        if (selectedObject) updateSelected({ fontSize: size });
                      }}
                      className="w-full accent-blue-600"
                    />
                  </div>
                </>
              )}

              {/* Stroke width for shapes / pen */}
              {(!selectedObject || ['draw', 'rectangle', 'circle', 'line', 'arrow'].includes(selectedObject.type)) && (
                <div>
                  <label className="text-xs font-semibold text-slate-600 dark:text-slate-300 block mb-1.5">
                    Linienstärke ({selectedObject?.strokeWidth || activeStrokeWidth}px)
                  </label>
                  <input
                    type="range"
                    min="1"
                    max="20"
                    value={selectedObject?.strokeWidth || activeStrokeWidth}
                    onChange={(e) => {
                      const w = parseInt(e.target.value, 10);
                      setActiveStrokeWidth(w);
                      if (selectedObject) updateSelected({ strokeWidth: w });
                    }}
                    className="w-full accent-blue-600"
                  />
                </div>
              )}

              {/* Opacity */}
              <div>
                <label className="text-xs font-semibold text-slate-600 dark:text-slate-300 block mb-1.5">
                  Deckkraft ({Math.round((selectedObject?.opacity ?? activeOpacity) * 100)}%)
                </label>
                <input
                  type="range"
                  min="0.1"
                  max="1"
                  step="0.05"
                  value={selectedObject?.opacity ?? activeOpacity}
                  onChange={(e) => {
                    const op = parseFloat(e.target.value);
                    setActiveOpacity(op);
                    if (selectedObject) updateSelected({ opacity: op });
                  }}
                  className="w-full accent-blue-600"
                />
              </div>

              {/* Rotation */}
              {selectedObject && (
                <div>
                  <label className="text-xs font-semibold text-slate-600 dark:text-slate-300 block mb-1.5">
                    Drehung ({selectedObject.rotation}°)
                  </label>
                  <input
                    type="range"
                    min="0"
                    max="360"
                    value={selectedObject.rotation}
                    onChange={(e) => updateSelected({ rotation: parseInt(e.target.value, 10) })}
                    className="w-full accent-blue-600"
                  />
                </div>
              )}

              {/* Page Controls & Navigation */}
              <div className="mt-auto pt-4 border-t border-slate-100 dark:border-slate-800">
                <div className="flex items-center justify-between mb-3">
                  <span className="text-xs font-semibold text-slate-600 dark:text-slate-300">
                    Seite {currentPage + 1} von {numPages}
                  </span>
                  <div className="flex items-center gap-1">
                    <button
                      onClick={() => setCurrentPage((p) => Math.max(0, p - 1))}
                      disabled={currentPage === 0}
                      className="p-1 rounded text-slate-500 disabled:opacity-30 hover:bg-slate-100 dark:hover:bg-slate-800"
                    >
                      <ChevronLeft className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => setCurrentPage((p) => Math.min(numPages - 1, p + 1))}
                      disabled={currentPage === numPages - 1}
                      className="p-1 rounded text-slate-500 disabled:opacity-30 hover:bg-slate-100 dark:hover:bg-slate-800"
                    >
                      <ChevronRight className="w-4 h-4" />
                    </button>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-2">
                  <button
                    onClick={rotateCurrentPage}
                    className="px-2.5 py-1.5 text-xs bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 text-slate-700 dark:text-slate-200 rounded-lg flex items-center justify-center gap-1.5 border border-slate-200 dark:border-slate-700 transition"
                  >
                    <RotateCw className="w-3.5 h-3.5" />
                    <span>Seite drehen</span>
                  </button>
                  <button
                    onClick={() => movePage('up')}
                    disabled={currentPage === 0}
                    className="px-2.5 py-1.5 text-xs bg-slate-50 dark:bg-slate-800 hover:bg-slate-100 text-slate-700 dark:text-slate-200 rounded-lg flex items-center justify-center gap-1.5 border border-slate-200 dark:border-slate-700 disabled:opacity-40 transition"
                  >
                    <span>Nach oben</span>
                  </button>
                </div>
              </div>
            </div>
          </div>

          {/* Bottom Bar: Quick Mobile Dock */}
          <div className="lg:hidden h-14 bg-white dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 flex items-center justify-around px-2 z-20">
            <button
              onClick={() => setActiveTool('select')}
              className={`p-2 rounded-lg ${activeTool === 'select' ? 'text-blue-600' : 'text-slate-500'}`}
            >
              <MousePointer className="w-5 h-5" />
            </button>
            <button
              onClick={() => setActiveTool('text')}
              className={`p-2 rounded-lg ${activeTool === 'text' ? 'text-blue-600' : 'text-slate-500'}`}
            >
              <Type className="w-5 h-5" />
            </button>
            <button
              onClick={() => setActiveTool('draw')}
              className={`p-2 rounded-lg ${activeTool === 'draw' ? 'text-blue-600' : 'text-slate-500'}`}
            >
              <PenTool className="w-5 h-5" />
            </button>
            <button
              onClick={() => setActiveTool('highlight')}
              className={`p-2 rounded-lg ${activeTool === 'highlight' ? 'text-blue-600' : 'text-slate-500'}`}
            >
              <Highlighter className="w-5 h-5" />
            </button>
            <button
              onClick={() => setShowSignatureModal(true)}
              className="p-2 rounded-lg text-indigo-600"
            >
              <FileText className="w-5 h-5" />
            </button>
            <button
              onClick={() => setShowMobileProps(!showMobileProps)}
              className="p-2 rounded-lg text-slate-600 dark:text-slate-300"
            >
              <Sliders className="w-5 h-5" />
            </button>
          </div>
        </div>
      )}

      {/* Signature & Initials Drawing Modal */}
      {showSignatureModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-2xl max-w-lg w-full p-6">
            <div className="flex items-center justify-between pb-4 border-b border-slate-100 dark:border-slate-800 mb-4">
              <h3 className="font-bold text-slate-900 dark:text-white text-base sm:text-lg">
                {isSigningInitials ? 'Initialen zeichnen' : 'Digitale Unterschrift zeichnen'}
              </h3>
              <button
                onClick={() => setShowSignatureModal(false)}
                className="text-slate-400 hover:text-slate-600 dark:hover:text-slate-200"
              >
                <CrossIcon className="w-5 h-5" />
              </button>
            </div>

            <div className="border border-dashed border-slate-300 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-950 p-1 mb-4 flex items-center justify-center">
              <canvas
                ref={signatureCanvasRef}
                width={440}
                height={180}
                onPointerDown={handleSignaturePointerDown}
                onPointerMove={handleSignaturePointerMove}
                onPointerUp={() => setIsSignatureDrawing(false)}
                className="w-full h-44 cursor-crosshair bg-white dark:bg-slate-900 rounded-lg shadow-inner"
              />
            </div>

            <div className="flex items-center justify-between gap-3">
              <button
                onClick={clearSignature}
                className="px-4 py-2 text-xs font-semibold text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 transition"
              >
                Löschen
              </button>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setShowSignatureModal(false)}
                  className="px-4 py-2 text-xs font-semibold text-slate-500 hover:text-slate-700 rounded-xl transition"
                >
                  Abbrechen
                </button>
                <button
                  onClick={saveSignature}
                  className="px-5 py-2 text-xs font-semibold bg-blue-600 hover:bg-blue-700 text-white rounded-xl shadow transition flex items-center gap-1.5"
                >
                  <CheckCircle2 className="w-4 h-4" />
                  <span>Einfügen</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { 
  FileText, 
  Image as ImageIcon, 
  Paperclip, 
  Download, 
  Copy, 
  Check, 
  Search, 
  Layers, 
  CheckCircle2, 
  AlertCircle,
  RefreshCw 
} from 'lucide-react';
import JSZip from 'jszip';
import { PDFDocument, PDFName, PDFDict, PDFStream } from 'pdf-lib';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { downloadBlob, formatBytes } from '@/lib/utils';
import { trackEvent } from '@/lib/analytics';

export type ExtractMode = 'images' | 'text' | 'attachments';

interface ExtractedImage {
  id: string;
  name: string;
  blob: Blob;
  width: number;
  height: number;
  size: number;
  dataUrl: string;
}

interface ExtractedAttachment {
  name: string;
  size: number;
  data: Uint8Array;
}

interface PdfExtractEngineProps {
  mode: ExtractMode;
  toolSlug?: string;
}

export function PdfExtractEngine({ 
  mode,
  toolSlug = 'pdf-bilder-extrahieren'
}: PdfExtractEngineProps) {
  const [file, setFile] = useState<File | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');

  // Results state
  const [extractedText, setExtractedText] = useState<string>('');
  const [pageTexts, setPageTexts] = useState<Array<{ page: number; text: string }>>([]);
  const [extractedImages, setExtractedImages] = useState<ExtractedImage[]>([]);
  const [extractedAttachments, setExtractedAttachments] = useState<ExtractedAttachment[]>([]);
  const [copied, setCopied] = useState(false);
  const [hasExtracted, setHasExtracted] = useState(false);
  const [activeTab, setActiveTab] = useState<'all' | number>('all');

  const handleFileSelected = (files: File[]) => {
    if (files.length > 0) {
      setFile(files[0]);
      setHasExtracted(false);
      setExtractedText('');
      setPageTexts([]);
      setExtractedImages([]);
      setExtractedAttachments([]);
      trackEvent('upload_completed', { toolSlug, mode });
    }
  };

  const executeExtraction = async () => {
    if (!file) return;
    setIsProcessing(true);
    setProgress(15);
    setStatusText('PDF-Dokument wird analysiert...');
    trackEvent('conversion_started', { toolSlug, mode });

    try {
      const arrayBuffer = await file.arrayBuffer();

      if (mode === 'text') {
        const pdfjsLib = await import('pdfjs-dist');
        if (typeof window !== 'undefined' && !pdfjsLib.GlobalWorkerOptions.workerSrc) {
          pdfjsLib.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.mjs`;
        }

        const doc = await pdfjsLib.getDocument({ data: new Uint8Array(arrayBuffer) }).promise;
        const totalPages = doc.numPages;
        const pages: Array<{ page: number; text: string }> = [];
        let fullText = '';

        for (let p = 1; p <= totalPages; p++) {
          setProgress(20 + Math.round((p / totalPages) * 70));
          setStatusText(`Text aus Seite ${p} von ${totalPages} wird extrahiert...`);

          const pageObj = await doc.getPage(p);
          const tc = await pageObj.getTextContent();
          const pageStr = tc.items.map((it: any) => it.str || '').join(' ').replace(/\s+/g, ' ').trim();

          pages.push({ page: p, text: pageStr });
          fullText += `--- Seite ${p} ---\n${pageStr}\n\n`;
        }

        setPageTexts(pages);
        setExtractedText(fullText.trim());
      } else if (mode === 'images') {
        const pdfjsLib = await import('pdfjs-dist');
        if (typeof window !== 'undefined' && !pdfjsLib.GlobalWorkerOptions.workerSrc) {
          pdfjsLib.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.mjs`;
        }

        const doc = await pdfjsLib.getDocument({ data: new Uint8Array(arrayBuffer) }).promise;
        const totalPages = doc.numPages;
        const images: ExtractedImage[] = [];

        // Extract images page-by-page
        for (let p = 1; p <= totalPages; p++) {
          setProgress(15 + Math.round((p / totalPages) * 75));
          setStatusText(`Bilder aus Seite ${p} von ${totalPages} werden lokalisiert...`);

          const page = await doc.getPage(p);
          const ops = await page.getOperatorList();

          for (let i = 0; i < ops.fnArray.length; i++) {
            // Check for paintImageXObject operator
            if (ops.fnArray[i] === pdfjsLib.OPS.paintImageXObject) {
              const imgObjId = ops.argsArray[i][0];
              try {
                const imgObj: any = await new Promise((resolve) => {
                  page.objs.get(imgObjId, (obj: any) => resolve(obj));
                });

                if (imgObj && imgObj.data) {
                  const w = imgObj.width;
                  const h = imgObj.height;
                  if (w > 10 && h > 10) {
                    const canvas = document.createElement('canvas');
                    canvas.width = w;
                    canvas.height = h;
                    const ctx = canvas.getContext('2d');
                    if (ctx) {
                      const imgData = ctx.createImageData(w, h);
                      const srcData = imgObj.data;
                      if (srcData.length === w * h * 4) {
                        imgData.data.set(srcData);
                      } else if (srcData.length === w * h * 3) {
                        // RGB to RGBA
                        for (let si = 0, di = 0; si < srcData.length; si += 3, di += 4) {
                          imgData.data[di] = srcData[si];
                          imgData.data[di + 1] = srcData[si + 1];
                          imgData.data[di + 2] = srcData[si + 2];
                          imgData.data[di + 3] = 255;
                        }
                      } else if (srcData.length === w * h) {
                        // Grayscale to RGBA
                        for (let si = 0, di = 0; si < srcData.length; si++, di += 4) {
                          imgData.data[di] = srcData[si];
                          imgData.data[di + 1] = srcData[si];
                          imgData.data[di + 2] = srcData[si];
                          imgData.data[di + 3] = 255;
                        }
                      }
                      ctx.putImageData(imgData, 0, 0);

                      const blob = await new Promise<Blob | null>((resolve) =>
                        canvas.toBlob((b) => resolve(b), 'image/png')
                      );

                      if (blob) {
                        const dataUrl = canvas.toDataURL('image/png');
                        images.push({
                          id: `${p}_${imgObjId}`,
                          name: `bild_s${p}_${images.length + 1}.png`,
                          blob,
                          width: w,
                          height: h,
                          size: blob.size,
                          dataUrl,
                        });
                      }
                    }
                  }
                }
              } catch {
                // Ignore non-standard image formats
              }
            }
          }
        }

        // Fallback: If no raw XObjects were extracted, render page snapshots as high-res images
        if (images.length === 0) {
          for (let p = 1; p <= Math.min(totalPages, 5); p++) {
            const page = await doc.getPage(p);
            const viewport = page.getViewport({ scale: 1.5 });
            const canvas = document.createElement('canvas');
            canvas.width = viewport.width;
            canvas.height = viewport.height;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              await page.render({ canvasContext: ctx, viewport }).promise;
              const blob = await new Promise<Blob | null>((resolve) =>
                canvas.toBlob((b) => resolve(b), 'image/png')
              );
              if (blob) {
                images.push({
                  id: `fallback_${p}`,
                  name: `seite_${p}.png`,
                  blob,
                  width: Math.round(viewport.width),
                  height: Math.round(viewport.height),
                  size: blob.size,
                  dataUrl: canvas.toDataURL('image/png'),
                });
              }
            }
          }
        }

        setExtractedImages(images);
      } else if (mode === 'attachments') {
        setProgress(50);
        setStatusText('Dateianhänge & ZUGFeRD-Rechnungsdaten durchsuchen...');

        const pdfDoc = await PDFDocument.load(arrayBuffer, { ignoreEncryption: true });
        const attachments: ExtractedAttachment[] = [];

        // Search EmbeddedFiles name tree in document catalog
        try {
          const names = pdfDoc.catalog.lookup(PDFName.of('Names'));
          if (names instanceof PDFDict) {
            const embeddedFiles = names.lookup(PDFName.of('EmbeddedFiles'));
            if (embeddedFiles instanceof PDFDict) {
              const namesArray = embeddedFiles.lookup(PDFName.of('Names'));
              // Names array pairs: [String, Dict]
              if (namesArray && 'asArray' in (namesArray as any)) {
                const arr = (namesArray as any).asArray();
                for (let i = 0; i < arr.length; i += 2) {
                  const fname = arr[i].value ? String(arr[i].value) : `anhang_${Math.floor(i / 2) + 1}.bin`;
                  const fileSpec = arr[i + 1];
                  if (fileSpec instanceof PDFDict) {
                    const ef = fileSpec.lookup(PDFName.of('EF'));
                    if (ef instanceof PDFDict) {
                      const fStream = ef.lookup(PDFName.of('F'));
                      if (fStream instanceof PDFStream) {
                        const bytes = fStream.getContents();
                        attachments.push({
                          name: fname,
                          size: bytes.length,
                          data: bytes,
                        });
                      }
                    }
                  }
                }
              }
            }
          }
        } catch {
          // No standard EmbeddedFiles tree
        }

        setExtractedAttachments(attachments);
      }

      setProgress(100);
      setIsProcessing(false);
      setHasExtracted(true);
      trackEvent('conversion_completed', { toolSlug, mode });
    } catch (err: any) {
      console.error(err);
      setIsProcessing(false);
      alert(`Fehler beim Extrahieren: ${err?.message || 'Unbekannter Fehler'}`);
      trackEvent('conversion_failed', { toolSlug, mode });
    }
  };

  const handleDownloadAllImagesZip = async () => {
    if (extractedImages.length === 0 || !file) return;
    const zip = new JSZip();
    extractedImages.forEach((img) => {
      zip.file(img.name, img.blob);
    });
    const zipBlob = await zip.generateAsync({ type: 'blob' });
    downloadBlob(zipBlob, `bilder_${file.name.replace('.pdf', '')}.zip`);
  };

  const handleDownloadAllAttachmentsZip = async () => {
    if (extractedAttachments.length === 0 || !file) return;
    const zip = new JSZip();
    extractedAttachments.forEach((att) => {
      zip.file(att.name, att.data);
    });
    const zipBlob = await zip.generateAsync({ type: 'blob' });
    downloadBlob(zipBlob, `anhaenge_${file.name.replace('.pdf', '')}.zip`);
  };

  const handleDownloadText = () => {
    if (!extractedText || !file) return;
    const textBlob = new Blob([extractedText], { type: 'text/plain;charset=utf-8' });
    downloadBlob(textBlob, `${file.name.replace('.pdf', '')}_text.txt`);
  };

  const handleCopyText = () => {
    if (!extractedText) return;
    navigator.clipboard.writeText(extractedText);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleReset = () => {
    setFile(null);
    setHasExtracted(false);
    setExtractedText('');
    setPageTexts([]);
    setExtractedImages([]);
    setExtractedAttachments([]);
    setIsProcessing(false);
  };

  if (isProcessing) {
    return <ProcessingStatus progress={progress} statusText={statusText} />;
  }

  return (
    <div className="w-full">
      {!file ? (
        <FileUploader
          acceptedExtensions={['.pdf']}
          maxFileSizeMB={50}
          onFilesSelected={handleFileSelected}
          title={
            mode === 'images'
              ? 'PDF für Bild-Extraktion ablegen'
              : mode === 'text'
                ? 'PDF für Text-Extraktion ablegen'
                : 'PDF für Anhänge-Extraktion ablegen'
          }
          subtitle="Schnelle und sichere Extraktion von Elementen direkt in Ihrem Browser"
        />
      ) : !hasExtracted ? (
        <div className="bg-white rounded-2xl border border-slate-200 p-6 sm:p-8 shadow-sm">
          <div className="flex items-center gap-3 pb-6 border-b border-slate-100">
            <div className="p-2.5 rounded-lg bg-sky-50 text-sky-700">
              {mode === 'images' ? <ImageIcon className="w-5 h-5" /> : mode === 'text' ? <FileText className="w-5 h-5" /> : <Paperclip className="w-5 h-5" />}
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900">{file.name}</h3>
              <p className="text-xs text-slate-500">{formatBytes(file.size)}</p>
            </div>
          </div>

          <div className="py-6 max-w-xl text-xs text-slate-600 leading-relaxed">
            {mode === 'images' && (
              <p>
                CoolWave durchsucht das Dokument nach allen eingebetteten Rastergrafiken und Fotos. Sie können jedes Bild einzeln ansehen oder alle Bilder gebündelt als ZIP-Archiv herunterladen.
              </p>
            )}
            {mode === 'text' && (
              <p>
                Extrahiert den gesamten lesbaren Text der PDF-Datei strukturiert nach Seitenzahlen. Ideal für Notizen, Suchanalysen oder die Weiterverarbeitung in Textverarbeitungsprogrammen.
              </p>
            )}
            {mode === 'attachments' && (
              <p>
                Liest eingebettete Dateianhänge (z. B. ZUGFeRD / Factur-X XML-Rechnungen, Tabellen oder Begleitdokumente) aus dem PDF-Datenbaum aus.
              </p>
            )}
          </div>

          <div className="pt-6 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4">
            <button
              onClick={handleReset}
              className="text-xs text-slate-500 hover:text-slate-800 font-medium"
            >
              Andere Datei wählen
            </button>

            <button
              onClick={executeExtraction}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm sm:text-base shadow-sm transition-colors"
            >
              {mode === 'images' ? <ImageIcon className="w-4 h-4" /> : mode === 'text' ? <FileText className="w-4 h-4" /> : <Paperclip className="w-4 h-4" />}
              <span>
                {mode === 'images' ? 'Bilder extrahieren' : mode === 'text' ? 'Text extrahieren' : 'Anhänge suchen & extrahieren'}
              </span>
            </button>
          </div>
        </div>
      ) : (
        /* Results View */
        <div className="space-y-6">
          {/* Header Action Bar */}
          <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div>
              <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold bg-emerald-50 text-emerald-700 mb-2">
                <CheckCircle2 className="w-3.5 h-3.5" />
                Extraktion abgeschlossen
              </span>
              <h2 className="text-lg font-bold text-slate-900">{file.name}</h2>
              <p className="text-xs text-slate-500">
                {mode === 'images' && `${extractedImages.length} Bild(er) gefunden`}
                {mode === 'text' && `${pageTexts.length} Seiten extrahiert (${extractedText.split(/\s+/).filter(Boolean).length} Wörter)`}
                {mode === 'attachments' && `${extractedAttachments.length} Dateianhang/-anhänge gefunden`}
              </p>
            </div>

            <div className="flex items-center gap-3">
              {mode === 'images' && extractedImages.length > 0 && (
                <button
                  onClick={handleDownloadAllImagesZip}
                  className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl bg-sky-600 hover:bg-sky-700 text-white text-xs font-bold shadow-sm transition-colors"
                >
                  <Download className="w-4 h-4" />
                  Alle Bilder als ZIP ({extractedImages.length})
                </button>
              )}

              {mode === 'attachments' && extractedAttachments.length > 0 && (
                <button
                  onClick={handleDownloadAllAttachmentsZip}
                  className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl bg-sky-600 hover:bg-sky-700 text-white text-xs font-bold shadow-sm transition-colors"
                >
                  <Download className="w-4 h-4" />
                  Alle Anhänge als ZIP ({extractedAttachments.length})
                </button>
              )}

              {mode === 'text' && (
                <>
                  <button
                    onClick={handleCopyText}
                    className="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-slate-100 hover:bg-slate-200 text-slate-800 text-xs font-bold transition-colors"
                  >
                    {copied ? <Check className="w-4 h-4 text-emerald-600" /> : <Copy className="w-4 h-4" />}
                    {copied ? 'Kopiert!' : 'In Zwischenablage kopieren'}
                  </button>
                  <button
                    onClick={handleDownloadText}
                    className="inline-flex items-center gap-2 px-4 py-2.5 rounded-xl bg-sky-600 hover:bg-sky-700 text-white text-xs font-bold shadow-sm transition-colors"
                  >
                    <Download className="w-4 h-4" />
                    Als .TXT speichern
                  </button>
                </>
              )}

              <button
                onClick={handleReset}
                className="inline-flex items-center gap-1.5 px-3 py-2 rounded-xl border border-slate-200 hover:border-slate-300 text-slate-600 text-xs font-medium"
              >
                <RefreshCw className="w-3.5 h-3.5" />
                Neu
              </button>
            </div>
          </div>

          {/* Mode-Specific Content Area */}
          {mode === 'images' && (
            <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">
              {extractedImages.length === 0 ? (
                <div className="text-center py-12 text-slate-500">
                  <ImageIcon className="w-10 h-10 mx-auto mb-3 text-slate-300" />
                  <p className="font-semibold text-slate-700">Keine eingebetteten Rasterbilder gefunden</p>
                  <p className="text-xs text-slate-500 mt-1">Dieses Dokument enthält reine Vektorgrafiken oder reinen Text.</p>
                </div>
              ) : (
                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
                  {extractedImages.map((img) => (
                    <div key={img.id} className="group relative rounded-xl border border-slate-200 bg-slate-50 p-2 overflow-hidden hover:shadow-md transition-shadow">
                      <div className="aspect-square flex items-center justify-center overflow-hidden rounded-lg bg-white mb-2">
                        <img src={img.dataUrl} alt={img.name} className="max-h-full max-w-full object-contain" />
                      </div>
                      <div className="flex items-center justify-between gap-1">
                        <div>
                          <p className="text-[11px] font-semibold text-slate-800 truncate max-w-[110px]">{img.name}</p>
                          <p className="text-[10px] text-slate-400">{img.width} × {img.height} px • {formatBytes(img.size)}</p>
                        </div>
                        <button
                          onClick={() => downloadBlob(img.blob, img.name)}
                          className="p-1.5 rounded-lg bg-sky-50 text-sky-700 hover:bg-sky-100 transition-colors"
                          title="Bild herunterladen"
                        >
                          <Download className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {mode === 'text' && (
            <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">
              <div className="flex items-center gap-2 pb-4 mb-4 border-b border-slate-100 overflow-x-auto">
                <button
                  onClick={() => setActiveTab('all')}
                  className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${
                    activeTab === 'all' ? 'bg-sky-600 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                  }`}
                >
                  Gesamter Text
                </button>
                {pageTexts.map((pt) => (
                  <button
                    key={pt.page}
                    onClick={() => setActiveTab(pt.page)}
                    className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${
                      activeTab === pt.page ? 'bg-sky-600 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                    }`}
                  >
                    Seite {pt.page}
                  </button>
                ))}
              </div>

              <div className="p-5 rounded-xl border border-slate-200 bg-slate-50 font-mono text-xs text-slate-800 leading-relaxed max-h-[500px] overflow-y-auto whitespace-pre-wrap">
                {activeTab === 'all' 
                  ? extractedText || 'Kein Text im Dokument enthalten.' 
                  : pageTexts.find((pt) => pt.page === activeTab)?.text || 'Kein Text auf dieser Seite.'}
              </div>
            </div>
          )}

          {mode === 'attachments' && (
            <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm">
              {extractedAttachments.length === 0 ? (
                <div className="text-center py-12 text-slate-500">
                  <Paperclip className="w-10 h-10 mx-auto mb-3 text-slate-300" />
                  <p className="font-semibold text-slate-700">Keine eingebetteten Dateianhänge gefunden</p>
                  <p className="text-xs text-slate-500 mt-1 max-w-md mx-auto">
                    Dieses Dokument enthält keine eingebetteten Dateianhänge oder ZUGFeRD / Factur-X XML-Rechnungsdaten.
                  </p>
                </div>
              ) : (
                <div className="space-y-2">
                  {extractedAttachments.map((att, i) => (
                    <div key={i} className="flex items-center justify-between p-4 rounded-xl border border-slate-200 bg-slate-50 hover:bg-slate-100 transition-colors">
                      <div className="flex items-center gap-3">
                        <Paperclip className="w-5 h-5 text-sky-600" />
                        <div>
                          <p className="text-sm font-bold text-slate-800">{att.name}</p>
                          <p className="text-xs text-slate-500">{formatBytes(att.size)}</p>
                        </div>
                      </div>
                      <button
                        onClick={() => {
                          const b = new Blob([att.data as unknown as BlobPart]);
                          downloadBlob(b, att.name);
                        }}
                        className="inline-flex items-center gap-1.5 px-4 py-2 rounded-xl bg-white border border-slate-300 hover:bg-slate-50 text-xs font-bold text-slate-700 shadow-sm"
                      >
                        <Download className="w-3.5 h-3.5" />
                        Herunterladen
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { PDFDocument, rgb, StandardFonts } from 'pdf-lib';
import { 
  FileText, 
  Hash, 
  AlignLeft, 
  AlignCenter, 
  AlignRight, 
  Sliders, 
  Download,
  Calendar,
  Layers
} from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { DownloadBox } from '@/components/tools/DownloadBox';
import { downloadBlob, formatBytes } from '@/lib/utils';
import { trackEvent } from '@/lib/analytics';

export type HeaderFooterMode = 'numbering' | 'header' | 'footer';

interface PdfHeaderFooterEngineProps {
  defaultMode?: HeaderFooterMode;
  toolSlug?: string;
}

export function PdfHeaderFooterEngine({ 
  defaultMode = 'numbering',
  toolSlug = 'pdf-seiten-nummerieren'
}: PdfHeaderFooterEngineProps) {
  const [file, setFile] = useState<File | null>(null);
  const [mode, setMode] = useState<HeaderFooterMode>(defaultMode);

  // Numbering configuration
  const [numberFormat, setNumberFormat] = useState('Seite {n} von {total}');
  const [numberPosition, setNumberPosition] = useState<'bottom-center' | 'bottom-right' | 'bottom-left' | 'top-center' | 'top-right'>('bottom-center');
  const [startNumber, setStartNumber] = useState(1);

  // Header / Footer text configuration
  const [leftText, setLeftText] = useState('');
  const [centerText, setCenterText] = useState('');
  const [rightText, setRightText] = useState('');
  const [drawDivider, setDrawDivider] = useState(false);

  // Styling & Options
  const [fontSize, setFontSize] = useState(9);
  const [fontFamily, setFontFamily] = useState<'helvetica' | 'times' | 'courier'>('helvetica');
  const [colorHex, setColorHex] = useState<'gray' | 'black' | 'blue'>('gray');
  const [marginOffset, setMarginOffset] = useState(25); // pt
  const [skipFirstPage, setSkipFirstPage] = useState(true);

  // Processing state
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [resultBlob, setResultBlob] = useState<Blob | null>(null);
  const [outputFilename, setOutputFilename] = useState('');

  const handleFileSelected = (files: File[]) => {
    if (files.length > 0) {
      setFile(files[0]);
      if (mode === 'header' && !centerText) setCenterText(files[0].name.replace(/\.[^/.]+$/, ''));
      if (mode === 'footer' && !rightText) setRightText('Seite {n}');
      trackEvent('upload_completed', { toolSlug });
    }
  };

  const getFontRgb = () => {
    switch (colorHex) {
      case 'black': return rgb(0.05, 0.05, 0.05);
      case 'gray': return rgb(0.4, 0.45, 0.5);
      case 'blue': return rgb(0.1, 0.35, 0.75);
      default: return rgb(0.4, 0.45, 0.5);
    }
  };

  const executeProcessing = async () => {
    if (!file) return;
    setIsProcessing(true);
    setProgress(15);
    setStatusText('PDF-Dokument wird analysiert...');
    trackEvent('conversion_started', { toolSlug, mode });

    try {
      const buffer = await file.arrayBuffer();
      const pdf = await PDFDocument.load(buffer, { ignoreEncryption: true });
      const pages = pdf.getPages();
      const totalPages = pages.length;

      let font;
      if (fontFamily === 'times') font = await pdf.embedFont(StandardFonts.TimesRoman);
      else if (fontFamily === 'courier') font = await pdf.embedFont(StandardFonts.Courier);
      else font = await pdf.embedFont(StandardFonts.Helvetica);

      setProgress(40);
      setStatusText(`Seiten (${totalPages}) werden aktualisiert...`);

      const textColor = getFontRgb();
      const todayStr = new Date().toLocaleDateString('de-DE');
      const docTitle = file.name.replace(/\.[^/.]+$/, '');

      // Helper to replace dynamic placeholders
      const resolveText = (pattern: string, pageIdx: number) => {
        const pageNum = pageIdx + startNumber;
        return pattern
          .replace(/{n}/g, String(pageNum))
          .replace(/{total}/g, String(totalPages))
          .replace(/{date}/g, todayStr)
          .replace(/{title}/g, docTitle);
      };

      pages.forEach((page, idx) => {
        if (skipFirstPage && idx === 0) return;

        const { width, height } = page.getSize();
        const sideMargin = 35;

        if (mode === 'numbering') {
          const text = resolveText(numberFormat, idx);
          const textWidth = font.widthOfTextAtSize(text, fontSize);

          let x = (width - textWidth) / 2;
          let y = marginOffset;

          if (numberPosition === 'bottom-left') {
            x = sideMargin;
            y = marginOffset;
          } else if (numberPosition === 'bottom-right') {
            x = width - sideMargin - textWidth;
            y = marginOffset;
          } else if (numberPosition === 'top-center') {
            x = (width - textWidth) / 2;
            y = height - marginOffset;
          } else if (numberPosition === 'top-right') {
            x = width - sideMargin - textWidth;
            y = height - marginOffset;
          }

          page.drawText(text, { x, y, size: fontSize, font, color: textColor });
        } else {
          // Header or Footer
          const isHeader = mode === 'header';
          const y = isHeader ? height - marginOffset : marginOffset;

          // Draw optional divider line
          if (drawDivider) {
            const lineY = isHeader ? y - 6 : y + fontSize + 4;
            page.drawLine({
              start: { x: sideMargin, y: lineY },
              end: { x: width - sideMargin, y: lineY },
              thickness: 0.5,
              color: rgb(0.8, 0.85, 0.9),
            });
          }

          // Left text
          if (leftText.trim()) {
            const resolved = resolveText(leftText, idx);
            page.drawText(resolved, { x: sideMargin, y, size: fontSize, font, color: textColor });
          }

          // Center text
          if (centerText.trim()) {
            const resolved = resolveText(centerText, idx);
            const w = font.widthOfTextAtSize(resolved, fontSize);
            page.drawText(resolved, { x: (width - w) / 2, y, size: fontSize, font, color: textColor });
          }

          // Right text
          if (rightText.trim()) {
            const resolved = resolveText(rightText, idx);
            const w = font.widthOfTextAtSize(resolved, fontSize);
            page.drawText(resolved, { x: width - sideMargin - w, y, size: fontSize, font, color: textColor });
          }
        }
      });

      setProgress(85);
      setStatusText('PDF wird gespeichert...');

      const bytes = await pdf.save();
      const blob = new Blob([bytes as unknown as BlobPart], { type: 'application/pdf' });
      setResultBlob(blob);

      const prefix = mode === 'numbering' ? 'nummeriert' : mode === 'header' ? 'kopfzeile' : 'fusszeile';
      setOutputFilename(`coolwave_${prefix}_${file.name}`);

      setProgress(100);
      setIsProcessing(false);
      trackEvent('conversion_completed', { toolSlug, mode });
    } catch (err: any) {
      console.error(err);
      setIsProcessing(false);
      alert(`Fehler beim Bearbeiten der PDF: ${err?.message || 'Unbekannter Fehler'}`);
      trackEvent('conversion_failed', { toolSlug, mode });
    }
  };

  const handleDownload = () => {
    if (!resultBlob) return;
    downloadBlob(resultBlob, outputFilename);
    trackEvent('download_completed', { toolSlug });
  };

  const handleReset = () => {
    setFile(null);
    setResultBlob(null);
    setIsProcessing(false);
  };

  if (resultBlob && file) {
    return (
      <DownloadBox
        filename={outputFilename}
        originalSizeBytes={file.size}
        resultSizeBytes={resultBlob.size}
        onDownload={handleDownload}
        onReset={handleReset}
        downloadLabel="Fertige PDF herunterladen"
      />
    );
  }

  if (isProcessing) {
    return <ProcessingStatus progress={progress} statusText={statusText} />;
  }

  return (
    <div className="w-full">
      {!file ? (
        <FileUploader
          acceptedExtensions={['.pdf']}
          maxFileSizeMB={50}
          onFilesSelected={handleFileSelected}
          title={
            mode === 'numbering' 
              ? 'PDF für Seitennummerierung ablegen' 
              : mode === 'header' 
                ? 'PDF für Kopfzeile ablegen' 
                : 'PDF für Fußzeile ablegen'
          }
          subtitle="Passen Sie Seitenzahlen, Dokumenttitel oder Vertraulichkeitshinweise flexibel an"
        />
      ) : (
        <div className="bg-white rounded-2xl border border-slate-200 p-6 sm:p-8 shadow-sm">
          {/* File Header */}
          <div className="flex items-center gap-3 pb-6 border-b border-slate-100">
            <div className="p-2.5 rounded-lg bg-sky-50 text-sky-700">
              <FileText className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900">{file.name}</h3>
              <p className="text-xs text-slate-500">{formatBytes(file.size)}</p>
            </div>
          </div>

          {/* Mode Tabs */}
          <div className="py-6 space-y-6 max-w-xl">
            <div className="flex rounded-xl bg-slate-100 p-1">
              <button
                type="button"
                onClick={() => setMode('numbering')}
                className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-xs font-bold transition-all ${
                  mode === 'numbering' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-600 hover:text-slate-900'
                }`}
              >
                <Hash className="w-4 h-4" />
                Seitenzahlen
              </button>
              <button
                type="button"
                onClick={() => setMode('header')}
                className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-xs font-bold transition-all ${
                  mode === 'header' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-600 hover:text-slate-900'
                }`}
              >
                <Layers className="w-4 h-4" />
                Kopfzeile
              </button>
              <button
                type="button"
                onClick={() => setMode('footer')}
                className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-xs font-bold transition-all ${
                  mode === 'footer' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-600 hover:text-slate-900'
                }`}
              >
                <AlignLeft className="w-4 h-4" />
                Fußzeile
              </button>
            </div>

            {/* Mode-Specific Settings */}
            {mode === 'numbering' ? (
              <div className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                    Zahlenformat
                  </label>
                  <input
                    type="text"
                    value={numberFormat}
                    onChange={(e) => setNumberFormat(e.target.value)}
                    className="w-full px-3.5 py-2.5 rounded-xl border border-slate-300 bg-white text-slate-900 text-sm focus:outline-none focus:ring-2 focus:ring-sky-500"
                    placeholder="z. B. Seite {n} von {total}"
                  />
                  <div className="flex flex-wrap gap-2 mt-2">
                    {[
                      'Seite {n} von {total}',
                      '{n}/{total}',
                      'Seite {n}',
                      '{n}',
                      '- {n} -',
                    ].map((fmt) => (
                      <button
                        key={fmt}
                        type="button"
                        onClick={() => setNumberFormat(fmt)}
                        className="px-2.5 py-1 rounded bg-slate-100 hover:bg-slate-200 text-[11px] font-semibold text-slate-700 transition-colors"
                      >
                        {fmt}
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                    Position auf der Seite
                  </label>
                  <div className="grid grid-cols-3 gap-2">
                    {[
                      { id: 'bottom-left', label: 'Unten Links' },
                      { id: 'bottom-center', label: 'Unten Mitte' },
                      { id: 'bottom-right', label: 'Unten Rechts' },
                      { id: 'top-center', label: 'Oben Mitte' },
                      { id: 'top-right', label: 'Oben Rechts' },
                    ].map((pos) => (
                      <button
                        key={pos.id}
                        type="button"
                        onClick={() => setNumberPosition(pos.id as any)}
                        className={`px-3 py-2 rounded-lg border text-xs font-bold transition-all text-center ${
                          numberPosition === pos.id
                            ? 'border-sky-600 bg-sky-50 text-sky-900 ring-1 ring-sky-600'
                            : 'border-slate-200 text-slate-600 hover:border-slate-300'
                        }`}
                      >
                        {pos.label}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            ) : (
              <div className="space-y-4">
                <p className="text-xs text-slate-500">
                  Platzhalter verfügbar: <code className="bg-slate-100 px-1 py-0.5 rounded font-mono">&#123;n&#125;</code> (Seite), <code className="bg-slate-100 px-1 py-0.5 rounded font-mono">&#123;total&#125;</code> (Gesamt), <code className="bg-slate-100 px-1 py-0.5 rounded font-mono">&#123;date&#125;</code> (Datum), <code className="bg-slate-100 px-1 py-0.5 rounded font-mono">&#123;title&#125;</code> (Titel).
                </p>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                  <div>
                    <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">
                      Links
                    </label>
                    <input
                      type="text"
                      value={leftText}
                      onChange={(e) => setLeftText(e.target.value)}
                      placeholder="z. B. {title}"
                      className="w-full px-3 py-2 rounded-lg border border-slate-300 text-xs text-slate-900"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">
                      Mitte
                    </label>
                    <input
                      type="text"
                      value={centerText}
                      onChange={(e) => setCenterText(e.target.value)}
                      placeholder="z. B. VERTRAULICH"
                      className="w-full px-3 py-2 rounded-lg border border-slate-300 text-xs text-slate-900"
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">
                      Rechts
                    </label>
                    <input
                      type="text"
                      value={rightText}
                      onChange={(e) => setRightText(e.target.value)}
                      placeholder="z. B. Seite {n}"
                      className="w-full px-3 py-2 rounded-lg border border-slate-300 text-xs text-slate-900"
                    />
                  </div>
                </div>

                <div className="pt-1">
                  <label className="flex items-center gap-2 cursor-pointer text-xs text-slate-700 font-medium">
                    <input
                      type="checkbox"
                      checked={drawDivider}
                      onChange={(e) => setDrawDivider(e.target.checked)}
                      className="rounded border-slate-300 text-sky-600 focus:ring-sky-500"
                    />
                    Dezente horizontale Trennlinie zeichnen
                  </label>
                </div>
              </div>
            )}

            {/* Typography & Layout Controls */}
            <div className="pt-4 border-t border-slate-100 grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">
                  Schriftgröße: {fontSize}pt
                </label>
                <input
                  type="range"
                  min="7"
                  max="14"
                  value={fontSize}
                  onChange={(e) => setFontSize(parseInt(e.target.value, 10))}
                  className="w-full accent-sky-600"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">
                  Schriftart
                </label>
                <select
                  value={fontFamily}
                  onChange={(e) => setFontFamily(e.target.value as any)}
                  className="w-full px-2.5 py-1.5 rounded-lg border border-slate-300 bg-white text-xs font-medium text-slate-800"
                >
                  <option value="helvetica">Helvetica (Standard)</option>
                  <option value="times">Times Roman (Serif)</option>
                  <option value="courier">Courier (Monospace)</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">
                  Farbe
                </label>
                <div className="flex gap-2">
                  {[
                    { id: 'gray', label: 'Grau', color: 'bg-slate-500' },
                    { id: 'black', label: 'Schwarz', color: 'bg-black' },
                    { id: 'blue', label: 'Blau', color: 'bg-blue-600' },
                  ].map((c) => (
                    <button
                      key={c.id}
                      type="button"
                      onClick={() => setColorHex(c.id as any)}
                      className={`flex-1 py-1.5 rounded border text-[11px] font-semibold transition-all ${
                        colorHex === c.id ? 'border-sky-600 bg-sky-50 text-sky-900 ring-1 ring-sky-600' : 'border-slate-200 text-slate-600'
                      }`}
                    >
                      {c.label}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            {/* Checkbox Options */}
            <div className="space-y-2 pt-2">
              <label className="flex items-center gap-2 cursor-pointer text-xs text-slate-700 font-medium">
                <input
                  type="checkbox"
                  checked={skipFirstPage}
                  onChange={(e) => setSkipFirstPage(e.target.checked)}
                  className="rounded border-slate-300 text-sky-600 focus:ring-sky-500"
                />
                Deckblatt überspringen (Erste Seite bleibt ohne Aufdruck)
              </label>
            </div>
          </div>

          {/* Action Footer */}
          <div className="pt-6 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4">
            <button
              onClick={handleReset}
              className="text-xs text-slate-500 hover:text-slate-800 font-medium"
            >
              Andere Datei wählen
            </button>

            <button
              onClick={executeProcessing}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm sm:text-base shadow-sm transition-colors"
            >
              <Download className="w-4 h-4" />
              <span>
                {mode === 'numbering' ? 'Seiten nummerieren' : mode === 'header' ? 'Kopfzeile anwenden' : 'Fußzeile anwenden'}
              </span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { PDFDocument, PDFName, PDFDict } from 'pdf-lib';
import { 
  FileText, 
  ShieldCheck, 
  Copy, 
  Check, 
  RefreshCw, 
  Info,
  Maximize2,
  Lock,
  Download,
  Layers,
  FileCheck
} from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { DownloadBox } from '@/components/tools/DownloadBox';
import { downloadBlob, formatBytes } from '@/lib/utils';
import { trackEvent } from '@/lib/analytics';

export type MetadataMode = 'view' | 'strip';

interface PdfMetadataEngineProps {
  mode: MetadataMode;
}

interface ParsedMetadata {
  title: string;
  author: string;
  subject: string;
  keywords: string[];
  creator: string;
  producer: string;
  creationDate: string;
  modificationDate: string;
  pageCount: number;
  pageDimensions: string;
  pdfVersion: string;
  encrypted: boolean;
  formFieldsCount: number;
  pdfAConformance: string;
}

export function PdfMetadataEngine({ mode }: PdfMetadataEngineProps) {
  const [file, setFile] = useState<File | null>(null);
  const [metadata, setMetadata] = useState<ParsedMetadata | null>(null);
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [progress, setProgress] = useState<number>(0);
  const [statusText, setStatusText] = useState<string>('');
  const [resultBlob, setResultBlob] = useState<Blob | null>(null);
  const [outputFilename, setOutputFilename] = useState<string>('');
  const [error, setError] = useState<string | null>(null);
  const [copiedKey, setCopiedKey] = useState<string | null>(null);

  const handleFileSelected = async (files: File[]) => {
    if (files.length === 0) return;
    const f = files[0];
    setFile(f);
    setError(null);
    setIsProcessing(true);
    setProgress(30);
    setStatusText('Dokumenteneigenschaften werden analysiert...');

    try {
      const buffer = await f.arrayBuffer();
      const pdf = await PDFDocument.load(buffer, { ignoreEncryption: true });

      // Page dimensions
      const pages = pdf.getPages();
      let dimsStr = 'Nicht ermittelbar';
      if (pages.length > 0) {
        const { width, height } = pages[0].getSize();
        const mmW = Math.round((width / 72) * 25.4);
        const mmH = Math.round((height / 72) * 25.4);
        const isA4 = Math.abs(mmW - 210) < 5 && Math.abs(mmH - 297) < 5;
        const isLetter = Math.abs(mmW - 216) < 5 && Math.abs(mmH - 279) < 5;
        dimsStr = `${mmW} × ${mmH} mm (${Math.round(width)} × ${Math.round(height)} pt)${isA4 ? ' — DIN A4' : isLetter ? ' — US Letter' : ''}`;
      }

      // Check form fields
      let formFieldsCount = 0;
      try {
        const form = pdf.getForm();
        formFieldsCount = form.getFields().length;
      } catch {}

      // PDF Version estimation from header bytes
      const headerStr = new TextDecoder('latin1').decode(new Uint8Array(buffer.slice(0, 20)));
      const versionMatch = headerStr.match(/%PDF-(\d\.\d)/);
      const pdfVersion = versionMatch ? `PDF ${versionMatch[1]}` : 'PDF 1.7';

      // Check PDF/A XMP
      const rawSample = new TextDecoder('latin1').decode(new Uint8Array(buffer.slice(0, 10000)));
      const isPdfA = rawSample.includes('pdfaid:part') || rawSample.includes('GTS_PDFA1');

      const meta: ParsedMetadata = {
        title: pdf.getTitle() || 'Nicht hinterlegt',
        author: pdf.getAuthor() || 'Nicht hinterlegt',
        subject: pdf.getSubject() || 'Nicht hinterlegt',
        keywords: pdf.getKeywords() ? [pdf.getKeywords()!] : [],
        creator: pdf.getCreator() || 'Nicht hinterlegt',
        producer: pdf.getProducer() || 'Nicht hinterlegt',
        creationDate: pdf.getCreationDate() ? pdf.getCreationDate()!.toLocaleString('de-DE') : 'Nicht hinterlegt',
        modificationDate: pdf.getModificationDate() ? pdf.getModificationDate()!.toLocaleString('de-DE') : 'Nicht hinterlegt',
        pageCount: pdf.getPageCount(),
        pageDimensions: dimsStr,
        pdfVersion,
        encrypted: false,
        formFieldsCount,
        pdfAConformance: isPdfA ? 'Erkannt (PDF/A-Konformitätssignatur)' : 'Standard PDF (Kein PDF/A)',
      };

      setMetadata(meta);
      setIsProcessing(false);
      trackEvent('metadata_inspected', { mode });
    } catch (err) {
      console.error(err);
      setError('Eigenschaften konnten nicht gelesen werden. Möglicherweise ist die Datei passwortgeschützt.');
      setIsProcessing(false);
      setFile(null);
    }
  };

  const handleCopy = (key: string, val: string) => {
    navigator.clipboard.writeText(val);
    setCopiedKey(key);
    setTimeout(() => setCopiedKey(null), 2000);
  };

  const exportPropertiesReport = () => {
    if (!metadata || !file) return;
    const jsonStr = JSON.stringify(
      {
        dateiname: file.name,
        dateigroesse: formatBytes(file.size),
        ...metadata,
      },
      null,
      2
    );
    const blob = new Blob([jsonStr], { type: 'application/json' });
    downloadBlob(blob, `eigenschaften_${file.name.replace('.pdf', '')}.json`);
  };

  const executeStripMetadata = async () => {
    if (!file) return;
    setIsProcessing(true);
    setProgress(30);
    setStatusText('Metadaten und Tracking-Tags werden bereinigt...');
    trackEvent('metadata_strip_started');

    try {
      const buffer = await file.arrayBuffer();
      const pdf = await PDFDocument.load(buffer, { ignoreEncryption: true });

      pdf.setTitle('');
      pdf.setAuthor('');
      pdf.setSubject('');
      pdf.setKeywords([]);
      pdf.setCreator('CoolWave Privacy Engine');
      pdf.setProducer('CoolWave Privacy Engine');

      setProgress(75);
      setStatusText('Dokument wird anonymisiert gespeichert...');

      const pdfBytes = await pdf.save({ useObjectStreams: true });
      const blob = new Blob([pdfBytes as unknown as BlobPart], { type: 'application/pdf' });
      setResultBlob(blob);

      const base = file.name.substring(0, file.name.lastIndexOf('.')) || file.name;
      setOutputFilename(`coolwave_${base}_anonymisiert.pdf`);

      setProgress(100);
      setIsProcessing(false);
      trackEvent('metadata_strip_completed');
    } catch (err) {
      console.error(err);
      setError('Fehler beim Entfernen der Metadaten.');
      setIsProcessing(false);
    }
  };

  const handleDownload = () => {
    if (!resultBlob) return;
    downloadBlob(resultBlob, outputFilename);
    trackEvent('download_completed', { mode: 'strip' });
  };

  const handleReset = () => {
    setFile(null);
    setMetadata(null);
    setResultBlob(null);
    setProgress(0);
    setIsProcessing(false);
    setError(null);
  };

  return (
    <div className="w-full">
      {!file && (
        <FileUploader
          onFilesSelected={handleFileSelected}
          allowMultiple={false}
          maxFileSizeMB={50}
          acceptedExtensions={['.pdf']}
          title="PDF-Dokument hier ablegen"
          subtitle={
            mode === 'view'
              ? 'PDF wählen, um Dokumenteigenschaften, Abmessungen & Metadaten anzuzeigen'
              : 'PDF wählen, um alle Autoren- & Ersteller-Metadaten restlos zu löschen'
          }
        />
      )}

      {error && (
        <div className="mt-4 p-4 rounded-xl bg-rose-50 border border-rose-200 text-rose-700 text-sm font-medium">
          {error}
        </div>
      )}

      {file && metadata && !resultBlob && !isProcessing && (
        <div className="p-6 rounded-2xl bg-white border border-slate-200 shadow-sm space-y-6">
          {/* Header */}
          <div className="flex flex-wrap items-center justify-between gap-4 pb-4 border-b border-slate-100">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-sky-50 text-sky-700 flex items-center justify-center border border-sky-100">
                <FileText className="w-5 h-5" />
              </div>
              <div>
                <h3 className="font-bold text-slate-900 text-sm sm:text-base">{file.name}</h3>
                <p className="text-xs text-slate-500">
                  {metadata.pageCount} {metadata.pageCount === 1 ? 'Seite' : 'Seiten'} • {formatBytes(file.size)}
                </p>
              </div>
            </div>

            <div className="flex items-center gap-3">
              {mode === 'view' && (
                <button
                  onClick={exportPropertiesReport}
                  className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-slate-100 hover:bg-slate-200 text-xs font-bold text-slate-700 transition-colors"
                >
                  <Download className="w-3.5 h-3.5" />
                  JSON-Report
                </button>
              )}
              <button
                onClick={handleReset}
                className="text-xs font-semibold text-slate-500 hover:text-slate-700 underline"
              >
                Anderes Dokument wählen
              </button>
            </div>
          </div>

          {/* Quick Technical Specs */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            <div className="p-3 bg-slate-50 rounded-xl border border-slate-100">
              <span className="text-[11px] text-slate-400 font-medium block">PDF-Version</span>
              <span className="text-sm font-bold text-slate-900">{metadata.pdfVersion}</span>
            </div>
            <div className="p-3 bg-slate-50 rounded-xl border border-slate-100">
              <span className="text-[11px] text-slate-400 font-medium block">Seitenabmessungen</span>
              <span className="text-sm font-bold text-slate-900 truncate block">{metadata.pageDimensions}</span>
            </div>
            <div className="p-3 bg-slate-50 rounded-xl border border-slate-100">
              <span className="text-[11px] text-slate-400 font-medium block">Formularfelder</span>
              <span className="text-sm font-bold text-slate-900">{metadata.formFieldsCount} Felder</span>
            </div>
            <div className="p-3 bg-slate-50 rounded-xl border border-slate-100">
              <span className="text-[11px] text-slate-400 font-medium block">PDF/A-Archivstatus</span>
              <span className="text-xs font-bold text-slate-800 truncate block">{metadata.pdfAConformance}</span>
            </div>
          </div>

          {/* Metadata Display Table */}
          <div className="space-y-3">
            <h4 className="text-xs font-bold text-slate-700 uppercase tracking-wider">
              Enthaltene Metadaten:
            </h4>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs">
              <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex items-center justify-between">
                <div>
                  <span className="text-slate-400 block mb-0.5 font-medium">Titel:</span>
                  <span className="font-semibold text-slate-800">{metadata.title}</span>
                </div>
                {metadata.title !== 'Nicht hinterlegt' && (
                  <button
                    onClick={() => handleCopy('title', metadata.title)}
                    className="p-1 text-slate-400 hover:text-slate-600"
                    title="Kopieren"
                  >
                    {copiedKey === 'title' ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
                  </button>
                )}
              </div>

              <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex items-center justify-between">
                <div>
                  <span className="text-slate-400 block mb-0.5 font-medium">Autor / Verfasser:</span>
                  <span className="font-semibold text-slate-800">{metadata.author}</span>
                </div>
                {metadata.author !== 'Nicht hinterlegt' && (
                  <button
                    onClick={() => handleCopy('author', metadata.author)}
                    className="p-1 text-slate-400 hover:text-slate-600"
                    title="Kopieren"
                  >
                    {copiedKey === 'author' ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
                  </button>
                )}
              </div>

              <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex items-center justify-between">
                <div>
                  <span className="text-slate-400 block mb-0.5 font-medium">Thema / Betreff:</span>
                  <span className="font-semibold text-slate-800">{metadata.subject}</span>
                </div>
                {metadata.subject !== 'Nicht hinterlegt' && (
                  <button
                    onClick={() => handleCopy('subject', metadata.subject)}
                    className="p-1 text-slate-400 hover:text-slate-600"
                    title="Kopieren"
                  >
                    {copiedKey === 'subject' ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
                  </button>
                )}
              </div>

              <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex items-center justify-between">
                <div>
                  <span className="text-slate-400 block mb-0.5 font-medium">Ersteller-Software (Creator):</span>
                  <span className="font-semibold text-slate-800">{metadata.creator}</span>
                </div>
                {metadata.creator !== 'Nicht hinterlegt' && (
                  <button
                    onClick={() => handleCopy('creator', metadata.creator)}
                    className="p-1 text-slate-400 hover:text-slate-600"
                    title="Kopieren"
                  >
                    {copiedKey === 'creator' ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
                  </button>
                )}
              </div>

              <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex items-center justify-between">
                <div>
                  <span className="text-slate-400 block mb-0.5 font-medium">PDF-Generator (Producer):</span>
                  <span className="font-semibold text-slate-800">{metadata.producer}</span>
                </div>
                {metadata.producer !== 'Nicht hinterlegt' && (
                  <button
                    onClick={() => handleCopy('producer', metadata.producer)}
                    className="p-1 text-slate-400 hover:text-slate-600"
                    title="Kopieren"
                  >
                    {copiedKey === 'producer' ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
                  </button>
                )}
              </div>

              <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex items-center justify-between">
                <div>
                  <span className="text-slate-400 block mb-0.5 font-medium">Erstellungsdatum:</span>
                  <span className="font-semibold text-slate-800">{metadata.creationDate}</span>
                </div>
              </div>

              <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex items-center justify-between">
                <div>
                  <span className="text-slate-400 block mb-0.5 font-medium">Letzte Änderung:</span>
                  <span className="font-semibold text-slate-800">{metadata.modificationDate}</span>
                </div>
              </div>

              <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex items-center justify-between">
                <div>
                  <span className="text-slate-400 block mb-0.5 font-medium">Schlagwörter:</span>
                  <span className="font-semibold text-slate-800">
                    {metadata.keywords.length > 0 ? metadata.keywords.join(', ') : 'Keine'}
                  </span>
                </div>
              </div>
            </div>
          </div>

          {/* Action to strip if in strip mode */}
          {mode === 'strip' && (
            <div className="pt-4 border-t border-slate-100">
              <button
                onClick={executeStripMetadata}
                className="w-full py-3.5 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm shadow-sm transition-colors flex items-center justify-center gap-2"
              >
                <ShieldCheck className="w-4 h-4" />
                Alle Metadaten restlos löschen & PDF herunterladen
              </button>
            </div>
          )}
        </div>
      )}

      {resultBlob && file && (
        <DownloadBox
          filename={outputFilename}
          originalSizeBytes={file.size}
          resultSizeBytes={resultBlob.size}
          onDownload={handleDownload}
          onReset={handleReset}
          downloadLabel="Anonymisierte PDF herunterladen"
        />
      )}
    </div>
  );
}

'use client';

import React, { useState, useRef } from 'react';
import { PDFDocument, PDFName, PDFArray, PDFDict, rgb } from 'pdf-lib';
import JSZip from 'jszip';
import { 
  Wrench, 
  Zap, 
  FileCheck, 
  Layers, 
  MessageSquareOff, 
  FileText, 
  CheckCircle2, 
  Info, 
  Download 
} from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { DownloadBox } from '@/components/tools/DownloadBox';
import { BatchProcessingQueue, BatchItem } from '@/components/tools/BatchProcessingQueue';
import { downloadBlob, formatBytes } from '@/lib/utils';
import { trackEvent } from '@/lib/analytics';
import { runConcurrentBatch } from '@/lib/batch-queue';
import { getBatchLimits, validateBatchFiles } from '@/config/batch.config';

export type RepairOptimizeMode = 'repair' | 'optimize' | 'pdfa' | 'flatten' | 'strip-annotations';

interface PdfRepairOptimizeEngineProps {
  mode: RepairOptimizeMode;
  toolSlug?: string;
}

export function PdfRepairOptimizeEngine({ 
  mode,
  toolSlug = 'pdf-optimieren'
}: PdfRepairOptimizeEngineProps) {
  const [singleFile, setSingleFile] = useState<File | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [resultBlob, setResultBlob] = useState<Blob | null>(null);
  const [outputFilename, setOutputFilename] = useState('');
  const [auditMessage, setAuditMessage] = useState<string>('');
  const [reductionPct, setReductionPct] = useState<number | null>(null);

  // Batch states
  const [batchItems, setBatchItems] = useState<BatchItem[]>([]);
  const [isBatchMode, setIsBatchMode] = useState(false);
  const [isZipping, setIsZipping] = useState(false);
  const abortControllerRef = useRef<AbortController | null>(null);

  const isPro = typeof window !== 'undefined' && localStorage.getItem('coolwave_pro_active') === 'true';
  const limits = getBatchLimits(isPro);

  const handleFilesSelected = (files: File[]) => {
    if (files.length === 0) return;

    if (files.length === 1 && !isBatchMode && batchItems.length === 0) {
      setSingleFile(files[0]);
      setIsBatchMode(false);
      trackEvent('upload_completed', { toolSlug, mode });
    } else {
      const validation = validateBatchFiles(files, isPro);
      if (!validation.valid) {
        alert(validation.error);
        return;
      }

      setIsBatchMode(true);
      setSingleFile(null);
      const newItems: BatchItem[] = files.map((f, idx) => ({
        id: `pdf_repair_batch_${Date.now()}_${idx}_${Math.random().toString(36).substring(7)}`,
        file: f,
        status: 'queued',
        progress: 0,
      }));
      setBatchItems(newItems);
      trackEvent('batch_upload_completed', { toolSlug, mode, count: files.length });
    }
  };

  const getModeTitle = () => {
    switch (mode) {
      case 'repair': return 'Beschädigte PDF reparieren';
      case 'optimize': return 'PDF-Dateigröße optimieren';
      case 'pdfa': return 'In ISO-konformes PDF/A-1b umwandeln';
      case 'flatten': return 'Formulare & Anmerkungen abflachen';
      case 'strip-annotations': return 'Alle Anmerkungen & Notizen entfernen';
      default: return 'PDF verarbeiten';
    }
  };

  const getModeIcon = () => {
    switch (mode) {
      case 'repair': return <Wrench className="w-5 h-5" />;
      case 'optimize': return <Zap className="w-5 h-5" />;
      case 'pdfa': return <FileCheck className="w-5 h-5" />;
      case 'flatten': return <Layers className="w-5 h-5" />;
      case 'strip-annotations': return <MessageSquareOff className="w-5 h-5" />;
      default: return <FileText className="w-5 h-5" />;
    }
  };

  /**
   * Universal processor for an individual PDF
   */
  const processSinglePdf = async (
    file: File,
    onProgress?: (pct: number, msg?: string) => void
  ): Promise<{ blob: Blob; fileName: string; audit: string; size: number }> => {
    onProgress?.(20, 'PDF-Dokument wird analysiert...');

    const buffer = await file.arrayBuffer();
    const pdf = await PDFDocument.load(buffer, { ignoreEncryption: true });
    const pages = pdf.getPages();

    let audit = '';
    let suffix = '_optimiert.pdf';

    if (mode === 'repair') {
      onProgress?.(50, 'Xref-Tabelle neu serialisieren...');
      suffix = '_repariert.pdf';
      audit = `Struktur-Integrität wiederhergestellt. ${pages.length} Seiten geborgen.`;
    } else if (mode === 'optimize') {
      onProgress?.(50, 'Datenströme bereinigen & komprimieren...');
      suffix = '_optimiert.pdf';
      pdf.setProducer('CoolWave High-Efficiency Engine');
      pdf.setCreator('CoolWave');
      audit = `Objektströme komprimiert und ungenutzte Strukturdaten bereinigt.`;
    } else if (mode === 'pdfa') {
      throw new Error('PDF/A-Konvertierung ist derzeit nicht verfuegbar. Es wird keine ungepruefte Archivdatei erstellt.');
      onProgress?.(50, 'PDF/A-1b XMP-Metadaten einbetten...');
      suffix = '_pdfa.pdf';
      pdf.setTitle(file.name.replace(/\.[^/.]+$/, ''));
      pdf.setSubject('ISO 19005-1 PDF/A-1b Archivdokument');
      pdf.setProducer('CoolWave PDF/A Archival Engine');
      pdf.setCreator('CoolWave');
      try {
        pdf.catalog.delete(PDFName.of('JavaScript'));
        pdf.catalog.delete(PDFName.of('AA'));
      } catch {}
      audit = `ISO 19005-1 (PDF/A-1b) Konformitätspaket integriert. Dynamische Skripte entfernt.`;
    } else if (mode === 'flatten') {
      onProgress?.(50, 'Formularfelder dauerhaft einbrennen...');
      suffix = '_abgeflacht.pdf';
      try {
        const form = pdf.getForm();
        form.flatten();
      } catch {}
      audit = `Formularfelder, Kontrollkästchen und Signaturen dauerhaft in Seitenstruktur gerendert.`;
    } else if (mode === 'strip-annotations') {
      onProgress?.(50, 'Kommentare & Hervorhebungen entfernen...');
      suffix = '_ohne_anmerkungen.pdf';
      let strippedCount = 0;
      pages.forEach((p) => {
        try {
          const annots = p.node.get(PDFName.of('Annots'));
          if (annots) {
            if (annots instanceof PDFArray) strippedCount += annots.size();
            p.node.delete(PDFName.of('Annots'));
          }
        } catch {}
      });
      audit = `${strippedCount} Anmerkungen, Notizen und Textmarker rückstandslos gelöscht.`;
    }

    onProgress?.(80, 'PDF wird finalisiert...');
    const savedBytes = await pdf.save({
      useObjectStreams: true,
      addDefaultPage: false,
    });

    const finalBlob = new Blob([savedBytes as unknown as BlobPart], { type: 'application/pdf' });
    const outName = `${file.name.replace(/\.[^/.]+$/, '')}${suffix}`;

    onProgress?.(100, 'Fertig');
    return { blob: finalBlob, fileName: outName, audit, size: finalBlob.size };
  };

  // Single file execute
  const executeSingleProcessing = async () => {
    if (!singleFile) return;
    setIsProcessing(true);
    setProgress(20);
    setStatusText('PDF-Dokument wird analysiert...');
    trackEvent('conversion_started', { toolSlug, mode });

    try {
      const result = await processSinglePdf(singleFile, (p, msg) => {
        setProgress(p);
        if (msg) setStatusText(msg);
      });

      setResultBlob(result.blob);
      setOutputFilename(result.fileName);
      setAuditMessage(result.audit);

      if (result.size < singleFile.size) {
        const saved = Math.round(((singleFile.size - result.size) / singleFile.size) * 100);
        setReductionPct(saved);
      }

      setIsProcessing(false);
      trackEvent('conversion_completed', { toolSlug, mode });
    } catch (err: any) {
      console.error(err);
      setIsProcessing(false);
      alert('Fehler bei der PDF-Verarbeitung.');
      trackEvent('conversion_failed', { toolSlug, mode });
    }
  };

  // Batch execute
  const startBatch = async () => {
    if (batchItems.length === 0) return;
    setIsProcessing(true);
    abortControllerRef.current = new AbortController();

    const tasks = batchItems.map((item) => ({
      id: item.id,
      run: async (signal?: AbortSignal) => {
        if (signal?.aborted) throw new Error('Abgebrochen');
        return await processSinglePdf(item.file, (pct, statusText) => {
          setBatchItems((prev) =>
            prev.map((i) => (i.id === item.id ? { ...i, progress: pct, statusText } : i))
          );
        });
      },
    }));

    await runConcurrentBatch(tasks, {
      concurrency: limits.clientConcurrency,
      signal: abortControllerRef.current.signal,
      onItemStart: (id) => {
        setBatchItems((prev) =>
          prev.map((i) => (i.id === id ? { ...i, status: 'processing', progress: 10 } : i))
        );
      },
      onItemComplete: (id, result) => {
        setBatchItems((prev) =>
          prev.map((i) =>
            i.id === id
              ? {
                  ...i,
                  status: 'completed',
                  progress: 100,
                  outputBlob: result.blob,
                  outputFileName: result.fileName,
                  outputSize: result.size,
                }
              : i
          )
        );
      },
      onItemError: (id, err) => {
        setBatchItems((prev) =>
          prev.map((i) =>
            i.id === id ? { ...i, status: 'failed', error: err.message, progress: 0 } : i
          )
        );
      },
    });

    setIsProcessing(false);
  };

  const cancelBatch = () => {
    abortControllerRef.current?.abort();
    setIsProcessing(false);
    setBatchItems((prev) =>
      prev.map((i) => (i.status === 'processing' || i.status === 'queued' ? { ...i, status: 'cancelled' } : i))
    );
  };

  const clearQueue = () => {
    setBatchItems([]);
    setIsBatchMode(false);
  };

  const removeItem = (id: string) => {
    setBatchItems((prev) => prev.filter((i) => i.id !== id));
  };

  const downloadItem = (item: BatchItem) => {
    if (item.outputBlob && item.outputFileName) {
      downloadBlob(item.outputBlob, item.outputFileName);
    }
  };

  const downloadAllZip = async () => {
    const completedItems = batchItems.filter((i) => i.status === 'completed' && i.outputBlob);
    if (completedItems.length === 0) return;

    setIsZipping(true);
    try {
      const zip = new JSZip();
      completedItems.forEach((item) => {
        if (item.outputBlob && item.outputFileName) {
          zip.file(item.outputFileName, item.outputBlob);
        }
      });

      const zipBlob = await zip.generateAsync({ type: 'blob' });
      downloadBlob(zipBlob, `coolwave_${mode}_stapel_${Date.now()}.zip`);
    } catch (err) {
      console.error('[Zip Error]:', err);
      alert('Fehler beim Erstellen des ZIP-Archivs.');
    } finally {
      setIsZipping(false);
    }
  };

  const handleResetSingle = () => {
    setSingleFile(null);
    setResultBlob(null);
    setOutputFilename('');
    setAuditMessage('');
    setReductionPct(null);
    setIsProcessing(false);
  };

  if (resultBlob && singleFile) {
    return (
      <div className="space-y-6 w-full">
        {auditMessage && (
          <div className="p-4 rounded-xl bg-emerald-50 border border-emerald-200 text-emerald-800 flex items-start gap-3">
            <CheckCircle2 className="w-5 h-5 text-emerald-600 shrink-0 mt-0.5" />
            <div>
              <p className="text-sm font-semibold">Erfolgreich verarbeitet</p>
              <p className="text-xs text-emerald-700 mt-0.5">{auditMessage}</p>
            </div>
          </div>
        )}

        <DownloadBox
          filename={outputFilename}
          originalSizeBytes={singleFile.size}
          resultSizeBytes={resultBlob.size}
          onDownload={() => downloadBlob(resultBlob, outputFilename)}
          onReset={handleResetSingle}
          downloadLabel="Verarbeitetes PDF herunterladen"
        />
      </div>
    );
  }

  if (isProcessing && !isBatchMode) {
    return <ProcessingStatus progress={progress} statusText={statusText} />;
  }

  return (
    <div className="w-full space-y-6">
      {isBatchMode && batchItems.length > 0 ? (
        <BatchProcessingQueue
          items={batchItems}
          isProcessing={isProcessing}
          onStartBatch={startBatch}
          onCancelBatch={cancelBatch}
          onClearQueue={clearQueue}
          onRemoveItem={removeItem}
          onDownloadItem={downloadItem}
          onDownloadAllZip={downloadAllZip}
          isZipping={isZipping}
          toolTitle={`${getModeTitle()} (Stapelverarbeitung)`}
        />
      ) : !singleFile ? (
        <FileUploader
          acceptedExtensions={['.pdf']}
          maxFileSizeMB={limits.maxFileSizeMB}
          allowMultiple={true}
          onFilesSelected={handleFilesSelected}
          title="PDF-Dateien hier ablegen (Einzel- oder Stapelmodus)"
          subtitle={`Bis zu ${limits.maxBatchFiles} PDFs gleichzeitig verarbeiten (${isPro ? 'Pro' : 'Kostenlos'})`}
        />
      ) : (
        /* Single File View (Preserved) */
        <div className="bg-white rounded-2xl border border-slate-200 p-6 sm:p-8 shadow-sm">
          <div className="flex items-center gap-3 pb-6 border-b border-slate-100">
            <div className="p-2.5 rounded-lg bg-sky-50 text-sky-700">
              {getModeIcon()}
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900">{singleFile.name}</h3>
              <p className="text-xs text-slate-500 mt-0.5">
                Dateigröße: <span className="font-semibold text-slate-700">{formatBytes(singleFile.size)}</span>
              </p>
            </div>
          </div>

          <div className="pt-6 flex flex-col sm:flex-row items-center justify-between gap-4">
            <button
              onClick={handleResetSingle}
              className="text-xs text-slate-500 hover:text-slate-800 font-medium"
            >
              Anderes Dokument wählen
            </button>

            <button
              onClick={executeSingleProcessing}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm sm:text-base shadow-sm transition-colors"
            >
              {getModeIcon()}
              <span>{getModeTitle()}</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { PDFDocument, degrees } from 'pdf-lib';
import { RotateCw, RotateCcw, FileText, Check } from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { DownloadBox } from '@/components/tools/DownloadBox';
import { downloadBlob, formatBytes } from '@/lib/utils';
import { trackEvent } from '@/lib/analytics';

export function PdfRotateEngine() {
  const [file, setFile] = useState<File | null>(null);
  const [rotationAngle, setRotationAngle] = useState<number>(90);
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [rotatedBlob, setRotatedBlob] = useState<Blob | null>(null);
  const [outputFilename, setOutputFilename] = useState('');

  const handleFileSelected = (files: File[]) => {
    if (files.length > 0) {
      setFile(files[0]);
      trackEvent('upload_completed', { toolSlug: 'pdf-drehen', size: files[0].size });
    }
  };

  const executeRotate = async () => {
    if (!file) return;
    setIsProcessing(true);
    setProgress(25);
    setStatusText('PDF-Seiten werden geladen...');
    trackEvent('conversion_started', { toolSlug: 'pdf-drehen', angle: rotationAngle });

    try {
      const buffer = await file.arrayBuffer();
      const pdf = await PDFDocument.load(buffer, { ignoreEncryption: true });
      const pages = pdf.getPages();

      setProgress(60);
      setStatusText(`Drehe ${pages.length} Seiten um ${rotationAngle}°...`);

      pages.forEach((page) => {
        const currentRotation = page.getRotation().angle;
        page.setRotation(degrees((currentRotation + rotationAngle) % 360));
      });

      setProgress(85);
      setStatusText('Dokument wird gespeichert...');

      const rotatedBytes = await pdf.save();
      const blob = new Blob([rotatedBytes as unknown as BlobPart], { type: 'application/pdf' });
      setRotatedBlob(blob);
      setOutputFilename(`coolwave_gedreht_${file.name}`);

      setProgress(100);
      setIsProcessing(false);
      trackEvent('conversion_completed', { toolSlug: 'pdf-drehen' });
    } catch (err) {
      console.error(err);
      setIsProcessing(false);
      alert('Fehler beim Drehen der PDF. Bitte prüfen Sie, ob die Datei geschützt ist.');
      trackEvent('conversion_failed', { toolSlug: 'pdf-drehen' });
    }
  };

  const handleDownload = () => {
    if (!rotatedBlob) return;
    downloadBlob(rotatedBlob, outputFilename);
    trackEvent('download_completed', { toolSlug: 'pdf-drehen' });
  };

  const handleReset = () => {
    setFile(null);
    setRotatedBlob(null);
    setIsProcessing(false);
  };

  if (rotatedBlob && file) {
    return (
      <DownloadBox
        filename={outputFilename}
        originalSizeBytes={file.size}
        resultSizeBytes={rotatedBlob.size}
        onDownload={handleDownload}
        onReset={handleReset}
        downloadLabel="Gedrehtes PDF herunterladen"
      />
    );
  }

  if (isProcessing) {
    return <ProcessingStatus progress={progress} statusText={statusText} />;
  }

  return (
    <div className="w-full">
      {!file ? (
        <FileUploader
          acceptedExtensions={['.pdf']}
          maxFileSizeMB={50}
          onFilesSelected={handleFileSelected}
          title="PDF zum Drehen ablegen"
          subtitle="Drehen Sie querliegende oder auf dem Kopf stehende Seiten dauerhaft"
        />
      ) : (
        <div className="bg-white rounded-2xl border border-slate-200 p-6 sm:p-8 shadow-sm">
          <div className="flex items-center gap-3 pb-6 border-b border-slate-100">
            <div className="p-2.5 rounded-lg bg-sky-50 text-sky-700">
              <FileText className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900">{file.name}</h3>
              <p className="text-xs text-slate-500">{formatBytes(file.size)}</p>
            </div>
          </div>

          <div className="py-6">
            <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-3">
              Drehwinkel wählen
            </label>

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              <button
                type="button"
                onClick={() => setRotationAngle(90)}
                className={`p-4 rounded-xl border text-center transition-all ${
                  rotationAngle === 90
                    ? 'border-sky-600 bg-sky-50/50 text-sky-950 ring-1 ring-sky-600 font-bold'
                    : 'border-slate-200 hover:border-slate-300'
                }`}
              >
                <RotateCw className="w-5 h-5 mx-auto mb-2 text-sky-600" />
                <span className="text-sm">90° Rechts</span>
                <span className="block text-[11px] text-slate-400 font-normal mt-0.5">
                  Im Uhrzeigersinn
                </span>
              </button>

              <button
                type="button"
                onClick={() => setRotationAngle(180)}
                className={`p-4 rounded-xl border text-center transition-all ${
                  rotationAngle === 180
                    ? 'border-sky-600 bg-sky-50/50 text-sky-950 ring-1 ring-sky-600 font-bold'
                    : 'border-slate-200 hover:border-slate-300'
                }`}
              >
                <RotateCw className="w-5 h-5 mx-auto mb-2 text-sky-600" />
                <span className="text-sm">180° Drehen</span>
                <span className="block text-[11px] text-slate-400 font-normal mt-0.5">
                  Auf den Kopf
                </span>
              </button>

              <button
                type="button"
                onClick={() => setRotationAngle(270)}
                className={`p-4 rounded-xl border text-center transition-all ${
                  rotationAngle === 270
                    ? 'border-sky-600 bg-sky-50/50 text-sky-950 ring-1 ring-sky-600 font-bold'
                    : 'border-slate-200 hover:border-slate-300'
                }`}
              >
                <RotateCcw className="w-5 h-5 mx-auto mb-2 text-sky-600" />
                <span className="text-sm">90° Links</span>
                <span className="block text-[11px] text-slate-400 font-normal mt-0.5">
                  Gegen Uhrzeigersinn
                </span>
              </button>
            </div>
          </div>

          <div className="pt-6 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4">
            <button
              onClick={handleReset}
              className="text-xs text-slate-500 hover:text-slate-800 font-medium"
            >
              Andere Datei wählen
            </button>

            <button
              onClick={executeRotate}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm sm:text-base shadow-sm transition-colors"
            >
              <RotateCw className="w-4 h-4" />
              <span>Seiten dauerhaft drehen</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useRef, useEffect } from 'react';
import { PenTool, FileText, CheckCircle2, ShieldCheck, RotateCcw, Upload, Type } from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { DownloadBox } from '@/components/tools/DownloadBox';
import { downloadBlob, formatBytes } from '@/lib/utils';
import { trackEvent } from '@/lib/analytics';

type SignMode = 'draw' | 'type' | 'upload';

export function PdfSignEngine() {
  const [file, setFile] = useState<File | null>(null);
  const [signMode, setSignMode] = useState<SignMode>('draw');
  const [signerName, setSignerName] = useState('');
  const [reason, setReason] = useState('Vertragsabschluss & Dokumentenfreigabe');
  const [typedSignature, setTypedSignature] = useState('');
  const [uploadedSignatureUrl, setUploadedSignatureUrl] = useState<string | null>(null);

  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [hasDrawn, setHasDrawn] = useState(false);

  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [resultBlob, setResultBlob] = useState<Blob | null>(null);
  const [outputFilename, setOutputFilename] = useState('');
  const [error, setError] = useState<string | null>(null);

  const handleFileSelected = (files: File[]) => {
    if (files.length > 0) {
      setFile(files[0]);
      setError(null);
      trackEvent('upload_completed', { toolSlug: 'pdf-signieren' });
    }
  };

  // Canvas drawing handlers
  const startDrawing = (e: React.MouseEvent<HTMLCanvasElement> | React.TouchEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    setIsDrawing(true);
    setHasDrawn(true);
    const rect = canvas.getBoundingClientRect();
    const x = 'touches' in e ? e.touches[0].clientX - rect.left : e.clientX - rect.left;
    const y = 'touches' in e ? e.touches[0].clientY - rect.top : e.clientY - rect.top;

    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineWidth = 2.5;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = '#0284c7'; // CoolWave Blue signature ink
  };

  const draw = (e: React.MouseEvent<HTMLCanvasElement> | React.TouchEvent<HTMLCanvasElement>) => {
    if (!isDrawing) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const rect = canvas.getBoundingClientRect();
    const x = 'touches' in e ? e.touches[0].clientX - rect.left : e.clientX - rect.left;
    const y = 'touches' in e ? e.touches[0].clientY - rect.top : e.clientY - rect.top;

    ctx.lineTo(x, y);
    ctx.stroke();
  };

  const stopDrawing = () => {
    setIsDrawing(false);
  };

  const clearCanvas = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    setHasDrawn(false);
  };

  // Upload signature image handler
  const handleSignatureUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const imgFile = e.target.files?.[0];
    if (imgFile) {
      const reader = new FileReader();
      reader.onload = () => {
        setUploadedSignatureUrl(reader.result as string);
      };
      reader.readAsDataURL(imgFile);
    }
  };

  // Render typed signature onto an offscreen canvas
  const getTypedSignatureDataUrl = (): string | null => {
    if (!typedSignature.trim()) return null;
    const offscreen = document.createElement('canvas');
    offscreen.width = 400;
    offscreen.height = 120;
    const ctx = offscreen.getContext('2d');
    if (!ctx) return null;

    ctx.fillStyle = '#0284c7';
    ctx.font = 'italic 42px "Brush Script MT", "Segoe Script", cursive, sans-serif';
    ctx.textBaseline = 'middle';
    ctx.fillText(typedSignature, 30, 60);
    return offscreen.toDataURL('image/png');
  };

  const handleExecute = async () => {
    if (!file) return;

    let signaturePngBase64: string | undefined;

    if (signMode === 'draw') {
      if (!hasDrawn || !canvasRef.current) {
        setError('Bitte zeichnen Sie Ihre Unterschrift in das vorgesehene Feld.');
        return;
      }
      signaturePngBase64 = canvasRef.current.toDataURL('image/png');
    } else if (signMode === 'type') {
      const dataUrl = getTypedSignatureDataUrl();
      if (!dataUrl) {
        setError('Bitte geben Sie Ihren Namen für die Signatur ein.');
        return;
      }
      signaturePngBase64 = dataUrl;
    } else if (signMode === 'upload') {
      if (!uploadedSignatureUrl) {
        setError('Bitte laden Sie eine Bilddatei Ihrer Unterschrift hoch.');
        return;
      }
      signaturePngBase64 = uploadedSignatureUrl;
    }

    setIsProcessing(true);
    setError(null);
    setProgress(20);
    setStatusText('Signatur und SHA-256 Integritätsstempel werden generiert...');

    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('action', 'sign');
      if (signaturePngBase64) {
        formData.append('signature', signaturePngBase64);
      }
      formData.append('signerName', signerName.trim() || 'CoolWave Benutzer');
      formData.append('reason', reason.trim() || 'Dokumentenfreigabe');

      setProgress(55);

      const res = await fetch('/api/v1/pdf/security', {
        method: 'POST',
        body: formData,
      });

      if (!res.ok) {
        let errMessage = 'Fehler beim Signieren des PDFs.';
        try {
          const errData = await res.json();
          if (errData.error) errMessage = errData.error;
        } catch {
          // Fallback
        }
        throw new Error(errMessage);
      }

      setProgress(85);
      setStatusText('Kryptografische Signatur wird eingebettet...');

      const blob = await res.blob();
      const contentDisposition = res.headers.get('Content-Disposition');
      let outName = `signiert_${file.name}`;
      if (contentDisposition && contentDisposition.includes('filename=')) {
        const match = contentDisposition.match(/filename="?([^";]+)"?/);
        if (match?.[1]) outName = decodeURIComponent(match[1]);
      }

      setResultBlob(blob);
      setOutputFilename(outName);
      setProgress(100);
      setIsProcessing(false);
      trackEvent('conversion_completed', { toolSlug: 'pdf-signieren' });
    } catch (err: unknown) {
      const msg = (err as Error).message || 'Fehler beim Signieren.';
      setError(msg);
      setIsProcessing(false);
      trackEvent('conversion_failed', { toolSlug: 'pdf-signieren' });
    }
  };

  const handleDownload = () => {
    if (!resultBlob) return;
    downloadBlob(resultBlob, outputFilename);
    trackEvent('download_completed', { toolSlug: 'pdf-signieren' });
  };

  const handleReset = () => {
    setFile(null);
    setSignerName('');
    setTypedSignature('');
    setUploadedSignatureUrl(null);
    clearCanvas();
    setResultBlob(null);
    setError(null);
    setIsProcessing(false);
  };

  if (resultBlob && file) {
    return (
      <DownloadBox
        filename={outputFilename}
        originalSizeBytes={file.size}
        resultSizeBytes={resultBlob.size}
        onDownload={handleDownload}
        onReset={handleReset}
        downloadLabel="Signiertes PDF herunterladen"
      />
    );
  }

  if (isProcessing) {
    return <ProcessingStatus progress={progress} statusText={statusText} />;
  }

  return (
    <div className="w-full">
      {!file ? (
        <FileUploader
          acceptedExtensions={['.pdf']}
          maxFileSizeMB={50}
          onFilesSelected={handleFileSelected}
          title="PDF zum Signieren ablegen"
          subtitle="Rechtssichere digitale Signatur mit SHA-256 Integritätsprüfung erstellen"
        />
      ) : (
        <div className="bg-white rounded-2xl border border-slate-200 p-6 sm:p-8 shadow-sm">
          <div className="flex items-center gap-3 pb-6 border-b border-slate-100">
            <div className="p-2.5 rounded-lg bg-sky-50 text-sky-700">
              <FileText className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900">{file.name}</h3>
              <p className="text-xs text-slate-500">{formatBytes(file.size)}</p>
            </div>
          </div>

          <div className="py-6 space-y-6 max-w-lg">
            {/* Signature Creation Tabs */}
            <div>
              <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                Unterschrift erstellen
              </label>
              <div className="flex gap-2 p-1 bg-slate-100 rounded-xl mb-4">
                <button
                  type="button"
                  onClick={() => setSignMode('draw')}
                  className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all flex items-center justify-center gap-1.5 ${
                    signMode === 'draw'
                      ? 'bg-white text-slate-900 shadow-sm'
                      : 'text-slate-600 hover:text-slate-900'
                  }`}
                >
                  <PenTool className="w-3.5 h-3.5" />
                  <span>Zeichnen</span>
                </button>
                <button
                  type="button"
                  onClick={() => setSignMode('type')}
                  className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all flex items-center justify-center gap-1.5 ${
                    signMode === 'type'
                      ? 'bg-white text-slate-900 shadow-sm'
                      : 'text-slate-600 hover:text-slate-900'
                  }`}
                >
                  <Type className="w-3.5 h-3.5" />
                  <span>Tippen</span>
                </button>
                <button
                  type="button"
                  onClick={() => setSignMode('upload')}
                  className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all flex items-center justify-center gap-1.5 ${
                    signMode === 'upload'
                      ? 'bg-white text-slate-900 shadow-sm'
                      : 'text-slate-600 hover:text-slate-900'
                  }`}
                >
                  <Upload className="w-3.5 h-3.5" />
                  <span>Bild laden</span>
                </button>
              </div>

              {/* Mode: Draw */}
              {signMode === 'draw' && (
                <div className="space-y-2">
                  <div className="relative border-2 border-dashed border-slate-300 rounded-xl bg-slate-50 overflow-hidden cursor-crosshair">
                    <canvas
                      ref={canvasRef}
                      width={460}
                      height={140}
                      onMouseDown={startDrawing}
                      onMouseMove={draw}
                      onMouseUp={stopDrawing}
                      onMouseLeave={stopDrawing}
                      onTouchStart={startDrawing}
                      onTouchMove={draw}
                      onTouchEnd={stopDrawing}
                      className="w-full h-36 touch-none"
                    />
                    {!hasDrawn && (
                      <div className="absolute inset-0 flex items-center justify-center pointer-events-none text-slate-400 text-xs">
                        Hier mit Maus oder Touchpad unterschreiben...
                      </div>
                    )}
                  </div>
                  <div className="flex justify-end">
                    <button
                      type="button"
                      onClick={clearCanvas}
                      className="text-xs text-slate-500 hover:text-rose-600 inline-flex items-center gap-1 font-medium"
                    >
                      <RotateCcw className="w-3 h-3" />
                      <span>Unterschrift löschen</span>
                    </button>
                  </div>
                </div>
              )}

              {/* Mode: Type */}
              {signMode === 'type' && (
                <div className="space-y-3">
                  <input
                    type="text"
                    value={typedSignature}
                    onChange={(e) => setTypedSignature(e.target.value)}
                    placeholder="Vorname Nachname eingeben..."
                    className="w-full px-3.5 py-2.5 rounded-xl border border-slate-300 bg-white text-slate-900 text-sm focus:outline-none focus:ring-2 focus:ring-sky-500"
                  />
                  {typedSignature && (
                    <div className="p-4 bg-sky-50 border border-sky-100 rounded-xl text-center">
                      <span className="text-3xl text-sky-700 italic font-serif">
                        {typedSignature}
                      </span>
                    </div>
                  )}
                </div>
              )}

              {/* Mode: Upload */}
              {signMode === 'upload' && (
                <div className="space-y-3">
                  <input
                    type="file"
                    accept="image/png, image/jpeg, image/webp"
                    onChange={handleSignatureUpload}
                    className="w-full text-xs text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-xl file:border-0 file:text-xs file:font-semibold file:bg-sky-50 file:text-sky-700 hover:file:bg-sky-100"
                  />
                  {uploadedSignatureUrl && (
                    <div className="p-3 bg-slate-50 rounded-xl border border-slate-200 flex justify-center">
                      {/* eslint-disable-next-line @next/next/no-img-element */}
                      <img
                        src={uploadedSignatureUrl}
                        alt="Hochgeladene Unterschrift Vorschau"
                        className="max-h-20 object-contain"
                      />
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Audit Details */}
            <div className="space-y-4 pt-2">
              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                  Name des Unterzeichners
                </label>
                <input
                  type="text"
                  value={signerName}
                  onChange={(e) => setSignerName(e.target.value)}
                  placeholder="z. B. Max Mustermann"
                  className="w-full px-3.5 py-2.5 rounded-xl border border-slate-300 bg-white text-slate-900 text-sm focus:outline-none focus:ring-2 focus:ring-sky-500"
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                  Signaturgrund / Verwendungszweck
                </label>
                <input
                  type="text"
                  value={reason}
                  onChange={(e) => setReason(e.target.value)}
                  placeholder="z. B. Geprüft und freigegeben"
                  className="w-full px-3.5 py-2.5 rounded-xl border border-slate-300 bg-white text-slate-900 text-sm focus:outline-none focus:ring-2 focus:ring-sky-500"
                />
              </div>
            </div>

            {/* Verification badge preview info */}
            <div className="p-3.5 bg-emerald-50/70 border border-emerald-200 rounded-xl space-y-1.5 text-xs text-emerald-950">
              <div className="flex items-center gap-1.5 font-bold text-emerald-900">
                <ShieldCheck className="w-4 h-4 text-emerald-600" />
                <span>Digitale CoolWave Prüfmarke</span>
              </div>
              <p className="text-emerald-900/80 leading-relaxed text-[11px]">
                Das Dokument erhält auf der letzten Seite einen fälschungssicheren Prüfstempel
                inklusive aktuellem Zeitstempel und SHA-256 Integritätshash.
              </p>
            </div>

            {error && (
              <div className="p-3 rounded-lg bg-rose-50 border border-rose-200 text-rose-700 text-xs">
                {error}
              </div>
            )}
          </div>

          <div className="pt-6 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4">
            <button
              onClick={handleReset}
              className="text-xs text-slate-500 hover:text-slate-800 font-medium"
            >
              Andere Datei wählen
            </button>

            <button
              onClick={handleExecute}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm sm:text-base shadow-sm transition-colors"
            >
              <CheckCircle2 className="w-4 h-4" />
              <span>PDF jetzt signieren</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import JSZip from 'jszip';
import { 
  FileImage, 
  RefreshCw 
} from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { DownloadBox } from '@/components/tools/DownloadBox';
import { downloadBlob, formatBytes } from '@/lib/utils';
import { trackEvent } from '@/lib/analytics';

interface PdfToImageEngineProps {
  targetFormat: 'JPG' | 'PNG';
}

export function PdfToImageEngine({ targetFormat }: PdfToImageEngineProps) {
  const [file, setFile] = useState<File | null>(null);
  const [pageCount, setPageCount] = useState<number>(0);
  const [firstPagePreview, setFirstPagePreview] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState<boolean>(false);
  const [progress, setProgress] = useState<number>(0);
  const [statusText, setStatusText] = useState<string>('');
  const [resultBlob, setResultBlob] = useState<Blob | null>(null);
  const [outputFilename, setOutputFilename] = useState<string>('');
  const [error, setError] = useState<string | null>(null);

  const handleFileSelected = async (files: File[]) => {
    if (files.length === 0) return;
    const f = files[0];
    setFile(f);
    setError(null);
    setIsProcessing(true);
    setProgress(20);
    setStatusText('PDF wird analysiert & Vorschau generiert...');

    try {
      const pdfjsLib = await import('pdfjs-dist');
      if (!pdfjsLib.GlobalWorkerOptions.workerSrc) {
        pdfjsLib.GlobalWorkerOptions.workerSrc = `https://unpkg.com/pdfjs-dist@${pdfjsLib.version}/build/pdf.worker.min.mjs`;
      }

      const buffer = await f.arrayBuffer();
      const loadingTask = pdfjsLib.getDocument({ data: new Uint8Array(buffer) });
      const pdf = await loadingTask.promise;
      const count = pdf.numPages;
      setPageCount(count);

      // Render first page preview
      const page1 = await pdf.getPage(1);
      const viewport = page1.getViewport({ scale: 0.8 });
      const canvas = document.createElement('canvas');
      canvas.width = viewport.width;
      canvas.height = viewport.height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        await page1.render({ canvasContext: ctx, viewport }).promise;
        setFirstPagePreview(canvas.toDataURL('image/jpeg', 0.8));
      }

      setIsProcessing(false);
      trackEvent('upload_completed', { targetFormat, pageCount: count });
    } catch (err) {
      console.error(err);
      setError('Die PDF-Datei konnte nicht gerendert werden. Eventuell ist sie passwortgeschützt.');
      setIsProcessing(false);
      setFile(null);
    }
  };

  const executeRasterization = async () => {
    if (!file) return;
    setError(null);
    setIsProcessing(true);
    setProgress(10);
    setStatusText('PDF-Seiten werden als Bilder gerendert...');
    trackEvent('conversion_started', { targetFormat });

    try {
      const pdfjsLib = await import('pdfjs-dist');
      if (!pdfjsLib.GlobalWorkerOptions.workerSrc) {
        pdfjsLib.GlobalWorkerOptions.workerSrc = `https://unpkg.com/pdfjs-dist@${pdfjsLib.version}/build/pdf.worker.min.mjs`;
      }

      const buffer = await file.arrayBuffer();
      const loadingTask = pdfjsLib.getDocument({ data: new Uint8Array(buffer) });
      const pdf = await loadingTask.promise;
      const count = pdf.numPages;

      const mimeType = targetFormat === 'JPG' ? 'image/jpeg' : 'image/png';
      const extension = targetFormat.toLowerCase();
      const base = file.name.substring(0, file.name.lastIndexOf('.')) || file.name;

      if (count === 1) {
        // Single page: direct image download
        setProgress(50);
        setStatusText('Seite 1 wird gerendert...');
        const page = await pdf.getPage(1);
        const viewport = page.getViewport({ scale: 2.0 }); // 2x high resolution
        const canvas = document.createElement('canvas');
        canvas.width = viewport.width;
        canvas.height = viewport.height;
        const ctx = canvas.getContext('2d');
        if (!ctx) throw new Error('Canvas context not available');

        if (targetFormat === 'JPG') {
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(0, 0, canvas.width, canvas.height);
        }

        await page.render({ canvasContext: ctx, viewport }).promise;

        canvas.toBlob((blob) => {
          if (!blob) throw new Error('Bild-Generierung fehlgeschlagen');
          setResultBlob(blob);
          setOutputFilename(`coolwave_${base}.${extension}`);
          setProgress(100);
          setIsProcessing(false);
          trackEvent('conversion_completed', { targetFormat, pages: 1 });
        }, mimeType, targetFormat === 'JPG' ? 0.92 : undefined);
      } else {
        // Multi-page: render all pages and bundle into ZIP
        const zip = new JSZip();

        for (let i = 1; i <= count; i++) {
          const currentProgress = 10 + Math.round((i / count) * 75);
          setProgress(currentProgress);
          setStatusText(`Seite ${i} von ${count} wird gerendert...`);

          const page = await pdf.getPage(i);
          const viewport = page.getViewport({ scale: 2.0 });
          const canvas = document.createElement('canvas');
          canvas.width = viewport.width;
          canvas.height = viewport.height;
          const ctx = canvas.getContext('2d');
          if (!ctx) continue;

          if (targetFormat === 'JPG') {
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
          }

          await page.render({ canvasContext: ctx, viewport }).promise;

          const dataUrl = canvas.toDataURL(mimeType, targetFormat === 'JPG' ? 0.92 : undefined);
          const base64Data = dataUrl.split(',')[1];
          const padIndex = String(i).padStart(2, '0');
          zip.file(`seite_${padIndex}.${extension}`, base64Data, { base64: true });
        }

        setProgress(90);
        setStatusText('ZIP-Archiv wird erstellt...');

        const zipBlob = await zip.generateAsync({ type: 'blob' });
        setResultBlob(zipBlob);
        setOutputFilename(`coolwave_${base}_${targetFormat.toLowerCase()}.zip`);
        setProgress(100);
        setIsProcessing(false);
        trackEvent('conversion_completed', { targetFormat, pages: count });
      }
    } catch (err) {
      console.error(err);
      setError('Fehler bei der Umwandlung der PDF in Bilder.');
      setIsProcessing(false);
    }
  };

  const handleDownload = () => {
    if (!resultBlob) return;
    downloadBlob(resultBlob, outputFilename);
    trackEvent('download_completed', { targetFormat });
  };

  const handleReset = () => {
    setFile(null);
    setResultBlob(null);
    setFirstPagePreview(null);
    setPageCount(0);
    setProgress(0);
    setIsProcessing(false);
    setError(null);
  };

  return (
    <div className="w-full">
      {!file && (
        <FileUploader
          onFilesSelected={handleFileSelected}
          allowMultiple={false}
          maxFileSizeMB={50}
          acceptedExtensions={['.pdf']}
          title={`PDF in ${targetFormat} umwandeln`}
          subtitle={`Wählen Sie eine PDF-Datei, um alle Seiten als ${targetFormat} zu exportieren`}
        />
      )}

      {error && (
        <div className="mt-4 p-4 rounded-xl bg-rose-50 border border-rose-200 text-rose-700 text-sm font-medium">
          {error}
        </div>
      )}

      {file && !resultBlob && !isProcessing && (
        <div className="p-6 rounded-2xl bg-white border border-slate-200 shadow-sm space-y-6">
          <div className="flex flex-wrap items-center justify-between gap-4 pb-4 border-b border-slate-100">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-sky-50 text-sky-700 flex items-center justify-center border border-sky-100">
                <FileImage className="w-5 h-5" />
              </div>
              <div>
                <h3 className="font-bold text-slate-900 text-sm sm:text-base">{file.name}</h3>
                <p className="text-xs text-slate-500">
                  {pageCount} {pageCount === 1 ? 'Seite' : 'Seiten'} • {formatBytes(file.size)}
                </p>
              </div>
            </div>

            <button
              onClick={handleReset}
              className="text-xs font-semibold text-slate-500 hover:text-slate-700 underline"
            >
              Anderes PDF wählen
            </button>
          </div>

          {/* First Page Preview */}
          {firstPagePreview && (
            <div className="flex flex-col items-center p-4 bg-slate-50/60 rounded-xl border border-slate-100">
              <span className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-3">
                Vorschau (Seite 1 von {pageCount}):
              </span>
              <img
                src={firstPagePreview}
                alt={file ? `PDF-Vorschau von ${file.name}` : "PDF-Seitenvorschau"}
                className="max-h-64 rounded-lg shadow-sm border border-slate-200 object-contain"
              />
            </div>
          )}

          <div>
            <button
              onClick={executeRasterization}
              className="w-full py-3.5 px-6 rounded-xl bg-sky-600 hover:bg-sky-500 text-white font-bold text-sm shadow-sm transition-colors flex items-center justify-center gap-2"
            >
              <FileImage className="w-4 h-4" />
              <span>
                {pageCount === 1 
                  ? `Als hochauflösendes ${targetFormat} umwandeln`
                  : `Alle ${pageCount} Seiten in ${targetFormat} umwandeln (ZIP-Download)`
                }
              </span>
            </button>
          </div>
        </div>
      )}

      {isProcessing && (
        <ProcessingStatus
          progress={progress}
          statusText={statusText}
        />
      )}

      {resultBlob && (
        <div className="space-y-4">
          <DownloadBox
            filename={outputFilename}
            resultSizeBytes={resultBlob.size}
            onDownload={handleDownload}
            onReset={handleReset}
            downloadLabel={
              outputFilename.endsWith('.zip')
                ? 'ZIP-Archiv mit allen Bildern herunterladen'
                : `${targetFormat}-Bild jetzt herunterladen`
            }
          />

          <div className="text-center">
            <button
              onClick={handleReset}
              className="inline-flex items-center gap-1.5 text-xs text-slate-500 hover:text-slate-700 font-medium"
            >
              <RefreshCw className="w-3.5 h-3.5" />
              <span>Weiteres PDF in Bilder umwandeln</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { PDFDocument, rgb, degrees, StandardFonts } from 'pdf-lib';
import { Stamp, FileText, Image as ImageIcon, Check, Type } from 'lucide-react';
import { FileUploader } from '@/components/tools/FileUploader';
import { ProcessingStatus } from '@/components/tools/ProcessingStatus';
import { DownloadBox } from '@/components/tools/DownloadBox';
import { downloadBlob, formatBytes } from '@/lib/utils';
import { trackEvent } from '@/lib/analytics';

type WatermarkMode = 'text' | 'image';

export function PdfWatermarkEngine() {
  const [file, setFile] = useState<File | null>(null);
  const [mode, setMode] = useState<WatermarkMode>('text');

  // Text watermark state
  const [watermarkText, setWatermarkText] = useState('VERTRAULICH');
  const [textColor, setTextColor] = useState<'red' | 'gray' | 'blue' | 'black'>('red');
  const [opacity, setOpacity] = useState(30); // percent
  const [fontSize, setFontSize] = useState(50);
  const [isDiagonal, setIsDiagonal] = useState(true);
  const [skipFirstPage, setSkipFirstPage] = useState(false);

  // Image watermark state
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [imageScale, setImageScale] = useState(40); // percent of page width

  // Processing state
  const [isProcessing, setIsProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [statusText, setStatusText] = useState('');
  const [resultBlob, setResultBlob] = useState<Blob | null>(null);
  const [outputFilename, setOutputFilename] = useState('');

  const handleFileSelected = (files: File[]) => {
    if (files.length > 0) {
      setFile(files[0]);
      trackEvent('upload_completed', { toolSlug: 'pdf-wasserzeichen' });
    }
  };

  const handleImageSelected = (e: React.ChangeEvent<HTMLInputElement>) => {
    const f = e.target.files?.[0];
    if (f) {
      setImageFile(f);
      const url = URL.createObjectURL(f);
      setImagePreview(url);
    }
  };

  const getColorRgb = () => {
    switch (textColor) {
      case 'red': return rgb(0.85, 0.15, 0.15);
      case 'gray': return rgb(0.45, 0.45, 0.45);
      case 'blue': return rgb(0.1, 0.35, 0.8);
      case 'black': return rgb(0.1, 0.1, 0.1);
      default: return rgb(0.85, 0.15, 0.15);
    }
  };

  const applyWatermark = async () => {
    if (!file) return;
    if (mode === 'text' && !watermarkText.trim()) return;
    if (mode === 'image' && !imageFile) return;

    setIsProcessing(true);
    setProgress(15);
    setStatusText('PDF wird geladen...');
    trackEvent('conversion_started', { toolSlug: 'pdf-wasserzeichen', mode });

    try {
      const buffer = await file.arrayBuffer();
      const pdf = await PDFDocument.load(buffer, { ignoreEncryption: true });
      const pages = pdf.getPages();

      setProgress(40);
      setStatusText(`Wasserzeichen wird auf ${pages.length} Seiten aufgebracht...`);

      const alpha = opacity / 100;
      const angle = isDiagonal ? degrees(45) : degrees(0);

      if (mode === 'text') {
        const helveticaBold = await pdf.embedFont(StandardFonts.HelveticaBold);
        const color = getColorRgb();

        pages.forEach((page, idx) => {
          if (skipFirstPage && idx === 0) return;
          const { width, height } = page.getSize();
          const textWidth = helveticaBold.widthOfTextAtSize(watermarkText, fontSize);
          const textHeight = helveticaBold.heightAtSize(fontSize);

          // Center positioning
          const x = width / 2 - (isDiagonal ? textWidth / 2.8 : textWidth / 2);
          const y = height / 2 - (isDiagonal ? 0 : textHeight / 2);

          page.drawText(watermarkText, {
            x,
            y,
            size: fontSize,
            font: helveticaBold,
            color,
            opacity: alpha,
            rotate: angle,
          });
        });
      } else if (mode === 'image' && imageFile) {
        const imgBuffer = await imageFile.arrayBuffer();
        let embeddedImage;
        if (imageFile.type === 'image/png' || imageFile.name.toLowerCase().endsWith('.png')) {
          embeddedImage = await pdf.embedPng(imgBuffer);
        } else {
          embeddedImage = await pdf.embedJpg(imgBuffer);
        }

        pages.forEach((page, idx) => {
          if (skipFirstPage && idx === 0) return;
          const { width, height } = page.getSize();
          const targetWidth = (width * imageScale) / 100;
          const targetHeight = (embeddedImage.height / embeddedImage.width) * targetWidth;

          const x = (width - targetWidth) / 2;
          const y = (height - targetHeight) / 2;

          page.drawImage(embeddedImage, {
            x,
            y,
            width: targetWidth,
            height: targetHeight,
            opacity: alpha,
          });
        });
      }

      setProgress(85);
      setStatusText('PDF wird gespeichert...');

      const bytes = await pdf.save();
      const blob = new Blob([bytes as unknown as BlobPart], { type: 'application/pdf' });
      setResultBlob(blob);
      setOutputFilename(`coolwave_wasserzeichen_${file.name}`);

      setProgress(100);
      setIsProcessing(false);
      trackEvent('conversion_completed', { toolSlug: 'pdf-wasserzeichen' });
    } catch (err) {
      console.error(err);
      setIsProcessing(false);
      alert('Fehler beim Anbringen des Wasserzeichens.');
      trackEvent('conversion_failed', { toolSlug: 'pdf-wasserzeichen' });
    }
  };

  const handleDownload = () => {
    if (!resultBlob) return;
    downloadBlob(resultBlob, outputFilename);
    trackEvent('download_completed', { toolSlug: 'pdf-wasserzeichen' });
  };

  const handleReset = () => {
    setFile(null);
    setImageFile(null);
    setImagePreview(null);
    setResultBlob(null);
    setIsProcessing(false);
  };

  if (resultBlob && file) {
    return (
      <DownloadBox
        filename={outputFilename}
        originalSizeBytes={file.size}
        resultSizeBytes={resultBlob.size}
        onDownload={handleDownload}
        onReset={handleReset}
        downloadLabel="PDF mit Wasserzeichen herunterladen"
      />
    );
  }

  if (isProcessing) {
    return <ProcessingStatus progress={progress} statusText={statusText} />;
  }

  return (
    <div className="w-full">
      {!file ? (
        <FileUploader
          acceptedExtensions={['.pdf']}
          maxFileSizeMB={50}
          onFilesSelected={handleFileSelected}
          title="PDF für Wasserzeichen ablegen"
          subtitle="Fügen Sie Status-Texte wie „Vertraulich“, „Entwurf“ oder Ihr Firmenlogo ein"
        />
      ) : (
        <div className="bg-white rounded-2xl border border-slate-200 p-6 sm:p-8 shadow-sm">
          <div className="flex items-center gap-3 pb-6 border-b border-slate-100">
            <div className="p-2.5 rounded-lg bg-sky-50 text-sky-700">
              <FileText className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-base font-bold text-slate-900">{file.name}</h3>
              <p className="text-xs text-slate-500">{formatBytes(file.size)}</p>
            </div>
          </div>

          {/* Mode Switcher */}
          <div className="py-6 space-y-6 max-w-xl">
            <div className="flex rounded-xl bg-slate-100 p-1">
              <button
                type="button"
                onClick={() => setMode('text')}
                className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-xs font-bold transition-all ${
                  mode === 'text' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-600 hover:text-slate-900'
                }`}
              >
                <Type className="w-4 h-4" />
                Text-Wasserzeichen
              </button>
              <button
                type="button"
                onClick={() => setMode('image')}
                className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-lg text-xs font-bold transition-all ${
                  mode === 'image' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-600 hover:text-slate-900'
                }`}
              >
                <ImageIcon className="w-4 h-4" />
                Logo / Bild-Wasserzeichen
              </button>
            </div>

            {mode === 'text' ? (
              <div className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                    Wasserzeichen-Text
                  </label>
                  <input
                    type="text"
                    value={watermarkText}
                    onChange={(e) => setWatermarkText(e.target.value)}
                    className="w-full px-3.5 py-2.5 rounded-xl border border-slate-300 bg-white text-slate-900 text-sm focus:outline-none focus:ring-2 focus:ring-sky-500"
                    placeholder="z. B. VERTRAULICH"
                  />
                  <div className="flex flex-wrap gap-2 mt-2">
                    {['VERTRAULICH', 'ENTWURF', 'KOPIE', 'MUSTER', 'GEPRÜFT'].map((preset) => (
                      <button
                        key={preset}
                        type="button"
                        onClick={() => setWatermarkText(preset)}
                        className="px-2.5 py-1 rounded bg-slate-100 hover:bg-slate-200 text-[11px] font-semibold text-slate-700 transition-colors"
                      >
                        {preset}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Color Selector */}
                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                    Farbe
                  </label>
                  <div className="flex gap-2">
                    {[
                      { id: 'red', label: 'Rot', color: 'bg-red-500' },
                      { id: 'gray', label: 'Grau', color: 'bg-slate-500' },
                      { id: 'blue', label: 'Blau', color: 'bg-blue-600' },
                      { id: 'black', label: 'Schwarz', color: 'bg-black' },
                    ].map((c) => (
                      <button
                        key={c.id}
                        type="button"
                        onClick={() => setTextColor(c.id as any)}
                        className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border text-xs font-medium transition-all ${
                          textColor === c.id ? 'border-sky-600 ring-2 ring-sky-200 bg-sky-50/50' : 'border-slate-200 hover:border-slate-300'
                        }`}
                      >
                        <span className={`w-3 h-3 rounded-full ${c.color}`} />
                        {c.label}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">
                      Deckkraft: {opacity}%
                    </label>
                    <input
                      type="range"
                      min="10"
                      max="90"
                      value={opacity}
                      onChange={(e) => setOpacity(parseInt(e.target.value, 10))}
                      className="w-full accent-sky-600"
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">
                      Schriftgröße: {fontSize}pt
                    </label>
                    <input
                      type="range"
                      min="20"
                      max="100"
                      value={fontSize}
                      onChange={(e) => setFontSize(parseInt(e.target.value, 10))}
                      className="w-full accent-sky-600"
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                    Ausrichtung
                  </label>
                  <div className="flex gap-3">
                    <button
                      type="button"
                      onClick={() => setIsDiagonal(true)}
                      className={`px-4 py-2 rounded-lg border text-xs font-bold transition-all ${
                        isDiagonal
                          ? 'border-sky-600 bg-sky-50 text-sky-900 ring-1 ring-sky-600'
                          : 'border-slate-200 text-slate-600 hover:border-slate-300'
                      }`}
                    >
                      45° Diagonal
                    </button>
                    <button
                      type="button"
                      onClick={() => setIsDiagonal(false)}
                      className={`px-4 py-2 rounded-lg border text-xs font-bold transition-all ${
                        !isDiagonal
                          ? 'border-sky-600 bg-sky-50 text-sky-900 ring-1 ring-sky-600'
                          : 'border-slate-200 text-slate-600 hover:border-slate-300'
                      }`}
                    >
                      Horizontal (0°)
                    </button>
                  </div>
                </div>
              </div>
            ) : (
              <div className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                    Logo / Stempelbild (PNG oder JPG)
                  </label>
                  <input
                    type="file"
                    accept="image/png, image/jpeg"
                    onChange={handleImageSelected}
                    className="block w-full text-xs text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-xl file:border-0 file:text-xs file:font-semibold file:bg-sky-50 file:text-sky-700 hover:file:bg-sky-100"
                  />
                  {imagePreview && (
                    <div className="mt-3 p-3 border border-slate-200 rounded-xl inline-block bg-slate-50">
                      <img src={imagePreview} alt="Vorschau des Wasserzeichen-Logos" className="max-h-24 max-w-full object-contain" />
                    </div>
                  )}
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">
                      Deckkraft: {opacity}%
                    </label>
                    <input
                      type="range"
                      min="10"
                      max="100"
                      value={opacity}
                      onChange={(e) => setOpacity(parseInt(e.target.value, 10))}
                      className="w-full accent-sky-600"
                    />
                  </div>

                  <div>
                    <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-1">
                      Bildgröße: {imageScale}% der Seitenbreite
                    </label>
                    <input
                      type="range"
                      min="15"
                      max="90"
                      value={imageScale}
                      onChange={(e) => setImageScale(parseInt(e.target.value, 10))}
                      className="w-full accent-sky-600"
                    />
                  </div>
                </div>
              </div>
            )}

            {/* Skip first page checkbox */}
            <div className="pt-2">
              <label className="flex items-center gap-2 cursor-pointer text-xs text-slate-700 font-medium">
                <input
                  type="checkbox"
                  checked={skipFirstPage}
                  onChange={(e) => setSkipFirstPage(e.target.checked)}
                  className="rounded border-slate-300 text-sky-600 focus:ring-sky-500"
                />
                Erste Seite überspringen (Deckblatt ohne Wasserzeichen)
              </label>
            </div>
          </div>

          <div className="pt-6 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-4">
            <button
              onClick={handleReset}
              className="text-xs text-slate-500 hover:text-slate-800 font-medium"
            >
              Andere Datei wählen
            </button>

            <button
              onClick={applyWatermark}
              disabled={mode === 'image' && !imageFile}
              className="w-full sm:w-auto inline-flex items-center justify-center gap-2 px-8 py-3 rounded-xl bg-sky-600 hover:bg-sky-700 text-white font-bold text-sm sm:text-base shadow-sm transition-colors disabled:opacity-50"
            >
              <Stamp className="w-4 h-4" />
              <span>Wasserzeichen anwenden</span>
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import {
  Type,
  Copy,
  Check,
  RotateCcw,
  Sparkles,
  ArrowRightLeft,
  Sliders,
  AlignLeft,
  ListFilter,
  FileDiff,
  Link2,
} from 'lucide-react';
import { trackEvent } from '@/lib/analytics';

export type TextUtilityToolId =
  | 'wortzaehler'
  | 'zeichenzaehler'
  | 'zeilen-zaehlen'
  | 'gross-kleinschreibung-aendern'
  | 'leerzeichen-entfernen'
  | 'doppelte-zeilen-entfernen'
  | 'text-vergleichen'
  | 'slug-generator';

interface TextUtilityEngineProps {
  toolId: TextUtilityToolId;
}

export function TextUtilityEngine({ toolId }: TextUtilityEngineProps) {
  const [input, setInput] = useState('');
  const [compareInput, setCompareInput] = useState('');
  const [output, setOutput] = useState('');
  const [copied, setCopied] = useState(false);

  // Options for Case Converter
  const [caseType, setCaseType] = useState<
    'upper' | 'lower' | 'title' | 'sentence' | 'camel' | 'pascal' | 'snake' | 'kebab' | 'alternating'
  >('title');

  // Options for Whitespace Remover
  const [whitespaceOption, setWhitespaceOption] = useState<
    'trim' | 'collapse' | 'all' | 'empty_lines' | 'tabs_to_spaces'
  >('collapse');

  // Options for Deduplicate
  const [caseSensitiveDedup, setCaseSensitiveDedup] = useState(false);
  const [sortDedup, setSortDedup] = useState<'none' | 'asc' | 'desc'>('none');

  // Options for Slug Generator
  const [slugSeparator, setSlugSeparator] = useState<'-' | '_'>('-');
  const [slugLowercase, setSlugLowercase] = useState(true);

  // Statistics
  const stats = useMemo(() => {
    const trimmed = input.trim();
    const words = trimmed ? trimmed.split(/\s+/).filter(Boolean) : [];
    const wordsCount = words.length;
    const charsCount = input.length;
    const charsNoSpaces = input.replace(/\s/g, '').length;
    const lettersCount = (input.match(/[a-zA-ZäöüÄÖÜß]/g) || []).length;
    const digitsCount = (input.match(/\d/g) || []).length;
    const whitespacesCount = (input.match(/\s/g) || []).length;
    const lines = input ? input.split('\n') : [];
    const linesCount = lines.length;
    const nonEmptyLinesCount = lines.filter((l) => l.trim().length > 0).length;
    const emptyLinesCount = linesCount - nonEmptyLinesCount;
    const paragraphsCount = trimmed ? input.split(/\n\s*\n/).filter(Boolean).length : 0;
    const sentencesCount = trimmed ? (input.match(/[.!?]+(?:\s|$)/g) || []).length || 1 : 0;
    const byteSize = new TextEncoder().encode(input).length;
    const readingTimeMin = Math.ceil(wordsCount / 200);
    const speakingTimeMin = Math.ceil(wordsCount / 130);

    const lineLengths = lines.map((l) => l.length);
    const maxLineLength = lineLengths.length > 0 ? Math.max(...lineLengths) : 0;
    const avgLineLength = linesCount > 0 ? Math.round(charsCount / linesCount) : 0;

    return {
      wordsCount,
      charsCount,
      charsNoSpaces,
      lettersCount,
      digitsCount,
      whitespacesCount,
      linesCount,
      nonEmptyLinesCount,
      emptyLinesCount,
      paragraphsCount,
      sentencesCount,
      byteSize,
      readingTimeMin,
      speakingTimeMin,
      maxLineLength,
      avgLineLength,
    };
  }, [input]);

  // Copy helper
  const copyToClipboard = (text: string) => {
    if (!text) return;
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  // 1. Case Converter Logic
  const handleCaseConvert = (type: typeof caseType) => {
    setCaseType(type);
    if (!input) {
      setOutput('');
      return;
    }

    let res = '';
    switch (type) {
      case 'upper':
        res = input.toUpperCase();
        break;
      case 'lower':
        res = input.toLowerCase();
        break;
      case 'title':
        res = input.replace(/\w\S*/g, (txt) => txt.charAt(0).toUpperCase() + txt.substr(1).toLowerCase());
        break;
      case 'sentence':
        res = input.toLowerCase().replace(/(^\s*\w|[.!?]\s*\w)/g, (c) => c.toUpperCase());
        break;
      case 'camel': {
        const words = input.trim().split(/[\s_-]+/);
        res = words
          .map((w, i) => (i === 0 ? w.toLowerCase() : w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()))
          .join('');
        break;
      }
      case 'pascal': {
        const words = input.trim().split(/[\s_-]+/);
        res = words.map((w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join('');
        break;
      }
      case 'snake':
        res = input
          .trim()
          .toLowerCase()
          .replace(/[\s-]+/g, '_')
          .replace(/[^\w_]/g, '');
        break;
      case 'kebab':
        res = input
          .trim()
          .toLowerCase()
          .replace(/[\s_]+/g, '-')
          .replace(/[^\w-]/g, '');
        break;
      case 'alternating':
        res = input
          .split('')
          .map((char, i) => (i % 2 === 0 ? char.toLowerCase() : char.toUpperCase()))
          .join('');
        break;
    }
    setOutput(res);
    trackEvent('conversion_completed', { toolSlug: 'gross-kleinschreibung-aendern', type });
  };

  // 2. Whitespace Remover Logic
  const handleWhitespaceRemove = (option: typeof whitespaceOption) => {
    setWhitespaceOption(option);
    if (!input) {
      setOutput('');
      return;
    }

    let res = '';
    switch (option) {
      case 'trim':
        res = input
          .split('\n')
          .map((l) => l.trim())
          .join('\n')
          .trim();
        break;
      case 'collapse':
        res = input.replace(/[ \t]+/g, ' ').replace(/\n\s*\n\s*\n/g, '\n\n').trim();
        break;
      case 'all':
        res = input.replace(/\s+/g, '');
        break;
      case 'empty_lines':
        res = input
          .split('\n')
          .filter((l) => l.trim().length > 0)
          .join('\n');
        break;
      case 'tabs_to_spaces':
        res = input.replace(/\t/g, '  ');
        break;
    }
    setOutput(res);
    trackEvent('conversion_completed', { toolSlug: 'leerzeichen-entfernen', option });
  };

  // 3. Deduplicate Lines Logic
  const handleDeduplicate = () => {
    if (!input) {
      setOutput('');
      return;
    }

    const lines = input.split(/\r?\n/);
    const seen = new Set<string>();
    const uniqueLines: string[] = [];

    for (const line of lines) {
      const key = caseSensitiveDedup ? line : line.toLowerCase();
      if (!seen.has(key)) {
        seen.add(key);
        uniqueLines.push(line);
      }
    }

    if (sortDedup === 'asc') {
      uniqueLines.sort((a, b) => a.localeCompare(b, 'de'));
    } else if (sortDedup === 'desc') {
      uniqueLines.sort((a, b) => b.localeCompare(a, 'de'));
    }

    setOutput(uniqueLines.join('\n'));
    trackEvent('conversion_completed', { toolSlug: 'doppelte-zeilen-entfernen' });
  };

  // 4. Slug Generator Logic
  const handleSlugGenerate = () => {
    if (!input) {
      setOutput('');
      return;
    }

    let slug = input.trim();

    // German umlauts conversion
    const umlautMap: Record<string, string> = {
      ä: 'ae',
      ö: 'oe',
      ü: 'ue',
      Ä: 'Ae',
      Ö: 'Oe',
      Ü: 'Ue',
      ß: 'ss',
    };
    for (const [k, v] of Object.entries(umlautMap)) {
      slug = slug.replace(new RegExp(k, 'g'), v);
    }

    if (slugLowercase) {
      slug = slug.toLowerCase();
    }

    // Remove accents
    slug = slug.normalize('NFD').replace(/[\u0300-\u036f]/g, '');

    // Replace special chars and whitespace with separator
    slug = slug.replace(/[^a-zA-Z0-9_-]+/g, slugSeparator);

    // Collapse duplicate separators
    const sepRegex = new RegExp(`\\${slugSeparator}+`, 'g');
    slug = slug.replace(sepRegex, slugSeparator);

    // Trim leading/trailing separators
    const trimRegex = new RegExp(`^\\${slugSeparator}|\\${slugSeparator}$`, 'g');
    slug = slug.replace(trimRegex, '');

    setOutput(slug);
    trackEvent('conversion_completed', { toolSlug: 'slug-generator' });
  };

  // 5. Diff Lines calculation for Text Vergleichen
  const diffResult = useMemo(() => {
    if (toolId !== 'text-vergleichen') return [];
    const linesA = input.split(/\r?\n/);
    const linesB = compareInput.split(/\r?\n/);
    const max = Math.max(linesA.length, linesB.length);
    const diffs: Array<{ lineNum: number; left?: string; right?: string; type: 'same' | 'diff' | 'left_only' | 'right_only' }> = [];

    for (let i = 0; i < max; i++) {
      const left = linesA[i];
      const right = linesB[i];
      if (left === undefined) {
        diffs.push({ lineNum: i + 1, right, type: 'right_only' });
      } else if (right === undefined) {
        diffs.push({ lineNum: i + 1, left, type: 'left_only' });
      } else if (left === right) {
        diffs.push({ lineNum: i + 1, left, right, type: 'same' });
      } else {
        diffs.push({ lineNum: i + 1, left, right, type: 'diff' });
      }
    }
    return diffs;
  }, [toolId, input, compareInput]);

  return (
    <div className="w-full bg-white rounded-2xl border border-slate-200 p-6 sm:p-8 shadow-sm">
      {/* ------------------------------------------------------------- */}
      {/* 1. WORTZÄHLER & ZEICHENZÄHLER & ZEILENZÄHLER */}
      {/* ------------------------------------------------------------- */}
      {(toolId === 'wortzaehler' || toolId === 'zeichenzaehler' || toolId === 'zeilen-zaehlen') && (
        <div className="space-y-6">
          {/* Key Metrics Grid */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            <div className={`p-4 rounded-xl text-center border ${toolId === 'wortzaehler' ? 'bg-sky-50 border-sky-200 ring-2 ring-sky-500/20' : 'bg-slate-50 border-slate-200'}`}>
              <div className="text-2xl font-black text-sky-700">{stats.wordsCount}</div>
              <div className="text-xs font-semibold text-slate-500 mt-0.5">Wörter</div>
            </div>
            <div className={`p-4 rounded-xl text-center border ${toolId === 'zeichenzaehler' ? 'bg-sky-50 border-sky-200 ring-2 ring-sky-500/20' : 'bg-slate-50 border-slate-200'}`}>
              <div className="text-2xl font-black text-slate-800">{stats.charsCount}</div>
              <div className="text-xs font-semibold text-slate-500 mt-0.5">Zeichen (inkl. Leerz.)</div>
            </div>
            <div className="p-4 rounded-xl bg-slate-50 border border-slate-200 text-center">
              <div className="text-2xl font-black text-slate-800">{stats.charsNoSpaces}</div>
              <div className="text-xs font-semibold text-slate-500 mt-0.5">Ohne Leerzeichen</div>
            </div>
            <div className={`p-4 rounded-xl text-center border ${toolId === 'zeilen-zaehlen' ? 'bg-sky-50 border-sky-200 ring-2 ring-sky-500/20' : 'bg-slate-50 border-slate-200'}`}>
              <div className="text-2xl font-black text-slate-800">{stats.linesCount}</div>
              <div className="text-xs font-semibold text-slate-500 mt-0.5">Zeilen</div>
            </div>
          </div>

          {/* Secondary Details Row */}
          <div className="grid grid-cols-2 sm:grid-cols-5 gap-2.5 text-xs">
            <div className="p-2.5 rounded-lg bg-slate-50 border border-slate-100 flex justify-between">
              <span className="text-slate-500">Absätze:</span>
              <span className="font-bold text-slate-800">{stats.paragraphsCount}</span>
            </div>
            <div className="p-2.5 rounded-lg bg-slate-50 border border-slate-100 flex justify-between">
              <span className="text-slate-500">Sätze:</span>
              <span className="font-bold text-slate-800">{stats.sentencesCount}</span>
            </div>
            <div className="p-2.5 rounded-lg bg-slate-50 border border-slate-100 flex justify-between">
              <span className="text-slate-500">Nicht-leere Zeilen:</span>
              <span className="font-bold text-slate-800">{stats.nonEmptyLinesCount}</span>
            </div>
            <div className="p-2.5 rounded-lg bg-slate-50 border border-slate-100 flex justify-between">
              <span className="text-slate-500">Lesezeit:</span>
              <span className="font-bold text-slate-800">~{stats.readingTimeMin} Min.</span>
            </div>
            <div className="p-2.5 rounded-lg bg-slate-50 border border-slate-100 flex justify-between col-span-2 sm:col-span-1">
              <span className="text-slate-500">Dateigröße:</span>
              <span className="font-bold text-slate-800">{stats.byteSize} B</span>
            </div>
          </div>

          {/* Text Area */}
          <div>
            <div className="flex items-center justify-between mb-2">
              <label className="text-xs font-bold text-slate-700 uppercase tracking-wide">
                Text zur Analyse eingeben oder einfügen
              </label>
              {input && (
                <button
                  onClick={() => setInput('')}
                  className="text-xs text-rose-600 hover:text-rose-700 flex items-center gap-1 font-medium"
                >
                  <RotateCcw className="w-3.5 h-3.5" /> Text leeren
                </button>
              )}
            </div>
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Fügen Sie Ihren Text hier ein (z. B. Essay, Artikel, E-Mail oder Quellcode)..."
              rows={12}
              className="w-full p-4 text-sm rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-sky-500 font-sans leading-relaxed resize-y"
            />
          </div>
        </div>
      )}

      {/* ------------------------------------------------------------- */}
      {/* 2. GROSS-/KLEINSCHREIBUNG ÄNDERN */}
      {/* ------------------------------------------------------------- */}
      {toolId === 'gross-kleinschreibung-aendern' && (
        <div className="space-y-6">
          <div>
            <label className="text-xs font-bold text-slate-700 uppercase tracking-wide block mb-2">
              Originaltext
            </label>
            <textarea
              value={input}
              onChange={(e) => {
                setInput(e.target.value);
              }}
              placeholder="Geben Sie den Text ein, dessen Groß- und Kleinschreibung geändert werden soll..."
              rows={6}
              className="w-full p-4 text-sm rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-sky-500 font-sans leading-relaxed"
            />
          </div>

          {/* Action Buttons */}
          <div>
            <label className="text-xs font-bold text-slate-700 uppercase tracking-wide block mb-2">
              Wählen Sie den Zielstil
            </label>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-2">
              <button
                onClick={() => handleCaseConvert('upper')}
                className={`p-2.5 rounded-lg border text-xs font-bold transition-colors ${caseType === 'upper' ? 'bg-sky-600 text-white border-sky-600' : 'bg-slate-50 border-slate-200 text-slate-700 hover:bg-slate-100'}`}
              >
                GROSSBUCHSTABEN
              </button>
              <button
                onClick={() => handleCaseConvert('lower')}
                className={`p-2.5 rounded-lg border text-xs font-bold transition-colors ${caseType === 'lower' ? 'bg-sky-600 text-white border-sky-600' : 'bg-slate-50 border-slate-200 text-slate-700 hover:bg-slate-100'}`}
              >
                kleinbuchstaben
              </button>
              <button
                onClick={() => handleCaseConvert('title')}
                className={`p-2.5 rounded-lg border text-xs font-bold transition-colors ${caseType === 'title' ? 'bg-sky-600 text-white border-sky-600' : 'bg-slate-50 border-slate-200 text-slate-700 hover:bg-slate-100'}`}
              >
                Title Case (Jedes Wort)
              </button>
              <button
                onClick={() => handleCaseConvert('sentence')}
                className={`p-2.5 rounded-lg border text-xs font-bold transition-colors ${caseType === 'sentence' ? 'bg-sky-600 text-white border-sky-600' : 'bg-slate-50 border-slate-200 text-slate-700 hover:bg-slate-100'}`}
              >
                Sentence case. (Satzanfang)
              </button>
              <button
                onClick={() => handleCaseConvert('camel')}
                className={`p-2.5 rounded-lg border text-xs font-bold transition-colors ${caseType === 'camel' ? 'bg-sky-600 text-white border-sky-600' : 'bg-slate-50 border-slate-200 text-slate-700 hover:bg-slate-100'}`}
              >
                camelCase
              </button>
              <button
                onClick={() => handleCaseConvert('pascal')}
                className={`p-2.5 rounded-lg border text-xs font-bold transition-colors ${caseType === 'pascal' ? 'bg-sky-600 text-white border-sky-600' : 'bg-slate-50 border-slate-200 text-slate-700 hover:bg-slate-100'}`}
              >
                PascalCase
              </button>
              <button
                onClick={() => handleCaseConvert('snake')}
                className={`p-2.5 rounded-lg border text-xs font-bold transition-colors ${caseType === 'snake' ? 'bg-sky-600 text-white border-sky-600' : 'bg-slate-50 border-slate-200 text-slate-700 hover:bg-slate-100'}`}
              >
                snake_case
              </button>
              <button
                onClick={() => handleCaseConvert('kebab')}
                className={`p-2.5 rounded-lg border text-xs font-bold transition-colors ${caseType === 'kebab' ? 'bg-sky-600 text-white border-sky-600' : 'bg-slate-50 border-slate-200 text-slate-700 hover:bg-slate-100'}`}
              >
                kebab-case
              </button>
            </div>
          </div>

          {/* Output Area */}
          <div>
            <div className="flex items-center justify-between mb-2">
              <label className="text-xs font-bold text-slate-700 uppercase tracking-wide">
                Konvertiertes Ergebnis
              </label>
              {output && (
                <button
                  onClick={() => copyToClipboard(output)}
                  className="text-xs text-sky-600 hover:text-sky-700 font-bold flex items-center gap-1.5"
                >
                  {copied ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
                  <span>{copied ? 'Kopiert!' : 'Kopieren'}</span>
                </button>
              )}
            </div>
            <textarea
              readOnly
              value={output}
              placeholder="Das konvertierte Ergebnis erscheint hier nach Klick auf eine der Schaltflächen..."
              rows={6}
              className="w-full p-4 text-sm rounded-xl border border-slate-200 bg-slate-50 font-sans leading-relaxed focus:outline-none"
            />
          </div>
        </div>
      )}

      {/* ------------------------------------------------------------- */}
      {/* 3. LEERZEICHEN ENTFERNEN */}
      {/* ------------------------------------------------------------- */}
      {toolId === 'leerzeichen-entfernen' && (
        <div className="space-y-6">
          <div>
            <label className="text-xs font-bold text-slate-700 uppercase tracking-wide block mb-2">
              Originaltext
            </label>
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Fügen Sie Text mit überflüssigen Leerzeichen oder Zeilenumbrüchen ein..."
              rows={6}
              className="w-full p-4 text-sm rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-sky-500 font-sans"
            />
          </div>

          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => handleWhitespaceRemove('collapse')}
              className={`px-3.5 py-2 rounded-lg text-xs font-bold border transition-colors ${whitespaceOption === 'collapse' ? 'bg-sky-600 text-white border-sky-600' : 'bg-slate-50 border-slate-200 hover:bg-slate-100 text-slate-700'}`}
            >
              Mehrfache Leerzeichen zusammenfassen
            </button>
            <button
              onClick={() => handleWhitespaceRemove('trim')}
              className={`px-3.5 py-2 rounded-lg text-xs font-bold border transition-colors ${whitespaceOption === 'trim' ? 'bg-sky-600 text-white border-sky-600' : 'bg-slate-50 border-slate-200 hover:bg-slate-100 text-slate-700'}`}
            >
              Zeilenanfang & -ende trimmen
            </button>
            <button
              onClick={() => handleWhitespaceRemove('empty_lines')}
              className={`px-3.5 py-2 rounded-lg text-xs font-bold border transition-colors ${whitespaceOption === 'empty_lines' ? 'bg-sky-600 text-white border-sky-600' : 'bg-slate-50 border-slate-200 hover:bg-slate-100 text-slate-700'}`}
            >
              Leerzeilen löschen
            </button>
            <button
              onClick={() => handleWhitespaceRemove('all')}
              className={`px-3.5 py-2 rounded-lg text-xs font-bold border transition-colors ${whitespaceOption === 'all' ? 'bg-sky-600 text-white border-sky-600' : 'bg-slate-50 border-slate-200 hover:bg-slate-100 text-slate-700'}`}
            >
              Alle Leerzeichen restlos entfernen
            </button>
          </div>

          <div>
            <div className="flex items-center justify-between mb-2">
              <label className="text-xs font-bold text-slate-700 uppercase tracking-wide">
                Bereinigter Text
              </label>
              {output && (
                <button
                  onClick={() => copyToClipboard(output)}
                  className="text-xs text-sky-600 hover:text-sky-700 font-bold flex items-center gap-1.5"
                >
                  {copied ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
                  <span>{copied ? 'Kopiert!' : 'Kopieren'}</span>
                </button>
              )}
            </div>
            <textarea
              readOnly
              value={output}
              placeholder="Bereinigter Text erscheint hier..."
              rows={6}
              className="w-full p-4 text-sm rounded-xl border border-slate-200 bg-slate-50 font-sans leading-relaxed focus:outline-none"
            />
          </div>
        </div>
      )}

      {/* ------------------------------------------------------------- */}
      {/* 4. DOPPELTE ZEILEN ENTFERNEN */}
      {/* ------------------------------------------------------------- */}
      {toolId === 'doppelte-zeilen-entfernen' && (
        <div className="space-y-6">
          <div>
            <label className="text-xs font-bold text-slate-700 uppercase tracking-wide block mb-2">
              Zeilenorientierter Text
            </label>
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Fügen Sie Ihre Liste ein (z. B. E-Mail-Adressen, URLs, Keywords)..."
              rows={7}
              className="w-full p-4 text-sm rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-sky-500 font-mono text-xs"
            />
          </div>

          <div className="flex flex-wrap items-center justify-between gap-4 p-4 rounded-xl bg-slate-50 border border-slate-200">
            <div className="flex flex-wrap items-center gap-4">
              <label className="flex items-center gap-2 text-xs font-semibold text-slate-700 cursor-pointer">
                <input
                  type="checkbox"
                  checked={caseSensitiveDedup}
                  onChange={(e) => setCaseSensitiveDedup(e.target.checked)}
                  className="rounded text-sky-600 focus:ring-sky-500"
                />
                Groß-/Kleinschreibung beachten
              </label>

              <div className="flex items-center gap-2 text-xs">
                <span className="text-slate-500 font-medium">Sortierung:</span>
                <select
                  value={sortDedup}
                  onChange={(e) => setSortDedup(e.target.value as any)}
                  className="px-2.5 py-1.5 rounded-lg border border-slate-300 bg-white font-medium text-slate-700"
                >
                  <option value="none">Reihenfolge beibehalten</option>
                  <option value="asc">Alphabetisch (A → Z)</option>
                  <option value="desc">Alphabetisch (Z → A)</option>
                </select>
              </div>
            </div>

            <button
              onClick={handleDeduplicate}
              className="px-5 py-2 rounded-xl bg-sky-600 hover:bg-sky-500 text-white font-bold text-xs shadow-sm transition-colors"
            >
              Duplikate filtern
            </button>
          </div>

          {output && (
            <div>
              <div className="flex items-center justify-between mb-2">
                <label className="text-xs font-bold text-slate-700 uppercase tracking-wide">
                  Eindeutige Zeilen ({output.split('\n').length} Zeilen)
                </label>
                <button
                  onClick={() => copyToClipboard(output)}
                  className="text-xs text-sky-600 hover:text-sky-700 font-bold flex items-center gap-1.5"
                >
                  {copied ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
                  <span>{copied ? 'Kopiert!' : 'Kopieren'}</span>
                </button>
              </div>
              <textarea
                readOnly
                value={output}
                rows={7}
                className="w-full p-4 text-xs rounded-xl border border-slate-200 bg-slate-50 font-mono focus:outline-none"
              />
            </div>
          )}
        </div>
      )}

      {/* ------------------------------------------------------------- */}
      {/* 5. TEXT VERGLEICHEN (DIFF) */}
      {/* ------------------------------------------------------------- */}
      {toolId === 'text-vergleichen' && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="text-xs font-bold text-slate-700 uppercase tracking-wide block mb-2">
                Originaltext (Version A)
              </label>
              <textarea
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Fügen Sie die ursprüngliche Version des Textes ein..."
                rows={8}
                className="w-full p-3.5 text-xs rounded-xl border border-slate-200 font-mono focus:outline-none focus:ring-2 focus:ring-sky-500"
              />
            </div>
            <div>
              <label className="text-xs font-bold text-slate-700 uppercase tracking-wide block mb-2">
                Veränderter Text (Version B)
              </label>
              <textarea
                value={compareInput}
                onChange={(e) => setCompareInput(e.target.value)}
                placeholder="Fügen Sie die überarbeitete Version des Textes ein..."
                rows={8}
                className="w-full p-3.5 text-xs rounded-xl border border-slate-200 font-mono focus:outline-none focus:ring-2 focus:ring-sky-500"
              />
            </div>
          </div>

          {diffResult.length > 0 && (
            <div className="border border-slate-200 rounded-xl overflow-hidden">
              <div className="bg-slate-100 px-4 py-2.5 border-b border-slate-200 text-xs font-bold text-slate-700 flex items-center justify-between">
                <span>Zeilenweiser Vergleich</span>
                <span className="text-slate-500 font-normal">Grün = Hinzugefügt / Rot = Entfernt / Gelb = Geändert</span>
              </div>
              <div className="divide-y divide-slate-100 font-mono text-xs max-h-96 overflow-y-auto">
                {diffResult.map((d, idx) => (
                  <div
                    key={idx}
                    className={`grid grid-cols-12 px-3 py-1.5 ${
                      d.type === 'same'
                        ? 'bg-white text-slate-700'
                        : d.type === 'diff'
                        ? 'bg-amber-50/80 text-amber-950'
                        : d.type === 'left_only'
                        ? 'bg-rose-50 text-rose-900'
                        : 'bg-emerald-50 text-emerald-900'
                    }`}
                  >
                    <div className="col-span-1 text-slate-400 select-none">{d.lineNum}</div>
                    <div className="col-span-5 border-r border-slate-200/60 pr-2 truncate">
                      {d.left !== undefined ? d.left : <span className="text-slate-300 italic">—</span>}
                    </div>
                    <div className="col-span-1 text-slate-400 select-none pl-2">{d.lineNum}</div>
                    <div className="col-span-5 truncate">
                      {d.right !== undefined ? d.right : <span className="text-slate-300 italic">—</span>}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* ------------------------------------------------------------- */}
      {/* 6. SLUG GENERATOR */}
      {/* ------------------------------------------------------------- */}
      {toolId === 'slug-generator' && (
        <div className="space-y-6">
          <div>
            <label className="text-xs font-bold text-slate-700 uppercase tracking-wide block mb-2">
              Titel oder Text für SEO-URL
            </label>
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Z. B.: Die 10 besten Tipps für schöne Fotos & günstige Kameras im März!"
              className="w-full p-4 text-sm rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-sky-500 font-sans"
            />
          </div>

          <div className="flex flex-wrap items-center justify-between gap-4 p-4 rounded-xl bg-slate-50 border border-slate-200">
            <div className="flex flex-wrap items-center gap-4">
              <label className="flex items-center gap-2 text-xs font-semibold text-slate-700 cursor-pointer">
                <input
                  type="checkbox"
                  checked={slugLowercase}
                  onChange={(e) => setSlugLowercase(e.target.checked)}
                  className="rounded text-sky-600 focus:ring-sky-500"
                />
                In Kleinbuchstaben umwandeln
              </label>

              <div className="flex items-center gap-2 text-xs">
                <span className="text-slate-500 font-medium">Trennzeichen:</span>
                <button
                  onClick={() => setSlugSeparator('-')}
                  className={`px-3 py-1 rounded-md border text-xs font-mono font-bold ${slugSeparator === '-' ? 'bg-sky-600 text-white border-sky-600' : 'bg-white border-slate-300 text-slate-700'}`}
                >
                  Bindestrich (-)
                </button>
                <button
                  onClick={() => setSlugSeparator('_')}
                  className={`px-3 py-1 rounded-md border text-xs font-mono font-bold ${slugSeparator === '_' ? 'bg-sky-600 text-white border-sky-600' : 'bg-white border-slate-300 text-slate-700'}`}
                >
                  Unterstrich (_)
                </button>
              </div>
            </div>

            <button
              onClick={handleSlugGenerate}
              className="px-5 py-2 rounded-xl bg-sky-600 hover:bg-sky-500 text-white font-bold text-xs shadow-sm transition-colors"
            >
              Slug generieren
            </button>
          </div>

          {output && (
            <div>
              <div className="flex items-center justify-between mb-2">
                <label className="text-xs font-bold text-slate-700 uppercase tracking-wide">
                  Generierter URL-Slug
                </label>
                <button
                  onClick={() => copyToClipboard(output)}
                  className="text-xs text-sky-600 hover:text-sky-700 font-bold flex items-center gap-1.5"
                >
                  {copied ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
                  <span>{copied ? 'Kopiert!' : 'Kopieren'}</span>
                </button>
              </div>
              <div className="p-4 rounded-xl border border-slate-200 bg-slate-50 font-mono text-sm text-sky-900 break-all select-all">
                {output}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

