'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { Check, Sparkles, Shield, Building2, ArrowRight } from 'lucide-react';
import { PRICING_PLANS } from '@/config/plans.config';
import { Breadcrumbs } from '@/components/common/Breadcrumbs';
import { setClientSubscription } from '@/lib/monetization/subscription';
import { trackProViewed, trackProClicked, trackSignupStarted, trackSignupCompleted } from '@/lib/analytics';

export function PricingClient() {
  const [isAnnual, setIsAnnual] = useState(true);
  const [loadingPlanId, setLoadingPlanId] = useState<string | null>(null);

  React.useEffect(() => {
    trackProViewed('pricing_page');
  }, []);

  const breadcrumbs = [
    { name: 'Preise & Tarife', url: '/de/preise' },
  ];

  const handlePlanSelect = async (planId: string) => {
    if (planId === 'free') {
      window.location.href = '/de';
      return;
    }

    setLoadingPlanId(planId);
    trackProClicked(planId, isAnnual ? 'yearly' : 'monthly');
    trackSignupStarted(planId);
    try {
      const res = await fetch('/api/v1/stripe/checkout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          planId,
          interval: isAnnual ? 'yearly' : 'monthly',
        }),
      });

      if (!res.ok) throw new Error('Checkout fehlgeschlagen');

      const data = await res.json();
      if (data.mode === 'sandbox') {
        // Activate locally
        // Paid access is granted only by the server.
        trackSignupCompleted(planId);
        alert('Das Upgrade ist derzeit nicht verfuegbar.');
      } else if (data.url) {
        trackSignupCompleted(planId);
        window.location.href = data.url;
      }
    } catch (err) {
      console.error(err);
      // Paid access is granted only by the server.
      alert('Das Upgrade ist derzeit nicht verfuegbar. Ihr Tarif wurde nicht geaendert.');
    } finally {
      setLoadingPlanId(null);
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 sm:py-12">
      <Breadcrumbs items={breadcrumbs} />

      {/* Header */}
      <div className="text-center max-w-3xl mx-auto my-8">
        <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-sky-50 border border-sky-100 text-sky-700 text-xs font-semibold mb-3">
          <Sparkles className="w-3.5 h-3.5 text-amber-500" />
          <span>Faire, transparente Preise</span>
        </span>
        <h1 className="text-3xl sm:text-5xl font-extrabold text-slate-900 tracking-tight">
          Finden Sie den passenden Tarif für Ihre Anforderungen
        </h1>
        <p className="mt-4 text-slate-600 text-sm sm:text-base leading-relaxed">
          Nutzen Sie alle Standard-Werkzeuge dauerhaft kostenlos. Für Vielnutzer und Unternehmen bieten wir erweiterte Dateilimits, Stapelverarbeitung und werbefreies Arbeiten.
        </p>

        {/* Monthly / Annual Toggle */}
        <div className="mt-8 inline-flex items-center p-1.5 rounded-2xl bg-slate-100 border border-slate-200">
          <button
            onClick={() => setIsAnnual(false)}
            className={`px-4 py-2 rounded-xl text-xs sm:text-sm font-bold transition-all ${
              !isAnnual
                ? 'bg-white text-slate-900 shadow-sm'
                : 'text-slate-600 hover:text-slate-900'
            }`}
          >
            Monatliche Zahlung
          </button>
          <button
            onClick={() => setIsAnnual(true)}
            className={`px-4 py-2 rounded-xl text-xs sm:text-sm font-bold transition-all flex items-center gap-1.5 ${
              isAnnual
                ? 'bg-white text-slate-900 shadow-sm'
                : 'text-slate-600 hover:text-slate-900'
            }`}
          >
            <span>Jährliche Zahlung</span>
            <span className="px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-800 text-[10px] font-extrabold">
              30% sparen
            </span>
          </button>
        </div>
      </div>

      {/* Heading Level 2 for Plans */}
      <h2 className="sr-only">Tarifauswahl und Leistungsumfang</h2>

      {/* Pricing Cards */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 my-12 items-stretch">
        {PRICING_PLANS.map((plan) => {
          const price = isAnnual
            ? (plan.priceYearlyEUR / 12).toFixed(2)
            : plan.priceMonthlyEUR.toFixed(2);

          return (
            <div
              key={plan.id}
              className={`rounded-3xl p-8 flex flex-col justify-between transition-all relative ${
                plan.isPopular
                  ? 'bg-slate-900 text-white shadow-xl ring-2 ring-sky-500'
                  : 'bg-white text-slate-900 border border-slate-200 shadow-sm hover:border-slate-300'
              }`}
            >
              {plan.badge && (
                <span
                  className={`absolute -top-3.5 left-1/2 -translate-x-1/2 text-[10px] uppercase font-bold tracking-wider px-3 py-1 rounded-full shadow-sm ${
                    plan.isPopular
                      ? 'bg-sky-600 text-white'
                      : 'bg-slate-800 text-slate-200'
                  }`}
                >
                  {plan.badge}
                </span>
              )}

              <div>
                <div className="flex items-center justify-between mb-2">
                  <h3 className="text-xl font-bold">{plan.name}</h3>
                </div>

                <p
                  className={`text-xs mb-6 leading-relaxed ${
                    plan.isPopular ? 'text-slate-300' : 'text-slate-500'
                  }`}
                >
                  {plan.description}
                </p>

                {/* Price block */}
                <div className="mb-6 pb-6 border-b border-slate-100 dark:border-slate-800">
                  <div className="flex items-baseline gap-1">
                    <span className="text-4xl font-black tracking-tight">
                      {plan.priceMonthlyEUR === 0 ? '€0' : `€${price}`}
                    </span>
                    {plan.priceMonthlyEUR > 0 && (
                      <span
                        className={`text-xs ${
                          plan.isPopular ? 'text-slate-400' : 'text-slate-500'
                        }`}
                      >
                        / Monat
                      </span>
                    )}
                  </div>
                  <span
                    className={`text-[11px] block mt-1 ${
                      plan.isPopular ? 'text-slate-400' : 'text-slate-500'
                    }`}
                  >
                    {isAnnual && plan.priceYearlyEUR > 0
                      ? `€${plan.priceYearlyEUR} jährlich abgerechnet`
                      : plan.periodLabel}
                  </span>
                </div>

                {/* Features List */}
                <ul className="space-y-3 mb-8 text-xs sm:text-sm">
                  {plan.features.map((feat, idx) => (
                    <li key={idx} className="flex items-start gap-2.5">
                      <div
                        className={`w-4 h-4 rounded-full flex items-center justify-center shrink-0 mt-0.5 ${
                          feat.included
                            ? plan.isPopular
                              ? 'bg-sky-500/20 text-sky-400'
                              : 'bg-emerald-50 text-emerald-600'
                            : 'opacity-30'
                        }`}
                      >
                        <Check className="w-3 h-3" />
                      </div>
                      <span
                        className={
                          feat.included
                            ? plan.isPopular
                              ? 'text-slate-200'
                              : 'text-slate-700'
                            : 'text-slate-400 line-through opacity-50'
                        }
                      >
                        {feat.text}
                      </span>
                    </li>
                  ))}
                </ul>
              </div>

              {/* CTA Button */}
              <button
                type="button"
                onClick={() => handlePlanSelect(plan.id)}
                disabled={loadingPlanId === plan.id}
                className={`w-full py-3 px-4 rounded-xl font-bold text-xs sm:text-sm transition-all shadow-sm cursor-pointer ${
                  plan.isPopular
                    ? 'bg-sky-600 hover:bg-sky-500 text-white'
                    : plan.id === 'free'
                    ? 'bg-slate-100 hover:bg-slate-200 text-slate-800'
                    : 'bg-slate-900 hover:bg-slate-800 text-white'
                }`}
              >
                {loadingPlanId === plan.id ? 'Wird vorbereitet...' : plan.ctaText}
              </button>
            </div>
          );
        })}
      </div>

      {/* Enterprise, Team & API Section */}
      <div className="max-w-4xl mx-auto my-12 p-6 sm:p-8 rounded-3xl bg-slate-900 text-white flex flex-col md:flex-row items-start md:items-center justify-between gap-6 shadow-xl border border-slate-800">
        <div>
          <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-sky-500/20 text-sky-400 text-xs font-semibold mb-2 border border-sky-400/30">
            <Building2 className="w-3.5 h-3.5" />
            <span>Business, Kanzleien & Entwickler</span>
          </span>
          <h3 className="text-xl sm:text-2xl font-bold tracking-tight">
            Individuelle Team-Lizenzen & REST-API
          </h3>
          <p className="text-xs sm:text-sm text-slate-300 mt-2 max-w-xl leading-relaxed">
            Integrieren Sie unsere DSGVO-konforme Konvertierungs-Engine direkt in Ihre Unternehmensabläufe. Dedizierte Serverkapazitäten, AVV nach Art. 28 DSGVO und persönlicher Ansprechpartner.
          </p>
        </div>

        <Link
          href="/de/kontakt?thema=business"
          className="w-full sm:w-auto shrink-0 min-h-[44px] inline-flex items-center justify-center gap-2 px-6 py-3 rounded-xl bg-sky-600 hover:bg-sky-500 text-white text-xs sm:text-sm font-bold shadow-sm transition-colors whitespace-nowrap"
        >
          <span>Unverbindlich anfragen</span>
          <ArrowRight className="w-4 h-4" />
        </Link>
      </div>

      {/* Trust & Guarantee Box */}
      <div className="max-w-3xl mx-auto p-6 rounded-2xl bg-sky-50/50 border border-sky-100 flex flex-col sm:flex-row items-center gap-4 text-center sm:text-left">
        <div className="p-3 rounded-xl bg-sky-600 text-white shrink-0">
          <Shield className="w-6 h-6" />
        </div>
        <div>
          <h3 className="font-bold text-slate-900 text-sm">
            14-tägige Geld-zurück-Garantie & jederzeit monatlich kündbar
          </h3>
          <p className="text-xs text-slate-600 mt-0.5">
            Sie können Ihr Abonnement mit einem Klick in Ihrem Kundenkonto kündigen. Rechnungen mit ausgewiesener Mehrwertsteuer für das Finanzamt werden automatisch generiert.
          </p>
        </div>
      </div>
    </div>
  );
}

