'use client';

import React, { useState, useEffect } from 'react';
import JSZip from 'jszip';
import { 
  FileText, 
  Image as ImageIcon, 
  CheckCircle, 
  AlertCircle, 
  Clock, 
  Loader2, 
  Download, 
  Trash2, 
  RefreshCw, 
  Zap, 
  Layers, 
  Play, 
  StopCircle,
  Archive
} from 'lucide-react';
import { formatBytes, downloadBlob } from '@/lib/utils';
import { batchConfig, getBatchLimits, BatchTierLimits } from '@/config/batch.config';

export type BatchItemStatus = 'queued' | 'processing' | 'completed' | 'failed' | 'cancelled';

export interface BatchItem {
  id: string;
  file: File;
  status: BatchItemStatus;
  progress: number;
  statusText?: string;
  outputBlob?: Blob;
  outputFileName?: string;
  outputSize?: number;
  error?: string;
}

interface BatchProcessingQueueProps {
  items: BatchItem[];
  isProcessing: boolean;
  onStartBatch: () => void;
  onCancelBatch: () => void;
  onClearQueue: () => void;
  onRemoveItem: (id: string) => void;
  onRetryItem?: (id: string) => void;
  onDownloadItem: (item: BatchItem) => void;
  onDownloadAllZip: () => void;
  isZipping?: boolean;
  toolTitle?: string;
}

export function BatchProcessingQueue({
  items,
  isProcessing,
  onStartBatch,
  onCancelBatch,
  onClearQueue,
  onRemoveItem,
  onRetryItem,
  onDownloadItem,
  onDownloadAllZip,
  isZipping = false,
  toolTitle = 'Stapelverarbeitung',
}: BatchProcessingQueueProps) {
  // Pro simulation state persisted in localStorage
  const [isPro, setIsPro] = useState<boolean>(false);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem('coolwave_pro_active');
      if (stored === 'true') setIsPro(true);
    }
  }, []);

  const togglePro = () => {
    const next = !isPro;
    setIsPro(next);
    if (typeof window !== 'undefined') {
      localStorage.setItem('coolwave_pro_active', next ? 'true' : 'false');
    }
  };

  const limits: BatchTierLimits = getBatchLimits(isPro);

  const completedCount = items.filter((i) => i.status === 'completed').length;
  const failedCount = items.filter((i) => i.status === 'failed').length;
  const processingCount = items.filter((i) => i.status === 'processing').length;
  const queuedCount = items.filter((i) => i.status === 'queued').length;
  const totalCount = items.length;

  const overallProgress = totalCount > 0
    ? Math.round(
        items.reduce((acc, item) => acc + (item.progress || 0), 0) / totalCount
      )
    : 0;

  const totalInputBytes = items.reduce((acc, i) => acc + i.file.size, 0);

  return (
    <div className="w-full bg-white rounded-2xl shadow-xl border border-slate-200 overflow-hidden">
      {/* Top Header & Limit Indicator */}
      <div className="bg-gradient-to-r from-slate-900 via-slate-800 to-indigo-950 p-6 text-white">
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-indigo-500/20 border border-indigo-400/30 flex items-center justify-center text-indigo-400">
              <Layers className="w-5 h-5" />
            </div>
            <div>
              <h3 className="text-lg font-bold flex items-center gap-2">
                {toolTitle}
                <span className="text-xs font-semibold px-2 py-0.5 rounded-full bg-indigo-500/30 text-indigo-200 border border-indigo-400/20">
                  {totalCount} {totalCount === 1 ? 'Datei' : 'Dateien'}
                </span>
              </h3>
              <p className="text-xs text-slate-300">
                Gesamtgröße: {formatBytes(totalInputBytes)} • Parallelität: {limits.clientConcurrency} Jobs gleichzeitig
              </p>
            </div>
          </div>

          {/* User Tier Badge & Pro Switch */}
          <div className="flex items-center gap-3 bg-slate-800/80 border border-slate-700/60 px-4 py-2 rounded-xl backdrop-blur-sm self-start md:self-auto">
            <div className="flex items-center gap-2">
              <Zap className={`w-4 h-4 ${isPro ? 'text-amber-400 fill-amber-400' : 'text-slate-400'}`} />
              <div className="text-left">
                <div className="text-xs font-bold text-slate-200">
                  {isPro ? 'Pro-Konto (aktiv)' : 'Kostenloser Tarif'}
                </div>
                <div className="text-[10px] text-slate-400">
                  Limit: max. {limits.maxBatchFiles} Dateien / {limits.maxFileSizeMB} MB je Datei
                </div>
              </div>
            </div>
            <button
              onClick={togglePro}
              type="button"
              className={`text-[10px] px-2.5 py-1 rounded-md font-semibold transition-colors ${
                isPro
                  ? 'bg-amber-500/20 text-amber-300 hover:bg-amber-500/30 border border-amber-500/40'
                  : 'bg-indigo-600 text-white hover:bg-indigo-500'
              }`}
            >
              {isPro ? 'Pro deaktivieren' : 'Pro testen'}
            </button>
          </div>
        </div>

        {/* Global Progress Bar */}
        <div className="mt-5">
          <div className="flex items-center justify-between text-xs mb-1.5 font-medium">
            <span className="text-slate-300">
              Fortschritt: {completedCount} von {totalCount} fertiggestellt
              {failedCount > 0 && <span className="text-rose-400 ml-2">({failedCount} fehlgeschlagen)</span>}
            </span>
            <span className="font-bold text-indigo-300">{overallProgress}%</span>
          </div>
          <div className="w-full h-2.5 bg-slate-700/60 rounded-full overflow-hidden">
            <div
              className={`h-full transition-all duration-300 ${
                failedCount > 0 && completedCount === 0
                  ? 'bg-rose-500'
                  : 'bg-gradient-to-r from-sky-400 via-indigo-500 to-emerald-400'
              }`}
              style={{ width: `${overallProgress}%` }}
            />
          </div>
        </div>
      </div>

      {/* Action Toolbar */}
      <div className="bg-slate-50 border-b border-slate-200 p-4 flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          {!isProcessing ? (
            <button
              onClick={onStartBatch}
              disabled={items.length === 0 || queuedCount === 0}
              className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-indigo-600 text-white font-medium text-sm hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed shadow-sm transition"
            >
              <Play className="w-4 h-4 fill-white" />
              Stapel starten ({queuedCount})
            </button>
          ) : (
            <button
              onClick={onCancelBatch}
              className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-rose-600 text-white font-medium text-sm hover:bg-rose-700 shadow-sm transition"
            >
              <StopCircle className="w-4 h-4" />
              Abbrechen
            </button>
          )}

          <button
            onClick={onClearQueue}
            disabled={isProcessing}
            className="inline-flex items-center gap-1.5 px-3 py-2 rounded-xl border border-slate-300 bg-white text-slate-700 font-medium text-sm hover:bg-slate-100 disabled:opacity-50 transition"
          >
            <Trash2 className="w-4 h-4 text-slate-500" />
            Warteschlange leeren
          </button>
        </div>

        {/* Download All as ZIP */}
        <button
          onClick={onDownloadAllZip}
          disabled={completedCount === 0 || isZipping}
          className="inline-flex items-center gap-2 px-4 py-2 rounded-xl bg-emerald-600 text-white font-semibold text-sm hover:bg-emerald-700 disabled:opacity-40 disabled:cursor-not-allowed shadow-sm transition"
        >
          {isZipping ? (
            <>
              <Loader2 className="w-4 h-4 animate-spin" />
              ZIP wird erstellt...
            </>
          ) : (
            <>
              <Archive className="w-4 h-4" />
              Alle als ZIP herunterladen ({completedCount})
            </>
          )}
        </button>
      </div>

      {/* Queue Items Table / List */}
      <div className="divide-y divide-slate-200 max-h-[440px] overflow-y-auto">
        {items.map((item, idx) => {
          const isPdf = item.file.name.toLowerCase().endsWith('.pdf');
          const isImg = /\.(jpg|jpeg|png|webp|gif|svg|bmp|tiff|avif|ico)$/i.test(item.file.name);

          return (
            <div
              key={item.id}
              className={`p-4 transition-colors flex flex-col sm:flex-row sm:items-center justify-between gap-3 ${
                item.status === 'processing'
                  ? 'bg-indigo-50/40'
                  : item.status === 'completed'
                  ? 'bg-emerald-50/20'
                  : item.status === 'failed'
                  ? 'bg-rose-50/20'
                  : 'hover:bg-slate-50/60'
              }`}
            >
              {/* File details & icon */}
              <div className="flex items-center gap-3 min-w-0 flex-1">
                <div
                  className={`w-9 h-9 rounded-lg flex items-center justify-center shrink-0 ${
                    isPdf
                      ? 'bg-rose-100 text-rose-600'
                      : isImg
                      ? 'bg-sky-100 text-sky-600'
                      : 'bg-indigo-100 text-indigo-600'
                  }`}
                >
                  {isPdf ? (
                    <FileText className="w-5 h-5" />
                  ) : isImg ? (
                    <ImageIcon className="w-5 h-5" />
                  ) : (
                    <Layers className="w-5 h-5" />
                  )}
                </div>

                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-2">
                    <span className="text-xs font-semibold text-slate-400">#{idx + 1}</span>
                    <p className="text-sm font-medium text-slate-900 truncate" title={item.file.name}>
                      {item.file.name}
                    </p>
                  </div>
                  <div className="flex items-center gap-2 text-xs text-slate-500 mt-0.5">
                    <span>{formatBytes(item.file.size)}</span>
                    {item.outputSize && item.outputSize !== item.file.size && (
                      <>
                        <span>→</span>
                        <span className="text-emerald-600 font-medium">
                          {formatBytes(item.outputSize)}
                        </span>
                      </>
                    )}
                    {item.statusText && (
                      <span className="text-slate-400 truncate max-w-[200px]">
                        • {item.statusText}
                      </span>
                    )}
                  </div>

                  {/* Progress bar per item */}
                  {item.status === 'processing' && (
                    <div className="w-full h-1.5 bg-indigo-100 rounded-full overflow-hidden mt-2">
                      <div
                        className="h-full bg-indigo-600 transition-all duration-200"
                        style={{ width: `${item.progress}%` }}
                      />
                    </div>
                  )}

                  {/* Error message */}
                  {item.status === 'failed' && item.error && (
                    <p className="text-xs text-rose-600 mt-1 flex items-center gap-1">
                      <AlertCircle className="w-3.5 h-3.5 shrink-0" />
                      {item.error}
                    </p>
                  )}
                </div>
              </div>

              {/* Status Badge & Actions */}
              <div className="flex items-center gap-2.5 shrink-0 self-end sm:self-center">
                {item.status === 'queued' && (
                  <span className="inline-flex items-center gap-1 text-xs px-2.5 py-1 rounded-full bg-slate-100 text-slate-600 font-medium border border-slate-200">
                    <Clock className="w-3 h-3" />
                    Wartend
                  </span>
                )}

                {item.status === 'processing' && (
                  <span className="inline-flex items-center gap-1.5 text-xs px-2.5 py-1 rounded-full bg-indigo-100 text-indigo-700 font-medium border border-indigo-200">
                    <Loader2 className="w-3 h-3 animate-spin text-indigo-600" />
                    {item.progress}%
                  </span>
                )}

                {item.status === 'completed' && (
                  <span className="inline-flex items-center gap-1 text-xs px-2.5 py-1 rounded-full bg-emerald-100 text-emerald-700 font-medium border border-emerald-200">
                    <CheckCircle className="w-3 h-3 text-emerald-600" />
                    Fertig
                  </span>
                )}

                {item.status === 'failed' && (
                  <span className="inline-flex items-center gap-1 text-xs px-2.5 py-1 rounded-full bg-rose-100 text-rose-700 font-medium border border-rose-200">
                    <AlertCircle className="w-3 h-3 text-rose-600" />
                    Fehler
                  </span>
                )}

                {item.status === 'cancelled' && (
                  <span className="inline-flex items-center gap-1 text-xs px-2.5 py-1 rounded-full bg-slate-100 text-slate-500 font-medium">
                    Abgebrochen
                  </span>
                )}

                {/* Individual Download Action */}
                {item.status === 'completed' && (
                  <button
                    onClick={() => onDownloadItem(item)}
                    type="button"
                    title="Diese Datei herunterladen"
                    className="p-1.5 rounded-lg bg-emerald-50 text-emerald-700 hover:bg-emerald-100 border border-emerald-200 transition"
                  >
                    <Download className="w-4 h-4" />
                  </button>
                )}

                {/* Retry action */}
                {item.status === 'failed' && onRetryItem && (
                  <button
                    onClick={() => onRetryItem(item.id)}
                    type="button"
                    title="Erneut versuchen"
                    className="p-1.5 rounded-lg bg-slate-100 text-slate-700 hover:bg-slate-200 transition"
                  >
                    <RefreshCw className="w-4 h-4" />
                  </button>
                )}

                {/* Remove from queue */}
                {!isProcessing && (
                  <button
                    onClick={() => onRemoveItem(item.id)}
                    type="button"
                    title="Aus Warteschlange entfernen"
                    className="p-1.5 rounded-lg text-slate-400 hover:text-rose-600 hover:bg-rose-50 transition"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

'use client';

import React from 'react';
import { 
  FileText, 
  Image as ImageIcon, 
  FileSpreadsheet, 
  FileAudio, 
  FileVideo, 
  FileArchive, 
  Trash2, 
  ArrowUp, 
  ArrowDown, 
  X 
} from 'lucide-react';
import { formatBytes } from '@/lib/utils';

export interface FileItem {
  id: string;
  file?: File;
  name: string;
  size: number;
}

interface FileCardProps {
  item: FileItem;
  index?: number;
  total?: number;
  onRemove?: () => void;
  onMoveUp?: () => void;
  onMoveDown?: () => void;
  className?: string;
}

function getFileIcon(filename: string) {
  const ext = filename.split('.').pop()?.toLowerCase() || '';
  if (['jpg', 'jpeg', 'png', 'webp', 'gif', 'svg', 'bmp', 'ico'].includes(ext)) {
    return <ImageIcon className="w-4 h-4 text-purple-600" />;
  }
  if (['xls', 'xlsx', 'csv'].includes(ext)) {
    return <FileSpreadsheet className="w-4 h-4 text-emerald-600" />;
  }
  if (['mp3', 'wav', 'ogg', 'm4a', 'flac'].includes(ext)) {
    return <FileAudio className="w-4 h-4 text-amber-600" />;
  }
  if (['mp4', 'webm', 'mov', 'avi'].includes(ext)) {
    return <FileVideo className="w-4 h-4 text-rose-600" />;
  }
  if (['zip', '7z', 'tar', 'gz'].includes(ext)) {
    return <FileArchive className="w-4 h-4 text-slate-600" />;
  }
  return <FileText className="w-4 h-4 text-sky-600" />;
}

export function FileCard({
  item,
  index,
  total,
  onRemove,
  onMoveUp,
  onMoveDown,
  className = '',
}: FileCardProps) {
  const ext = item.name.split('.').pop()?.toUpperCase() || '';
  const canReorder = onMoveUp !== undefined && onMoveDown !== undefined && total !== undefined && total > 1;

  return (
    <div
      className={`group flex items-center justify-between gap-3 p-2.5 sm:p-3 rounded-xl bg-white border border-slate-200/90 hover:border-slate-300 hover:bg-slate-50/50 transition-all ${className}`}
    >
      <div className="flex items-center gap-2.5 min-w-0 flex-1">
        {index !== undefined && (
          <span className="w-5 h-5 rounded-full bg-slate-100 text-slate-500 font-mono text-[11px] font-semibold flex items-center justify-center shrink-0">
            {index + 1}
          </span>
        )}

        <div className="w-8 h-8 rounded-lg bg-slate-50 border border-slate-200/60 flex items-center justify-center shrink-0">
          {getFileIcon(item.name)}
        </div>

        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-1.5">
            <span
              className="text-xs sm:text-sm font-semibold text-slate-900 truncate max-w-[200px] sm:max-w-md block"
              title={item.name}
            >
              {item.name}
            </span>
            <span className="text-[10px] font-mono font-medium px-1.5 py-0.2 rounded bg-slate-100 text-slate-600 shrink-0">
              {ext}
            </span>
          </div>
          <span className="text-[11px] text-slate-400 font-medium">{formatBytes(item.size)}</span>
        </div>
      </div>

      <div className="flex items-center gap-1 shrink-0">
        {canReorder && (
          <>
            <button
              type="button"
              onClick={onMoveUp}
              disabled={index === 0}
              className="p-1.5 rounded-lg text-slate-400 hover:text-slate-700 hover:bg-slate-100 disabled:opacity-20 disabled:cursor-not-allowed transition cursor-pointer touch-target-44"
              aria-label={`„${item.name}" nach oben verschieben`}
              title="Nach oben verschieben"
            >
              <ArrowUp className="w-3.5 h-3.5" />
            </button>
            <button
              type="button"
              onClick={onMoveDown}
              disabled={index !== undefined && total !== undefined && index === total - 1}
              className="p-1.5 rounded-lg text-slate-400 hover:text-slate-700 hover:bg-slate-100 disabled:opacity-20 disabled:cursor-not-allowed transition cursor-pointer touch-target-44"
              aria-label={`„${item.name}" nach unten verschieben`}
              title="Nach unten verschieben"
            >
              <ArrowDown className="w-3.5 h-3.5" />
            </button>
          </>
        )}

        {onRemove && (
          <button
            type="button"
            onClick={onRemove}
            className="p-1.5 rounded-lg text-slate-400 hover:text-rose-600 hover:bg-rose-50 transition cursor-pointer touch-target-44"
            aria-label={`„${item.name}" entfernen`}
            title="Datei entfernen"
          >
            <X className="w-4 h-4" />
          </button>
        )}
      </div>
    </div>
  );
}

'use client';

import React from 'react';
import { Plus, Trash2 } from 'lucide-react';
import { FileCard, FileItem } from './FileCard';
import { Button } from '@/components/common/Button';

interface FileListProps {
  items: FileItem[];
  onRemove: (id: string) => void;
  onMoveUp?: (index: number) => void;
  onMoveDown?: (index: number) => void;
  onClearAll?: () => void;
  onAddFiles?: (files: File[]) => void;
  acceptedExtensions?: string[];
  title?: string;
  allowMultiple?: boolean;
}

export function FileList({
  items,
  onRemove,
  onMoveUp,
  onMoveDown,
  onClearAll,
  onAddFiles,
  acceptedExtensions = [],
  title = 'Ausgewählte Dateien',
  allowMultiple = true,
}: FileListProps) {
  if (items.length === 0) return null;

  return (
    <div className="w-full bg-white rounded-2xl border border-slate-200 p-4 sm:p-6 shadow-xs">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 pb-4 border-b border-slate-100">
        <div>
          <h3 className="text-sm sm:text-base font-bold text-slate-900 flex items-center gap-2">
            <span>{title}</span>
            <span className="px-2 py-0.5 rounded-full bg-slate-100 text-slate-700 text-xs font-semibold">
              {items.length}
            </span>
          </h3>
          {onMoveUp && onMoveDown && items.length > 1 && (
            <p className="text-[11px] text-slate-400 mt-0.5">
              Reihenfolge mit den Pfeiltasten nach Wunsch anpassen.
            </p>
          )}
        </div>

        <div className="flex items-center gap-2">
          {onAddFiles && allowMultiple && (
            <label
              htmlFor="file-list-add-more"
              className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-slate-200 bg-white hover:bg-slate-50 text-slate-700 text-xs font-semibold cursor-pointer transition-colors"
            >
              <Plus className="w-3.5 h-3.5 text-sky-600" />
              <span>Weitere hinzufügen</span>
              <input
                id="file-list-add-more"
                type="file"
                multiple
                accept={acceptedExtensions.join(',')}
                className="hidden"
                onChange={(e) => {
                  if (e.target.files && e.target.files.length > 0) {
                    onAddFiles(Array.from(e.target.files));
                    e.target.value = '';
                  }
                }}
              />
            </label>
          )}

          {onClearAll && items.length > 1 && (
            <button
              type="button"
              onClick={onClearAll}
              className="p-1.5 text-xs text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition"
              title="Alle entfernen"
              aria-label="Alle Dateien entfernen"
            >
              <Trash2 className="w-3.5 h-3.5" />
            </button>
          )}
        </div>
      </div>

      <div className="space-y-2 mt-3.5 max-h-[380px] overflow-y-auto pr-1">
        {items.map((item, index) => (
          <FileCard
            key={item.id}
            item={item}
            index={index}
            total={items.length}
            onRemove={() => onRemove(item.id)}
            onMoveUp={onMoveUp ? () => onMoveUp(index) : undefined}
            onMoveDown={onMoveDown ? () => onMoveDown(index) : undefined}
          />
        ))}
      </div>
    </div>
  );
}

