export interface BatchTask<T> {
  id: string;
  run: (signal?: AbortSignal) => Promise<T>;
  onProgress?: (percent: number, statusText?: string) => void;
}

export interface BatchRunnerOptions {
  concurrency: number;
  signal?: AbortSignal;
  onItemStart?: (id: string) => void;
  onItemComplete?: (id: string, result: any) => void;
  onItemError?: (id: string, error: Error) => void;
  onBatchProgress?: (completedCount: number, totalCount: number) => void;
}

export async function runConcurrentBatch<T>(
  tasks: BatchTask<T>[],
  options: BatchRunnerOptions
): Promise<Map<string, { success: boolean; result?: T; error?: string }>> {
  const results = new Map<string, { success: boolean; result?: T; error?: string }>();
  const concurrency = Math.max(1, options.concurrency || 2);
  let activeIndex = 0;
  let completedCount = 0;

  async function worker() {
    while (activeIndex < tasks.length) {
      if (options.signal?.aborted) break;

      const currentIndex = activeIndex++;
      const task = tasks[currentIndex];
      if (!task) break;

      options.onItemStart?.(task.id);

      try {
        const res = await task.run(options.signal);
        results.set(task.id, { success: true, result: res });
        options.onItemComplete?.(task.id, res);
      } catch (err: unknown) {
        const errorMsg = (err as Error).message || 'Verarbeitung fehlgeschlagen';
        results.set(task.id, { success: false, error: errorMsg });
        options.onItemError?.(task.id, err as Error);
      } finally {
        completedCount++;
        options.onBatchProgress?.(completedCount, tasks.length);
      }
    }
  }

  const workerPromises: Promise<void>[] = [];
  const workerCount = Math.min(concurrency, tasks.length);

  for (let i = 0; i < workerCount; i++) {
    workerPromises.push(worker());
  }

  await Promise.all(workerPromises);
  return results;
}

import { adsConfig, isAdsEnabled } from '@/config/ads.config';
import { getClientSubscription } from '@/lib/monetization/subscription';
import { getCookieConsent } from '@/components/common/CookieBanner';

let isScriptInjected = false;

export function canDisplayAds(): boolean {
  if (!isAdsEnabled()) return false;

  // 1. Pro users receive ZERO ads
  const sub = getClientSubscription();
  if (sub.isPro || sub.entitlements.noAds) {
    return false;
  }

  // 2. Consent check (ePrivacy & GDPR)
  const consent = getCookieConsent();
  if (!consent || !consent.marketing) {
    return false;
  }

  return true;
}

export function loadAdSenseScript(): boolean {
  if (typeof window === 'undefined') return false;
  if (isScriptInjected) return true;

  if (!canDisplayAds()) {
    return false;
  }

  const clientId = adsConfig.clientId;
  if (!clientId || !clientId.startsWith('ca-pub-')) {
    // In development or when publisher ID is not configured, we do not inject external scripts
    return false;
  }

  try {
    const script = document.createElement('script');
    script.src = `https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=${clientId}`;
    script.async = true;
    script.crossOrigin = 'anonymous';
    document.head.appendChild(script);
    isScriptInjected = true;
    return true;
  } catch (err) {
    console.error('[AdSense] Failed to inject AdSense script:', err);
    return false;
  }
}

export function requestAdRender(elementId: string): void {
  if (typeof window === 'undefined') return;
  if (!canDisplayAds()) return;

  try {
    // @ts-expect-error window.adsbygoogle is injected by Google AdSense
    const adsbygoogle = window.adsbygoogle || [];
    adsbygoogle.push({});
  } catch (err) {
    // Graceful fallback if ad-blocker is active
  }
}

