export interface SystemSettingItem {
  id?: string;
  key: string;
  value: any;
  description?: string | null;
  updatedAt?: Date;
}

const DEFAULT_SETTINGS: Record<string, { value: any; description: string }> = {
  'general.maintenance_mode': {
    value: false,
    description: 'Wartungsmodus: Deaktiviert alle Konvertierungstools für reguläre Benutzer.',
  },
  'monetization.ads_enabled': {
    value: true,
    description: 'Werbeanzeigen: Schaltet Google AdSense für Besucher ohne Pro-Abonnement ein.',
  },
  'monetization.billing_enabled': {
    value: true,
    description: 'Stripe Billing: Erlaubt Buchung von Pro-Abonnements.',
  },
  'limits.free_file_size_mb': {
    value: 50,
    description: 'Standard-Dateigrößenlimit für die kostenlose Version (MB).',
  },
  'limits.pro_file_size_mb': {
    value: 500,
    description: 'Standard-Dateigrößenlimit für Pro-Nutzer (MB).',
  },
  'storage.temp_retention_minutes': {
    value: 15,
    description: 'Aufbewahrungsdauer temporärer Dateien vor automatischer Bereinigung (Minuten).',
  },
};

export async function getAllSettings(): Promise<SystemSettingItem[]> {
  if (!isDatabaseConfigured()) {
    return Object.entries(DEFAULT_SETTINGS).map(([key, item]) => ({
      key,
      value: item.value,
      description: item.description,
    }));
  }

  try {
    const dbSettings = await prisma.adminSettings.findMany();
    const map = new Map(dbSettings.map((s) => [s.key, s]));

    return Object.entries(DEFAULT_SETTINGS).map(([key, fallback]) => {
      const existing = map.get(key);
      if (existing) {
        let parsed = fallback.value;
        try {
          parsed = JSON.parse(existing.value);
        } catch {
          parsed = existing.value;
        }
        return {
          id: existing.id,
          key: existing.key,
          value: parsed,
          description: existing.description || fallback.description,
          updatedAt: existing.updatedAt,
        };
      }

      return {
        key,
        value: fallback.value,
        description: fallback.description,
      };
    });
  } catch (err) {
    console.warn('[SettingsService] Failed to load DB settings:', err);
    return Object.entries(DEFAULT_SETTINGS).map(([key, item]) => ({
      key,
      value: item.value,
      description: item.description,
    }));
  }
}

export async function updateSetting(
  key: string,
  value: any,
  actorUserId?: string
): Promise<SystemSettingItem> {
  if (!isDatabaseConfigured()) {
    throw new Error('Datenbank ist nicht konfiguriert.');
  }

  const stringValue = JSON.stringify(value);
  const description = DEFAULT_SETTINGS[key]?.description;

  const result = await prisma.adminSettings.upsert({
    where: { key },
    create: {
      key,
      value: stringValue,
      description,
    },
    update: {
      value: stringValue,
      description: description || undefined,
    },
  });

  // Record Audit Log
  await prisma.auditLog.create({
    data: {
      actorUserId: actorUserId || null,
      action: 'SETTING_UPDATED',
      targetType: 'AdminSettings',
      targetId: key,
      metadata: JSON.stringify({ key, value, timestamp: new Date().toISOString() }),
    },
  }).catch(() => {});

  let parsed = value;
  try {
    parsed = JSON.parse(result.value);
  } catch {
    parsed = result.value;
  }

  return {
    id: result.id,
    key: result.key,
    value: parsed,
    description: result.description,
    updatedAt: result.updatedAt,
  };
}

import { prisma, isDatabaseConfigured } from '@/server/db/prisma';
import { TOOLS_CONFIG } from '@/config/tools.config';
import { ToolDefinition } from '@/types/tool';

export interface OperationalToolConfig {
  toolSlug: string;
  enabled: boolean;
  hidden: boolean;
  isFeatured: boolean;
  isComingSoon: boolean;
  freeMaxFileSizeMB: number | null;
  proMaxFileSizeMB: number | null;
  freeMaxBatch: number | null;
  proMaxBatch: number | null;
  dailyLimit: number | null;
  customTitleDe: string | null;
  customMetaDescriptionDe: string | null;
  customH1De: string | null;
  updatedAt?: Date;
}

/**
 * Returns merged tool definitions where operational database configurations override static registry values
 */
export async function getMergedToolDefinitions(): Promise<ToolDefinition[]> {
  if (!isDatabaseConfigured()) {
    return TOOLS_CONFIG;
  }

  try {
    const overrides = await prisma.toolConfiguration.findMany();
    const overrideMap = new Map(overrides.map((o) => [o.toolSlug, o]));

    return TOOLS_CONFIG.map((tool) => {
      const dbConfig = overrideMap.get(tool.slug);
      if (!dbConfig) return tool;

      return {
        ...tool,
        status: !dbConfig.enabled
          ? 'maintenance'
          : dbConfig.isComingSoon
          ? 'beta'
          : tool.status,
        badge: dbConfig.isFeatured ? 'Beliebt' : tool.badge,
        freeLimits: {
          maxFileSizeMB: dbConfig.freeMaxFileSizeMB ?? tool.freeLimits.maxFileSizeMB,
          maxBatch: dbConfig.freeMaxBatch ?? tool.freeLimits.maxBatch,
        },
        proLimits: {
          maxFileSizeMB: dbConfig.proMaxFileSizeMB ?? tool.proLimits.maxFileSizeMB,
          maxBatch: dbConfig.proMaxBatch ?? tool.proLimits.maxBatch,
        },
        titleDe: dbConfig.customTitleDe || tool.titleDe,
        metaDescriptionDe: dbConfig.customMetaDescriptionDe || tool.metaDescriptionDe,
        h1De: dbConfig.customH1De || tool.h1De,
      };
    });
  } catch (err) {
    console.warn('[ToolConfigService] Failed to load DB overrides, using static tools:', err);
    return TOOLS_CONFIG;
  }
}

/**
 * Updates or creates operational configuration for a tool in the database
 */
export async function updateToolConfiguration(
  toolSlug: string,
  updates: Partial<OperationalToolConfig>,
  actorUserId?: string
): Promise<OperationalToolConfig | null> {
  if (!isDatabaseConfigured()) {
    throw new Error('Datenbank ist nicht konfiguriert.');
  }

  const existingTool = TOOLS_CONFIG.find((t) => t.slug === toolSlug);
  if (!existingTool) {
    throw new Error(`Tool mit Slug „${toolSlug}“ existiert nicht.`);
  }

  const config = await prisma.toolConfiguration.upsert({
    where: { toolSlug },
    create: {
      toolSlug,
      enabled: updates.enabled ?? true,
      hidden: updates.hidden ?? false,
      isFeatured: updates.isFeatured ?? false,
      isComingSoon: updates.isComingSoon ?? false,
      freeMaxFileSizeMB: updates.freeMaxFileSizeMB ?? null,
      proMaxFileSizeMB: updates.proMaxFileSizeMB ?? null,
      freeMaxBatch: updates.freeMaxBatch ?? null,
      proMaxBatch: updates.proMaxBatch ?? null,
      dailyLimit: updates.dailyLimit ?? null,
      customTitleDe: updates.customTitleDe ?? null,
      customMetaDescriptionDe: updates.customMetaDescriptionDe ?? null,
      customH1De: updates.customH1De ?? null,
    },
    update: {
      ...updates,
    },
  });

  // Record Audit Log
  await prisma.auditLog.create({
    data: {
      actorUserId: actorUserId || null,
      action: 'TOOL_CONFIG_UPDATED',
      targetType: 'ToolConfiguration',
      targetId: toolSlug,
      metadata: JSON.stringify({ updates, timestamp: new Date().toISOString() }),
    },
  }).catch(() => {});

  return config;
}

/**
 * Lists all tool configurations and statuses
 */
export interface AdminToolListItem extends ToolDefinition {
  isEnabled: boolean;
  isHidden: boolean;
  isProOnly: boolean;
  maxFileSizeMB: number;
  title: string;
  category: any;
  operational?: OperationalToolConfig;
}

export async function listToolConfigurations(): Promise<AdminToolListItem[]> {
  let overrideMap = new Map<string, OperationalToolConfig>();

  if (isDatabaseConfigured()) {
    try {
      const overrides = await prisma.toolConfiguration.findMany();
      overrideMap = new Map(overrides.map((o) => [o.toolSlug, o as OperationalToolConfig]));
    } catch {
      // ignore
    }
  }

  return TOOLS_CONFIG.map((tool) => {
    const op = overrideMap.get(tool.slug);
    return {
      ...tool,
      isEnabled: op?.enabled ?? (tool.status !== 'maintenance'),
      isHidden: op?.hidden ?? false,
      isProOnly: (tool as any).isProOnly || false,
      maxFileSizeMB: op?.freeMaxFileSizeMB ?? tool.freeLimits.maxFileSizeMB,
      title: tool.titleDe,
      category: tool.category,
      operational: op,
    };
  });
}

import { PrismaClient } from '@prisma/client';
import { DATABASE_CONFIG, IS_PRODUCTION } from '@/config/env.config';

declare global {
  // Allow global `var` declarations in TypeScript
  // eslint-disable-next-line no-var
  var prismaGlobal: PrismaClient | undefined;
}

export function isDatabaseConfigured(): boolean {
  return DATABASE_CONFIG.isConfigured;
}

function createPrismaClient(): PrismaClient {
  const client = new PrismaClient({
    log: !IS_PRODUCTION ? ['warn', 'error'] : ['error'],
    datasources: {
      db: {
        url: DATABASE_CONFIG.url || 'postgresql://placeholder:placeholder@localhost:5432/placeholder',
      },
    },
  });

  return client;
}

export const prisma: PrismaClient = globalThis.prismaGlobal ?? createPrismaClient();

if (!IS_PRODUCTION) {
  globalThis.prismaGlobal = prisma;
}

/**
 * Health check helper for database connectivity
 */
export async function checkDatabaseConnection(): Promise<{ ok: boolean; error?: string; latencyMs?: number }> {
  if (!isDatabaseConfigured()) {
    return { ok: false, error: 'DATABASE_URL is not configured' };
  }

  const start = Date.now();
  try {
    // Perform simple query to verify connection
    await prisma.$queryRawUnsafe('SELECT 1');
    return { ok: true, latencyMs: Date.now() - start };
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown database connection error';
    return { ok: false, error: message, latencyMs: Date.now() - start };
  }
}

/**
 * Health check alias returning structured status
 */
export async function checkDatabaseHealth(): Promise<{ status: 'ok' | 'offline'; latencyMs?: number }> {
  const res = await checkDatabaseConnection();
  return {
    status: res.ok ? 'ok' : 'offline',
    latencyMs: res.latencyMs,
  };
}

