export class ConversionEngine {
  private services: IConversionService[] = [];
  private activeWorkers = 0;
  private activeMediaWorkers = 0;
  private activeOcrWorkers = 0;
  private isDispatcherRunning = false;

  constructor() {
    this.services = [
      new PdfSecurityService(),
      new PdfService(),
      new OfficeService(),
      new ImageService(),
      new OcrService(),
      new AudioService(),
      new VideoService(),
      new ArchiveService(),
    ];
  }

  private isMediaJob(type: string): boolean {
    return (
      type.startsWith('audio') ||
      type.startsWith('video') ||
      type.includes('mp3') ||
      type.includes('webm') ||
      type.includes('gif')
    );
  }

  private isOcrJob(type: string): boolean {
    return (
      type.startsWith('ocr_') ||
      type.startsWith('ocr-') ||
      type.includes('ocr') ||
      type.includes('durchsuchbar')
    );
  }

  getService(type: string): IConversionService | undefined {
    return this.services.find((s) => s.canHandle(type));
  }

  // Concurrent worker pool dispatcher
  async triggerWorker(): Promise<void> {
    if (this.isDispatcherRunning) return;
    this.isDispatcherRunning = true;

    const infraConfig = getInfrastructureConfig();
    const maxConcurrency = infraConfig.concurrency.general;
    const maxMediaConcurrency = infraConfig.concurrency.media;
    const maxOcrConcurrency = infraConfig.concurrency.ocr;

    try {
      while (true) {
        while (this.activeWorkers < maxConcurrency) {
          const job = await jobQueue.dequeue();
          if (!job) break;

          // Skip cancelled or expired jobs
          if (job.status === 'cancelled' || job.status === 'expired') {
            continue;
          }

          const isMedia = this.isMediaJob(job.type);
          const isOcr = this.isOcrJob(job.type);

          if (isMedia && this.activeMediaWorkers >= maxMediaConcurrency) {
            // Re-enqueue job to defer until a media slot opens
            await jobQueue.enqueue(job);
            await new Promise((r) => setTimeout(r, 100));
            break;
          }

          if (isOcr && this.activeOcrWorkers >= maxOcrConcurrency) {
            // Re-enqueue job to defer until an OCR slot opens
            await jobQueue.enqueue(job);
            await new Promise((r) => setTimeout(r, 100));
            break;
          }

          this.activeWorkers++;
          if (isMedia) this.activeMediaWorkers++;
          if (isOcr) this.activeOcrWorkers++;

          this.processJob(job).finally(() => {
            this.activeWorkers--;
            if (isMedia) this.activeMediaWorkers--;
            if (isOcr) this.activeOcrWorkers--;
            this.triggerWorker().catch((err) => console.error('[Worker Re-trigger Error]:', err));
          });
        }

        if (this.activeWorkers === 0 && jobQueue.getQueueLength() === 0) {
          break;
        }

        await new Promise((resolve) => setTimeout(resolve, 80));
        if (this.activeWorkers === 0 && jobQueue.getQueueLength() === 0) {
          break;
        }
      }
    } finally {
      this.isDispatcherRunning = false;
    }
  }

  private async processJob(job: ConversionJob): Promise<void> {
    const service = this.getService(job.type);

    if (!service) {
      await storageProvider.delete(job.input.storagePath);
      await jobQueue.updateJob(job.id, {
        status: 'failed',
        error: `Kein Konvertierungs-Service für Job-Typ „${job.type}“ registriert.`,
        completedAt: new Date().toISOString(),
      });
      return;
    }

    const infraConfig = getInfrastructureConfig();
    let timeoutMs = infraConfig.timeouts.generalMs;
    if (this.isMediaJob(job.type)) {
      timeoutMs = infraConfig.timeouts.mediaMs;
    } else if (this.isOcrJob(job.type)) {
      timeoutMs = infraConfig.timeouts.ocrMs;
    }

    const abortController = new AbortController();
    const timeoutId = setTimeout(() => {
      abortController.abort();
    }, timeoutMs);

    const startTime = Date.now();
    let outputPath: string | undefined;
    try {
      await jobQueue.updateJob(job.id, {
        status: 'processing',
        startedAt: new Date().toISOString(),
        progress: 10,
      });

      // Track conversion started
      analyticsService.track({
        eventType: 'conversion_started',
        toolSlug: job.type,
        fileSizeBytes: job.input.sizeBytes,
      }).catch(() => {});

      // Read input from ephemeral storage
      const inputBuffer = await storageProvider.read(job.input.storagePath);

      const options: ServiceOptions = {
        ...(job.options || {}),
        targetFormat:
          (job.options as any)?.targetFormat ||
          (job as any).outputType ||
          job.type.split('_to_')[1]?.toUpperCase(),
        jobType: job.type,
        type: job.type,
      };

      const result = await service.execute(
        inputBuffer,
        job.input.originalName,
        options,
        async (progress) => {
          await jobQueue.updateJob(job.id, { progress });
        },
        abortController.signal
      );

      const current = await jobQueue.getJob(job.id);
      if (abortController.signal.aborted || !current || ['cancelled', 'expired'].includes(current.status)) throw new Error('Verarbeitung abgebrochen.');
      // Save output in isolated storage
      const savedOutput = await storageProvider.saveOutput(result.data, result.fileName);
      outputPath = savedOutput.storagePath;

      // Data minimization & cost saving: delete input immediately on success
      if (infraConfig.storage.purgeInputImmediately && job.input?.storagePath) {
        await storageProvider.delete(job.input.storagePath);
      }

      const downloadUrl = generateSignedDownloadUrl(job.id, job.expiration);
      const durationMs = Date.now() - startTime;

      // Track conversion completed
      analyticsService.track({
        eventType: 'conversion_completed',
        toolSlug: job.type,
        durationMs,
        outputSizeBytes: savedOutput.sizeBytes,
        fileSizeBytes: job.input.sizeBytes,
      }).catch(() => {});

      const completed = await jobQueue.updateJob(job.id, {
        status: 'completed',
        progress: 100,
        completedAt: new Date().toISOString(),
        output: {
          fileName: result.fileName,
          mimeType: result.mimeType,
          sizeBytes: savedOutput.sizeBytes,
          storagePath: savedOutput.storagePath,
          downloadUrl,
        },
      });
      if (completed?.status !== 'completed') await storageProvider.delete(savedOutput.storagePath);
    } catch (err: unknown) {
      const errorMsg = 'Die Datei konnte nicht verarbeitet werden. Bitte pruefen Sie Format, Inhalt und Passwort.';
      if (outputPath) await storageProvider.delete(outputPath);
      analyticsService.track({
        eventType: 'conversion_failed',
        toolSlug: job.type,
        errorCode: errorMsg,
      }).catch(() => {});

      // Zero unnecessary retention: delete input even on failure to avoid storage leaks
      if (infraConfig.storage.purgeInputImmediately && job.input?.storagePath) {
        try {
          await storageProvider.delete(job.input.storagePath);
        } catch {
          // Best-effort cleanup
        }
      }

      await jobQueue.updateJob(job.id, {
        status: 'failed',
        error: errorMsg,
        completedAt: new Date().toISOString(),
      });
    } finally {
      clearTimeout(timeoutId);
    }
  }
}

// Global conversion engine singleton
export const conversionEngine = new ConversionEngine();

import path from 'path';

export interface FileValidationResult {
  valid: boolean;
  error?: string;
  code?: string;
  safeFilename: string;
  detectedFormat?: string;
}

const DANGEROUS_EXTENSIONS = new Set([
  '.exe', '.dll', '.so', '.dylib', '.bat', '.cmd', '.sh', '.bash',
  '.php', '.phtml', '.php3', '.php4', '.php5', '.phps',
  '.py', '.pyc', '.pyo', '.js', '.mjs', '.cjs', '.vbs', '.vbe',
  '.scr', '.msi', '.msp', '.com', '.bin', '.reg', '.wsf', '.wsh',
  '.jar', '.war', '.apk', '.iso', '.dmg',
]);

/**
 * Strips directory traversal sequences, null bytes, and non-printable control characters.
 */
export function sanitizeFilename(originalName: string): string {
  if (!originalName || typeof originalName !== 'string') {
    return `file_${Date.now()}`;
  }

  // Strip null bytes and control chars
  let cleaned = originalName.replace(/[\x00-\x1f\x7f]/g, '');

  // Extract base filename (removes directory paths like ../ or C:\)
  cleaned = path.posix.basename(cleaned.replace(/\\/g, '/'));

  // Replace backslashes and forward slashes if any remain
  cleaned = cleaned.replace(/[/\\]/g, '_');

  // Replace suspicious characters while keeping international unicode / german umlauts
  cleaned = cleaned.replace(/[<>:"|?*]/g, '_').trim();

  // If filename begins with dot or dash, sanitize
  cleaned = cleaned.replace(/^[.-]+/, '');

  if (!cleaned) {
    cleaned = `upload_${Date.now()}`;
  }

  // Truncate if excessively long (preserve extension)
  if (cleaned.length > 200) {
    const ext = path.extname(cleaned);
    const base = path.basename(cleaned, ext).slice(0, 190);
    cleaned = `${base}${ext}`;
  }

  return cleaned;
}

/**
 * Inspects raw buffer magic bytes to detect true file format and reject spoofed/malicious uploads.
 */
export function validateUploadedFile(
  buffer: Buffer,
  rawFilename: string,
  declaredMime?: string
): FileValidationResult {
  const safeFilename = sanitizeFilename(rawFilename);
  const ext = path.extname(safeFilename).toLowerCase();

  // 1. Block dangerous executable extensions
  if (DANGEROUS_EXTENSIONS.has(ext)) {
    return {
      valid: false,
      code: 'DISALLOWED_FILE_TYPE',
      error: `Aus Sicherheitsgründen sind ausführbare Dateien (${ext}) strikt untersagt.`,
      safeFilename,
    };
  }

  const allowed = new Set('pdf doc docx odt rtf txt html htm xls xlsx csv ppt pptx odp epub png jpg jpeg gif webp svg psd eps heic heif avif bmp tiff tif ico mp3 wav flac ogg m4a mp4 aac mov webm mkv avi zip 7z tar gz gzip tgz'.split(' '));
  if (!allowed.has(ext.slice(1))) return { valid: false, safeFilename, code: 'UNSUPPORTED_EXTENSION', error: 'Nicht unterstuetztes Dateiformat.' };
  if (ext === '.svg') {
    const text = buffer.toString('utf8');
    if (!/<svg\b/i.test(text) || /<!ENTITY|<!DOCTYPE|<script|<foreignObject|\bon\w+\s*=|(?:href|src)\s*=\s*["'](?!#|data:image\/(?:png|jpeg);base64,)|url\(\s*["']?(?!#)/i.test(text)) return { valid: false, safeFilename, code: 'UNSAFE_SVG', error: 'SVG mit aktiven oder externen Inhalten ist nicht erlaubt.' };
  }
  // 2. Minimum file size check (empty files cannot be processed)
  if (buffer.length === 0) {
    return {
      valid: false,
      code: 'EMPTY_FILE',
      error: 'Die hochgeladene Datei ist leer (0 Bytes).',
      safeFilename,
    };
  }

  // 3. Inspect binary executable signatures (DOS MZ, ELF, Mach-O)
  if (buffer.length >= 2) {
    // DOS / Windows PE header (MZ)
    if (buffer[0] === 0x4d && buffer[1] === 0x5a) {
      return {
        valid: false,
        code: 'MALICIOUS_EXECUTABLE_DETECTED',
        error: 'Ausführbare Binärdateien (Windows PE/MZ) sind aus Sicherheitsgründen untersagt.',
        safeFilename,
      };
    }
  }

  if (buffer.length >= 4) {
    // Linux ELF header (\x7fELF)
    if (buffer[0] === 0x7f && buffer[1] === 0x45 && buffer[2] === 0x4c && buffer[3] === 0x46) {
      return {
        valid: false,
        code: 'MALICIOUS_EXECUTABLE_DETECTED',
        error: 'Ausführbare Linux-Binärdateien (ELF) sind untersagt.',
        safeFilename,
      };
    }
    // Mach-O header
    if (
      (buffer[0] === 0xfe && buffer[1] === 0xed && buffer[2] === 0xfa && (buffer[3] === 0xce || buffer[3] === 0xcf)) ||
      (buffer[0] === 0xce && buffer[1] === 0xfa && buffer[2] === 0xed && buffer[3] === 0xfe) ||
      (buffer[0] === 0xcf && buffer[1] === 0xfa && buffer[2] === 0xed && buffer[3] === 0xfe)
    ) {
      return {
        valid: false,
        code: 'MALICIOUS_EXECUTABLE_DETECTED',
        error: 'Ausführbare macOS-Binärdateien (Mach-O) sind untersagt.',
        safeFilename,
      };
    }
  }

  // 4. Magic-byte verification per format family
  let detectedFormat = 'unknown';

  // PDF verification: must contain %PDF- in the header
  if (ext === '.pdf') {
    const headerSlice = buffer.subarray(0, Math.min(buffer.length, 1024)).toString('latin1');
    if (!headerSlice.includes('%PDF-')) {
      return {
        valid: false,
        code: 'SPOOFED_PDF',
        error: 'Die Datei hat die Endung .pdf, enthält jedoch keine gültige PDF-Signatur (%PDF-).',
        safeFilename,
      };
    }
    detectedFormat = 'pdf';
  }

  // ZIP-based OpenXML and Oasis formats (.docx, .xlsx, .pptx, .odt, .odp, .epub, .zip)
  else if (['.docx', '.xlsx', '.pptx', '.odt', '.odp', '.epub', '.zip'].includes(ext)) {
    const isZip =
      buffer.length >= 4 &&
      buffer[0] === 0x50 &&
      buffer[1] === 0x4b &&
      (buffer[2] === 0x03 || buffer[2] === 0x05 || buffer[2] === 0x07) &&
      (buffer[3] === 0x04 || buffer[3] === 0x06 || buffer[3] === 0x08);

    if (!isZip) {
      return {
        valid: false,
        code: 'SPOOFED_ARCHIVE',
        error: `Die Datei (${ext}) weist keine gültige ZIP/OpenXML-Signatur (PK..) auf.`,
        safeFilename,
      };
    }
    detectedFormat = 'zip_archive';
  }

  // Legacy Compound File Binary Format (.doc, .xls, .ppt)
  else if (['.doc', '.xls', '.ppt'].includes(ext)) {
    const isCfbf =
      buffer.length >= 8 &&
      buffer[0] === 0xd0 &&
      buffer[1] === 0xcf &&
      buffer[2] === 0x11 &&
      buffer[3] === 0xe0 &&
      buffer[4] === 0xa1 &&
      buffer[5] === 0xb1 &&
      buffer[6] === 0x1a &&
      buffer[7] === 0xe1;

    // Some RTF or XML files are saved as .doc
    const isRtf = buffer.subarray(0, 5).toString('latin1') === '{\\rtf';
    const isXmlOrZip = buffer.subarray(0, 5).toString('latin1').includes('<?xml') || (buffer[0] === 0x50 && buffer[1] === 0x4b);

    if (!isCfbf && !isRtf && !isXmlOrZip) {
      return {
        valid: false,
        code: 'SPOOFED_OFFICE',
        error: `Die Datei (${ext}) ist keine gültige Microsoft Office Binärdatei.`,
        safeFilename,
      };
    }
    detectedFormat = 'legacy_office';
  }

  // PNG verification
  else if (ext === '.png') {
    const isPng =
      buffer.length >= 8 &&
      buffer[0] === 0x89 &&
      buffer[1] === 0x50 &&
      buffer[2] === 0x4e &&
      buffer[3] === 0x47 &&
      buffer[4] === 0x0d &&
      buffer[5] === 0x0a &&
      buffer[6] === 0x1a &&
      buffer[7] === 0x0a;

    if (!isPng) {
      return {
        valid: false,
        code: 'SPOOFED_PNG',
        error: 'Die Datei hat die Endung .png, enthält jedoch keine gültige PNG-Signatur.',
        safeFilename,
      };
    }
    detectedFormat = 'png';
  }

  // JPEG verification
  else if (['.jpg', '.jpeg'].includes(ext)) {
    const isJpeg = buffer.length >= 3 && buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff;
    if (!isJpeg) {
      return {
        valid: false,
        code: 'SPOOFED_JPEG',
        error: 'Die Datei hat die Endung .jpg/.jpeg, enthält jedoch keine gültige JPEG-Signatur.',
        safeFilename,
      };
    }
    detectedFormat = 'jpeg';
  }

  // GIF verification
  else if (ext === '.gif') {
    const gifHeader = buffer.subarray(0, 6).toString('latin1');
    if (gifHeader !== 'GIF87a' && gifHeader !== 'GIF89a') {
      return {
        valid: false,
        code: 'SPOOFED_GIF',
        error: 'Die Datei weist keine gültige GIF-Signatur auf.',
        safeFilename,
      };
    }
    detectedFormat = 'gif';
  }

  // WEBP verification (RIFF....WEBP)
  else if (ext === '.webp') {
    const isRiff = buffer.subarray(0, 4).toString('latin1') === 'RIFF';
    const isWebp = buffer.subarray(8, 12).toString('latin1') === 'WEBP';
    if (!isRiff || !isWebp) {
      return {
        valid: false,
        code: 'SPOOFED_WEBP',
        error: 'Die Datei weist keine gültige WebP/RIFF-Signatur auf.',
        safeFilename,
      };
    }
    detectedFormat = 'webp';
  }

  // BMP verification (BM)
  else if (ext === '.bmp') {
    if (buffer.length < 2 || buffer[0] !== 0x42 || buffer[1] !== 0x4d) {
      return {
        valid: false,
        code: 'SPOOFED_BMP',
        error: 'Die Datei weist keine gültige BMP-Signatur auf.',
        safeFilename,
      };
    }
    detectedFormat = 'bmp';
  }

  // TIFF verification
  else if (['.tif', '.tiff'].includes(ext)) {
    const isLe = buffer[0] === 0x49 && buffer[1] === 0x49 && buffer[2] === 0x2a && buffer[3] === 0x00;
    const isBe = buffer[0] === 0x4d && buffer[1] === 0x4d && buffer[2] === 0x00 && buffer[3] === 0x2a;
    if (!isLe && !isBe) {
      return {
        valid: false,
        code: 'SPOOFED_TIFF',
        error: 'Die Datei weist keine gültige TIFF-Signatur auf.',
        safeFilename,
      };
    }
    detectedFormat = 'tiff';
  }

  // PSD verification (8BPS)
  else if (ext === '.psd') {
    const isPsd = buffer.subarray(0, 4).toString('latin1') === '8BPS';
    if (!isPsd) {
      return {
        valid: false,
        code: 'SPOOFED_PSD',
        error: 'Die Datei weist keine gültige Adobe Photoshop PSD-Signatur auf.',
        safeFilename,
      };
    }
    detectedFormat = 'psd';
  }

  // RTF verification
  else if (ext === '.rtf') {
    const isRtf = buffer.subarray(0, 5).toString('latin1') === '{\\rtf';
    if (!isRtf) {
      return {
        valid: false,
        code: 'SPOOFED_RTF',
        error: 'Die Datei weist keine gültige Rich Text Format (RTF) Signatur auf.',
        safeFilename,
      };
    }
    detectedFormat = 'rtf';
  }

  // Plain Text & CSV verification (check for excessive binary null bytes)
  else if (['.txt', '.csv'].includes(ext)) {
    const sample = buffer.subarray(0, Math.min(buffer.length, 2048));
    let nullCount = 0;
    for (let i = 0; i < sample.length; i++) {
      if (sample[i] === 0x00) nullCount++;
    }
    if (nullCount > 2) {
      return {
        valid: false,
        code: 'BINARY_TEXT_MISMATCH',
        error: 'Die Text-/CSV-Datei enthält unzulässige Binärdaten (Null-Bytes).',
        safeFilename,
      };
    }
    detectedFormat = 'text';
  }

  // -------------------------------------------------------------
  // AUDIO MAGIC BYTES (MP3, WAV, FLAC, OGG, M4A)
  // -------------------------------------------------------------
  else if (ext === '.mp3') {
    const hasId3 = buffer.length >= 3 && buffer[0] === 0x49 && buffer[1] === 0x44 && buffer[2] === 0x33;
    const hasSync = buffer.length >= 2 && buffer[0] === 0xff && (buffer[1] & 0xe0) === 0xe0;
    if (!hasId3 && !hasSync) {
      return {
        valid: false,
        code: 'SPOOFED_MP3',
        error: 'Die Datei weist keine gültige MP3-Signatur (ID3 / Sync Frame) auf.',
        safeFilename,
      };
    }
    detectedFormat = 'mp3';
  } else if (ext === '.wav') {
    const isRiff = buffer.length >= 12 && buffer.subarray(0, 4).toString('latin1') === 'RIFF';
    const isWave = buffer.length >= 12 && buffer.subarray(8, 12).toString('latin1') === 'WAVE';
    if (!isRiff || !isWave) {
      return {
        valid: false,
        code: 'SPOOFED_WAV',
        error: 'Die Datei weist keine gültige WAV/RIFF-Signatur auf.',
        safeFilename,
      };
    }
    detectedFormat = 'wav';
  } else if (ext === '.flac') {
    const isFlac = buffer.length >= 4 && buffer.subarray(0, 4).toString('latin1') === 'fLaC';
    if (!isFlac) {
      return {
        valid: false,
        code: 'SPOOFED_FLAC',
        error: 'Die Datei weist keine gültige FLAC-Signatur auf.',
        safeFilename,
      };
    }
    detectedFormat = 'flac';
  } else if (ext === '.ogg') {
    const isOgg = buffer.length >= 4 && buffer.subarray(0, 4).toString('latin1') === 'OggS';
    if (!isOgg) {
      return {
        valid: false,
        code: 'SPOOFED_OGG',
        error: 'Die Datei weist keine gültige OGG-Signatur auf.',
        safeFilename,
      };
    }
    detectedFormat = 'ogg';
  } else if (['.m4a', '.mp4'].includes(ext)) {
    const isFtyp = buffer.length >= 8 && buffer.subarray(4, 8).toString('latin1') === 'ftyp';
    if (!isFtyp) {
      return {
        valid: false,
        code: 'SPOOFED_MP4_M4A',
        error: 'Die Datei weist keine gültige MP4/M4A ftyp-Signatur auf.',
        safeFilename,
      };
    }
    detectedFormat = ext === '.m4a' ? 'm4a' : 'mp4';
  }

  // -------------------------------------------------------------
  // VIDEO MAGIC BYTES (WebM, MKV, AVI, MOV)
  // -------------------------------------------------------------
  else if (['.webm', '.mkv'].includes(ext)) {
    // EBML header (\x1a\x45\xdf\xa3)
    const isEbml =
      buffer.length >= 4 &&
      buffer[0] === 0x1a &&
      buffer[1] === 0x45 &&
      buffer[2] === 0xdf &&
      buffer[3] === 0xa3;
    if (!isEbml) {
      return {
        valid: false,
        code: 'SPOOFED_MATROSKA',
        error: 'Die Datei weist keine gültige WebM/MKV EBML-Signatur auf.',
        safeFilename,
      };
    }
    detectedFormat = ext === '.webm' ? 'webm' : 'mkv';
  } else if (ext === '.avi') {
    const isRiff = buffer.length >= 12 && buffer.subarray(0, 4).toString('latin1') === 'RIFF';
    const isAvi = buffer.length >= 12 && buffer.subarray(8, 12).toString('latin1') === 'AVI ';
    if (!isRiff || !isAvi) {
      return {
        valid: false,
        code: 'SPOOFED_AVI',
        error: 'Die Datei weist keine gültige AVI/RIFF-Signatur auf.',
        safeFilename,
      };
    }
    detectedFormat = 'avi';
  }

  // -------------------------------------------------------------
  // ARCHIVES (7Z, GZIP, TAR)
  // -------------------------------------------------------------
  else if (ext === '.7z') {
    // 7z signature: 37 7A BC AF 27 1C
    const is7z =
      buffer.length >= 6 &&
      buffer[0] === 0x37 &&
      buffer[1] === 0x7a &&
      buffer[2] === 0xbc &&
      buffer[3] === 0xaf &&
      buffer[4] === 0x27 &&
      buffer[5] === 0x1c;
    if (!is7z) {
      return {
        valid: false,
        code: 'SPOOFED_7Z',
        error: 'Die Datei weist keine gültige 7-Zip Signatur auf.',
        safeFilename,
      };
    }
    detectedFormat = '7z';
  } else if (ext === '.gz') {
    // GZIP header: 1F 8B
    const isGzip = buffer.length >= 2 && buffer[0] === 0x1f && buffer[1] === 0x8b;
    if (!isGzip) {
      return {
        valid: false,
        code: 'SPOOFED_GZIP',
        error: 'Die Datei weist keine gültige GZIP-Signatur (1F 8B) auf.',
        safeFilename,
      };
    }
    detectedFormat = 'gzip';
  }

  return {
    valid: true,
    safeFilename,
    detectedFormat,
  };
}

import JSZip from 'jszip';

export interface ArchiveSafetyLimits {
  /** Maximum allowable uncompressed size in bytes (default 250 MB) */
  maxUncompressedBytes?: number;
  /** Maximum compression ratio before triggering bomb alert (default 100:1) */
  maxCompressionRatio?: number;
  /** Maximum number of file entries allowed inside archive (default 5,000) */
  maxEntries?: number;
}

export class ZipBombError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ZipBombError';
  }
}

/**
 * Safely loads and validates a ZIP archive against decompression bombs,
 * infinite expansion ratios, and archive path traversal attacks.
 */
export async function safeLoadZip(
  buffer: Buffer,
  limits: ArchiveSafetyLimits = {}
): Promise<JSZip> {
  const maxBytes = limits.maxUncompressedBytes || 250 * 1024 * 1024; // 250 MB
  const maxRatio = limits.maxCompressionRatio || 100;
  const maxEntries = limits.maxEntries || 5000;

  let zip: JSZip;
  try {
    zip = await JSZip.loadAsync(buffer);
  } catch (err: any) {
    throw new Error(`Archiv konnte nicht gelesen werden: ${err?.message || 'Ungültiges Format'}`);
  }

  const entries = Object.keys(zip.files);

  // 1. Entry count check
  if (entries.length > maxEntries) {
    throw new ZipBombError(
      `Sicherheitswarnung: Archiv enthält zu viele Einträge (${entries.length} > ${maxEntries}).`
    );
  }

  let totalUncompressedSize = 0;
  const compressedSize = buffer.length;

  for (const filename of entries) {
    const originalName = (zip.files[filename] as JSZip.JSZipObject & { unsafeOriginalName?: string }).unsafeOriginalName || filename;
    if (/(^|[\\/])\.\.([\\/]|$)/.test(originalName) || /^[\\/]|^[a-zA-Z]:/.test(originalName)) throw new ZipBombError('Unsafe archive path.');
    // 2. Path traversal attack check in ZIP entry names
    if (
      filename.includes('../') ||
      filename.includes('..\\') ||
      filename.startsWith('/') ||
      filename.startsWith('\\') ||
      /^[a-zA-Z]:/.test(filename)
    ) {
      throw new ZipBombError(
        `Sicherheitswarnung: Unzulässige Pfad-Traversal-Sequenz in Archiv-Eintrag ("${filename}").`
      );
    }

    const entry = zip.files[filename];
    // In JSZip internal metadata
    const uncompressedSize = (entry as any)._data?.uncompressedSize || 0;
    totalUncompressedSize += uncompressedSize;

    // 3. Absolute size check
    if (totalUncompressedSize > maxBytes) {
      throw new ZipBombError(
        `Sicherheitswarnung: Dekomprimierte Dateigröße überschreitet das Sicherheitslimit von ${Math.round(
          maxBytes / (1024 * 1024)
        )} MB.`
      );
    }
  }

  // 4. Compression ratio check (only if archive expands beyond 10 MB)
  if (totalUncompressedSize > 10 * 1024 * 1024 && compressedSize > 0) {
    const ratio = totalUncompressedSize / compressedSize;
    if (ratio > maxRatio) {
      throw new ZipBombError(
        `Sicherheitswarnung: Verdacht auf Decompression-Bomb (Kompressionsverhältnis ${Math.round(
          ratio
        )}:1 überschreitet Limit von ${maxRatio}:1).`
      );
    }
  }

  return zip;
}

import fs from 'fs/promises';
import path from 'path';
import crypto from 'crypto';
import zlib from 'zlib';
import { promisify } from 'util';
import { execFile } from 'child_process';
import JSZip from 'jszip';
import { safeLoadZip } from '@/server/security/safeArchive';
import { IConversionService, ConversionResult } from '../base.service';
import { ServiceOptions } from '@/types/job';

const gunzipAsync = promisify(zlib.gunzip);

import fsSync from 'fs';

let cached7zPath: string | null = null;
function get7zPath(): string {
  if (cached7zPath) return cached7zPath;
  if (process.env.SEVEN_ZIP_PATH && fsSync.existsSync(process.env.SEVEN_ZIP_PATH)) {
    cached7zPath = process.env.SEVEN_ZIP_PATH;
    return cached7zPath;
  }
  const winBinary = path.join(process.cwd(), 'node_modules', '7z-bin', 'bin', 'win', 'x64', '7z.exe');
  if (fsSync.existsSync(winBinary)) {
    cached7zPath = winBinary;
    return cached7zPath;
  }
  const linuxBinary = path.join(process.cwd(), 'node_modules', '7z-bin', 'bin', 'linux', 'x64', '7za');
  if (fsSync.existsSync(linuxBinary)) {
    cached7zPath = linuxBinary;
    return cached7zPath;
  }
  cached7zPath = '7z';
  return cached7zPath;
}

const MAX_UNCOMPRESSED_BYTES = 150 * 1024 * 1024; // 150 MB max uncompressed limit
const MAX_ENTRIES_COUNT = 500; // 500 files max per archive

export class ArchiveService implements IConversionService {
  name = 'ArchiveService';
  supportedTypes = [
    'archive_zip_create',
    'archive_zip_extract',
    'archive_7z_extract',
    'archive_tar_extract',
    'archive_gzip_extract',
    'zip-erstellen',
    'zip-entpacken',
    '7z-entpacken',
    'tar-entpacken',
    'gzip-entpacken',
  ];

  canHandle(type: string): boolean {
    return (
      this.supportedTypes.includes(type) ||
      type.startsWith('archive_') ||
      type.endsWith('-entpacken') ||
      type === 'zip-erstellen'
    );
  }

  async execute(
    inputBuffer: Buffer,
    inputName: string,
    options: ServiceOptions,
    onProgress: (percent: number) => void,
    signal?: AbortSignal
  ): Promise<ConversionResult> {
    onProgress(10);
    if (signal?.aborted) throw new Error('Operation abgebrochen');

    const jobType = options.jobType || options.type || 'archive_zip_extract';
    const baseName = path.basename(inputName, path.extname(inputName));
    const inputExt = path.extname(inputName).toLowerCase();

    // -------------------------------------------------------------
    // 1. GZIP EXTRACTION (Native Node.js zlib)
    // -------------------------------------------------------------
    if (jobType === 'archive_gzip_extract' || jobType === 'gzip-entpacken' || inputExt === '.gz') {
      onProgress(30);
      try {
        const decompressed = await gunzipAsync(inputBuffer, { maxOutputLength: MAX_UNCOMPRESSED_BYTES });
        if (decompressed.length > MAX_UNCOMPRESSED_BYTES) {
          throw new Error('Sicherheitswarnung: Archiv überschreitet das Entpackungslimit (Decompression Bomb Verdacht).');
        }
        onProgress(100);

        // Remove .gz extension to reveal underlying file name (e.g. file.tar or file.txt)
        const uncompressedName = inputName.replace(/\.gz$/i, '') || `${baseName}.out`;
        const ext = path.extname(uncompressedName).toLowerCase();

        return {
          data: decompressed,
          fileName: uncompressedName,
          mimeType: ext === '.tar' ? 'application/x-tar' : 'application/octet-stream',
        };
      } catch (err: any) {
        throw new Error(`GZIP-Entpackung fehlgeschlagen: ${err?.message || err}`);
      }
    }

    // -------------------------------------------------------------
    // 2. ZIP CREATION (JSZip)
    // -------------------------------------------------------------
    if (jobType === 'archive_zip_create' || jobType === 'zip-erstellen') {
      onProgress(30);
      const zip = new JSZip();

      // If options.files passed, pack them; otherwise wrap inputBuffer
      if (Array.isArray(options.files) && options.files.length > 0) {
        for (const file of options.files) {
          const safeName = path.basename(file.name || 'file.bin');
          zip.file(safeName, file.data);
        }
      } else {
        const safeName = path.basename(inputName || 'datei.bin');
        zip.file(safeName, inputBuffer);
      }

      onProgress(70);
      const zipBuffer = await zip.generateAsync({
        type: 'nodebuffer',
        compression: 'DEFLATE',
        compressionOptions: { level: 6 },
      });

      onProgress(100);
      return {
        data: zipBuffer,
        fileName: `${baseName}.zip`,
        mimeType: 'application/zip',
      };
    }

    // -------------------------------------------------------------
    // 3. ZIP EXTRACTION (JSZip with security checks)
    // -------------------------------------------------------------
    if (
      (jobType === 'archive_zip_extract' || jobType === 'zip-entpacken' || inputExt === '.zip') &&
      jobType !== '7z-entpacken' &&
      jobType !== 'tar-entpacken'
    ) {
      const zip = new JSZip();
      const loadedZip = await safeLoadZip(inputBuffer, { maxEntries: MAX_ENTRIES_COUNT, maxUncompressedBytes: MAX_UNCOMPRESSED_BYTES });
      onProgress(40);

      let totalBytes = 0;
      let fileCount = 0;
      const outputZip = new JSZip();
      const files = Object.keys(loadedZip.files);

      if (files.length > MAX_ENTRIES_COUNT) {
        throw new Error(`Sicherheitswarnung: Archiv enthält über ${MAX_ENTRIES_COUNT} Dateien.`);
      }

      for (const filename of files) {
        if (signal?.aborted) throw new Error('Operation abgebrochen');

        const zipEntry = loadedZip.files[filename];
        // Path Traversal check
        const normalized = path.normalize(filename).replace(/^[a-zA-Z]:/, '').replace(/^(\.\.[\/\\])+/, '');
        if (normalized.includes('..') || path.isAbsolute(normalized)) {
          throw new Error('Sicherheitswarnung: Unzulässige Pfadstruktur im Archiv entdeckt (Path Traversal).');
        }

        if (!zipEntry.dir) {
          const content = await zipEntry.async('nodebuffer');
          totalBytes += content.length;
          fileCount++;

          if (totalBytes > MAX_UNCOMPRESSED_BYTES) {
            throw new Error('Sicherheitswarnung: Archiv überschreitet das Entpackungslimit von 150 MB (Decompression Bomb).');
          }

          outputZip.file(normalized, content);
        }
      }

      onProgress(80);
      const repackedZip = await outputZip.generateAsync({
        type: 'nodebuffer',
        compression: 'DEFLATE',
        compressionOptions: { level: 6 },
      });

      onProgress(100);
      return {
        data: repackedZip,
        fileName: `${baseName}_entpackt.zip`,
        mimeType: 'application/zip',
      };
    }

    // -------------------------------------------------------------
    // 4. 7Z & TAR EXTRACTION (via 7z.exe with strict isolation)
    // -------------------------------------------------------------
    const workDir = path.join(process.env.COOLWAVE_TEMP_DIR || path.join(process.cwd(), '.tmp'), 'workdir', `arch_${crypto.randomUUID()}`);
    await fs.mkdir(workDir, { recursive: true });

    const archiveInputPath = path.join(workDir, `archive${inputExt || '.7z'}`);
    const extractOutDir = path.join(workDir, 'extracted');
    await fs.mkdir(extractOutDir, { recursive: true });
    await fs.writeFile(archiveInputPath, inputBuffer);

    onProgress(35);

    try {
      const sevenBin = get7zPath();
      // Execute 7z extraction with hard 30s timeout
      await new Promise<void>((resolve, reject) => {
        const child = execFile(
          /*turbopackIgnore: true*/ sevenBin,
          ['x', archiveInputPath, `-o${extractOutDir}`, '-y', '-r'],
          { timeout: 30000, maxBuffer: 10 * 1024 * 1024 },
          (err, _stdout, stderr) => {
            if (err) {
              if (err.killed) {
                return reject(new Error('Archiv-Entpackung wegen Zeitüberschreitung (Timeout 30s) abgebrochen.'));
              }
              return reject(new Error(`7-Zip Entpackungsfehler: ${err.message}. ${stderr || ''}`));
            }
            resolve();
          }
        );

        if (signal) {
          signal.addEventListener('abort', () => {
            try {
              child.kill('SIGTERM');
            } catch {}
            reject(new Error('Operation abgebrochen'));
          });
        }
      });

      onProgress(65);
      if (signal?.aborted) throw new Error('Operation abgebrochen');

      // Scan extracted directory recursively, verify sizes and repack into clean zip
      const outputZip = new JSZip();
      let totalUncompressedBytes = 0;
      let totalFiles = 0;

      async function scanDir(dir: string, relPath: string = '') {
        const entries = await fs.readdir(dir, { withFileTypes: true });
        for (const entry of entries) {
          const fullPath = path.join(dir, entry.name);
          const entryRel = relPath ? `${relPath}/${entry.name}` : entry.name;

          // Path traversal security check
          const normalized = path.normalize(entryRel).replace(/^[a-zA-Z]:/, '').replace(/^(\.\.[\/\\])+/, '');
          if (normalized.includes('..') || path.isAbsolute(normalized)) {
            throw new Error('Sicherheitswarnung: Verdächtige Dateinamen im extrahierten Archiv entdeckt.');
          }

          if (entry.isDirectory()) {
            await scanDir(fullPath, entryRel);
          } else if (entry.isFile()) {
            totalFiles++;
            if (totalFiles > MAX_ENTRIES_COUNT) {
              throw new Error(`Sicherheitswarnung: Archiv überschreitet maximal zulässige Dateianzahl von ${MAX_ENTRIES_COUNT}.`);
            }
            const fileData = await fs.readFile(fullPath);
            totalUncompressedBytes += fileData.length;
            if (totalUncompressedBytes > MAX_UNCOMPRESSED_BYTES) {
              throw new Error('Sicherheitswarnung: Entpacktes Archiv überschreitet das Sicherheitslimit von 150 MB.');
            }
            outputZip.file(normalized, fileData);
          }
        }
      }

      await scanDir(extractOutDir);
      onProgress(85);

      const repackedZip = await outputZip.generateAsync({
        type: 'nodebuffer',
        compression: 'DEFLATE',
        compressionOptions: { level: 6 },
      });

      onProgress(100);
      return {
        data: repackedZip,
        fileName: `${baseName}_entpackt.zip`,
        mimeType: 'application/zip',
      };
    } finally {
      try {
        await fs.rm(workDir, { recursive: true, force: true });
      } catch (err) {
        console.error('[ArchiveService Cleanup Error]:', err);
      }
    }
  }
}

import { IConversionService, ConversionResult } from "../base.service";
import { ServiceOptions } from "@/types/job";
import { PDFDocument } from "pdf-lib";
import sharp from "sharp";

export type SupportedImageTarget =
  | "png"
  | "jpg"
  | "jpeg"
  | "webp"
  | "gif"
  | "svg"
  | "bmp"
  | "tiff"
  | "tif"
  | "ico"
  | "avif"
  | "pdf"
  | "psd";

export class ImageService implements IConversionService {
  name = "ImageService";
  supportedTypes = [
    "image_convert",
    "image_convert_server",
    "image_to_pdf",
    "image_metadata_strip",
    "design_convert",
  ];

  canHandle(type: string): boolean {
    return (
      this.supportedTypes.includes(type) ||
      type.startsWith("image_") ||
      type.startsWith("img_") ||
      type.startsWith("design_")
    );
  }

  async execute(
    inputBuffer: Buffer,
    inputName: string,
    options: ServiceOptions,
    onProgress: (percent: number) => void,
    signal?: AbortSignal
  ): Promise<ConversionResult> {
    onProgress(10);
    if (signal?.aborted) throw new Error("Bildkonvertierung abgebrochen.");

    const maxSizeBytes = Number(options.maxFileSizeMB || 50) * 1024 * 1024;
    if (inputBuffer.length > maxSizeBytes) {
      throw new Error(`Die Datei ueberschreitet das Limit von ${options.maxFileSizeMB || 50} MB.`);
    }

    const baseName = inputName.replace(/\.[^/.]+$/, "");
    const ext = (inputName.split(".").pop() || "").toLowerCase();

    let target = (
      options.targetFormat ||
      options.outputType ||
      (options.jobType === "image_to_pdf" ? "pdf" : "")
    ).toLowerCase().replace(".", "") as SupportedImageTarget;

    const jobTypeStr = String(options.jobType || "");
    if (!target) {
      if (jobTypeStr.includes("to_png")) target = "png";
      else if (jobTypeStr.includes("to_jpg") || jobTypeStr.includes("to_jpeg")) target = "jpg";
      else if (jobTypeStr.includes("to_webp")) target = "webp";
      else if (jobTypeStr.includes("to_gif")) target = "gif";
      else if (jobTypeStr.includes("to_svg")) target = "svg";
      else if (jobTypeStr.includes("to_bmp")) target = "bmp";
      else if (jobTypeStr.includes("to_tiff")) target = "tiff";
      else if (jobTypeStr.includes("to_ico")) target = "ico";
      else if (jobTypeStr.includes("to_avif")) target = "avif";
      else if (jobTypeStr.includes("to_pdf")) target = "pdf";
      else if (jobTypeStr.includes("to_psd")) target = "psd";
      else target = "png";
    }

    // PSD INPUT: decode flat composite via ag-psd or sharp fallback
    if (ext === "psd" && target !== "psd") {
      onProgress(20);
      let psdPngBuffer: Buffer;
      try {
        const agPsd = await import("ag-psd");
        const psd = agPsd.readPsd(inputBuffer, { skipLayerImageData: true });
        const imgData = (psd as any).imageData;
        if (imgData && imgData.data) {
          psdPngBuffer = await sharp(Buffer.from(imgData.data), {
            raw: { width: imgData.width, height: imgData.height, channels: 4 },
          }).png().toBuffer();
        } else {
          throw new Error("Kein Bildinhalt im PSD gefunden.");
        }
      } catch {
        try { psdPngBuffer = await sharp(inputBuffer).png().toBuffer(); }
        catch (e: any) {
          throw new Error(`PSD-Datei konnte nicht gelesen werden: ${e?.message || e}`);
        }
      }
      return this._encodeSharp(sharp(psdPngBuffer), target, baseName, options, onProgress, signal);
    }

    // EPS INPUT: requires Ghostscript via sharp/libvips
    if (ext === "eps" && (target as string) !== "eps") {
      onProgress(20);
      let epsPngBuffer: Buffer;
      try {
        epsPngBuffer = await sharp(inputBuffer, { density: 150 }).png().toBuffer();
      } catch {
        throw new Error(
          "EPS-Konvertierung benoetigt Ghostscript auf dem Server. " +
          "Die Datei konnte nicht verarbeitet werden. " +
          "Tipp: Konvertieren Sie die EPS-Datei zunaechst mit einem lokalen Tool in PDF oder PNG."
        );
      }
      return this._encodeSharp(sharp(epsPngBuffer), target, baseName, options, onProgress, signal);
    }

    // TARGET: PSD (raster-in-PSD, flat)
    if (target === "psd") {
      onProgress(25);
      let pngBuffer: Buffer;
      try { pngBuffer = await sharp(inputBuffer).png().toBuffer(); }
      catch { throw new Error("Das Eingabebild konnte nicht verarbeitet werden."); }
      onProgress(60);
      const psdData = await this._buildMinimalPsd(pngBuffer);
      onProgress(100);
      return {
        data: psdData,
        fileName: `${baseName}.psd`,
        mimeType: "image/vnd.adobe.photoshop",
      };
    }

    // PDF -> SVG: True vector text & geometry extraction via pdfjs-dist
    if (ext === "pdf" && target === "svg") {
      onProgress(20);
      try {
        const pdfjsLib = await import("pdfjs-dist");
        const loadingTask = pdfjsLib.getDocument({ data: new Uint8Array(inputBuffer) });
        const pdf = await loadingTask.promise;
        const page1 = await pdf.getPage(1);
        const viewport = page1.getViewport({ scale: 1.0 });
        const width = Math.round(viewport.width);
        const height = Math.round(viewport.height);

        onProgress(50);
        const textContent = await page1.getTextContent();
        const escapeXml = (str: string) =>
          str
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;')
            .replace(/'/g, '&apos;');

        const textElements: string[] = [];
        for (const item of textContent.items as Array<{ str: string; transform: number[]; fontName?: string }>) {
          if (!item.str || !item.str.trim()) continue;
          const x = Math.round(item.transform[4]);
          const y = Math.round(height - item.transform[5]);
          const fontSize = Math.max(8, Math.round(Math.hypot(item.transform[0], item.transform[1]))) || 12;
          textElements.push(
            `  <text x="${x}" y="${y}" font-size="${fontSize}px" font-family="Inter, -apple-system, sans-serif" fill="#1e293b">${escapeXml(item.str)}</text>`
          );
        }

        onProgress(85);
        const svgContent = `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="${width}pt" height="${height}pt" viewBox="0 0 ${width} ${height}">
  <title>${escapeXml(baseName)} – CoolWave SVG</title>
  <rect width="100%" height="100%" fill="#ffffff"/>
${textElements.join('\n')}
</svg>`;

        onProgress(100);
        return {
          data: Buffer.from(svgContent, "utf-8"),
          fileName: `${baseName}.svg`,
          mimeType: "image/svg+xml",
        };
      } catch (e: any) {
        throw new Error(`PDF-SVG-Konvertierung fehlgeschlagen: ${e?.message}`);
      }
    }

    // SVG -> PDF: rasterize via sharp then embed
    if (ext === "svg" && target === "pdf") {
      onProgress(25);
      const svgPng = await sharp(inputBuffer, { density: 150 }).png().toBuffer();
      onProgress(55);
      const pdf = await PDFDocument.create();
      const embeddedImg = await pdf.embedPng(svgPng);
      const { width, height } = embeddedImg.scale(1);
      const pdfPage = pdf.addPage([width, height]);
      pdfPage.drawImage(embeddedImg, { x: 0, y: 0, width, height });
      const pdfBytes = await pdf.save();
      onProgress(100);
      return {
        data: Buffer.from(pdfBytes),
        fileName: `${baseName}.pdf`,
        mimeType: "application/pdf",
      };
    }

    // Image -> PDF
    if (target === "pdf") {
      onProgress(30);
      const pdf = await PDFDocument.create();
      let normalizedBuffer = inputBuffer;
      if (ext !== "png" && ext !== "jpg" && ext !== "jpeg") {
        normalizedBuffer = await sharp(inputBuffer).png().toBuffer();
      }
      onProgress(60);
      let embeddedImg;
      try { embeddedImg = await pdf.embedPng(normalizedBuffer); }
      catch { embeddedImg = await pdf.embedJpg(normalizedBuffer); }
      const { width, height } = embeddedImg.scale(1);
      const page = pdf.addPage([width, height]);
      page.drawImage(embeddedImg, { x: 0, y: 0, width, height });
      const pdfBytes = await pdf.save();
      onProgress(100);
      return {
        data: Buffer.from(pdfBytes),
        fileName: `${baseName}.pdf`,
        mimeType: "application/pdf",
      };
    }

    onProgress(25);
    if (signal?.aborted) throw new Error("Bildkonvertierung abgebrochen.");

    let sharpInstance: any;
    if (ext === "heic" || ext === "heif") {
      try {
        const heicDecodeModule = await import("heic-decode");
        const heicDecode = (heicDecodeModule as any).default || heicDecodeModule;
        const decoded = await heicDecode({ buffer: inputBuffer });
        sharpInstance = sharp(Buffer.from(decoded.data), {
          raw: { width: decoded.width, height: decoded.height, channels: 4 },
        });
      } catch (heicErr: any) {
        try { sharpInstance = sharp(inputBuffer); await sharpInstance.metadata(); }
        catch { throw new Error(`HEIC-Dekodierung fehlgeschlagen: ${heicErr?.message || heicErr}`); }
      }
    } else if (ext === "bmp") {
      try { sharpInstance = sharp(inputBuffer); await sharpInstance.metadata(); }
      catch {
        const bmpModule = await import("bmp-js");
        const bmp = (bmpModule as any).default || bmpModule;
        const decoded = bmp.decode(inputBuffer);
        sharpInstance = sharp(decoded.data, {
          raw: { width: decoded.width, height: decoded.height, channels: 4 },
        });
      }
    } else if (ext === "ico") {
      try {
        const icoModule = await import("icojs");
        const { decodeIco } = (icoModule as any).default || icoModule;
        const images = await decodeIco(inputBuffer);
        if (!images || images.length === 0) throw new Error("Keine gueltigen Icon-Bilder gefunden.");
        images.sort((a: any, b: any) => b.width * b.height - a.width * a.height);
        sharpInstance = sharp(Buffer.from(images[0].buffer));
      } catch (err: any) {
        throw new Error(`ICO-Dekodierung fehlgeschlagen: ${err.message || err}`);
      }
    } else {
      sharpInstance = sharp(inputBuffer);
    }

    return this._encodeSharp(sharpInstance, target, baseName, options, onProgress, signal);
  }

  private async _encodeSharp(
    sharpInstance: any,
    target: SupportedImageTarget,
    baseName: string,
    options: ServiceOptions,
    onProgress: (p: number) => void,
    signal?: AbortSignal
  ): Promise<ConversionResult> {
    onProgress(50);
    if (signal?.aborted) throw new Error("Abgebrochen.");

    let outputBuffer: Buffer;
    let outputMime = "image/png";
    let outputExt: string = target;
    const quality = typeof options.quality === "number" ? options.quality : 90;

    switch (target) {
      case "png": {
        outputBuffer = await sharpInstance.png({ compressionLevel: 8 }).toBuffer();
        outputMime = "image/png"; outputExt = "png"; break;
      }
      case "jpg": case "jpeg": {
        outputBuffer = await sharpInstance
          .flatten({ background: options.backgroundColor || "#ffffff" })
          .jpeg({ quality, mozjpeg: true }).toBuffer();
        outputMime = "image/jpeg"; outputExt = "jpg"; break;
      }
      case "webp": {
        outputBuffer = await sharpInstance.webp({ quality }).toBuffer();
        outputMime = "image/webp"; outputExt = "webp"; break;
      }
      case "gif": {
        outputBuffer = await sharpInstance.gif().toBuffer();
        outputMime = "image/gif"; outputExt = "gif"; break;
      }
      case "avif": {
        outputBuffer = await sharpInstance.avif({ quality }).toBuffer();
        outputMime = "image/avif"; outputExt = "avif"; break;
      }
      case "tiff": case "tif": {
        outputBuffer = await sharpInstance.tiff().toBuffer();
        outputMime = "image/tiff"; outputExt = "tiff"; break;
      }
      case "bmp": {
        const { data, info } = await sharpInstance.ensureAlpha().raw().toBuffer({ resolveWithObject: true });
        const bmpModule = await import("bmp-js");
        const bmp = (bmpModule as any).default || bmpModule;
        const encoded = bmp.encode({ data, width: info.width, height: info.height });
        outputBuffer = encoded.data;
        outputMime = "image/bmp"; outputExt = "bmp"; break;
      }
      case "ico": {
        const pngForIco = await sharpInstance
          .resize(256, 256, { fit: "inside", background: { r: 0, g: 0, b: 0, alpha: 0 } })
          .png().toBuffer();
        const pModule = await import("png-to-ico");
        const pngToIco = (pModule as any).default || pModule;
        outputBuffer = await pngToIco(pngForIco);
        outputMime = "image/x-icon"; outputExt = "ico"; break;
      }
      case "svg": {
        const intermediatePng = await sharpInstance.png().toBuffer();
        const potraceModule = await import("potrace");
        const potrace = (potraceModule as any).default || potraceModule;
        const svgString: string = await new Promise((resolve, reject) => {
          potrace.trace(intermediatePng, { threshold: 128, steps: 4 }, (err: Error | null, svg: string) => {
            if (err) reject(err); else resolve(svg);
          });
        });
        outputBuffer = Buffer.from(svgString, "utf-8");
        outputMime = "image/svg+xml"; outputExt = "svg"; break;
      }
      default: {
        outputBuffer = await sharpInstance.png().toBuffer();
        outputMime = "image/png"; outputExt = "png"; break;
      }
    }

    onProgress(100);
    return {
      data: outputBuffer,
      fileName: `${baseName}.${outputExt}`,
      mimeType: outputMime,
    };
  }

  private async _buildMinimalPsd(pngBuffer: Buffer): Promise<Buffer> {
    const meta = await sharp(pngBuffer).metadata();
    const w = meta.width || 1;
    const h = meta.height || 1;
    const rgbRaw = await sharp(pngBuffer).flatten({ background: "#ffffff" }).removeAlpha().raw().toBuffer();

    const rPlane = Buffer.alloc(w * h);
    const gPlane = Buffer.alloc(w * h);
    const bPlane = Buffer.alloc(w * h);
    for (let i = 0; i < w * h; i++) {
      rPlane[i] = rgbRaw[i * 3];
      gPlane[i] = rgbRaw[i * 3 + 1];
      bPlane[i] = rgbRaw[i * 3 + 2];
    }

    const header = Buffer.alloc(26);
    header.write("8BPS", 0, "ascii");
    header.writeUInt16BE(1, 4);
    header.writeUInt16BE(3, 12);
    header.writeUInt32BE(h, 14);
    header.writeUInt32BE(w, 18);
    header.writeUInt16BE(8, 22);
    header.writeUInt16BE(3, 24);

    const colorModeLen = Buffer.alloc(4);
    const resourcesLen = Buffer.alloc(4);
    const layersLen = Buffer.alloc(4);
    const compression = Buffer.alloc(2);
    const imageData = Buffer.concat([rPlane, gPlane, bPlane]);

    return Buffer.concat([header, colorModeLen, resourcesLen, layersLen, compression, imageData]);
  }
}

