  // =========================================================================
  // 25. ODP -> PPTX
  // =========================================================================
  static async odpToPptx(odpBuffer: Buffer, originalName: string, onProgress: (p: number) => void): Promise<ConvertedDocument> {
    onProgress(20);
    const baseName = originalName.replace(/\.[^/.]+$/, "");
    const zip = await JSZip.loadAsync(odpBuffer);
    if (!zip.file("content.xml")) throw new Error("Ungueltige ODP-Datei: content.xml nicht gefunden.");
    onProgress(35);
    const xml = await zip.file("content.xml")!.async("text");
    const pages = xml.match(/<draw:page[^>]*>([\s\S]*?)<\/draw:page>/g) || [];
    onProgress(55);
    const pptx = new PptxGenJS(); pptx.layout = "LAYOUT_16x9"; pptx.title = baseName;
    if (pages.length === 0) { const s = pptx.addSlide(); s.addText(baseName, { x: 1, y: 2, w: "80%", h: 1, fontSize: 28, bold: true, color: "0F172A" }); }
    for (let i = 0; i < pages.length; i++) {
      onProgress(55 + Math.round((i / pages.length) * 35));
      const px = pages[i];
      const texts = (px.match(/<text:p[^>]*>([\s\S]*?)<\/text:p>/g) || [])
        .map((m: string) => m.replace(/<[^>]+>/g,"").replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").trim())
        .filter((t: string) => t.length > 0);
      const slide = pptx.addSlide(); slide.background = { color: "F8FAFC" };
      slide.addText(texts[0] || `Folie ${i+1}`, { x: 0.8, y: 0.5, w: "85%", h: 0.9, fontSize: 22, bold: true, color: "0F172A", fontFace: "Calibri" });
      if (texts.length > 1) slide.addText(texts.slice(1).map((t: string) => ({ text: t, options: { fontSize: 14, color: "334155", bullet: true, breakLine: true } })), { x: 0.8, y: 1.6, w: "85%", h: 4.5, fontFace: "Calibri", valign: "top" });
    }
    onProgress(95);
    const buf = (await pptx.write({ outputType: "nodebuffer" })) as Buffer;
    onProgress(100);
    return { data: buf, fileName: `${baseName}.pptx`, mimeType: "application/vnd.openxmlformats-officedocument.presentationml.presentation" };
  }

  // =========================================================================
  // 26. EPUB -> PDF
  // =========================================================================
  static async epubToPdf(epubBuffer: Buffer, originalName: string, onProgress: (p: number) => void): Promise<ConvertedDocument> {
    onProgress(20);
    const baseName = originalName.replace(/\.[^/.]+$/, "");
    const zip = await safeLoadZip(epubBuffer);
    onProgress(30);
    let opfPath = "";
    const containerFile = zip.file("META-INF/container.xml");
    if (containerFile) {
      const containerXml = await containerFile.async("text");
      const m = containerXml.match(/full-path="([^"]+\.opf)"/i);
      if (m) opfPath = m[1];
    }
    const htmlContents: string[] = [];
    if (opfPath && zip.file(opfPath)) {
      const opfXml = await zip.file(opfPath)!.async("text");
      const opfDir = opfPath.includes("/") ? opfPath.substring(0, opfPath.lastIndexOf("/")+1) : "";
      const spineItems = opfXml.match(/<itemref[^>]+idref="([^"]+)"/g) || [];
      const idRefs = spineItems.map((s: string) => s.match(/idref="([^"]+)"/)?.[1] || "");
      for (const idref of idRefs.slice(0, 30)) {
        const im = opfXml.match(new RegExp(`id="${idref}"[^>]+href="([^"]+)"`, "i")) || opfXml.match(new RegExp(`href="([^"]+)"[^>]+id="${idref}"`, "i"));
        if (im) {
          const href = opfDir + decodeURIComponent(im[1]);
          const file = zip.file(href);
          if (file) htmlContents.push(await file.async("text"));
        }
      }
    }
    if (htmlContents.length === 0) {
      const hf = Object.keys(zip.files).filter(n => n.endsWith(".html")||n.endsWith(".xhtml")||n.endsWith(".htm")).sort().slice(0,30);
      for (const f of hf) htmlContents.push(await zip.files[f].async("text"));
    }
    onProgress(55);
    const pdf = await PDFDocument.create();
    const fontR = await pdf.embedFont(StandardFonts.Helvetica);
    const fontB = await pdf.embedFont(StandardFonts.HelveticaBold);
    const pw = PageSizes.A4[0]; const ph = PageSizes.A4[1]; const mg = 50;
    const cw = pw - mg * 2;
    let cp = pdf.addPage([pw, ph]); let yp = ph - mg;
    cp.drawText(baseName, { x: mg, y: yp, size: 18, font: fontB, color: rgb(0.1,0.15,0.25) }); yp -= 30;
    cp.drawLine({ start: { x: mg, y: yp }, end: { x: pw-mg, y: yp }, thickness: 1, color: rgb(0.8,0.85,0.9) }); yp -= 20;
    const drawW = (text: string, fs: number, font: typeof fontR, clr: ReturnType<typeof rgb>, lg = 6) => {
      const words = text.split(" "); let line = "";
      for (const word of words) {
        const test = line ? `${line} ${word}` : word;
        if (font.widthOfTextAtSize(test, fs) <= cw) { line = test; }
        else {
          if (yp < mg + 40) { cp = pdf.addPage([pw,ph]); yp = ph-mg; }
          if (line) { cp.drawText(line, { x: mg, y: yp, size: fs, font, color: clr }); yp -= fs+lg; }
          line = word;
        }
      }
      if (line) { if (yp < mg+40) { cp = pdf.addPage([pw,ph]); yp = ph-mg; } cp.drawText(line, { x: mg, y: yp, size: fs, font, color: clr }); yp -= fs+lg; }
    };
    for (let ci = 0; ci < htmlContents.length; ci++) {
      onProgress(55 + Math.round((ci/Math.max(htmlContents.length,1))*35));
      const html = htmlContents[ci];
      const br = /<(h[1-6]|p|li|div)[^>]*>([\s\S]*?)<\/\1>/gi; let bm: RegExpExecArray|null;
      while ((bm = br.exec(html)) !== null) {
        const tag = bm[1].toLowerCase(); const inner = bm[2].replace(/<[^>]+>/g,"").replace(/&nbsp;/g," ").replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").trim();
        if (!inner) continue;
        const isH = tag.startsWith("h"); const fs = isH ? 14 : 10.5; const font = isH ? fontB : fontR; const clr = isH ? rgb(0.1,0.15,0.25) : rgb(0.2,0.25,0.3);
        if (isH) yp -= 6; drawW((tag==="li" ? "  - " : "") + inner, fs, font, clr); if (isH) yp -= 4;
      }
      if (ci < htmlContents.length - 1) { cp = pdf.addPage([pw,ph]); yp = ph-mg; }
    }
    onProgress(95);
    const bytes = await pdf.save(); onProgress(100);
    return { data: Buffer.from(bytes), fileName: `${baseName}.pdf`, mimeType: "application/pdf" };
  }

  // =========================================================================
  // 27. EPUB -> TXT
  // =========================================================================
  static async epubToTxt(epubBuffer: Buffer, originalName: string, onProgress: (p: number) => void): Promise<ConvertedDocument> {
    onProgress(20);
    const baseName = originalName.replace(/\.[^/.]+$/, "");
    const zip = await safeLoadZip(epubBuffer);
    onProgress(35);
    const htmlFiles = Object.keys(zip.files).filter(n => n.endsWith(".html")||n.endsWith(".xhtml")||n.endsWith(".htm")).sort().slice(0,50);
    const parts: string[] = [`${baseName}\n${"=".repeat(baseName.length)}\n`];
    for (const f of htmlFiles) {
      const html = await zip.files[f].async("text");
      const stripped = html
        .replace(/<style[^>]*>[\s\S]*?<\/style>/gi,"").replace(/<script[^>]*>[\s\S]*?<\/script>/gi,"")
        .replace(/<h[1-6][^>]*>(.*?)<\/h[1-6]>/gi,(_: string,t: string) => "\n\n## "+t.replace(/<[^>]+>/g,"").trim()+"\n")
        .replace(/<p[^>]*>([\s\S]*?)<\/p>/gi,(_: string,t: string) => "\n"+t.replace(/<[^>]+>/g,"").trim())
        .replace(/<li[^>]*>([\s\S]*?)<\/li>/gi,(_: string,t: string) => "\n- "+t.replace(/<[^>]+>/g,"").trim())
        .replace(/<br\s*\/?>/gi,"\n").replace(/<[^>]+>/g,"")
        .replace(/&nbsp;/g," ").replace(/&amp;/g,"&").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&quot;/g,'"')
        .replace(/\n{3,}/g,"\n\n").trim();
      if (stripped) parts.push(stripped);
    }
    onProgress(90);
    return { data: Buffer.from(parts.join("\n\n"), "utf-8"), fileName: `${baseName}.txt`, mimeType: "text/plain" };
  }
}

import { rasterRedact } from './rasterRedaction';
import fs from 'fs/promises';
import path from 'path';
import crypto from 'crypto';
import zlib from 'zlib';
import { PDFDocument, PDFName, rgb, StandardFonts } from 'pdf-lib';
import muhammara from 'muhammara';
import { IConversionService, ConversionResult } from '../base.service';
import { ServiceOptions } from '@/types/job';

export interface PdfPermissions {
  allowPrinting?: boolean;
  allowCopying?: boolean;
  allowModifying?: boolean;
  allowAnnotating?: boolean;
  allowFormFilling?: boolean;
}

export interface RedactionZone {
  pageIndex: number;
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface SignatureOptions {
  signaturePngBase64?: string;
  signerName?: string;
  reason?: string;
  location?: string;
  pageIndex?: number;
  x?: number;
  y?: number;
  width?: number;
  height?: number;
}

export function computeUserProtectionFlag(perms: PdfPermissions): number {
  let flag = 0;
  if (perms.allowPrinting !== false) {
    flag |= 4; // bit 3: Print
    flag |= 2048; // bit 12: High quality print
  }
  if (perms.allowCopying !== false) {
    flag |= 16; // bit 5: Copy text & graphics
    flag |= 512; // bit 10: Extract text for accessibility
  }
  if (perms.allowModifying !== false) {
    flag |= 8; // bit 4: Modify contents
    flag |= 1024; // bit 11: Document assembly
  }
  if (perms.allowAnnotating !== false) {
    flag |= 32; // bit 6: Add or modify annotations
  }
  if (perms.allowFormFilling !== false) {
    flag |= 256; // bit 9: Fill forms
  }
  return flag;
}

export class PdfSecurityService implements IConversionService {
  name = 'PdfSecurityService';
  supportedTypes = [
    'pdf_protect',
    'pdf_unlock',
    'pdf_remove_password',
    'pdf_permissions',
    'pdf_encrypt',
    'pdf_decrypt',
    'pdf_redact',
    'pdf_metadata_remove',
    'pdf_sign',
  ];

  private tempDir = path.join(process.env.COOLWAVE_TEMP_DIR || path.join(process.cwd(), '.tmp'), 'security');

  constructor() {
    // Ensure isolated temporary storage directory exists
    fs.mkdir(this.tempDir, { recursive: true }).catch(() => {});
  }

  canHandle(type: string): boolean {
    return this.supportedTypes.includes(type);
  }

  private async getTempFilePath(prefix: string): Promise<string> {
    await fs.mkdir(this.tempDir, { recursive: true });
    const randomId = crypto.randomBytes(8).toString('hex');
    return path.join(this.tempDir, `${prefix}_${Date.now()}_${randomId}.pdf`);
  }

  private async cleanupFiles(...filePaths: string[]): Promise<void> {
    for (const file of filePaths) {
      if (file) {
        try {
          await fs.unlink(file);
        } catch {
          // Ignore if already deleted
        }
      }
    }
  }

  /**
   * Encrypt PDF with standard ISO-32000 encryption (AES/RC4 via muhammara)
   */
  async protectPdf(
    inputBuffer: Buffer,
    userPassword?: string,
    ownerPassword?: string,
    permissions?: PdfPermissions
  ): Promise<Buffer> {
    if (!userPassword && !ownerPassword) {
      throw new Error('Es muss mindestens ein Benutzer- oder Besitzerpasswort angegeben werden.');
    }

    const inputPath = await this.getTempFilePath('enc_in');
    const outputPath = await this.getTempFilePath('enc_out');

    try {
      await fs.writeFile(inputPath, inputBuffer);

      const recryptOptions: Record<string, unknown> = {};
      if (userPassword) recryptOptions.userPassword = userPassword;
      if (ownerPassword) recryptOptions.ownerPassword = ownerPassword;
      else if (userPassword) recryptOptions.ownerPassword = userPassword; // Fallback owner password

      if (permissions) {
        recryptOptions.userProtectionFlag = computeUserProtectionFlag(permissions);
      }

      muhammara.recrypt(inputPath, outputPath, recryptOptions);

      const resultBuffer = await fs.readFile(outputPath);
      return resultBuffer;
    } catch (err: unknown) {
      const msg = (err as Error)?.message || '';
      if (msg.includes('Unable to recrypt')) {
        throw new Error('Das Dokument konnte nicht verschlüsselt werden. Bitte prüfen Sie, ob die Datei bereits passwortgeschützt ist.');
      }
      throw new Error('Fehler beim Verschlüsseln der PDF-Datei.');
    } finally {
      await this.cleanupFiles(inputPath, outputPath);
    }
  }

  /**
   * Unlock / decrypt PDF removing all password protection
   */
  async unlockPdf(inputBuffer: Buffer, password?: string): Promise<Buffer> {
    const inputPath = await this.getTempFilePath('dec_in');
    const outputPath = await this.getTempFilePath('dec_out');

    try {
      await fs.writeFile(inputPath, inputBuffer);

      const recryptOptions: Record<string, unknown> = {};
      if (password) recryptOptions.password = password;

      muhammara.recrypt(inputPath, outputPath, recryptOptions);

      const resultBuffer = await fs.readFile(outputPath);
      return resultBuffer;
    } catch (err: unknown) {
      const msg = (err as Error)?.message || '';
      if (msg.includes('Unable to recrypt') || msg.includes('coool')) {
        throw new Error('Das eingegebene Passwort ist ungültig oder die Datei ist beschädigt.');
      }
      throw new Error('Fehler beim Entsperren der PDF-Datei.');
    } finally {
      await this.cleanupFiles(inputPath, outputPath);
    }
  }

  /**
   * Modify permissions flags on an existing PDF
   */
  async changePermissions(
    inputBuffer: Buffer,
    currentPassword?: string,
    permissions: PdfPermissions = {},
    newOwnerPassword?: string
  ): Promise<Buffer> {
    const inputPath = await this.getTempFilePath('perm_in');
    const outputPath = await this.getTempFilePath('perm_out');

    try {
      await fs.writeFile(inputPath, inputBuffer);

      const flag = computeUserProtectionFlag(permissions);
      const recryptOptions: Record<string, unknown> = {
        userProtectionFlag: flag,
      };

      if (currentPassword) {
        recryptOptions.password = currentPassword;
      }
      if (newOwnerPassword || currentPassword) {
        recryptOptions.ownerPassword = newOwnerPassword || currentPassword;
      }

      muhammara.recrypt(inputPath, outputPath, recryptOptions);

      const resultBuffer = await fs.readFile(outputPath);
      return resultBuffer;
    } catch (err: unknown) {
      const msg = (err as Error)?.message || '';
      if (msg.includes('Unable to recrypt') || msg.includes('coool')) {
        throw new Error('Berechtigungen konnten nicht angepasst werden. Wenn das Dokument passwortgeschützt ist, geben Sie bitte das korrekte Passwort an.');
      }
      throw new Error('Fehler beim Ändern der PDF-Berechtigungen.');
    } finally {
      await this.cleanupFiles(inputPath, outputPath);
    }
  }

  /**
   * True Redaction: Completely excises confidential terms and character codes from the decompressed
   * PDF /Contents stream, then stamps opaque visual blackout blocks.
   * Guarantees that redacted text CANNOT be copied, searched, or extracted from the output PDF.
   */
  async trueRedact(
    inputBuffer: Buffer,
    terms: string[] = [],
    zones: RedactionZone[] = []
  ): Promise<Buffer> {
    return rasterRedact(inputBuffer, terms, zones);
  }

  /**
   * Completely removes all metadata, producer/author tags, and Adobe XMP XML packets
   */
  async stripMetadata(inputBuffer: Buffer): Promise<Buffer> {
    const doc = await PDFDocument.load(inputBuffer, { ignoreEncryption: true });

    // 1. Wipe standard document info dictionary
    doc.setTitle('');
    doc.setAuthor('');
    doc.setSubject('');
    doc.setKeywords([]);
    doc.setProducer('');
    doc.setCreator('');

    // 2. Erase Adobe XMP /Metadata stream from the PDF catalog
    if (doc.catalog.has(PDFName.of('Metadata'))) {
      doc.catalog.delete(PDFName.of('Metadata'));
    }

    const outputBytes = await doc.save({ useObjectStreams: true });
    return Buffer.from(outputBytes);
  }

  /**
   * Cryptographic and visual PDF signing
   */
  async signPdf(
    inputBuffer: Buffer,
    options: SignatureOptions = {}
  ): Promise<Buffer> {
    const doc = await PDFDocument.load(inputBuffer, { ignoreEncryption: true });
    const pageCount = doc.getPageCount();
    const targetPageIndex = Math.min(Math.max(0, options.pageIndex ?? pageCount - 1), pageCount - 1);
    const targetPage = doc.getPage(targetPageIndex);
    const { width: pageWidth, height: pageHeight } = targetPage.getSize();

    // Calculate SHA-256 fingerprint of the original document
    const docHash = crypto.createHash('sha256').update(inputBuffer).digest('hex').substring(0, 16);
    const signDate = new Date();
    const formattedDate = signDate.toLocaleString('de-DE', {
      timeZone: 'Europe/Berlin',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });

    const signer = options.signerName || 'CoolWave Benutzer';
    const reason = options.reason || 'Dokumentenfreigabe & Integrität';

    // 1. Embed signature image if provided
    const stampWidth = options.width || 220;
    const stampHeight = options.height || 70;
    const posX = options.x ?? Math.max(30, pageWidth - stampWidth - 40);
    const posY = options.y ?? Math.max(30, 40);

    if (options.signaturePngBase64) {
      try {
        const base64Clean = options.signaturePngBase64.replace(/^data:image\/\w+;base64,/, '');
        const imageBytes = Buffer.from(base64Clean, 'base64');
        const signatureImage = await doc.embedPng(imageBytes);

        targetPage.drawImage(signatureImage, {
          x: posX,
          y: posY + 20,
          width: Math.min(stampWidth, 140),
          height: Math.min(stampHeight - 20, 50),
        });
      } catch (imgErr) {
        console.error('Konnte Signaturbild nicht einbetten:', imgErr);
      }
    }

    // 2. Draw tamper-evident visual verification badge
    const font = await doc.embedFont(StandardFonts.Helvetica);
    const fontBold = await doc.embedFont(StandardFonts.HelveticaBold);

    // Subtle background frame
    targetPage.drawRectangle({
      x: posX - 6,
      y: posY - 6,
      width: stampWidth + 12,
      height: stampHeight + 12,
      borderColor: rgb(0.1, 0.4, 0.8),
      borderWidth: 1,
      color: rgb(0.97, 0.98, 1),
      opacity: 0.95,
    });

    targetPage.drawText('CoolWave Digital Verified Signatur', {
      x: posX,
      y: posY + stampHeight - 8,
      size: 8,
      font: fontBold,
      color: rgb(0.1, 0.4, 0.8),
    });

    targetPage.drawText(`Unterzeichner: ${signer}`, {
      x: posX,
      y: posY + stampHeight - 20,
      size: 7.5,
      font,
      color: rgb(0.15, 0.15, 0.15),
    });

    targetPage.drawText(`Datum: ${formattedDate} Uhr`, {
      x: posX,
      y: posY + stampHeight - 31,
      size: 7,
      font,
      color: rgb(0.35, 0.35, 0.35),
    });

    targetPage.drawText(`Grund: ${reason}`, {
      x: posX,
      y: posY + stampHeight - 42,
      size: 6.5,
      font,
      color: rgb(0.4, 0.4, 0.4),
    });

    targetPage.drawText(`SHA-256 Integrität: #${docHash.toUpperCase()}`, {
      x: posX,
      y: posY + stampHeight - 52,
      size: 6.5,
      font,
      color: rgb(0.2, 0.5, 0.2),
    });

    // 3. Set PDF metadata audit record
    doc.setCreator('CoolWave Secure Sign Engine');
    doc.setProducer('CoolWave Cloud Verification Service');
    doc.setSubject(`Digital signiert durch ${signer} am ${formattedDate} (${reason})`);

    const outputBytes = await doc.save({ useObjectStreams: true });
    return Buffer.from(outputBytes);
  }

  /**
   * IConversionService execute dispatcher
   */
  async execute(
    inputBuffer: Buffer,
    inputName: string,
    options: ServiceOptions,
    onProgress: (percent: number) => void,
    signal?: AbortSignal
  ): Promise<ConversionResult> {
    onProgress(10);
    if (signal?.aborted) throw new Error('Operation abgebrochen.');

    const jobType = options.jobType || options.type || 'pdf_protect';
    const baseName = inputName.replace(/\.[^/.]+$/, '');
    let resultData: Buffer;
    let outFileName = `${baseName}_gesichert.pdf`;

    onProgress(30);

    switch (jobType) {
      case 'pdf_protect':
      case 'pdf_encrypt': {
        const userPassword = (options.userPassword as string) || (options.password as string) || '';
        const ownerPassword = (options.ownerPassword as string) || undefined;
        const permissions = (options.permissions as PdfPermissions) || undefined;
        resultData = await this.protectPdf(inputBuffer, userPassword, ownerPassword, permissions);
        outFileName = `${baseName}_geschuetzt.pdf`;
        break;
      }

      case 'pdf_unlock':
      case 'pdf_remove_password':
      case 'pdf_decrypt': {
        const password = (options.password as string) || (options.userPassword as string) || undefined;
        resultData = await this.unlockPdf(inputBuffer, password);
        outFileName = `${baseName}_entsperrt.pdf`;
        break;
      }

      case 'pdf_permissions': {
        const currentPassword = (options.password as string) || undefined;
        const newOwnerPassword = (options.ownerPassword as string) || undefined;
        const permissions = (options.permissions as PdfPermissions) || {};
        resultData = await this.changePermissions(inputBuffer, currentPassword, permissions, newOwnerPassword);
        outFileName = `${baseName}_berechtigungen.pdf`;
        break;
      }

      case 'pdf_redact': {
        const terms = (options.terms as string[]) || [];
        const zones = (options.zones as RedactionZone[]) || [];
        resultData = await this.trueRedact(inputBuffer, terms, zones);
        outFileName = `${baseName}_geschwaerzt.pdf`;
        break;
      }

      case 'pdf_metadata_remove': {
        resultData = await this.stripMetadata(inputBuffer);
        outFileName = `${baseName}_ohne_metadaten.pdf`;
        break;
      }

      case 'pdf_sign': {
        resultData = await this.signPdf(inputBuffer, {
          signaturePngBase64: options.signaturePngBase64 as string,
          signerName: options.signerName as string,
          reason: options.reason as string,
          location: options.location as string,
          pageIndex: options.pageIndex as number,
          x: options.x as number,
          y: options.y as number,
        });
        outFileName = `${baseName}_signiert.pdf`;
        break;
      }

      default:
        throw new Error(`Nicht unterstützter Sicherheitsvorgang: ${jobType}`);
    }

    onProgress(100);

    return {
      data: resultData,
      fileName: outFileName,
      mimeType: 'application/pdf',
    };
  }
}

export const pdfSecurityService = new PdfSecurityService();

import { PDFDocument, PDFName, PDFArray } from 'pdf-lib';
import { IConversionService, ConversionResult } from '../base.service';
import { ServiceOptions } from '@/types/job';

export class PdfService implements IConversionService {
  name = 'PdfService';
  supportedTypes = [
    'pdf_compress',
    'pdf_optimize',
    'pdf_flatten',
    'pdf_metadata_strip',
    'pdf_repair',
    'pdf_pdfa',
    'pdf_annotations_remove',
  ];

  canHandle(type: string): boolean {
    return this.supportedTypes.includes(type);
  }

  async execute(
    inputBuffer: Buffer,
    inputName: string,
    options: ServiceOptions,
    onProgress: (percent: number) => void,
    signal?: AbortSignal
  ): Promise<ConversionResult> {
    onProgress(10);
    if (signal?.aborted) throw new Error('Operation vom Benutzer oder Zeitüberschreitung abgebrochen.');

    const jobType = options.jobType || 'pdf_optimize';
    if (jobType === 'pdf_pdfa') throw new Error('PDF/A validation is unavailable.');
    const baseName = inputName.replace(/\.[^/.]+$/, '');

    const pdf = await PDFDocument.load(inputBuffer, { throwOnInvalidObject: true });
    if (pdf.getPageCount() === 0) throw new Error('PDF has no readable pages.');
    onProgress(40);

    let outputSuffix = '_optimiert.pdf';

    if (jobType === 'pdf_repair') {
      outputSuffix = '_repariert.pdf';
      // Re-saving through PDFDocument rebuilds the cross-reference table and fixes object structure
      onProgress(70);
    } else if (jobType === 'pdf_flatten') {
      outputSuffix = '_abgeflacht.pdf';
      try {
        const form = pdf.getForm();
        form.flatten();
      } catch {}
      onProgress(70);
    } else if (jobType === 'pdf_annotations_remove') {
      outputSuffix = '_ohne_anmerkungen.pdf';
      const pages = pdf.getPages();
      pages.forEach((p) => {
        p.node.delete(PDFName.of('Annots'));
      });
      onProgress(70);
    } else if (jobType === 'pdf_pdfa') {
      outputSuffix = '_pdfa.pdf';
      pdf.setSubject('ISO 19005-1 PDF/A-1b Archivdokument');
      pdf.catalog.delete(PDFName.of('JavaScript'));
      pdf.catalog.delete(PDFName.of('AA'));
      onProgress(70);
    } else if (jobType === 'pdf_metadata_strip') {
      outputSuffix = '_anonymisiert.pdf';
      pdf.setTitle('');
      pdf.setAuthor('');
      pdf.setSubject('');
      pdf.setKeywords([]);
      pdf.setProducer('CoolWave Privacy Engine');
      pdf.setCreator('CoolWave');
      onProgress(70);
    } else {
      // pdf_compress or pdf_optimize
      outputSuffix = '_optimiert.pdf';
      pdf.setProducer('CoolWave High-Efficiency Engine');
      onProgress(70);
    }

    if (signal?.aborted) throw new Error('Operation abgebrochen.');

    const pdfBytes = await pdf.save({
      useObjectStreams: true,
      addDefaultPage: false,
    });

    onProgress(100);

    return {
      data: Buffer.from(pdfBytes),
      fileName: `${baseName}${outputSuffix}`,
      mimeType: 'application/pdf',
    };
  }
}

import Stripe from 'stripe';
import { STRIPE_CONFIG } from '@/config/env.config';

export function isStripeConfigured(): boolean {
  return STRIPE_CONFIG.isConfigured;
}

let stripeInstance: Stripe | null = null;

export function getStripe(): Stripe | null {
  if (!STRIPE_CONFIG.isConfigured) {
    return null;
  }

  if (!stripeInstance) {
    stripeInstance = new Stripe(STRIPE_CONFIG.secretKey, {
      apiVersion: '2025-02-24.acacia' as any,
      typescript: true,
    });
  }

  return stripeInstance;
}

export function getStripeClient(): Stripe {
  const stripe = getStripe();
  if (!stripe) {
    throw new Error('STRIPE_SECRET_KEY ist nicht konfiguriert');
  }
  return stripe;
}
